#!/usr/bin/env bash
# ci_workflow.sh - read what .github/workflows/ci.yml actually *executes*, so
# several suites can assert wiring the same way instead of each inventing it.
#
# Why this is a library rather than a helper inside one suite: three places now
# need to ask "does ci.yml really run X?" -- test/ci_coverage_test.sh (every
# suite is wired), test/action_pin_test.sh (the coverage step itself is still
# wired), and test/sec18_denylist_test.sh (the e2e script is wired). Written out
# three times they drifted immediately: two of the copies were plain line
# searches that a trailing comment or a `name:` mention satisfied, so a disabled
# step read as wired -- the "absence == pass" shape those very assertions exist
# to prevent (found in review, twice, after the strong version already existed).
# CLAUDE.md §6 asks for extraction at the second or third occurrence; this is it.
#
# What "executes" means here, and why each part is needed:
#
#   * Only the values of `run:` keys count. Searching raw lines lets
#     `run: echo skipped  # bash test/foo_test.sh` and
#     `- name: TODO re-enable bash test/foo_test.sh` pass as wiring.
#   * Comments are stripped from those values, so an inline `#` inside a
#     `run: |` block cannot smuggle a match either.
#   * A step carrying `if: false` or `continue-on-error: true` is dropped, and
#     so is every step of a job carrying one. The first never runs; the second
#     runs but cannot fail the job, so neither gates anything -- and disabling
#     that way is one added line rather than a deletion, which makes it the
#     easier mistake to miss.
#   * Commands are published as *gating segments*: each command line is split at
#     `;` `&&` `||` `|` `&`, and a segment counts only when its own failure can
#     still fail the job. `bash x || true`, a trailing `&`, a pipe without
#     `pipefail`, and anything after `set +e` all run the command while
#     discarding its verdict -- `continue-on-error: true` spelled in one token.
#   * Both a per-command and a per-step view are published. `shellcheck $SHELL_FILES`
#     has to be true of one command; `bash -n "$f"` and `for f in $SHELL_FILES`
#     are two lines of one step and only make sense together.
#   * Commands are tagged with the job they belong to, so a caller can ask
#     "does *this* job run it" -- a variable defined in one job is invisible to
#     another, so an unscoped answer would call a cross-job split wired.
#
# Usage:
#   source "${SCRIPT_DIR}/lib/ci_workflow.sh"
#   ci_workflow_load "<path to ci.yml>" "<scratch file>"   # returns non-zero on failure;
#                                          the caller decides whether to bail
#   ci_workflow_command_matches <job> <regex>...  # one gating command matches all of them
#   ci_workflow_step_matches    <job> <regex>...  # one step matches all, across its commands
#   ci_workflow_runs_script     <path> [<job>]    # some gating command invokes that script
#   ci_workflow_env_records     def <name>        # jobs whose env defines that folded block
#   ci_workflow_env_records     val <name>        # the entries of that block, one per line
#   ci_workflow_regex_escape    <string>          # literal text -> safe ERE fragment
# `<job>` は絞り込むジョブ名。空文字列を渡すとジョブを問わない。

# **コマンドの手前に置ける前置き**（実行ラッパと環境変数の代入）を表す断片。
# 下の 2 つの開始位置が**同じ一覧**を読むためにここ 1 か所に置く——別々に書くと、
# 片方だけが `sudo shellcheck …` のような等価な書き換えを認めなくなる（レビューで実測）
# **`time` も前置きに入れる**（`strip_struct_wrappers()` / `strip_command_prefixes()` が
# 既に「自分では何も変えない飾り」として扱っているのと揃える）——`time bash x` は
# スクリプトを実行し、その失敗もそのまま伝わる（`set -e` の下で `time false` は exit 1）のに、
# 一覧に無いせいで「実行されていない」と**事実と逆の診断**を出していた（fail-closed。レビューで実測）。
# `-p` は `time` にだけ続けられる形にする（素の `-p ` を前置きとして認めると、
# 無関係な綴りの先頭を命令の位置と読む方向へ広がる）。綴りは
# `strip_command_prefixes()` の `^time[[:space:]]+(-p[[:space:]]+)?` と揃える。
# **`!` は入れない**——あちらは終了状態を**反転**するので、本当にゲートしない
CI_WORKFLOW_COMMAND_PREFIXES='((sudo|env|nice|timeout|command|exec)[[:space:]]+|time[[:space:]]+(-p[[:space:]]+)?|[0-9]+[smhd]?[[:space:]]+|[A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*[[:space:]]+)*'

# **必ず走るグループの開き**（部分シェル `(` とブレースグループ `{`）を表す断片。
# どちらも本体を無条件に走らせ、終了状態もそのまま伝える（`set -e` の下で
# `{ false; }` も `( false )` も中断する）ので、**何個重なっていても命令の位置は変わらない**。
# 1 つの `(` しか許していなかった頃は、`{ bash x; }` ・ `{ ( bash x ) }` ・ `( ( bash x ) )` が
# 実際には走ってゲートしているのに「実行されていない」と**事実と逆の診断**で
# 必須ジョブを赤くしていた（fail-closed。レビューで実測。しかもこの差分は深さの勘定に
# 重ねた開きを教えた側なので、**錨だけが追いついていない**状態だった）。
# **`{` は空白を必須にする**——`{bash x;}` は bash として成り立たない綴りなので、
# 許すと `${VAR}` のような無関係な綴りまで命令の位置と読む方向へ広がるだけ
# **開き 1 つ分の綴り。** 下の「何個でも」はこれを繰り返したもので、
# `chain_status_probe()` は 1 つずつ落とすのでこちらを読む（綴りを 2 か所に分けない）。
# **波括弧は `[{]`（括り）で書き、`\{`（逃がし）にしない。** この綴りは awk へ `-v` で渡すが、
# `-v` の値は**逃がし列として解釈される**ので、`\{` は実装ごとに扱いが違う——`gawk` は
# 「escape sequence `\{' treated as plain `{'」を**毎回 stderr へ出し**、awk の出力を
# 比較している検査（プログラムの大きさの回帰テスト）がその警告で落ちる。`mawk` は黙って
# 受けるので**手元では通り CI だけが赤くなる**（実測。CI は gawk・この開発環境は mawk）
CI_WORKFLOW_GROUP_OPENER='([(][[:space:]]*|[{][[:space:]]+)'
# **先頭に置いたリダイレクト 1 つ分の綴り**（`> out` / `2>> log` / `&> log` / `>& 2` / `>| out`）。
# 転送先までを 1 つとして数える。**`[<>]` 1 文字で書いてはいけない**（issue #177。実測）——
# `>>` の 2 文字目が転送先として読まれるので `) >> log` が「コマンドを運ぶ記録」になり、
# `carries_command()` が真を返して**ステップ最後のコマンドの照会が「後ろにコマンドがある」と
# 読む**＝正しく配線されている綴りを未配線と報告する（`) > log` は wired なのに
# `) >> log` だけが not-wired になる非対称。issue #177。**当時の消費側は issue #152 の
# 引き上げだったが、それは #199 で削除したので根拠は上の照会に移っている**）。
# **記号は 1 つずつ並べる**（`[<>][<>]?[<>]?` のような「`<` `>` の 1〜3 連」にしない）。
# あの綴りは**どこで切るかが曖昧**で、実装によって答えが変わる——`<<< x set +e` を
# mawk は `<<` ＋ 転送先 `<` と読んで前置きを落とし切れず、`set` を見失う（実測。
# **手元が mawk・CI が gawk** というこのリポジトリの組み合わせでは、こういう曖昧さが
# 「手元では通り CI だけが赤くなる」形で出る＝`CI_WORKFLOW_GROUP_OPENER` の注記と同じ理由）。
# 並べたトークンなら切れ目が 1 通りに決まる。長いものを先に書くのは、最長一致でない
# 実装（先頭から当てる実装）でも同じ答えになるようにするため。
# **区間指定（`{1,3}`）は使わない**——このファイルは 1 つも使っておらず、`-v` で渡す値の
# 逃がし列の扱いが awk 実装ごとに違う。
# **残る境界**: `>| out` は `split_commands` が `|` をパイプの区切りとして切るのでここへ届かない
# （issue #177 の境界。倒れる向きは「コマンドに数えない」側＝`main` と同じ扱い）
CI_WORKFLOW_REDIRECT_LEAD='[0-9]*(<<<|&>>|<<|>>|&>|>&|<&|>[|]|[<>])[[:space:]]*[^[:space:]]+'
CI_WORKFLOW_GROUP_OPENERS="${CI_WORKFLOW_GROUP_OPENER}*"

# **コマンドの開始位置**を表す正規表現の断片（上の前置きを読み飛ばす）。
# **`shellcheck` の網だけがこれを使う**（`test/ci_coverage_test.sh`）。あちらは
# `top` を渡さない＝制御構造の深さで絞らないので、錨が唯一の歯止めになる。
# **「`top` を渡さない照会はすべて狭い錨」とは書かないこと**——`bash -n` の網も
# `top` を渡さないが、あちらは一覧をループで回すほかに書きようが無いので
# `CI_WORKFLOW_BLOCK_BODY_START` を使う（issue #114。選び分けの正本は
# `test/ci_coverage_test.sh` の「錨は網ごとに選び分ける」）。
# issue #123 (3) で `ci_workflow_runs_script` はこちらから下の定数へ移った（理由は下記）。
# このライブラリ自身は使わなくなったので、`source` した側が読む
# shellcheck disable=SC2034
CI_WORKFLOW_COMMAND_START="^[[:space:]]*${CI_WORKFLOW_GROUP_OPENERS}${CI_WORKFLOW_COMMAND_PREFIXES}"

# **ブロック本体の先頭**も開始位置として許す版（`do` / `then` / `else` を 1 つだけ読み飛ばす）。
#
# **なぜ 2 つに分けるのか。** `split_commands` は `;` で切るので、1 行に畳んだ
# `for f in $LIST; do bash -n "$f"; done` の断片は `do bash -n "$f"` になる。
# `CI_WORKFLOW_COMMAND_START` は `^` に錨を打っていて `do` を知らないため、
# **意味の変わらない 1 行書き**が照合から外れていた（issue #114 (1)。向きは fail-closed で、
# 実際にはすべてのファイルが構文チェックされているのに「一覧に載せても構文チェックされない」と
# **事実と逆の診断**で CI を赤くする）。
#
# **`ci_workflow_runs_script` もこれを使う（issue #123 (3) で変えた）。**
# かつてここには「あちらに使ってはいけない——`do` を許すと 0 回まわるループの本体を
# 実行の証拠に数える」と書いてあったが、**止めているのは錨ではなく `top` の絞り込み**
# （`uncertain == 0` の記録だけを通す）だった。`for … do` / `until true` / 条件が読めない
# `if` はいずれも `uncertain` を立てるので、錨が継続語を許しても渡ってこない。
# 逆に `if true; then` / `while true; do` は `true_at` の側（`uncertain` を立てない）なので
# 本体は確実に走り、**狭い錨のままでは「1 行に畳んだだけで実行されていない」と
# 事実と逆の診断**になっていた（issue #123 (3)）。
# 実 `bash -e`（末尾に成功する番兵を足して「失敗が中断させるか」を測る）を真値とした
# 30 形の差分照合で、**7 形が改善し新しい誤りは 0 形**。対は `test/ci_workflow_test.sh` の
# 「1 行の… の本体は実行の証拠になる / にしない」2 群。
# **ただしこの 30 形は「飾り」の軸を 1 つも含んでいなかった**（レビューで実測）。狙って
# 当てた 15 形では 2 系統の fail-open が見つかり、**`!` で反転された開き**はこの差分で閉じた
# （下の `STRUCT_INVERTED`。複数行の綴りは `main` から開いていた既存の穴で、同時に閉じた）。
# もう 1 系統＝**複合コマンドを閉じた `fi` に付いた `&&`** は閉じていない——あれは
# 「ステップの最後のコマンドかどうかを見ない」という `main` からの判断がそのまま出たもので、
# 素の `bash <スイート> && echo ok` と**まったく同じ振る舞い**（実測: どちらも最後の
# コマンドなら GATES、後ろに 1 行あれば NOGATE）。位置を見る形へ直すのは別の差分（issue #149）。
# **「新しい誤りは 0 形」を広い集合の結論として読まないこと。**
# **`shellcheck` の網は引き続き `CI_WORKFLOW_COMMAND_START`**——あちらは `top` を
# 渡さないので、錨を広げると 1 行書きの 0 回ループが配線に化ける（issue #146 に
# 残っている穴が、より手軽な綴りで開く）。**`bash -n` の網はこちらを使う**
# （issue #114。ループで回すほかに書きようが無いため、0 回まわりうる弱さを承知で受ける）。
# **3 つの照会で許す語が違うこと自体が意図**で、1 つへ寄せてはいけない
# （選び分けの正本は `test/ci_coverage_test.sh` の「錨は網ごとに選び分ける」）。
#
# **広げる前に、死に体の本体が除かれていることが前提。** 本体の先頭を命令の位置として
# 認めると、`( if false; then shellcheck $LIST; fi )` の 1 行書きまで照合を満たしてしまう
# （issue #114 のレビューで実測。`main` でも同じコードを複数行で書くと素通りしていた既存の穴）。
# 除いているのは `flush_step()` の `dead_depth`（`strip_dead_cond_prefixes()` 経由で
# 偽と分かる条件を見る）で、**その判定を緩めるとこの定数を使う 2 つの網が同時に fail-open になる**。
# 対になる検査は `test/ci_workflow_test.sh` の
# 「コマンド単位: …の中の偽と分かる条件は満たさない」6 件。
#
# 読み飛ばすのは 1 つだけにする（`do do …` のような綴りは bash として成り立たないので、
# 繰り返しを許すと照合が緩むだけで得が無い）。`elif` は**条件**の位置であって本体ではないので
# 入れない（入れると、通らない条件の中の綴りを配線の証拠に数える方向へ広がる）。
# **この定数はライブラリ内（`ci_workflow_runs_script`）と `source` した側
# （`test/ci_coverage_test.sh` の `bash -n` の網）の両方が読む。** issue #123 (3) で
# 前者が加わったので `shellcheck disable=SC2034` は外した（参照が在るのに付けたままにすると、
# 「何も変えない門番」が 1 つ増える）。
# **グループの開きは `do` / `then` / `else` の後ろに置く。** 断片が `( do …` のように
# 開きの直後に本体の語を持つ綴りは bash として成り立たないので、手前へ置くと
# この定数では**一度も当たらない**（何も変えない門番＝読み手に「守られている」と
# 誤解させるだけ。同ファイルがそう書いている）。実際に起きる綴りは逆順の
# `for f in $LIST; do ( bash -n "$f" ); done` を 1 行に畳んだ `do ( bash -n "$f" )` で、
# 手前に置いた版ではこれが no-match になり、**全ファイルが構文チェックされているのに
# 「されていない」と事実と逆の診断**を出していた（レビューで実測）
CI_WORKFLOW_BLOCK_BODY_START="^[[:space:]]*((do|then|else)[[:space:]]+)?${CI_WORKFLOW_GROUP_OPENERS}${CI_WORKFLOW_COMMAND_PREFIXES}"

# **YAML のコメントが始まる位置**を表す正規表現の断片（行頭、または空白の直後の `#`）。
# 値の途中の `#`（`name: a#b`）はコメントではないので、ここで空白を任意にしてはいけない
# ——特権判定でそれをやると、値の中の `#` で行を切って後ろの本物の `secrets:` を捨て、
# **特権ワークフローを read-only と誤判定する**（実測。fail-open）。
# **綴りをこの 1 か所に集約する**のが要点で、以前は同じ規則が 4 か所に書き写されており、
# そのうち 1 つだけを緩めても全スイートが緑のまま通った（レビューで実測）。
# 引用の中の `#` は `emit_structural_lines` が伏せてあるので、この断片に当たるのは本物のコメントだけ。
#
# **`strip_comment()` はこの定数を使わない**（意図的な例外）。あちらは**シェルの引用規則**で
# `#` を判別する（`mask_quoted` で引用を伏せてから探す）ので、規則そのものが別物。
# 同じ綴りに揃えると、YAML 側の都合でこの断片を変えたときにシェルの解釈まで巻き添えで動く。
# **ただし `strip_comment()` の入力が常にシェルとは限らない**: 呼び出しの 1 つ
# （ステップの区切りを見る `probe`）は YAML の構造行を渡しており、そこでは
# `- name: don'"'"'t skip  # note` のアポストロフィをシェルの引用の開始と読んで
# コメントを落とさない。いまは後段の判定がどれも行頭に錨を張っているので実害は無いが、
# **「この入力は来ない」ではなく「来ても後段が耐える」**が現状の理由なので、
# 後段に行頭以外の照合を足すときはここを見直すこと
CI_WORKFLOW_COMMENT_START='(^|[[:space:]])#'

# **YAML のノードプロパティ（アンカー `&name` / タグ `!tag` `!!str`）の綴り。**
# 鍵と値のあいだに置ける飾りで、値そのものではない（`run: &suites |` の `&suites`）。
# 名前を終わらせる文字は**タグ側では**フロー形式の区切り 4 種だけで（アンカー側は実装に
# 合わせて英数字と `-` `_` に限る。下の `CI_WORKFLOW_ANCHOR_NAME`）、**`#` は含めない**
# （`#` がコメントを始めるのは空白の後ろだけなので、`&a#b` の `#` は名前の一部）。
# **ここはシェル側（値を取り出す読み手）の話で、伏せ処理の歩きは別の規則**（issue #201）。
# **綴りの源はこの 1 か所で、鍵の後ろの値を読むすべての場所が同じものを読む。**
# 選び分けの規則は 2 つだけ:
#   - **ブロックの印（`|` / `>`）の手前**を読むなら `prop_re`（＝`..._BLOCK`。名前の無い `!` も許す）
#   - **値そのものを取り出す**なら `prop_plain_re`（＝名前を要する形。理由は下の fail-open）
# **読み手の一覧はここに書き写さない**——増えるたびにこの注記だけが古くなる
# （`prop_re` / `prop_plain_re` を `grep` すれば現在の全部が出る）。写しを持つと、
# どれか 1 つだけが古くなって「構造行では本文を読み飛ばすのに抽出側は値として読む」ような
# 食い違いが生まれる（issue #126 で実際に起きた形で、レビューでも `run:` の素のスカラー・
# `env:` の折りたたみ・`shell:` / `if:` の値と 4 か所の取りこぼしが見つかっている。
# いずれも「実行しているスイートが未配線になる」fail-closed だが、配線を証明できないのは同じ）
CI_WORKFLOW_PROP_STOP_CHARS='][{},'
# **伏せ処理の歩きがアンカー名を終わらせる文字は別の定数で持つ**（issue #201 のレビュー）。
# 綴りは上と同じだが**答える問いが違う**: 上は「素のスカラーから値を取り出すときに
# タグ名へ含めない文字」で**広げると fail-open**（確かめられない綴りで「ゲートしている」と言う）、
# こちらは「伏せ処理の歩きでアンカー名を終わらせる文字」で**狭めると fail-open**
# （issue #124 の経路）。1 つの定数から両方へ供給していると、issue #218 でアンカー側を
# 広げるつもりで `,` を外した瞬間に**タグの値抽出も黙って広がる**。
# **綴りが一致しているのは偶然**なので、片方を動かすときにもう片方を一緒に動かさない
CI_WORKFLOW_ANCHOR_STOP_CHARS='][{},'
CI_WORKFLOW_ANCHOR_STOP="[${CI_WORKFLOW_ANCHOR_STOP_CHARS}]"
# プロパティの後ろに空白を要求するのは YAML の規則（`&n|` は正しくない）で、伏せ処理側の条件と同じ。
# **名前に使える文字はアンカーとタグで違う**（同じにすると必ずどちらかが壊れる。実測）。
# アンカーは **PyYAML / libyaml の実装に合わせて英数字と `-` `_` だけ**にする——
# 仕様（YAML 1.2）はもっと広いが、実装がそこまで許さない: `&shell.files` は PyYAML が
# **走査の時点でエラー**にし、`&a:b` は名前を `a` で切って値を `:b bash …` と読む。
# 広い集合で読むと後者が `bash <スイート>` に見え、**走らないスイートを「ゲートしている」と
# 言う fail-open** になる（レビューで実測）。狭めれば空白が続かず読まない側＝fail-closed へ落ちる
CI_WORKFLOW_ANCHOR_NAME='[A-Za-z0-9_-]'
# タグは逆に**狭められない**——`!!str` の名前は `!str` で `!` を含み、タグ短縮形
# （`!e!suffix`）や URI 形（`!<tag:yaml.org,2002:str>`）は `:` `/` `.` `%` を普通に使う。
# ここを英数字に狭めると `!!str` が読めなくなる（実測で 2 件の対が落ちた）ので、
# フロー形式の区切り・空白・引用符だけを終わりとする広い集合のままにする
CI_WORKFLOW_TAG_NAME="[^${CI_WORKFLOW_PROP_STOP_CHARS}[:space:]\"']"
# **逐語タグ（`!<…>`）は上の集合では読めない**（issue #182。実測）。YAML の逐語タグの中身は
# URI 文字で、**フロー形式の区切りを含んでよい**——`!<tag:yaml.org,2002:str>` の `,` がそれ。
# 上の集合は `,` で名前を切るので、このタグは読み飛ばせない。すると直後の引用符が
# 「値の始まり」と認められず、値の中の `#` が伏せられないまま構造行へ残り、消費側が
# そこで行を切って**後ろの本物の `secrets:` を捨てる**——そのワークフローが read-only と
# 判定され、**FR-9.6(b) の SHA ピン強制が丸ごと外れる**（issue #124 と同じ経路の **fail-open**）。
# **区切りを上の集合から外して直してはいけない**（この定数に限る）。外すと値を取り出す側
# （`prop_plain_re`）が `run: !x, bash <スイート>` を名前 `!x,` ＋ 値 `bash <スイート>` として読み、
# **走るか確かめられない綴りで「ゲートしている」と言い出す**（実測。`PyYAML` はまさにそう読むが、
# **GitHub の解析器は PyYAML ではない**——アンカーの集合を実装に合わせて狭めてある理由と同じで、
# 確かめられない側は読まない＝fail-closed に倒す）。
# **理由を「YAML の定義で入りえない」と書いてはいけない**（issue #201 で訂正した）——以前ここは
# 「短縮形のタグ名は `ns-tag-char` でフロー形式の区切りを含めない」と断定していたが、
# **PyYAML は `!!str,x` / `!x,y` / `!x[y` / `!x]y` を問題なく compose する**（実測。タグは
# `tag:yaml.org,2002:str,x` になり、同じ行の `secrets:` 鍵も残る）。据え置く根拠は綴りの可否ではなく
# **2 つの読み手で安全な向きが逆**であること: こちらは読みすぎると fail-open、
# 伏せ処理側は読まないと fail-open。だから**あちらはタグ名を区切りで止めない**（下の歩きの注記）。
# **なお構造行の側では外しても何も変わらない**（実測。プロパティの綴りは手を加えずそのまま
# 出力へ送るので、名前が伸びても後ろの `secrets:` は構造行に残る）——隠す向きに倒れるのは
# 逐語タグを**読み飛ばせないとき**だけで、それが下で別扱いにしている理由。
# 形の違う 2 つなので**綴りも 2 つに分ける**。閉じる `>` が同じ行に無ければ読まない（fail-closed）。
# 逐語の形を先に書くのは、最長一致でない実装でも同じ答えになるようにするため
# （`CI_WORKFLOW_REDIRECT_LEAD` と同じ理由）
CI_WORKFLOW_VERBATIM_TAG='!<[^>[:space:]"]+>'
# **名前を要する形。素のスカラーの値から落とすのはこちらだけ。**
# 名前の無い `!` をここで認めると、`run: ! bash test/x.sh` が値 `bash test/x.sh` として
# 読まれて「ゲートしている」と報告される。ところが**その綴りが実際にどう扱われるかは
# ここからは確かめられない**（GitHub のワークフロー解析器は PyYAML ではない）ので、
# ランナーが `! bash …` をそのままシェルへ渡す側だと、終了状態が反転して**ゲートしない
# ステップをゲートしていると言う fail-open** になる。読まなければ逆向き（未配線＝fail-closed）
# で、同じ綴りを `assert_not_wired` で固定してある
CI_WORKFLOW_NODE_PROPERTY="((&${CI_WORKFLOW_ANCHOR_NAME}+|${CI_WORKFLOW_VERBATIM_TAG}|!${CI_WORKFLOW_TAG_NAME}+)[[:space:]]+)*"
# **ブロックの印（`|` / `>`）の手前だけ、名前の無い `!` も許す形。**
# `run: ! |` は YAML の非特定タグで正当（PyYAML も通す）。しかも `! |` はシェルとしては
# 構文エラーなので**競合する読み方が無い**＝上の fail-open が起こらない。
# 一方 **素の `&` はどちらでも認めない**（`{name: & "b"}` は PyYAML もエラー。読むと
# 後ろの引用が開いて本物の `, secrets:` を伏せる＝隠す向き）。
# この非対称は伏せ処理側の `propend > i || ch == "!"` と**対で保つこと**（対になるのは
# **こちらの定数**で、上の名前を要する形ではない——取り違えると、片方を直したときに
# もう片方が issue #126 か上の fail-open のどちらかを開き直す）。
# **なお伏せ処理側の 1 文字ずつの歩きは名前の集合を共有しない**（終わりの文字だけを
# `prop_stop_re` で見る）。あちらの安全な向きは逆で、プロパティを読まないと引用が
# 開かず**本物の `, secrets:` を伏せてしまう**（issue #124 の経路＝SHA ピンの強制が外れる）ため、
# 狭めない。**残っている境界**: そのため `&a:b "a #b, secrets: inherit"` のような綴りでは
# 2 つの読み手の答えが分かれる（配線の判定は fail-closed、特権の判定は値を引用として
# 伏せる側＝危険側）。どちらに倒しても別の綴りで逆向きの穴が開くので、
# **問いごとに安全な向きが逆である**ことを承知で分けてある（issue #126 のレビューで実測）
CI_WORKFLOW_NODE_PROPERTY_BLOCK="((&${CI_WORKFLOW_ANCHOR_NAME}+|${CI_WORKFLOW_VERBATIM_TAG}|!${CI_WORKFLOW_TAG_NAME}*)[[:space:]]+)*"

# 抽出した「実行されるコマンド」を保持するファイル。1 行が
# `<ジョブ名>#<ステップ番号><TAB><ゲートに効くか(1/0)><TAB><コマンドの断片>`
CI_WORKFLOW_COMMANDS=""

# 文字列を拡張正規表現のリテラルとして扱えるようにエスケープする
# （パス中の `.` が任意の 1 文字として働くと、別名のファイルに当たってしまう）
ci_workflow_regex_escape() {
    # 英数字・`_`・`-`・`/` 以外の文字の前にバックスラッシュを置く
    printf '%s' "$1" | sed 's|[^[:alnum:]_/-]|\\&|g'
}

# ワークフローから「YAML の構造として意味を持つ行」だけを `行番号:行の内容` の形で書き出す関数
# 第 1 引数: ワークフローファイルのパス
#
# 何を落とすか: ブロックスカラー（`run: |` / `prompt: >-` 等）の本文。あれは YAML の構造ではなく
# ただの文字列なので、そこに書かれた `permissions:` や `uses:` を宣言と読み違えてはいけない。
# スカラーを開始する行そのもの（`run: |`）は構造なので残す。
#
# なぜ 1 か所に集約するか: 特権判定と `uses:` 抽出の**両方**がこの前提を必要とするのに、
# 片方だけに読み飛ばしを入れると非対称な誤りが出る。実際、判定側だけに入れた段階では
# `run:` の本文に書かれた `- uses: …@v7` が違反として誤報され、正しくピンされている
# `post-ci-verify.yml`（`prompt:` に長いブロックスカラーを持つ）で CI が恒常的に赤くなりえた。
# 出力形式を `grep -n` と同じ `行番号:内容` に揃えてあるので、消費側は行番号を保ったまま使える
emit_structural_lines() {
    # 検査対象のファイルパスを変数に入れる
    local path="$1"

    # 引用符の 2 種類は awk の変数として 1 文字ずつ渡す（awk のプログラムはシェルの単一引用符で
    # 囲まれており、その中に `'` を直接書けないため）。
    # `flow_re` は**構造としてしか意味を持たない文字**の集合（フロー形式の区切りと、コメントを始める `#`）、
    # `flow_mask` はそれを伏せる代役の文字
    # `anchor_stop_re` は**アンカー名（`&name`）を終わらせる文字**の集合。
    # フロー形式の区切り 4 種（`,` `[` `]` `{` `}`）は PyYAML / libyaml がアンカー名に許さないので
    # （`&a,b` / `&a}b` はどちらも parse エラー＝実測）、**フロー形式の中にいるかどうかに
    # 関わらず**名前の終わりとして扱う。**タグ名には使わない**——短縮形のタグ名はこれらを
    # 含められるので、切ると issue #201 の fail-open になる（理由は使う側の注記が持つ）。
    # **シェル側の `CI_WORKFLOW_PROP_STOP_CHARS` とは別の定数から来る**（綴りは同じだが
    # 問いが違い、安全な向きも逆。定数の注記が理由を持つ）。
    # `flow_re` とは別に持つのは意図的で、**`#` を含めない**のが違い（`#` がコメントを始めるのは
    # 空白の後ろだけなので、`&a#b` の `#` は名前の一部。ここで切ると名前を読み違える）。
    # 引用符 2 種も名前を終わらせる（`dq` / `sq` は awk 変数なので、この集合とは別に判定する）
    awk -v dq='"' -v sq="'" -v flow_re='[][{},#]' -v flow_mask='~' \
        -v comment_re="${CI_WORKFLOW_COMMENT_START}" \
        -v anchor_stop_re="${CI_WORKFLOW_ANCHOR_STOP}" \
        -v prop_re="${CI_WORKFLOW_NODE_PROPERTY_BLOCK}" \
        -v tight_openers='{[,' '
        # 引用スカラーの中で、位置 i の 1 文字から始まるのが「終端ではない脱出表記」かどうかを返す。
        # 二重引用では `\` が次の 1 文字を脱出させ、単一引用では `'"'"''"'"'` が文字としてのアポストロフィ。
        #
        # **終端の見立てを 1 か所に集約する**のが要点。同じ規則を必要とする所が 2 つあり
        # （引用の中身を伏せる `mask_quoted_flow_punctuation` と、続きの行で閉じるかを見る
        # `open_type_after_continuation`）、以前は同じ 2 行が両方に書き写されていた。片方だけを緩めると
        # **向きの違う壊れ方**が同時には見えない: 伏せる側が早く閉じると `- name: '"'"'don'"'"''"'"'t x, uses: p'"'"'`
        # の `p` が幻の参照として報告され（issue #93 の 2 件目そのもの）、閉じ判定側が早く閉じると
        # 続きの行の途中で「もう引用の外」と誤り、次の行から伏せる処理が復活して**本物の区切りごと
        # 伏せ、可変タグを見逃す**（**fail-open**）。綴りを共有していれば、どちらの向きの回帰も
        # 同じ 1 行の変更として現れる。
        # `ch` は呼び出し側で取り出し済みの 1 文字を受け取る（同じ `substr` を二度引かないため）
        function is_escape_at(src, i, ch, qt) {
            # 二重引用の中の `\` は、次に何が来ても脱出表記の始まり
            if (qt == dq && ch == "\\") return 1
            # 単一引用の中の `'"'"''"'"'`（2 つ続く）は、閉じではなく文字としてのアポストロフィ
            if (qt == sq && ch == sq && substr(src, i + 1, 1) == sq) return 1
            # どちらでもなければ脱出表記ではない（＝同じ種類の引用符ならそこで閉じる）
            return 0
        }
        # いま見ている 1 文字が「値が始まりうる位置」に置かれているかを返す。
        #
        # **引用スカラーの開始判定と、フロー形式（`{` / `[`）に入るかの判定の両方がこれを使う。**
        # 同じ規則を 2 か所へ書き写すと、片方だけを緩めたときにもう片方が黙って追随せず、
        # 「フローに入ったと数えているのに引用の開始は認めない（またはその逆）」という
        # 食い違いが生まれる。判定は 1 か所に置く。
        #
        # 引数はすべて呼び出し側の状態を写したもの（awk の関数はローカルを覗けないため）:
        # `prev` = 引用の外で最後に見た空白以外の文字、`gap` = その後ろに空白があったか、
        # `keyq` = いまの `:` が引用された鍵の直後か、`dashind` = 直前の `-` が行頭の印の位置か、
        # `depth` = いまフロー形式（`{` `[`）の中にいる深さ
        function at_value_start(prev, gap, keyq, dashind, depth) {
            # 行頭（まだ何も見ていない）は、素のスカラーの継続行かどうかを決められないので
            # 開始と認めない（決められないなら伏せない＝ fail-closed）。
            # **この 1 行は現状どのテストにも守られていない**（`if (0) return 0` へ変えても
            # 全 7 スイートが緑。issue #119 の補足 2 で実測）。ただし**消してよい行ではない**:
            # awk の `index(s, "")` は **1 を返す**ので、下の 1 つ目の条件は `prev` が空でも
            # `depth > 0` なら真になり、**行頭の引用符を値の開始と読んで中身を伏せ始める**
            # （伏せる＝隠す向き＝fail-open）。いま到達しないのは `flowdepth` が
            # `mask_quoted_flow_punctuation()` の局所変数で**行ごとに 0 から数え直す**ため、
            # `depth > 0` が成り立つ行では必ず `{` か `[` を見ており `prev != ""` になるから。
            # つまりこれは「フロー形式の深さを行をまたいで持ち越す」改修を入れた瞬間に
            # 効き始める backstop で、**到達しないことは不変条件ではなく今の実装の副産物**。
            # （以前ここと `docs/requirements.md` は「この条件を消しても fail-open が残る」
            #   「`-` の `gap` を除くすべての変異がこのスイート単体で赤くなる」と書いていたが、
            #   どちらも実測で誤り。issue #119 で記述をそろえた）
            if (prev == "") return 0
            # フロー形式の区切り（`{` `[` `,`）の直後。**フロー形式の中にいるときだけ**。
            # ブロック形式ではこの 3 文字はただの平文で、YAML の素のスカラーに普通に現れる
            # （`- name: Build image, '"'"'tis the slow step` は PyYAML が 1 つの平文として読む）。
            # 深さを見ずに開始と認めると、閉じない引用が「複数行スカラーの始まり」として
            # 次の行以降へ引き継がれ、以降の行がすべて「続き」扱いになる。すると
            # `run: |` がブロックスカラーとして認識されなくなり、**本文に書かれた検証コマンドが
            # 抽出から丸ごと消える**（実測: `bash test/guard_test.sh` が「配線されていない」と
            # 判定され、type-check ジョブの網羅性テストが落ちる）。同じ入力で `run:` の本文が
            # 構造として漏れ、そこにある `uses: …@v1` が幻の参照としても報告される
            if (depth > 0 && index(tight_openers, prev) > 0) return 1
            # 鍵に続く `:`。素の鍵は空白を挟んでいることを要求し（`{name:"a` は
            # `name:"a` までで 1 つの鍵になり、引用スカラーは始まっていない）、
            # 引用された鍵（JSON 形式の `{"name":"a"}`）なら空白は要らない
            if (prev == ":" && (gap || keyq)) return 1
            # 並びの `-`。行頭の印の位置にあり、かつ空白を挟んでいるときだけ
            # （語中の `pre-'"'"'release` を弾いているのはこの位置判定）
            if (prev == "-" && gap && dashind) return 1
            # どれにも当たらなければ、値が始まりうる位置ではない
            return 0
        }
        # 引用符に囲まれたスカラー（値）の中にあるフロー形式の区切り文字を、代役の文字へ置き換える。
        #
        # なぜ要るか（issue #93 の 2 件目）: この関数はもともと引用符を無条件に落としていたため、
        # `- name: "compare pinning, uses: policy"` が `- name: compare pinning, uses: policy` に
        # なり、**ただの手順名が「カンマの直後の `uses:`」というフロー形式の宣言に化けていた**。
        # 消費側は位置規則でしか構造を見分けられないので、参照 `policy` を報告して
        # **正しく SHA ピンされたリポジトリの必須チェックを恒常的に赤くしていた**（実測）。
        #
        # **`#` も同じ理由で伏せる。** YAML でコメントを始めるのは引用の外の `#` だけだが、
        # 引用符を落とした後の行を見る消費側にはその区別が付かない。実際、特権判定は
        # `{name: "a: #b", secrets: inherit, …}` の**値の中の** `#` で行を切ってしまい、
        # 後ろの本物の `secrets:` を捨てて read-only と誤判定していた（＝そのワークフロー内の
        # 可変タグが検査から全部外れる **fail-open**。実測で再現）。コメントの位置も
        # **引用の在りかを知っているこの層で決める**のが筋で、消費側が引用の消えた行から
        # 推測し直す形は、規則が 3 通りに分かれて弱い写しが残る原因になっていた。
        #
        # なぜ「区切り文字だけ」を伏せるのか: 引用の中身ごと伏せると
        # `uses: "actions/checkout@v7"` の参照まで読めなくなり、可変タグが検査を素通りする
        # （＝このファイルが繰り返し塞いできた fail-open へ逆戻りする）。伏せるのは
        # **構造としてしか意味を持たない文字**に限り、参照の綴りには一切触れない。
        #
        # なぜ 1 文字を 1 文字へ置き換えるのか: **構造行を元の行と桁で突き合わせられる状態に保つため**。
        # 桁の計算そのものは伏せたあとの行だけを見ているので、長さが変わっても通る経路が多い。
        # ただし**伏せた結果が診断へそのまま出る**経路があり（引用された値が区切り文字を含む形。
        # 下の「値の綴りが変わる場合」を参照）、そこは綴りが変わるため
        # `action_pin_test.sh` の該当ケースが 1 対 1 を実際に固定している。
        # 加えて、元の行と桁がずれる変換を入れると将来「生の行の桁と突き合わせる消費側」が
        # 黙って壊れるため、安い保険として 1 対 1 を守る。
        #
        # **伏せると値の綴りが変わる場合がある。** 引用された値そのものが区切り文字を含むとき
        # （`uses: "${{ inputs.action_ref }}"` など）は、その値も `$~~` のように変わる。
        # 検査は通らない側へ倒れる（＝ピン済みとは扱われない）ので安全側だが、診断に出る綴りが
        # ファイル中の文字列と一致しなくなる点は承知のうえ。
        #
        # **どこで始まり、どこで終わるかは YAML の規則どおりに見る。** ここを緩めるとどちらの向きにも
        # 壊れることが、この関数を作る過程で実測できた:
        #   - 開始を緩めた場合（引用符なら何でも開始と読む）… 素のスカラー途中のアポストロフィ
        #     （`don'"'"'t`）が開始になり、次のアポストロフィ（`it'"'"'s`）までが「引用の中」になる。
        #     その範囲に**本物の**区切りが挟まっていると、それごと伏せて `uses:` を見逃す
        #     （実測: `- {name: pre-'"'"'release, uses: actions/evil@v1, note: it'"'"'s ok}` で
        #     可変タグが検査から丸ごと消えた。**fail-open**）。
        #   - 終了を緩めた場合（最初の同種の引用符で必ず閉じる）… YAML の脱出表記
        #     （単一引用の `'"'"''"'"'`／二重引用の `\"`）で早く閉じてしまい、残りが引用の外として
        #     出てくる。実測: `- name: '"'"'don'"'"''"'"'t compare pinning, uses: policy'"'"'` で
        #     issue #93 の 2 件目（幻の参照 `policy`）がそのまま再現した。
        # そこで開始は**値が始まりうる位置**に限り、終了は**脱出表記を解いてから**判定する。
        # 判断が付かない引用（位置が合わない・行内で閉じない）は伏せずに従来の姿へ倒す
        # ＝「余分に赤くなる」側であって、見逃しは生まない（fail-closed）。
        #
        # 引用符そのものは今までどおり落とす（`"permissions":` と `permissions:` を同じ形に
        # 揃える FR-8.1 の前提。脱出表記や入れ子で現れた引用符も同じく落とす）。
        function mask_quoted_flow_punctuation(src,   out, raw, masked, quote, prev, gap, closed, keyq, seqzone, dashind, in_comment, flowdepth, i, ch, nxt, len, propend, vtend, vtprobe, propraw, is_anchor) {
            # **引用符を 1 つも含まない行は、そのまま返す。** その場合この関数がやることは
            # 「1 文字ずつ読んで同じ文字を書き戻す」だけで、結果は入力と必ず一致する。
            # ワークフローの行の大半（`runs-on: ubuntu-latest` など）がこれに当たり、
            # 素通しすると `emit_structural_lines` の実行時間が実測で約 1/3.6 になる
            if (index(src, dq) == 0 && index(src, sq) == 0) { MASK_OPEN_TYPE = ""; return src }
            # 確定した出力・引用の中身の写し・開いている引用符の種類を初期化する
            out = ""; raw = ""; quote = ""
            # 引用の外で最後に見た空白以外の文字と、その後ろに空白があったか（開始位置の判定に使う）
            prev = ""; gap = 0
            # 直前の非空白が引用スカラーの終わりだったか／いまの `:` がその直後の `:` だったか
            closed = 0; keyq = 0
            # 引用の外で本物のコメント（`#`）に入ったか。**行末まで閉じない引用を次の行へ引き継ぐか**の
            # 判断だけに使い、伏せる判断そのものには影響させない（出力は従来どおり）
            in_comment = 0
            # 行頭からまだ字下げと `-` しか見ていないか（`-` が本物の並びの印かを見分けるのに使う）
            # と、直前の `-` がその位置にあったか
            seqzone = 1; dashind = 0
            # いまフロー形式（`{` `[`）の中にいる深さ。0 ならブロック形式で、`{` `[` `,` は
            # 構造ではなくただの平文（`at_value_start` の判定に使う）
            flowdepth = 0
            # 1 文字ずつ見るので、行の長さを先に求めておく
            len = length(src)
            # 行の左端から 1 文字ずつ走査する
            for (i = 1; i <= len; i++) {
                # いま見ている 1 文字を取り出す
                ch = substr(src, i, 1)
                # まだ引用の外にいる場合
                if (quote == "") {
                    # 引用符かどうかを先に見る
                    if (ch == dq || ch == sq) {
                        # 値が始まりうる位置に置かれているときだけ、スカラーの開始として扱う。
                        # フローの区切り（`{` `[` `,`）の直後なら空白の有無を問わない。
                        # 素の鍵に続く `:` は**空白を挟んでいることを要求する**（`{name:"a` は
                        # `name:"a` までで 1 つの鍵になり、引用スカラーは始まっていない）。
                        # 並びの `-` は**位置**で見る（下の `dashind`）: 語中の `pre-'"'"'release` を
                        # 弾いているのはこの位置判定であって、空白の有無ではない。
                        # `-` 側の `gap` は「`- ` が並びの印になるには空白が要る」という YAML の
                        # 規則をそのまま書いたもので、**これを外しても現行のテストは全部緑になる**
                        # （外して困る入力＝`-'"'"'a, uses: x'"'"'` の類は、YAML では行全体が 1 つの
                        # 素のスカラーになり本物の `uses:` を含みえないため）。規則どおりに書いた
                        # 保守側の守りとして残している、という位置づけ。
                        # ただし**引用された鍵に続く `:` は空白を要らない**（JSON 形式の
                        # `{"name":"a, uses: policy"}` は正しい YAML で、PyYAML も
                        # `{'"'"'name'"'"': '"'"'a, uses: policy'"'"'}` と読む）。素の鍵の `{name:"a` とは
                        # 区別が付く: あちらは `name:"a` までが 1 つの鍵になるので開始と認めない。
                        #
                        # **行頭の引用符は開始と認めない。** 素のスカラーは複数行に続けられ、
                        # その**継続行は引用符から始まってよい**（YAML が禁じるのはスカラーの
                        # 先頭文字だけ）。この関数は 1 行ずつしか見ないので、行頭の引用符が
                        # 新しいスカラーの開始なのか継続行の中の 1 文字なのかを決められない。
                        # 決められないまま開始と読むと、そこから次の引用符までの**本物の区切り**を
                        # 伏せて `uses:` や `secrets:` を見逃す（実測: `steps: [{name: a` の次行を
                        # `'"'"'b, uses: actions/evil@v1'"'"', z: 1}, …]` とすると可変タグが検査から消えた）。
                        # 決められないなら伏せない＝従来の姿へ倒す（fail-closed）
                        # **`prev != ""` を先に確かめる。** `index()` に空の探し文字列を渡すと
                        # 実装によって答えが割れ、mawk 1.3.4 は `index("{[,", "")` に **1** を返す。
                        # つまりこの守りが無いと、行頭（まだ何も見ていない状態）が
                        # 「フローの区切りの直後」と判定され、上に書いた fail-open が
                        # **条件を消しても消えないまま**残る（実測でここに気付いた）
                        if (at_value_start(prev, gap, keyq, dashind, flowdepth)) {
                            quote = ch; raw = ""; continue
                        }
                        # 位置が合わない引用符は、従来どおり落とすだけ（伏せない＝今日と同じ挙動）。
                        # ただし**位置に関する記憶はここで全部落とす**: 行頭の印の並び（`seqzone`）も、
                        # 「直前が引用の終わりだった」（`closed`）も、空白の有無（`gap`）も、
                        # 落とした引用符をまたいで持ち越してよい根拠が無い。持ち越すと
                        # `{"a"" :"b, secrets: inherit", …}` のような壊れた形で「引用された鍵の
                        # 直後の `:`」と誤認し、本物の `, secrets:` を伏せて read-only へ倒す
                        # （＝ワークフロー内の可変タグが検査から全部外れる **fail-open**。実測）
                        seqzone = 0; closed = 0; gap = 0
                        continue
                    }
                    # **YAML のノードプロパティ（アンカー `&name` / タグ `!tag` `!!str`）を読み飛ばす。**
                    # これらは鍵と値の**間**に置ける飾りで、値そのものではない。読み飛ばさないと
                    # 直後の引用符の「直前の文字」がプロパティの末尾（`&n` なら `n`）になり、
                    # 開始位置の規則（`:` / `-` / フローの区切りの直後）にどれも当たらず開始と
                    # 認められない。すると値の中の `#` が伏せられないまま構造行に残り、消費側が
                    # そこで行を切って**後ろの本物の `secrets:` を捨てる**。結果その
                    # ワークフローが read-only と判定され、**FR-9.6(b) の SHA ピン強制が丸ごと
                    # 外れる**（issue #124。`&n ` の 3 文字を足すだけで可変タグが素通りする **fail-open**）
                    if ((ch == "&" || ch == "!") && at_value_start(prev, gap, keyq, dashind, flowdepth)) {
                        # **種別は肯定形で 1 回だけ決める。** 以前は `ch != "!"`（＝アンカー）を
                        # 2 か所に書き写していたが、門番へ 3 つ目の印を足したときに
                        # その印が**両方で黙ってタグ扱い**（＝名前を区切りで切らない緩い側）になる。
                        # 肯定形にしておけば、知らない印は自動的にアンカー側＝切る側へ落ちる（fail-closed）
                        is_anchor = (ch == "&")
                        # プロパティの名前の終わりを探す。**終わらせる文字は種別で違う**
                        # （下の歩きの注記が正本。アンカーはフロー形式の区切りでも終わり、
                        # タグは空白・二重引用符・「開きの直後の単引用符」だけで終わる）。
                        # **逐語タグ（`!<…>`）だけは別の形**（issue #182。実測）——中身は URI 文字で
                        # **フロー形式の区切りを含んでよい**ので、`!<tag:yaml.org,2002:str>` は
                        # 上の 3 種では `,` で切れてしまい、プロパティとして読み飛ばせない。
                        # 読み飛ばせないと直後の引用符が「値の始まり」と認められず、値の中の `#` が
                        # 伏せられないまま構造行へ残り、消費側がそこで行を切って
                        # **後ろの本物の `secrets:` を捨てる**（issue #124 と同じ経路の fail-open。
                        # 実測で `{name: !<tag:x,2002:str> "a #b", secrets: inherit}` が read-only と
                        # 判定された）。**シェル側の `CI_WORKFLOW_TAG_NAME` は広げない**
                        # （広げると値を取り出す側が確かめられない綴りを「ゲートしている」と読む。実測）
                        # ——**こちらの歩きはタグ名を区切りで止めない**ので、短縮形のタグ名に
                        # `,` `[` `]` を含む綴りは下で読み飛ばせる（issue #201。安全な向きが逆）。
                        # 形が違うので判定も分ける。閉じる `>` が同じ行に無ければ読まない（fail-closed。
                        # `!<` を閉じない綴りは YAML として成り立たないので、読んで得るものが無い）
                        propend = i
                        if (ch == "!" && substr(src, i + 1, 1) == "<") {
                            # **閉じる `>` は「途切れずに届く」ときだけ認める**（レビュー指摘、実測）。
                            # `index()` で行のどこかの `>` を拾うと、`!<a >` のような**閉じていない**
                            # 綴りが後ろの `>` で閉じたものとして読まれ、続く引用符を開いて
                            # **本物の `, secrets:` を伏せる**（＝この差分が入れた fail-open。
                            # 実測で `main` は privileged・この綴りを拾う版は plain）。
                            # 途切れとして数えるのは空白と二重引用符の 2 つ——逐語タグの中身は
                            # YAML の `ns-uri-char` で、どちらも含めない。**単引用符は止めない**
                            # （中身に含めてよい綴りなので、止めるとそれを含むタグでプロパティを
                            # 読めず、まさに issue #182 の fail-open へ戻る＝実測）
                            vtend = 0
                            vtprobe = i + 2
                            while (vtprobe <= len) {
                                nxt = substr(src, vtprobe, 1)
                                if (nxt ~ /[[:space:]]/ || nxt == dq) break
                                if (nxt == ">") { vtend = vtprobe; break }
                                vtprobe++
                            }
                            # 中身が 1 文字以上あるときだけ逐語タグとして読む（`!<>` は認めない。
                            # シェル側の綴りが `+` を求めているのと対で保つ）
                            if (vtend > i + 2) { propend = vtend }
                        }
                        # **逐語タグとして読めなかったとき、および読めても後ろに空白が
                        # 続かないときは短縮形の歩きへ落とす**（レビュー指摘、実測）。
                        # 落とさないと `!<a>b>` のように**最初の `>` で閉じて続きがある**綴りで
                        # プロパティを読まないまま値の引用が開かず、`main` が伏せていた `#` を
                        # 伏せ損なって特権判定が privileged → plain へ動く（この差分が入れた退行）。
                        # 落とせば逐語として読めない綴りはすべて `main` と同じ答えに戻り、
                        # 動くのは**逐語として正しく読める綴りだけ**になる
                        if (propend == i || substr(src, propend + 1, 1) !~ /^[[:space:]]$/) {
                            propend = i
                            # **止まる文字はプロパティの種類で違う**（issue #201）。
                            # **タグ名はフロー形式の区切りでは止めない。** 短縮形のタグ名は
                            # `,` `[` `]` を含められる（PyYAML で 1 文字ずつ実測。`!!str,x` は
                            # `tag:yaml.org,2002:str,x` として compose でき、同じ行の `secrets:` 鍵も残る）のに
                            # 以前は区切りで切っていたため `!!str,x "a #b"` がプロパティとして読めず、
                            # 値の `#` が伏せられないまま構造行へ残って消費側が行を切り、
                            # **後ろの本物の `secrets: inherit` を捨てていた**（read-only と誤分類＝
                            # FR-9.6(b) の SHA ピン強制がワークフロー全体で外れる fail-open）。
                            # **`{` `}` も止めない。** PyYAML はこの 2 文字をタグ名に許さないが、
                            # 「名前を短く切る」のがこの歩きでの fail-open 側なので、**YAML として
                            # 成り立たない綴りも読み飛ばす側へ倒す**（実測: 止めると `!x{y "a #b"`
                            # ほか 6 形が read-only＝ピン強制の外れる側へ落ちた。止めなければ
                            # privileged＝FR-8.1 が `permissions:` の判定について要求している
                            # 「解釈できない書き方に出会った場合も特権に倒す」と同じ向き）。
                            # アンカー名は従来の集合のまま（`&a,b` / `&a}b` は PyYAML が拒む）
                            # ——**この非対称は意図したもの**で、広げてよいかは別に測ってある
                            # （実測では真値のある 106 形で退行 0 だが、#124 / #126 で値を取り出す側と
                            # 対で入れた判断に触るので **issue #218** で別の変更セットとして扱う）
                            while (propend < len) {
                                nxt = substr(src, propend + 1, 1)
                                if (nxt ~ /[[:space:]]/) break
                                if (is_anchor && nxt ~ anchor_stop_re) break
                                # **二重引用符は両方で止まる**（PyYAML はタグ名にもアンカー名にも
                                # 受け付けない＝実測）。**単引用符はタグだけ止まらない**
                                # ——名前に単引用符を含む短縮形（`!x` ＋ 単引用符 ＋ `y`）は
                                # PyYAML が compose でき、止めると同じ fail-open が綴り 1 文字で
                                # 残る（220 形の総当たりで区切り系を直した後もこの 2 形だけ
                                # 残っていた＝実測）。出力に混ざる引用符は下の `gsub` が落とすので、
                                # 「構造行に引用符を 1 つも残さない」不変条件は保たれる。
                                # **このコメントに単引用符そのものを書かないこと**——awk の
                                # プログラムはシェルの単引用符で囲まれており、1 文字で引用が
                                # 閉じてライブラリ全体が構文エラーになる（実測で `bash -n` が落ちた）
                                if (nxt == dq) break
                                # **フロー形式の開き（`{` `[` `,`）の直後の単引用符は飲み込まない。**
                                # そこから始まる引用スカラーを名前へ取り込むと、その中の `#` を
                                # 伏せられないまま構造行へ残し、消費側が行を切って**後ろの本物の
                                # `secrets:` を落とす**（この差分のレビューで実測。`{name: !t[` ＋
                                # 単引用符の値は `main` が privileged・飲み込む版が plain。
                                # 区切りを名前に許したぶん、こちらの手当てが要る）。
                                # 名前の途中（直前が普通の文字）の単引用符はタグなら飲み込む
                                # ——PyYAML が受け付ける綴りで、止めると issue #124 の
                                # fail-open が綴り 1 文字で残る（実測）
                                if (nxt == sq && (is_anchor || index(tight_openers, substr(src, propend, 1)) > 0)) break
                                propend++
                            }
                        }
                        # プロパティとして読む条件は 2 つ。
                        # (1) **名前が 1 文字以上あること。** 素の `&` だけ（`{name: & "b, secrets: x"}`）は
                        #     YAML が受け付けない綴りなので、プロパティとして読まない。読んでしまうと
                        #     後ろの引用が開いて**本物の `, secrets:` を伏せてしまう**（隠す向き＝危険側）。
                        # (2) **プロパティと値の間に空白があること**（YAML の規則。`&n"a"` は正しくない）。
                        #     空白が続かない形＝値が続かない形（`{name: &n}` の類）。
                        # どちらも満たさない綴りは**プロパティとして読まず従来の姿へ倒す**（fail-closed）。
                        # これにより、名前に引用符を含む `&a"b`（PyYAML も受け付けない）が
                        # そのまま構造行へ出て「構造行に引用符を 1 つも残さない」不変条件を
                        # 破ることも防いでいる（引用符は従来どおり落とす経路へ落ちる）
                        # **`!` だけは名前なしでも読む**（YAML の非特定タグ `run: ! |` は正当。
                        # 読まないと「鍵と指示子のあいだのプロパティ」の手当て（issue #126）が
                        # この綴りだけ外れる）。`&` の側は上の (1) のとおり 1 文字以上を要求する
                        # ——この非対称はシェル定数 `CI_WORKFLOW_NODE_PROPERTY_BLOCK`（名前の無い `!` も
                        # 許す形）と**対で保つこと**。`CI_WORKFLOW_NODE_PROPERTY`（名前を要する形）の
                        # 方へ揃えると、どちらを動かしても issue #126 か素のスカラーの fail-open が開く
                        if ((propend > i || ch == "!") && substr(src, propend + 1, 1) ~ /^[[:space:]]$/) {
                            # プロパティの綴りは構造でも値でもないのでそのまま出力へ送る。
                            # **ただし引用符だけは落とす**（レビュー指摘、実測）——逐語タグの中身は
                            # 単引用符を含んでよく（それを含む綴りも YAML として読める）、そのまま出すと
                            # 「構造行に引用符を 1 つも残さない」不変条件が破れる。消費側はその前提で
                            # 正規化しているので、破ると特権判定が fail-open へ倒れうる。
                            # **短縮形のタグも単引用符を名前に含めて来る**（issue #201。PyYAML が
                            # その綴りを受け付けるので歩きを止めていない）ので、ここへ来るのは
                            # 逐語タグだけではない。**落とす側に倒すのは綴りに依存しない**
                            # （二重引用符はどちらの歩きでも中身から外してある）
                            propraw = substr(src, i, propend - i + 1)
                            gsub(/["\047]/, "", propraw)
                            out = out propraw
                            # 行頭の「字下げと `-` だけ」の並びはここで終わり（プロパティはそのどちらでもない）
                            seqzone = 0
                            # **`prev` / `keyq` / `dashind` は書き換えない。** プロパティは値ではないので、
                            # 直後に来る引用符や `{` は「プロパティが無かった場合と同じ位置」に
                            # 置かれているものとして判定する（これがこの読み飛ばしの目的）
                            # 直後には必ず空白があるので、開始位置の判定のために立てておく
                            gap = 1
                            # 読み終えた位置まで進める（`for` の `i++` で次は上記の空白から再開する）
                            i = propend
                            continue
                        }
                    }
                    # 引用の外の文字は構造かもしれないので、一切手を加えず出力へ送る
                    out = out ch
                    # 空白は位置判定に影響させない。**「直前が引用の終わりだったか」の記憶も
                    # ここでは消さない**のが要点で、効いてくるのは `{"a" :"b"}` のように
                    # **コロンの前にだけ空白がある**書き方（`{"a" : "b"}` の方は後ろの空白で
                    # `gap` が立つので、記憶が無くても開始と認められる）。ここで消すと
                    # issue #93 の 2 件目（幻の参照）がその書き方でだけ戻る
                    if (ch ~ /[[:space:]]/) { gap = 1; continue }
                    # 引用の外で行頭か空白の直後に来た `#` は、そこから行末までがコメント。
                    # **コメントの中で開いた引用は、次の行へ続く引用スカラーではない**ので、
                    # ここを控えておいて末尾の引き継ぎ判断から外す（理由は関数末尾のコメント）
                    if (ch == "#" && (prev == "" || gap)) in_comment = 1
                    # フロー形式に入るのは、**値が始まりうる位置に置かれた** `{` / `[` だけ。
                    # スカラーの途中に現れる `{`（`- name: Compare {a, "b} against c` は
                    # PyYAML が 1 つの平文として読む）はただの文字なので数えない
                    if ((ch == "{" || ch == "[") && at_value_start(prev, gap, keyq, dashind, flowdepth)) flowdepth++
                    # 対応する閉じ括弧は、フロー形式の中にいるときだけ数え戻す
                    # （ブロック形式の平文に現れた `}` で深さを負にしないため）
                    else if ((ch == "}" || ch == "]") && flowdepth > 0) flowdepth--
                    # `:` を見たら「引用された鍵の直後の `:` か」を控える（上の開始判定で使う）
                    if (ch == ":") keyq = closed
                    # `-` を見たら「行頭から字下げと `-` しか見ていない位置か」を控える。
                    # YAML で `- ` が並びの印になるのはこの位置だけで、スカラーの途中の
                    # `Lint - '"'"'tis time` の `-` はただの文字。ここを見ないと、その `-` の後ろの
                    # 引用符が開始と認められ、**本物の区切りごと伏せて `uses:` を見逃す**（実測）
                    if (ch == "-") dashind = seqzone
                    # 字下げと `-` 以外の文字が出た時点で、行頭の印の並びは終わり
                    if (ch != "-") seqzone = 0
                    # 直前の文字として覚え、空白と引用終わりの記憶はここで消す
                    prev = ch; gap = 0; closed = 0
                    continue
                }
                # 脱出表記はスカラーの終端ではないので読み飛ばす。
                # **どれが脱出表記かの判断は `is_escape_at` が唯一の持ち主**（続きの行の判定と共有）で、
                # ここが持つのは「読み飛ばすときに写しへ何を残すか」だけ
                if (is_escape_at(src, i, ch, quote)) {
                    # 単一引用の `'"'"''"'"'`。従来の一律削除に合わせて、写しに足さずに 2 文字ぶん読み飛ばす
                    if (quote == sq) { i++; continue }
                    # 以下は二重引用の `\X`。脱出される側の 1 文字を先に覗く
                    nxt = substr(src, i + 1, 1)
                    # バックスラッシュ自体は従来どおり素の文字として残す
                    raw = raw ch
                    # 脱出された文字が引用符なら従来の一律削除に合わせて落とし、それ以外は控える
                    if (nxt != "" && nxt != dq && nxt != sq) raw = raw nxt
                    # 脱出された 1 文字はいま処理したので、次の文字まで読み進める
                    i++
                    continue
                }
                # 同じ種類の引用符が来たらスカラーの終わり（脱出表記は上で処理済み）
                if (ch == quote) {
                    # 中身の写しから、フロー形式の区切り文字だけを代役へ一括で置き換える
                    masked = raw
                    gsub(flow_re, flow_mask, masked)
                    # 伏せた写しを出力へ確定させ、引用の外へ戻る
                    out = out masked
                    # 閉じた直後に続く引用符を「開始」と誤読しないよう、開始位置になりえない文字を
                    # 直前の文字として置く（`"` は開始位置の文字集合のどれにも含まれない）。
                    # 併せて「直前は引用の終わりだった」ことを控える（JSON 形式の鍵の判定に使う）
                    prev = dq; gap = 0; closed = 1
                    # 引用スカラーが 1 つ出た時点で、行頭の「字下げと `-` だけ」の並びは終わり。
                    # ここを降ろさないと、後ろの `-` を並びの印と誤読して次の引用符を開始と認め、
                    # 本物の区切りごと伏せてしまう（`"a" - '"'"'b, uses: …'"'"'` で実測）
                    seqzone = 0
                    # 引用の状態を片付けて次の文字へ進む
                    quote = ""; raw = ""
                    continue
                }
                # 入れ子の別種の引用符は、従来の一律削除と同じく落とす（写しにも入れない）
                if (ch == dq || ch == sq) continue
                # それ以外は中身としてそのまま控える（伏せるのは閉じるときにまとめて行う）
                raw = raw ch
            }
            # 行末まで来ても引用が閉じていなければ、伏せずに元の姿で出力する。
            # 複数行にまたがる引用スカラーなど、この行だけでは対応が取れない場合に
            # 伏せてしまうと**本物の区切りを隠して `uses:` を見逃す**ため、従来の挙動へ倒す（fail-closed）
            # 行末まで閉じなかった引用の**種類**を呼び出し側へ知らせる（awk に多値返却が無いため
            # グローバルへ置く。既存の `mask_quoted` / `MASK_UNCLOSED` と同じ形）。
            # 次の行以降は「引用スカラーの続き」なので、伏せる判断を止めるのに使う
            # **コメントの中で開いた引用は引き継がない。** YAML のコメントは行末までなので、
            # そこに書かれた `\"` は次の行へ続く引用スカラーの始まりではない。引き継ぐと、以降の行が
            # すべて「引用スカラーの続き」と見なされ、**`run: |` がブロックスカラーとして認識されなくなり
            # シェル本文が構造として漏れ出す**（実測: 行末コメントに閉じない `\"` を 1 つ置くだけで、
            # `run:` の本文にある `uses: …@v1` が幻の参照として報告され、`permissions: write-all` を
            # 宣言と読んで read-only のワークフローが特権と判定された。**必須チェックが恒常的に赤くなる**）
            MASK_OPEN_TYPE = in_comment ? "" : quote
            if (quote != "") out = out raw
            # 組み立てた 1 行を返す
            return out
        }
        # 引用符を落とすだけで、伏せる処理は一切しない写しを返す（従来の一律削除と同じ結果）。
        # **複数行にまたがる引用スカラーの「続きの行」に使う**: その行のどこが引用の内側かは
        # 行だけ見ても決まらないので、伏せずに素の姿で出す＝余分に赤くなる側へ倒す
        function strip_quotes_only(src,   out) {
            # 引用符 2 種の文字集合を組み立て、まとめて落とす（従来の一律削除と同じ結果）
            out = src
            gsub("[" dq sq "]", "", out)
            # 組み立てた 1 行を返す
            return out
        }

        # 開いたままの引用スカラー（種類 `qt`）を持つ「続きの行」を読み、**その行の末尾で
        # 開いたままになっている引用の種類**を返す（開いていなければ空文字）。
        #
        # **「閉じたか」ではなく「末尾で何が開いているか」を返す**のが要点。閉じたかどうかだけを見て
        # そこで打ち切ると、**同じ行の後ろでもう 1 つ引用が開く**形を取り逃がす。すると次の行は
        # 「引用の中なのに普通の行」として扱われ、そこに書かれた `run: |` がブロックスカラーとして
        # 認識されて**続く行が本文として丸ごと落ちる**（実測: `- name: \"a` / `  b\" note: '"'"'c` /
        # `  run: |` と続く入力で、そのあとの 2 行が構造行から消えた。**fail-open**）。
        # 終端かどうかの規則は `is_escape_at` に集約してあり、伏せる処理側と同じものを使う
        #
        # **併せて、その行を構造行としてどう出すかも決める**（`MASK_CONT_TEXT` へ置く）。
        # 引用の中身に当たる範囲の `#` だけを伏せるのが要点で、伏せないと消費側が値の中の `#` で
        # 行を切り、**後ろの本物の `secrets:` を捨てて特権ワークフローを read-only に化けさせる**
        # （issue #124 の 2 件目。FR-9.6(b) の SHA ピン強制が丸ごと外れる **fail-open**）。
        # **伏せるのは `#` だけで、フロー形式の区切り（`,` `{` `[`）には触れない。** 続きの行かどうかの
        # 見立てが外れていた場合、区切りまで伏せると本物の `, secrets:` を隠してしまい、
        # いま塞いでいるのと同じ向きの穴を別の形で開けることになる。`#` を伏せる向きは
        # 「行が切れなくなる」＝構造が残る側にしか働かないので、見立てが外れても
        # 余分に赤くなるだけで見逃しには倒れない。
        # この非対称のおかげで、読点が生きて幻の参照が出る既知の残件
        # （`KNOWN RESIDUAL: a quoted scalar spanning lines still yields a phantom`）は
        # これまでどおりの挙動で残る（意図的。あちらは「余分に赤くなる」側）
        function open_type_after_continuation(src, qt,   i, ch, len, head, tail) {
            # 行の長さを求めてから 1 文字ずつ見る
            len = length(src)
            for (i = 1; i <= len; i++) {
                ch = substr(src, i, 1)
                # 脱出表記は終端ではないので 2 文字ぶん読み飛ばす
                if (is_escape_at(src, i, ch, qt)) { i++; continue }
                # 同じ種類の引用符が素で現れたら、そこで閉じる。
                # **残りは普通の YAML なので、通常の判定にそのままかける**（開始位置の規則も
                # コメントの扱いも 1 か所に持たせるため。返ってくる行そのものは使わず、
                # 「末尾で開いたままの引用の種類」だけを受け取る）。
                # 残りは行の途中から始まるので、行頭まわりの位置の記憶（`seqzone` など）は
                # 真っさらな状態から数え直される。ずれる向きは「引用と認める機会が増える」＝
                # 引き継ぎが増える側で、引き継ぎは**伏せるのをやめる方向にしか効かない**ため
                # 見逃しには倒れない（実測でも余分に赤くなるだけだった）。
                # **これは「引き継ぎが 1 行増える」ことについての話**で、
                # 引き継ぎが**永久に解けなくなる**（ラッチする）場合は別——そちらは
                # 両向きに壊れる（issue #119。下の `open_type == ""` が塞いでいる）
                if (ch == qt) {
                    # ここまでが「開いていた引用スカラーの中身」。引用符を落としたうえで
                    # `#` だけを代役へ置き換える（理由は関数のコメント）
                    head = strip_quotes_only(substr(src, 1, i - 1))
                    gsub(/#/, flow_mask, head)
                    # 閉じ引用符より後ろは**引用の外＝普通の YAML** なので、通常の判定を
                    # そのままかける。ここを「引用符を落とすだけ」に留めると、後ろに別の
                    # 引用値があったときにその中の `#` が伏せられず、**同じ行の後ろにある
                    # 本物の `secrets:` がそこで切り落とされる**（`{name: "a` の続きの行が
                    # `", note: "b #c", secrets: inherit, uses: …}` という形。この関数が
                    # 塞いでいるはずの穴が、閉じ引用符の後ろで再発する）。
                    # 「見立てが外れたときに本物の区切りを隠す」危険があるのは**閉じ引用符より
                    # 前**（＝上の `head`。だから片や `#` だけを伏せる）で、後ろは行の途中から
                    # 読み直す普通の行と変わらない
                    tail = mask_quoted_flow_punctuation(substr(src, i + 1))
                    # 構造行として出す 1 行を組み立てておく（呼び出し側が使う）
                    MASK_CONT_TEXT = head tail
                    # **末尾で開いたままの引用の種類**は、いま呼んだ判定が控えている
                    # （同じ部分文字列を 2 度走査しないために戻り値と副作用を 1 回で受け取る）
                    return MASK_OPEN_TYPE
                }
            }
            # 閉じなかった＝行全体が引用スカラーの中身で、同じ引用がこの行の末尾でもまだ開いている。
            # 中身なので `#` を伏せてよい（この行には構造が 1 文字も含まれない）
            MASK_CONT_TEXT = strip_quotes_only(src)
            gsub(/#/, flow_mask, MASK_CONT_TEXT)
            return qt
        }
        # ブロックスカラーの本文の中かどうかと、その開始行の字下げ幅を覚える
        BEGIN { in_scalar = 0; scalar_indent = 0; open_type = ""; was_continuation = 0 }
        {
            # 判定に使う 1 行分の文字列を作業用の変数へ取り出す
            line = $0
            # Windows 改行（CR）が混じっていても末尾の空白判定が狂わないよう取り除く
            sub(/\r$/, "", line)
            # 空行は構造を持たないので、状態を変えずに読み飛ばす
            if (line ~ /^[[:space:]]*$/) next

            # 最初に現れる非空白文字の位置から、その行の字下げ幅を求める
            indent = match(line, /[^[:space:]]/) - 1

            # ブロックスカラーの本文は、字下げが浅くなるまで丸ごと読み飛ばす
            if (in_scalar) {
                if (indent > scalar_indent) next
                in_scalar = 0
            }

            # 引用符を落として `"uses":` と `uses:` を同じ形に揃えてから書き出す。
            # ここで揃えておけば、消費側それぞれが引用の有無を数え上げずに済む。
            # 併せて、引用の中にあるフロー形式の区切り文字を代役の文字へ伏せる
            # （ただの値に書かれた読点や括弧を構造と読み違えないため。理由は関数側のコメント）
            # **引用スカラーの続きの行では伏せない。** 行頭側から見ると、その行に現れる引用符は
            # 「閉じる側」かもしれず、開始と読むと後ろの**本物の区切り**ごと伏せて `uses:` /
            # `secrets:` を見逃す（実測: `steps: [{name: "a,` の次行 `,", uses: "…"}]` で
            # 可変タグが検査から消えた。**fail-open**）。
            # **「伏せるのをやめる方向にしか効かない」とは書けない**（issue #119）。
            # 閉じ位置の見立て自体は確かに余分に赤くなる側へ倒れるが、**続きかどうかの印
            # （`open_type`）がラッチすると両向きに壊れる**: 伏せ処理が死ねば引用の中の `#` が
            # 行を切って本物の `secrets:` が落ち（fail-open）、ブロックスカラー判定が死ねば
            # 後続の `run: |` の本文が構造行として漏れる（fail-closed）。
            # ラッチの経路は下の `open_type == ""` が塞いでいる
            # この行が引用スカラーの続きだったかを控える（下のブロックスカラー判定で使う）
            was_continuation = (open_type != "") ? 1 : 0
            if (open_type != "") {
                # この行の末尾で開いたままの引用を控え直す（閉じていれば空文字＝次の行から通常どおり伏せる）。
                # 同じ 1 回の走査で、構造行として出す 1 行（引用符を落とし、引用の中身の `#` だけを
                # 伏せたもの）も `MASK_CONT_TEXT` に用意される
                open_type = open_type_after_continuation(line, open_type)
                # 続きの行は上で組み立てたものをそのまま出す
                emitted = MASK_CONT_TEXT
            } else {
                # 通常の行は従来どおり伏せる
                emitted = mask_quoted_flow_punctuation(line)
                # 行末まで閉じなかったなら、その種類を控えて次の行から続きとして扱う
                open_type = MASK_OPEN_TYPE
            }
            # ここまで残った行は構造なので、行番号を付けて書き出す
            print NR ":" emitted

            # スカラー開始かどうかは、コメント・大文字小文字を揃えた写しで判定する。
            # `#` の直前に空白か行頭を要求するのは他の 3 か所と同じ規則（YAML でコメントが
            # 始まるのはその位置だけ）。引用の中の `#` は上で伏せてあるので、ここに残る `#` は
            # 本物のコメントだけになる
            probe = emitted
            sub(comment_re ".*$", "", probe)
            probe = tolower(probe)

            # `run: |` や `prompt: >-` のような行なら、次の行から本文として読み飛ばす
            # **引用スカラーの続きの行ではブロックスカラーを始めない。** その行は文字列の中身なので、
            # そこに `run: |` と書いてあっても構造ではない。判定してしまうと以降の行を本文として
            # 読み飛ばし、**その中にある本物の `uses:` が抽出から丸ごと消える**
            # （実測: `- {name: "a` / `run: |` / `", uses: actions/evil@v1}` で可変タグが検査から
            # 消え、違反 0 件で通った。**fail-open**）
            # **その行を出ていく時点で引用が開いたままなら、やはりブロックスカラーを始めない**
            # （issue #119 (1)(2)）。`was_continuation` は「その行に**入る**前の状態」しか見ないので、
            # 1 行が「ブロックスカラーを開く」と「引用を開いたまま終わる」を**同時に**満たす形
            # （`- run: "|`）では両方が立つ。すると次の行が本文として `next` で読み飛ばされ、
            # **閉じ引用符を載せた行がその読み飛ばしに飲まれて** `open_type` が永久に閉じない
            # ——以降そのファイル全体で伏せ処理とブロックスカラー判定が死ぬ。壊れ方は両向きで、
            # 伏せ処理が死ぬと引用の中の `#` が行を切って本物の `secrets:` が落ち（**fail-open**。
            # 特権ワークフローが read-only に化けて FR-9.6(b) のピン検査をすり抜ける）、
            # ブロックスカラー判定が死ぬと後続の `run: |` の本文が構造行として漏れて
            # 実在するスイートが「未配線」になる（**fail-closed**。実測で `NOT-WIRED` / 読み込み失敗）。
            # **いったんラッチすると同じファイル内に回復経路が無い**ので、引用が閉じていない行は
            # 引用スカラーの途中として扱う（＝ブロックスカラーに倒さない fail-closed 側）
            # **鍵と指示子のあいだのノードプロパティ（`run: &suites |` / `run: !!str |`）も読む**
            # （issue #126）。読まないとその行がブロックスカラーの開始と認められず、本文の
            # シェルスクリプトが構造行として漏れて**実在するスイートが「未配線」になる**
            # （fail-closed。`run: |` に `&suites ` を足すだけで答えが変わる）。
            # 綴りは `prop_re`（シェル側の `CI_WORKFLOW_NODE_PROPERTY_BLOCK`。ブロックの印の
            # 手前なので名前の無い `!` も許す形）が唯一の源で、
            # **伏せ処理の歩きとは終わらせる文字が違う**（issue #201。あちらはタグ名を
            # 区切りで切らず、アンカー名だけ `anchor_stop_re` で切る）。こちらは
            # `CI_WORKFLOW_PROP_STOP_CHARS` 由来のままで、広げると値を取り出す側が
            # 確かめられない綴りを読む fail-open に倒れる（定数の注記が理由を持つ）
            if (!was_continuation && open_type == "" \
                && probe ~ ("^[[:space:]]*(-[[:space:]]+)?[a-z_][a-z0-9_.-]*[[:space:]]*:[[:space:]]*" prop_re "[|>]([0-9]*[+-]?|[+-]?[0-9]*)[[:space:]]*$")) {
                in_scalar = 1
                # 本文の範囲は**鍵の桁**で決める。ダッシュの桁で決めると、
                # `- if: >-` の本文だけでなく**同じ手順の兄弟キー**（次行の `uses:` 等）まで
                # 飲み込んでしまい、可変タグが検査対象から丸ごと外れる（実測）
                if (match(probe, /^[[:space:]]*-[[:space:]]+/)) {
                    # `- ` を含む前置きの長さが、そのまま鍵の桁になる
                    scalar_indent = RLENGTH
                } else {
                    scalar_indent = indent
                }
            }
        }
    ' "$path"
}
# 構造行の表を用意したうえで、渡した awk プログラムをワークフローに対して実行する。
# 第 1 引数がワークフロー、第 2 引数が一時ファイルの土台、第 3 引数が awk プログラム本体。
#
# **表の読み込みと後始末をここだけに持つ**のが要点。同じ 6 行の `getline` 断片と
# 「構造行を書き出す → awk → 終了コードを控える → 消す」の型を各所へ書き写すと、
# `emit_structural_lines` の出力形式を変えたときに片方だけが古くなり、
# 表が空のまま「該当なし」という**静かに誤った答え**を返す（本ライブラリを切り出した理由と同じ）。
# awk は BEGIN ブロックを複数持てるので、呼び出し側は自分の初期化を別の BEGIN に書けばよい
ci_workflow_run_with_structure() {
    # 引数を受け取る
    local workflow="$1" scratch="$2" program="$3"
    # 構造行の一覧を控えるファイル
    local structural_file="${scratch}.structural"
    # awk プログラムを書き出す先（下記のとおり引数では渡さない）
    local program_file="${scratch}.awk"
    # 構造行を書き出す。失敗したら以降の解析が成立しない（中間ファイルは残さない）
    if ! emit_structural_lines "${workflow}" > "${structural_file}"; then
        rm -f "${structural_file}" || true
        return 1
    fi
    # **プログラムは引数ではなくファイルで渡す（`-f`）。**
    # Linux の `MAX_ARG_STRLEN` は 1 引数あたり 128 KiB（32 ページ）で、これは
    # `ARG_MAX` を上げても変わらない固定値。このプログラムは既に 119 KiB あり、
    # **残り 11 KiB ほどで `awk: Argument list too long` に当たって解析が丸ごと死ぬ**
    # ——検出網が全滅するので失敗は派手（fail-closed）だが、コメントを 200 行足すだけで
    # 何の予告もなく踏む崖だった（実測: 本 PR の追加で 136 KiB に達し、260 表明が一斉に落ちた）。
    # `-f` は複数指定すると連結された 1 つのプログラムとして扱われる仕様なので、
    # 前置きの BEGIN と呼び出し側を 1 つのファイルに書き出せば意味は変わらない。
    # 書き出しに失敗したら**解析せずに落とす**（プログラムが欠けたまま「該当なし」を
    # 返すと、走っていないスイートが緑で通る）
    # **`&&` で繋ぐのが要点。** 波括弧の並びの終了コードは**最後のコマンドのもの**なので、
    # `;` で並べると前置きの書き出しだけが失敗しても 0 が返る。そのとき awk は
    # 構造行の表を読まないプログラムを走らせ、`structural[]` が空のまま
    # 「どの行も構造行ではない」＝**該当なし**を静かに返す（fail-open。レビューで指摘）
    if ! { printf '%s\n' '
        BEGIN {
            while ((getline entry < structural_file) > 0) {
                colon = index(entry, ":")
                if (colon > 0) { structural[substr(entry, 1, colon - 1) + 0] = 1 }
            }
            close(structural_file)
        }
        ' && printf '%s\n' "${program}"; } > "${program_file}"; then
        # 書き出せなかったら解析せずに落とす（中間ファイルも残さない）
        rm -f "${structural_file}" "${program_file}" || true
        return 1
    fi
    # 構造行の表を BEGIN で読み込んでから、呼び出し側のプログラムを続ける
    awk -v structural_file="${structural_file}" -v comment_re="${CI_WORKFLOW_COMMENT_START}" \
        -v prop_re="${CI_WORKFLOW_NODE_PROPERTY_BLOCK}" \
        -v prop_plain_re="${CI_WORKFLOW_NODE_PROPERTY}" \
        -v group_open_re="${CI_WORKFLOW_GROUP_OPENER}" \
        -v redirect_lead_re="${CI_WORKFLOW_REDIRECT_LEAD}" \
        -f "${program_file}" "${workflow}"
    # awk の終了コードを控える（後始末で上書きされないように）
    local status=$?
    # 中間ファイルを片付ける（失敗しても終了コードは変えない）
    rm -f "${structural_file}" "${program_file}" || true
    # awk の結果をそのまま返す
    return "${status}"
}

# ci.yml を読み、実行される `run:` の中身をステップ番号付きで書き出す。
# 第 1 引数がワークフローのパス、第 2 引数が出力先ファイル。
#
# **構造の判定は `emit_structural_lines` に委ねる**のが要点。ステップの区切りや `if:` の検出を
# 生の行に対して行うと、`run: |` の**本文**に書かれた `- 箇条書き` でステップを切ってしまい
# （実行されているスイートが「配線されていない」と誤報される）、本文中の `if: false` で
# ステップ全体が消える。ブロックスカラー本文を構造と読み違えない判定は上にあるので、それを使う。
#
# **ステップの区切りは字下げで決める。** 「`- ` で始まる構造行」を一律に区切りとすると、
# `with:` / `args:` の下の `- --quiet` のような**入れ子の並び**でもステップが切れる。
# そこで区切りが起きると、その手前で立てた `if: false` の印が新しい疑似ステップにリセットされ、
# **止めたはずのステップが「実行されている」と読まれる**（レビューで実測）。
# 同じ理由でジョブの境界も追う: ジョブ直下の `if:` / `continue-on-error:` はそのジョブの
# 全ステップに掛かり、また**ジョブが変わる前に直前のステップを確定させない**と、
# 次のジョブの無効化キーが前のジョブ最後のステップを取り消してしまう（同じくレビューで実測）
ci_workflow_extract() {
    # 中間ファイルの置き場は出力先とは別の名前にする（読み書きが同じファイルに見えないように）
    local scratch="$2.extract"
    # 構造行の表の用意・後始末は共有ヘルパーに任せ、ここは解析だけを書く。
    # awk のプログラムはシェルに展開させてはいけないので単一引用符で渡す
    # shellcheck disable=SC2016
    ci_workflow_run_with_structure "$1" "${scratch}" '

        # 構造行の表（structural[行番号]）は ci_workflow_run_with_structure が用意する。
        # 入れ子の深さを覚える変数は **-1（まだどこにも入っていない）で始める**必要がある。
        # awk の未初期化変数は 0 なので、初期化を落とすと `step_dash_indent` が 0 と読まれ、
        # ジョブ直下の `continue-on-error:` までステップ内のキーとして扱われ、
        # ジョブ単位の無効化が効かなくなる（この初期化を落として実測した）
        BEGIN {
            jobs_indent = -1; job_indent = -1; steps_indent = -1
            step_dash_indent = -1; env_indent = -1; step_key_indent = -1; defaults_indent = -1; job_key_indent = -1
            # ブロックスカラーの基準字下げも同じ規約（-1 = まだ決まっていない）。
            # 0 で始まると「基準は 0 桁と確定済み」の意味になり、字下げを 1 桁も落とさなくなる
            run_base_indent = -1
            # ヒアドキュメントの待ち行列（`hd_i` が消化中の位置、`hd_n` が積まれた数）。
            # **明示的に初期化する**のが要点で、awk の未初期化変数は数値として 0 なので
            # 放置すると `hd_i <= hd_n` が 0 <= 0 で真になり、`run:` の 1 行目から
            # 「本文の読み飛ばし中」と誤読して**全ステップの中身が消える**
            hd_n = 0
            hd_i = 1

            # **ワークフロー直下の `defaults:` は先に 1 度だけ読んでおく。**
            # 出力はジョブ 1 つ分を確定させてから行うため、`jobs:` より後ろに書かれた既定を
            # 本文と同じ 1 回の走査で拾うと、既に確定したジョブには反映できない
            # （YAML のキー順は自由で、Actions は位置に関わらずトップレベルの `defaults:` を適用する）。
            # 桁 0 の行だけを見るので、`run: |` の本文（必ず字下げされる）と取り違えることはない
            while ((getline preline < ARGV[1]) > 0) {
                # Windows 改行が混じっていても桁の判定が狂わないよう CR を落とす
                sub(/\r$/, "", preline)
                # **行末コメントを落としてから判定する。** 本文側の走査は既にそうしており
                # （`if: false  # 理由` を取りこぼさないため）、ここだけ生の行を見ると
                # `defaults:  # 全ジョブ共通` がフロー形式に、`shell: bash  # 明示` が未知のシェルに見え、
                # **全ジョブの全ステップが合否の証拠から外れて**すべて「配線されていない」と誤報される
                sub(comment_re ".*$", "", preline)
                # **鍵の引用符も本文の走査と同じ規則で落とす。** ここだけ素の綴りを見ていると
                # `"defaults":` / `"shell":` の 2 文字で既定シェルの検出をすり抜けられ、
                # `-e` を落とすワークフロー既定が「無い」ものとして扱われる（レビューで実測）
                preline = unquote_key(preline)
                # 空行（コメントだけの行を含む）はブロックの内外を変えない
                if (preline ~ /^[[:space:]]*$/) { continue }
                # 桁 0 の鍵が来たら、直前のトップレベルブロックは終わっている
                if (preline !~ /^[[:space:]]/) { in_top_defaults = (preline ~ /^defaults:/) }
                # フロー形式（`defaults: {run: {shell: …}}`）は中身を構造として読めないので未知扱い
                if (preline ~ /^defaults:[[:space:]]*[^[:space:]]/) { workflow_shell = "?" ; in_top_defaults = 0 }
                # `run:` がフロー形式なら中の `shell:` を読めないので、未知のシェル扱いにする
                if (in_top_defaults && preline ~ /^[[:space:]]+run:[[:space:]]*[^[:space:]]/) {
                    workflow_shell = "?"
                }
                # ブロック形式の中に現れた `shell:` を既定として控える
                if (in_top_defaults && preline ~ /^[[:space:]]+shell:[[:space:]]*[^[:space:]]/) {
                    workflow_shell = read_shell_value(preline)
                }
            }
            # 本文の走査に影響しないよう読み終えたファイルを閉じる
            close(ARGV[1])
        }

        # **シェルの引用符の扱いはこの 1 か所に集約する。** 以前は「コメントの開始位置」「括弧の釣り合い」
        # 「行が閉じているか」「区切り記号かどうか」で同じ状態機械を 4 回書いており、
        # どれか 1 つにだけ修正が入ると「どこでコマンドが終わるか」と「行が続いているか」の
        # 答えが食い違う（§6 DRY。レビューで指摘）。
        #
        # **`emit_structural_lines` の `mask_quoted_flow_punctuation` とは別物**（統合しないこと）。
        # あちらは **YAML** の引用規則（`'"'"''"'"'` と `\"` の脱出、値が始まりうる位置だけを開始と認める）を
        # 見て、フロー形式の区切り文字だけを伏せて**中身は残す**。こちらは **シェル** の引用規則
        # （単一引用符の外ではバックスラッシュが次の 1 文字を打ち消す）を見て、**中身ごと空白へ潰す**。
        # 対象の言語も、残すものも違うので、片方の規則をもう片方へ持ち込むとどちらも壊れる
        # （例: シェルの `\` 打ち消しを YAML 側へ入れると `<<\MARK` と同種の取り違えが起きる）。
        #
        # 引用符で囲まれた部分を**同じ長さの空白**へ置き換えた写しを返す。桁がずれないので、
        # 呼び出し側は写しの上で位置を探して、元の文字列を同じ位置で切れる。
        # 閉じずに行が終わったかどうかは `MASK_UNCLOSED` に入れる（awk に多値返却が無いため）。
        # 規則は 1 つ: **単一引用符の外側では、バックスラッシュが次の 1 文字を打ち消す**
        function mask_quoted(t,   i, c, out, in_single, in_double) {
            # **引用符も打ち消しも含まない本文は、そのまま返す**（issue #166）。
            # その場合この関数がやることは「1 文字ずつ読んで同じ文字を書き戻す」だけで、
            # 結果は入力と必ず一致する（`MASK_UNCLOSED` も 0）。`run:` の本文の大半が
            # これに当たり、呼び出しは断片ごとに何度も起きる
            # （`drop_arm_head_close` / `case_arm_consumed` / `strip_comment` / `starts_case_arm` 等）。
            # **`\\` を条件に含めるのが要点**——この関数は打ち消された 2 文字を空白へ潰すので、
            # `\\` を含む本文を素通しすると釣り合いもコメントの判定も変わる
            # （`bash <スイート> \&& echo ok` が `&&` と読まれる fail-open。レビューで実測）。
            # **兄弟の `mask_quoted_flow_punctuation` は同じ形の素通しを持つが、条件に
            # `\\` を含めていない——あちらは引用符の中でしか打ち消しを解釈せず、
            # 引用符の外の `\\` は素の文字として残すので、含める必要が無いだけ。**
            # 「揃っていない」と見て**こちらから落とすと上記の fail-open が開く**ので揃えない
            if (index(t, "\"") == 0 && index(t, "\047") == 0 && index(t, "\\") == 0) { MASK_UNCLOSED = 0; return t }
            out = ""; in_single = 0; in_double = 0
            for (i = 1; i <= length(t); i++) {
                c = substr(t, i, 1)
                # 打ち消された 2 文字は、区切りにもコメントにも括弧にもならない
                if (c == "\\" && !in_single && i < length(t)) { out = out "  "; i++; continue }
                # 引用符そのものは中身と同じく空白にする（開閉の状態だけ更新する）
                if (c == "\"" && !in_single) { in_double = !in_double; out = out " "; continue }
                if (c == "\047" && !in_double) { in_single = !in_single; out = out " "; continue }
                # 引用符の内側は文字列なので、すべて空白へ潰す
                if (in_single || in_double) { out = out " "; continue }
                # 引用符の外側はそのまま残す
                out = out c
            }
            # 閉じないまま行が終わったか（次の行へ続いているか）を控える
            MASK_UNCLOSED = (in_single || in_double) ? 1 : 0
            return out
        }

        # コメント部分（行頭、または空白に続く # から行末まで）を落とす。
        # 引用符の内側の `#` は落とさない——素の正規表現で切ると
        # `bash x --label \047issue # 94\047 || true` が途中で切られ、**後ろの `|| true` ごと消える**
        function strip_comment(t,   masked, i, prev) {
            masked = mask_quoted(t)
            for (i = 1; i <= length(masked); i++) {
                # 引用符の外側に現れた `#` だけが候補
                if (substr(masked, i, 1) != "#") { continue }
                # 行頭か、空白の直後であればそこからがコメント（判定は元の文字列で行う）
                prev = (i > 1) ? substr(t, i - 1, 1) : ""
                if (i == 1 || prev == " " || prev == "\t") { return substr(t, 1, i - 1) }
            }
            return t
        }
        # 前後の空白を落とす
        function trim(t) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", t); return t }

        # **先頭のスペースの数を数える。** YAML の字下げはスペースのみで、タブは字下げに
        # 使えない（＝本文先頭のタブは内容の一部）。基準字下げを**測る側**と、終端判定で
        # **落とす側**の両方がここを使う。2 か所へ書き写すと、片方だけ直したときに
        # 落とす量がずれて issue #108 の穴が開き直る
        function leading_spaces(t,   n) {
            n = match(t, /[^ ]/)
            # 全部スペースの行（空行扱い）は長さそのものが字下げ
            return (n ? n - 1 : length(t))
        }

        # **ヒアドキュメントの終端行かどうかを bash と同じ厳しさで判定する。**
        # bash が終端と認めるのは「区切り語だけが置かれた行」だけで、行末コメントが
        # 付いた行や余分な字下げが残る行は本文のまま。ここを緩くすると本文の途中で
        # 読み飛ばしが終わり、**ただのデータが「実行されるコマンド」に化ける**
        # （issue #108）。`ci_coverage_test.sh` はこの記録を根拠に「全スイートが
        # 実行されるか」を判定するので、ワークフローから外されたスイートが
        # ヒアドキュメントの中で名前を挙げられているだけで「実行されている」と通る
        # ——このライブラリが塞ぐために作られた「不在＝合格」そのものの形になる。
        # 判定できないものは呼び出し側で「本文が続く」に倒れる（fail-closed）。
        # 引数: raw=生の行 / dash=`<<-` で開いたか /
        #       base_indent=ブロックスカラーの基準字下げ / word=区切り語
        # **引数名は `indent` にしない。** awk の引数は関数スコープだが、同名のグローバル
        # `indent`（構造行の入れ子判定に使う）を黙って隠すため、ここで代入する編集が
        # 外側に効かない／外側の値を読むつもりの編集が別物を読む、という罠になる
        function heredoc_terminates(raw, dash, base_indent, word,   lead, drop, rest) {
            # YAML のブロックスカラーは本文全体が字下げされている。bash が実際に見るのは
            # **その基準字下げ分だけ**を落とした後の行なので、まず同じ分を落として揃える。
            # 先頭の**スペース**の長さを 1 度測り、基準字下げとの小さい方だけを落とす
            # （基準より深い字下げは bash にも残るので、ここでも残す）。
            # タブは YAML の字下げではなく内容なので、ここでは落とさない
            # ——落とすのは `<<-` の規則に従って下で行う
            lead = leading_spaces(raw)
            # 実際の字下げと基準の**小さい方**だけを落とす。基準より浅い本文行は
            # YAML ではブロックスカラーを終える（＝ここへ来ない）ので、この下限が効くのは
            # 全部スペースの行だけで、どちらに倒れても `rest` は区切り語と一致しない。
            # なお heredoc が開いている時点で基準は必ず確定済み（開いた行自身が
            # 非空の本文行として決めている）なので、base_indent が負になる経路は無い
            drop = (lead < base_indent) ? lead : base_indent
            rest = substr(raw, drop + 1)
            # **`<<-` が落とすのは先頭のタブだけで、スペースは落とさない。**
            # YAML の字下げはスペースなので、ここを「字下げは何でも許す」と緩めると、
            # 実際のワークフローで書ける唯一の形がちょうど検査を素通りする（issue #108）
            if (dash) { sub(/^\t+/, "", rest) }
            # 残りが区切り語ちょうどのときだけ終端。**コメントを剥がしてから比べない**
            # ——`MARK # 説明` は bash にとって本文であって終端ではない
            return (rest == word)
        }

        # **鍵を囲む引用符を落として揃える。** YAML は `"shell": bash` を `shell: bash` と
        # 同じ鍵として読むので、素の綴りだけを見ると引用符 2 つで検出をすり抜けられる。
        # 値には触らない（値の引用符は `read_shell_value` / `is_disabling` 側で扱う）
        function unquote_key(t,   probe) {
            probe = t
            if (probe ~ /^[[:space:]]*-?[[:space:]]*["\047][A-Za-z0-9_.-]+["\047][[:space:]]*:/) {
                match(probe, /["\047][A-Za-z0-9_.-]+["\047]/)
                probe = substr(probe, 1, RSTART - 1) substr(probe, RSTART + 1, RLENGTH - 2) substr(probe, RSTART + RLENGTH)
            }
            return probe
        }

        # `shell:` の行から値だけを取り出す。**引用符は落とす**——YAML では `shell: "bash"` と
        # `shell: bash` は同じスカラーなので、引用の有無で「未知のシェル」に転ぶと、
        # 見た目だけの整形で「どこからも呼ばれていない」と事実と逆の診断が出る
        # （`is_disabling` が同じ理由で引用符を正規化しているのと揃える）。
        # 2 か所（ステップの `shell:` と `defaults:` の `shell:`）から呼ぶのでここに置く（§6 DRY）
        function read_shell_value(t,   value) {
            value = t
            sub(/^[[:space:]]*-?[[:space:]]*shell:[[:space:]]*/, "", value)
            # **ノードプロパティも落とす**（issue #126 のレビューで実測）。`shell: &s bash` は
            # 値が `bash` の正当な YAML なのに、残すと「未知のシェル」に転んで**実際に走って
            # ゲートしているステップが「未配線」になる**（`run:` 側と同じ鍵と値の非対称）。
            # 落とすのは名前のある形だけ（`run:` の素のスカラーと同じ理由で、名前の無い `!` は
            # 読まない側＝fail-closed へ倒す）
            sub("^" prop_plain_re, "", value)
            gsub(/["\047]/, "", value)
            return trim(value)
        }

        # 断片の中の丸括弧の釣り合い（開き − 閉じ）を返す。引用符の中は数えない
        function paren_delta(t,   masked, i, c, delta) {
            masked = mask_quoted(t)
            delta = 0
            for (i = 1; i <= length(masked); i++) {
                c = substr(masked, i, 1)
                if (c == "(") { delta++ }
                else if (c == ")") { delta-- }
            }
            return delta
        }

        # 引用符が閉じていない（＝次の行へ続く）かどうかを返す
        function unbalanced_quotes(t) {
            mask_quoted(t)
            return MASK_UNCLOSED
        }

        # 指定した個数の空白を返す。**桁を保ったまま塗り潰す**ために使う
        # （長さの変わる置換をすると、写しの上で見つけた位置で元の行を切れなくなる）
        function spaces(n,   s) {
            s = ""
            while (length(s) < n) { s = s " " }
            return s
        }

        # 算術展開（`$(( … ))` / `(( … ))`）を**同じ長さの空白へ塗り潰した**写しを返す。
        # 内側の入れ子から順に潰すので `$(( (1 << A) + B ))` のような形も残らない。
        # heredoc の判定にだけ使う。
        # **長さを保つ**のが要点で、`collect_heredocs` はこの写しの上で `<<` の位置を探し、
        # 区切り語そのものは**元の行の同じ位置**から読む（引用符やバックスラッシュは
        # 写しの上では潰れているため）。1 文字へ縮める昔の版では桁がずれて別の場所を読む
        function strip_arithmetic(t,   guard) {
            # 置換のたびに減るのは括弧の数だけだが、万一に備えて回数にも上限を置く
            guard = 0
            while (guard < 100) {
                guard++
                # まず `((` … `))` の形を丸ごと塗り潰す
                if (match(t, /\$?\(\([^()]*\)\)/)) {
                    t = substr(t, 1, RSTART - 1) spaces(RLENGTH) substr(t, RSTART + RLENGTH)
                    continue
                }
                # **入れ子があると上の形に当たらない**（`$(( (1 << BIT) | FLAG ))` など）。
                # まだ算術式らしい `((` が残っているときに限り、内側の括弧を 1 つ潰して近づける。
                # `(` を無条件に潰すと `( cat <<EOF )` のような部分シェルの heredoc まで
                # 見えなくしてしまうので、`((` が残っていることを条件にする
                if (index(t, "((") > 0 && match(t, /\([^()]*\)/)) {
                    t = substr(t, 1, RSTART - 1) spaces(RLENGTH) substr(t, RSTART + RLENGTH)
                    continue
                }
                # これ以上潰せるものが無ければ終わり
                break
            }
            return t
        }

        # 元の行 `raw` の `start` 桁から**区切り語 1 つ**を読み、その文字列を返す。
        # 読み終えた次の桁は `HEREDOC_WORD_END` に入れる（awk に多値返却が無いため）。
        #
        # **区切り語の 4 綴りをここで一手に引き受ける**のが要点。bash は `<<EOF` / `<<"EOF"` /
        # `<<\047EOF\047` / `<<\EOF` を**すべて同じ区切り語 `EOF`** として扱う（引用は本文中の展開を
        # 抑止するだけで、終端の綴りは変えない）。以前は引用符だけを別関数で外し、残りを
        # `mask_quoted` に通してから正規表現で切り出していたため、
        #   - `<<\MARK` … `mask_quoted` が `\M` を空白 2 つへ潰して区切り語が `ARK` に化け、
        #     終端に一生出会えず**本文の後ろの実行まで捨てる**（issue #110・fail-closed）
        #   - `<<""`   … 空の区切り語に一致する綴りが無く**そもそも heredoc が開かない**ので、
        #     本文（＝実行されない文字列）が実行として記録される（issue #111 (2)・fail-open）
        # の 2 つが同時に起きていた。元の行から 1 文字ずつ読めばどちらも自然に消える
        function read_heredoc_word(raw, start,   len, i, c, quote, word) {
            len = length(raw)
            word = ""
            i = start
            while (i <= len) {
                c = substr(raw, i, 1)
                # バックスラッシュは次の 1 文字を「そのままの字」にする（`<<\MARK` → `MARK`）
                if (c == "\\" && i < len) { word = word substr(raw, i + 1, 1); i += 2; continue }
                # 引用符の内側は閉じ引用符まで丸ごと取り込む（`<<"EOF"` / `<<\047EOF\047`）。
                # **空の引用（`<<""`）もここを通る**ので、長さ 0 の区切り語が素直に得られる
                if (c == "\"" || c == "\047") {
                    quote = c
                    i++
                    while (i <= len && substr(raw, i, 1) != quote) { word = word substr(raw, i, 1); i++ }
                    i++
                    continue
                }
                # 空白・リダイレクト・制御演算子は区切り語の終わり
                if (c ~ /[[:space:];&|<>()]/) { break }
                # ここまで来た 1 文字は区切り語の一部
                word = word c
                i++
            }
            # 読み終えた次の桁を控える（呼び出し側が同じ行の続きを走査するために使う）
            HEREDOC_WORD_END = i
            return word
        }

        # 1 行が開くヒアドキュメントを**すべて**、bash が本文を読む順（＝行の左から右）に集め、
        # `hd_word[1..hd_n]` / `hd_dash[1..hd_n]` へ入れる。開いた数を返す。
        #
        # **1 行に 2 つ以上書ける**のが要点。`cat <<A > a; cat <<B > b` と書くと bash は
        # **A の本文を先に**読み、その後ろに B の本文が続く。以前は貪欲な `^.*<<-?` で
        # **行の最後の 1 つ**だけを覚えていたため、A の本文の中に現れた `B` で読み飛ばしを
        # 終えてしまい、まだ A の本文である行（＝実行されない文字列）が「実行されるコマンド」
        # として記録されていた（issue #111 (1)・fail-open）。
        #
        # **`<<-` は追跡中の区切り語ごとに覚える。** 以前は「行のどこかに `<<-` があるか」で
        # 一括判定しており、`cat <<-A; cat <<B` のように混在すると素の `<<` の終端判定にまで
        # タブ剥がしが伝染して早く終端した（issue #111 (3)・fail-open）
        function collect_heredocs(raw,   probe, len, i, j, dash) {
            # 開き直すたびに待ち行列を空にする（前の行の残りを引きずらない）
            hd_n = 0
            hd_i = 1
            # 引用符の中と算術展開を**桁を保ったまま**塗り潰した写しの上で `<<` を探す。
            # `echo "use << HERE"` の `<<` や `$(( 1 << 2 ))` の左シフトは heredoc ではない
            probe = strip_arithmetic(mask_quoted(raw))
            len = length(probe)
            i = 1
            while (i <= len) {
                # `<<` 以外の桁は読み飛ばす
                if (substr(probe, i, 2) != "<<") { i++; continue }
                # here-string（`<<<`）は 1 語を渡すだけで本文を持たない
                if (substr(probe, i, 3) == "<<<") { i += 3; continue }
                # `<<` の次の桁から見る
                j = i + 2
                dash = 0
                # `<<-` は本文と終端の**先頭のタブ**を落とす綴り
                if (substr(probe, j, 1) == "-") { dash = 1; j++ }
                # 区切り語の前の空白は読み飛ばす。**判定は元の行で行う**——写しの上では
                # 引用符が空白に潰れているので、`<<""` の引用符を「前置きの空白」と
                # 読み飛ばして別の場所を区切り語にしてしまう
                while (j <= len && (substr(raw, j, 1) == " " || substr(raw, j, 1) == "\t")) { j++ }
                # 区切り語を 1 つ読み、待ち行列の末尾へ足す
                hd_n++
                hd_word[hd_n] = read_heredoc_word(raw, j)
                hd_dash[hd_n] = dash
                # 同じ行にまだ `<<` が続くかもしれないので、読み終えた次の桁から探し直す
                i = HEREDOC_WORD_END
            }
            return hd_n
        }

        # 1 行を制御演算子（`;` `&&` `||` `|` `&`）で切り、seg[] に本文・ops[] に直後の演算子を入れる。
        # **区切りを見てはじめて「失敗が job に伝わるか」が決まる**のがこの分割の理由で、
        # 演算子をコマンド末尾に貼り付いた形でしか見ないと、間に引数やリダイレクトが 1 つ入るだけで
        # `bash x 2>&1 | tee log`（落ちてもステップは 0 で終わる）を「ゲートしている」と読む
        function split_commands(line, seg, ops,   i, n, c, nxt, prv, start, masked) {
            # 引用符の中を空白へ潰した写しの上で区切りを探す（桁が同じなので元の文字列を切れる）
            masked = mask_quoted(line)
            n = 0; start = 1
            for (i = 1; i <= length(masked); i++) {
                c = substr(masked, i, 1)
                nxt = substr(masked, i + 1, 1)
                prv = (i > 1) ? substr(masked, i - 1, 1) : ""
                # `;` は区切り。直後のコマンドは前の結果に関係なく走る
                if (c == ";") {
                    n++; seg[n] = substr(line, start, i - start); ops[n] = ";"; start = i + 1
                    continue
                }
                # `||`（前が失敗したときだけ走る）と `|`（パイプ）を見分ける
                if (c == "|") {
                    n++; seg[n] = substr(line, start, i - start)
                    if (nxt == "|") { ops[n] = "||"; i++ } else { ops[n] = "|" }
                    start = i + 1
                    continue
                }
                if (c == "&") {
                    # `2>&1` / `&>log` / `<&3` はリダイレクトであって区切りではない
                    if (prv == ">" || prv == "<" || nxt == ">") { continue }
                    # `&&`（前が成功したときだけ走る）と `&`（バックグラウンド実行）を見分ける
                    n++; seg[n] = substr(line, start, i - start)
                    if (nxt == "&") { ops[n] = "&&"; i++ } else { ops[n] = "&" }
                    start = i + 1
                    continue
                }
            }
            # 最後の断片は演算子を伴わない（行末まで続く）
            n++; seg[n] = substr(line, start); ops[n] = ""
            # 断片の数を返す（呼び出し側は 1..n だけを読む）
            return n
        }

        # その断片が関数定義かどうかを返す。**0 = 定義ではない / 1 = 見出しだけ（`{` は次の行）/
        # 2 = 本体を開く（`{` が同じ行）**。
        # bash の綴りは `function f` / `function f()` / `f()` の 3 通りあり、
        # **綴りの一覧を 2 か所に分けて持つと必ず片方が漏れる**（実際 `function f()` の綴りが
        # どちらからも抜けており、定義が階層を開かないのに閉じ `}` だけが深さを減らして
        # 外側のブロックを潰していた ＝ 条件付きでしか走らない呼び出しが実行の証拠に化ける fail-open）。
        # 見出しと本体を別々に数えるのは、**どちらも開き側に数えると 2 つ開いて 1 つしか閉じず**、
        # 以降ずっと「入れ子の中」に見えるため（深さも `fndef` も戻らない）
        function function_form(t,   head) {
            # 見出しの綴り（`function` の有無と `()` の有無の組み合わせ）
            head = function_head_re()
            # `{` が同じ行にあるなら、この断片が本体を開く
            if (t ~ head "[[:space:]]*\\{([[:space:]]|$)") { return 2 }
            # `{` が無ければ見出しだけ。次に来る `{` が本体の開き
            if (t ~ head "[[:space:]]*$") { return 1 }
            # それ以外は関数定義ではない
            return 0
        }

        # その断片の**先頭**が複合コマンドを 1 つ開く綴りかを分類する。
        # **0 = 開かない / 1 = 必ず走る条件（`if true` / `while true`）/
        #   2 = 走るか分からない制御構造（条件・ループ・`case`）/ 3 = 関数定義（本体を同じ断片で開く）/
        #   4 = 関数の見出しだけ（`{` は次の行）/ 5 = ブレースグループ**。
        # **分類を関数に切り出したのは、同じ断片から開きを 2 つ以上取り出すため**（issue #123 (5)）。
        # 開き側の判定が `if` / `else if` の連鎖として 1 か所に埋まっていた頃は 1 断片で 1 つしか
        # 開けず、`f() { g() { : ; }; …` のように本体が同じ断片でもう 1 つ開く綴りで階層が
        # 1 つ足りなくなっていた（続く `}` が関数の階層を閉じ、**呼ばれていない関数の本文の残りが
        # 最上位のコード**として読まれる fail-open）。
        # **綴りの一覧はここが唯一の源で、関数定義の綴りだけは `function_form()` へ委ねる**
        # （`function_head_re()` の一覧を写さないため。写すと必ず片方が漏れる、が同ファイルの教訓）
        # `cached_fn_form` / `use_cached` は、呼び出し側が断片ごとに 1 度だけ求めている
        # `function_form()` の結果を使い回すための引数（同関数は正規表現を組み立てるので
        # 呼び直すと無駄が大きい、というのが 1 度だけ求めている理由）。ループの 2 周目以降は
        # 本文が別物なので測り直す
        # **部分シェルの開きの綴りを返す唯一の場所**（`close_word_re()` と同じ理由）。
        # 断片の先頭に並ぶ `(` は、開き側の歩き方 4 つ（本体のループ・`last_deciding_open()` /
        # `walk_opens_case()` / 下の上限）が同じ綴りで読まなければ階層の数え方が割れる
        function subshell_open_re() {
            return "^\\([[:space:]]*"
        }

        # 断片の先頭に並ぶ `(` のうち、**この断片を抜けたあとも開いたまま残る**数の上限。
        # 釣り合いが 0 の断片（`( : )`）は中で閉じ切るので 1 つも残らず、階層を開いてはいけない。
        # **本体のループは補正済みの `paren` を上限に使う**（アーム模様の `(` を除いた値で、
        # こちらより正確）。歩く側がそれを使えないのは、`paren` の算出が
        # `set_arm_here` → `case_scope` → `walk_opens_case()` に依存して循環するため。
        # **食い違いは「`|` で切られたアーム模様の `(`」だけではない（issue #145）。**
        # ここに「食い違っても判定は変わらない」と書いてあった断りは**実測で偽**だった:
        # 1 行書きのアーム（丸括弧なしの `a)`）は**対応する `(` を持たない `)`** を持つので、
        # 生の釣り合いではそれが先頭の `(` を打ち消して上限が 0 になり、
        # `f() { ( case $X in a) :;; esac ; bash x ) }` で `case` の階層が開かず、
        # 続く `esac` が**関数の階層**を閉じて、呼ばれていない本体が「最上位で確実に走る」
        # として記録されていた（fail-open）。**直したのは本体のループの釣り合いの方**で
        # （`paren_probe` を `drop_arm_head_close()` に通す）、**ここは生の釣り合いのまま**。
        # **同じ補正をここへ入れるのは実測で悪化した**（issue #145 の作業中に試して外した）:
        # 上限が 1 へ増えると先頭の `(` を越えて `case` が見つかり `case_depth` が増えるが、
        # その結果 `( case $M in a) echo hi ;; esac ; set +e` 改行 `bash x` 改行 `)` と
        # `( { … ; } )` の 2 形が**補正ありでは `not-wired`・無しでは `wired`** になった
        # （実 bash は GATES＝部分シェルの中の `set +e` は親の errexit を消さないので
        #  失敗は伝わる。つまり補正を入れた側だけが正しくゲートしている設定を
        #  「配線されていない」と報告する fail-closed）。800 ケースの総当たりで差はこの 2 形だけ。
        # **ここに補正を入れ直す前に、同じ 800 ケースで悪化しないことを測ること。**
        # **「判定は変わらない」とも書き戻さないこと**（上の実測が否定している）。
        function lead_subshell_cap(t,   d) {
            d = paren_delta(t)
            return (d > 0) ? d : 0
        }

        # 先頭に並ぶ部分シェルの開きを**越えた残り**を返し、**越えた数を `LEAD_SUBSHELLS` へ控える**
        # （`cap` が越えられる上限）。
        # **数え方をここ 1 か所に置く**のが要点（レビューで実測した退行）。歩く側で
        # `while (n < cap …)` と書くと、`n` は**その断片で開いた階層すべて**の数なので
        # 手前に `{` や `f() {` があるだけで上限に当たり、**`(` を 1 つも越えられない**
        # （`{ ( if false; then :; fi ) ; bash x; }` で死に体の印が 2 階層浅くなり、
        #  閉じた後も残って*走る*呼び出しが `not-wired` に化けた＝fail-closed）。
        # 綴りの共有だけでは足りず、**算術も共有する**必要がある。
        # **数と残りを 1 度の歩きで返す**のも同じ理由——「数える関数」と「落とす関数」に
        # 分けると同じ前置きを 2 度歩くうえ、「その `k` はこの綴りから数えたものか」という
        # **誰も強制していない約束**が生まれる（2 行を入れ替えるだけで数と文字列が黙ってずれ、
        # どのテストからも見えない）。awk は値を 1 つしか返せないので、
        # `mask_quoted()` が `MASK_*` でやっているのと同じくグローバルへ控える
        function cross_lead_subshells(t, cap,   n, probe) {
            probe = t; n = 0
            while (n < cap && probe ~ subshell_open_re()) {
                n++
                sub(subshell_open_re(), "", probe)
            }
            LEAD_SUBSHELLS = n
            return probe
        }

        function open_form(t, cached_fn_form, use_cached,   ff, probe) {
            # **自分では階層を開かない飾り（`time` / `!`）の後ろも分類する。**
            # （`eval` は**落とさない**。理由は `strip_struct_wrappers()` の説明）
            # 読まないと `time if false; then X; fi` の `if` が 1 階層も開かず、X が
            # 「最上位で走る」として記録される（issue #114 のレビューで実測）。
            # 綴りの一覧は `strip_struct_wrappers()` が唯一の源（`(` を含めない理由も同関数に）。
            # **関数定義とブレースの判定は剥がす前の綴りで行う**——`function_form()` は
            # 見出しの綴りを見るので、飾りが付いた形はそもそも関数定義ではない
            probe = strip_struct_wrappers(t)
            # **「必ず走る」条件を先に見る。** `if true` は下の一般形にも当たるので、
            # 順序を逆にすると本体が「走るか分からない」側に落ちて、正しくゲートしている
            # 呼び出しが実行の証拠から外れる
            if (probe ~ /^(if|while)[[:space:]]+(true|:)([[:space:]]|;|$)/) { return 1 }
            # 条件・ループ・`case` は、条件や対象を読まないと本体が走るか決まらない
            if (probe ~ /^(if|while|until|for|case|select)([[:space:]]|$)/) { return 2 }
            # 関数定義の綴りは `function_form()` が唯一の判定（3 綴りの一覧を写さない）
            ff = use_cached ? cached_fn_form : function_form(t)
            # 本体を同じ断片で開く綴り（`f() { …`）
            if (ff == 2) { return 3 }
            # 見出しだけの綴り（`f()` で行が終わり、次の `{` が本体）
            if (ff == 1) { return 4 }
            # 素のブレースグループ（`{ cmd; }`）
            if (t ~ /^\{([[:space:]]|$)/) { return 5 }
            # どれでもなければ複合コマンドは開かない
            return 0
        }

        # この断片が開く階層のうち、**この断片で見つかる `set` がその中で走るもの**の数を、
        # 副作用なしで先に数える（辿り方は開き側のループと同じ）。**先に数えるのが要点**——
        # 階層が開くのは断片の**末尾**なので、開き終わってから測ると、同じ断片で開いた
        # 階層の中で走る `set` を 1 つ浅く記録してしまい、括りの打ち消しが成立しなくなる。
        # 素の「開いた数」ではない: `if set +e; then …` の `set` は**条件の位置**にあり、
        # `if` が開く階層の**外**で走る（`strip_command_prefixes()` が `if ` を剥がして
        # 見つけるので、素直に数えると 1 つ深く記録して打ち消しが成立しなくなる）。
        # 逆にブレース・関数の本体・`case` のアームは中で走るので数える
        #
        # **先頭に並ぶ部分シェルも越えて数える**（issue #180）。ここには以前その処理が無く、
        # 「`set_command()` は `(` を剥がさないので釣り合っていない先頭の `(` の後ろの `set` は
        # そもそも見つからない」ことを理由に置いていなかった。その前提は issue #180 で崩れた
        # ——`( set +e` と 1 行で書いた握り潰しを読まないと、**部分シェルの中の呼び出しが
        # まるごと「合否に効く」と読まれる fail-open** だったので、呼び出し側が先頭の
        # 部分シェルを越えた先も探すようにした。当時のコメントが「前提が崩れたら自前で
        # 導き直さず `cross_lead_subshells()` をここでも通すこと」と指示していたので、そうしている。
        # **`strip_command_prefixes()` へ `(` を足す形では直さない**——あちらで落とすと
        # `open_form()` が後ろの `if` も形 2 として返し、1 つの断片で同じ階層を二重に開く
        # （同関数の「`(` は入れない」の段落が理由を記録している）。越えるのは呼び出し側と
        # ここだけに閉じる。
        # 素の「開いた数」ではない点は下記のとおり変わらない（`if set +e; then` の `set` は
        # 条件の位置にあるので `if` の階層は数えない）
        # **この歩きは「`set` を探す側」と「深さを数える側」の両方が使う**（issue #187）。
        # 1 度の歩きで (1) 深さの増分（戻り値）、(2) 命令の位置の綴り（`SET_OPEN_REST`）、
        # (3) 越えた**一番内側の部分シェル**の深さの増分（`SET_OPEN_SUB`。0 なら部分シェルの
        # 外）を返す。**探す側に別の歩きを持たせないこと**——以前は探す側が
        # `cross_lead_subshells()` を 1 回だけ呼んでいたため、`{ ( set +e` ・ `time ( set +e`
        # のように**前置きが `(` の手前にある綴り**で握り潰しを 1 つも見つけられず、
        # その部分シェルの中の呼び出しがまるごと「合否に効く」と読まれていた
        # （実測で真値 NOGATE なのに wired。**1 トークン前置きするだけで通っている
        # スイートをゲートから外せる fail-open**）。ここは交互に剥がす（前置き →
        # `(` を越える → 繰り返す）ので、同じ族がまとめて閉じる。
        # **控えるのは「最後に越えた部分シェル」の深さ**で、歩き終わりの深さではない
        # ——`( { set +e` は部分シェルが `+1`・ブレースが `+2` で、`set` が属するのは前者
        function set_open_depth(t, cached_fn_form, use_cached,   n, k, probe, rest, cap, leadn, sub_at, lead_stripped, fnd) {
            probe = t; n = 0; leadn = 0; sub_at = 0; fnd = 0
            # **上限はループの外で 1 度だけ求める**（`t` は変わらないので値は同じ）。
            # 兄弟の 2 つ（`last_deciding_open()` / `walk_opens_case()`）も同じ形で、
            # ここだけ中で呼ぶと開きが 1 つ増えるたびに断片全体の走査が 1 回増え、
            # 3 つの歩調がずれる起点になる
            cap = lead_subshell_cap(t)
            while (1) {
                # **上限は越えた数（`leadn`）で数える**（`n` と共有すると手前の `{` だけで
                # 上限に当たる。理由は `cross_lead_subshells()` の説明）。
                # **この越えにピンは無い**（外しても 1 件も落ちない＝実測）。それでも残すのは、
                # 外すと「部分シェルの中で走る `set`」を**親の深さ**で記録することになり、
                # `apply_errexit()` の打ち消し条件（`weak_depth >= at`）と閉じるときの
                # 取り消し（`weak_depth > depth`）が読む値が嘘になるため。いまは打ち消しが
                # 成立しなくても `at_uncertain == 0` の側で同じ答えになるので差が出ないだけで、
                # そこを締める変更が入った瞬間に静かな fail-closed になる
                # **自分では階層を開かない飾り（`time` / `!`）の後ろの `(` も越える**
                # （issue #187）。本体の開きループが同じ剥がしをしてから部分シェルを開くので
                # （`open_stripped ~ /^[({]/` の門番）、ここで剥がさないと `time ( set +e` の
                # 握り潰しが見つからないまま本体だけが階層を開き、**その部分シェルの中の
                # 呼び出しがまるごと「合否に効く」と読まれる**（実測で真値 NOGATE なのに wired）。
                # **この剥がしを兄弟の歩き（`last_deciding_open()` / `walk_opens_case()`）へは
                # 入れていない**（issue #187 のレビュー指摘、測って入れなかった）。
                # `subshell_open_re()` の説明は「4 つの歩きが同じ綴りを読む」ことを不変条件と
                # 書いているが、同じ剥がしを両方へ足した版を作って測ったところ、構成した 7 形
                # （`time ( case a in a) set +e` ・ `{ (` 版 ・ `time ( f() { set +e; } )` ・
                # `time ( if false; …)` ・ `{ ( for …)` 等）で**答えが 1 件も変わらなかった**。
                # 何も変えない仕掛けは置かない規約に従って入れていないが、**不変条件は
                # いま厳密には成り立っていない**——`time (` / `{ (` の綴りで
                # `walk_opens_case()` は部分シェルを越えないので `opens_case_here` が立たず、
                # アーム走査が切れる（それが答えを変える綴りが見つかったら、1 つの補助関数に
                # 切り出して 4 つの歩きすべてから呼ぶこと。片方だけ足し直さない）
                # **剥がした先が素のグループ（`(` / `{`）のときだけ使う**——門番は本体の
                # 開きループ（`open_stripped ~ /^[({]/`）と同じ綴りにそろえる。`{` も通すのは
                # `time { ( set +e` のように飾り・ブレース・部分シェルが重なる綴りがあるため
                # （`(` だけに絞ると、この形が fail-open のまま残る＝実測）。制御構造と
                # 関数定義を剥がさないのも本体と同じ理由で、`function_form()` は見出しの綴りを
                # 見るので飾り付きを剥がして渡すと「定義」と誤分類しうる
                lead_stripped = strip_struct_wrappers(probe)
                if (lead_stripped != probe && lead_stripped ~ /^[({]/) { probe = lead_stripped }
                probe = cross_lead_subshells(probe, cap - leadn)
                leadn += LEAD_SUBSHELLS; n += LEAD_SUBSHELLS
                # 越えた分があれば、その一番内側の深さを控える（上の説明）
                if (LEAD_SUBSHELLS > 0) { sub_at = n }
                # **控えた `fn_form` を使うのは綴りが 1 文字も変わっていないときだけ**
                # （issue #187 のレビュー指摘）。以前は `n == 0` を条件にしていたが、上の
                # 飾りの剥がしは `n` を増やさずに `probe` を書き換えるので、**剥がした先の
                # 綴りを「元の綴りで求めた `function_form()`」で分類**しうる。本体の開きループは
                # `(open_probe == struct_text)` と綴りで比べている（issue #142 のレビュー）ので、
                # 歩調もそちらへそろえる。**この直しにピンは無い**（`n == 0` へ戻しても 758 件
                # すべて緑＝実測）——`function_form(t)` が非 0 になり、かつ上の剥がしが効く
                # 綴りは `time () { … }` だけで、それは `bash -n` が構文エラーにする。
                # 倒れる向きが「数え落とす側」なので残してあるが、テストは守っていない
                k = open_form(probe, cached_fn_form, (use_cached && probe == t))
                # 何も開かない綴りと見出しだけの綴りはここで終わり
                if (k == 0 || k == 4) { break }
                # `case` のアームの本文はその中で走る（`case` を数えてそこで終わり）
                if (k == 2) { if (opens_case_word(probe)) { n++ } break }
                # `if` / ループの後ろは条件・対象の位置なので、その階層は数えない
                if (k == 1) { break }
                # ブレースと関数の本体は中で走る
                n++
                # **越えた関数定義の数を控える**（issue #189 のレビュー）。命令の位置が
                # 定義の**本文**にあるかは `in_fndef_here` では分からない——あれは
                # `function_form(struct_text)` 由来で `^` 錨なので、`( f() { exit 0` の
                # ように手前に `(` が付くと定義を見られず 0 を返す。数えずに済ませると
                # 「定義しただけの `exit`」を最上位の脱出として扱い、**呼んでいない関数の
                # 本文のせいでその部分シェルの残りが死に体になる**（実測で真値 GATES なのに
                # not-wired ＝正しくゲートしているスイートを赤くする fail-closed）
                # **越えた関数定義は「何番目の階層か」も控える**（issue #189 のレビュー）。
                # 部分シェルを越えた位置（`sub_at`）と比べて、その部分シェルが定義の
                # **外**か**本文の中**かを呼び出し側が区別できるようにする
                # （`( f() { exit 0` は外・`f() { ( exit 0` は中で、答えが逆になる）
                if (k == 3) { fnd++; SET_OPEN_FNNAME = function_name(probe); SET_OPEN_FNAT = n }
                rest = open_rest(probe, k)
                if (rest == probe) { break }
                probe = rest
            }
            # **歩き終わった位置と越えた部分シェルを控える**（issue #187。上の説明）
            SET_OPEN_REST = probe
            SET_OPEN_SUB = sub_at
            SET_OPEN_FNDEF = fnd
            # 越えた定義が 1 つも無ければ名前と位置は持ち越さない（前の断片の値が残らないように）
            if (fnd == 0) { SET_OPEN_FNNAME = ""; SET_OPEN_FNAT = 0 }
            return n
        }

        # この断片が開く階層のうち、**走るかどうかがそこで決まる一番内側**のものの
        # 深さの増分を返す（無ければ 0）。関数の台帳へ載せる階層は、後の断片が
        # `enclosing_scope_depth()` で求めるものと同じでなければならず、開く前の深さに
        # `+1` と決め打ちすると `f() { g() { set +e` のように**必ず走る階層を挟まずに
        # 2 つ開く**綴りで記録側だけ浅くなり、本文の `set -e` が打ち消せない
        # （正しくゲートする綴りを赤くする。レビューで実測）
        function last_deciding_open(t, cached_fn_form, use_cached, pending,   n, k, last, probe, rest, cap, leadn) {
            probe = t; n = 0; last = 0; leadn = 0
            cap = lead_subshell_cap(t)
            while (1) {
                # **先頭の部分シェルも 1 階層**（本体のループが開くので数を合わせる）。
                # ただし**決め手にはしない**——部分シェルは必ず走るので、走るかどうかが
                # そこで決まる階層ではない。
                # **上限は越えた数（`leadn`）で数える**（`n` と共有すると手前の `{` だけで
                # 上限に当たる。理由は `cross_lead_subshells()` の説明）
                probe = cross_lead_subshells(probe, cap - leadn)
                leadn += LEAD_SUBSHELLS; n += LEAD_SUBSHELLS
                k = open_form(probe, cached_fn_form, (use_cached && n == 0))
                # 何も開かない綴りと、見出しだけの綴りはここで終わり
                if (k == 0 || k == 4) { break }
                n++
                # 走るか分からない階層（制御構造・`case`）と関数定義の本体はそこで決まる。
                # 見出しの次の `{` も本体なので、その 1 つ目だけは同じ扱いにする
                if (k == 2 || k == 3 || (k == 5 && pending && n == 1)) { last = n }
                # 本体が同じ断片の中で続く綴り以外は、そこで終わり
                if (k != 3 && k != 5) { break }
                rest = open_rest(probe, k)
                if (rest == probe) { break }
                probe = rest
            }
            return last
        }

        # **返すのは「`case` を含めて何階層開くか」**（0 = `case` を開かない）。真偽だけでは
        # 足りない——アームの中の `set` を記録する階層は「`case` までに開いた分」だけ深く、
        # `{ case x in a) set +e` のように前に別の開きがあると 1 では足りない
        # （記録側と打ち消し側の階層が食い違い、同じアームの `set -e` が打ち消せなくなる。
        #   正しくゲートする綴りを赤くする。レビューで実測）
        function walk_opens_case(t, cached_fn_form, use_cached,   n, k, probe, rest, cap, leadn) {
            probe = t; n = 0; leadn = 0
            cap = lead_subshell_cap(t)
            while (1) {
                # 先頭の部分シェルを越える。越えないと `( case $X in (a|b)` で
                # `case` が見えず `case_scope` が偽になり、**アーム模様の `(` を
                # 部分シェルの開きとして数える補正が働かない**（釣り合いが 1 つ多く
                # 膨らんで階層が閉じ切らず、以降の `set +e` がすべて
                # 「子シェルの中」として無視される。issue #142 のレビューで実測）。
                # **上限は越えた数（`leadn`）で数える**（理由は `cross_lead_subshells()` の説明）
                probe = cross_lead_subshells(probe, cap - leadn)
                leadn += LEAD_SUBSHELLS; n += LEAD_SUBSHELLS
                k = open_form(probe, cached_fn_form, (use_cached && n == 0))
                # `case` を開く形に当たったらそこで確定（その `case` 自身も 1 階層）
                if (k == 2 && opens_case_word(probe)) { return n + 1 }
                # 本体が同じ断片の中で続く綴り以外は、そこで終わり
                if (k != 3 && k != 5) { return 0 }
                n++
                rest = open_rest(probe, k)
                # 1 文字も減らなければ打ち切る（開き側のループと同じ保険）
                if (rest == probe) { return 0 }
                probe = rest
            }
        }

        # `open_form()` が返した形の**開き 1 つ分だけ**を先頭から落として、その後ろを返す。
        # 呼んでよいのは形 3（関数定義）と形 5（ブレース）だけ——**その 2 つだけが
        # 「開いた直後が命令の位置」**だから。条件の位置（`if <条件>` / `for … in <一覧>`）へは
        # 辿らない（そこに複合を書く綴りは `split_commands` が `;` で切った先にしか現れず、
        # 推測で辿ると条件そのものを本体と取り違える）。
        # **`function_body_rest()` は使えない。** あちらは入れ子の見出しを**まとめて**落として
        # 最奥の命令を返す（`set` と呼び出しの探索が求める形）ので、途中の階層を数える
        # この用途では 1 つずつ落とす必要がある
        function open_rest(t, form,   s) {
            s = t
            # 関数定義なら、まず見出しを落とす（綴りは `function_head_re()` が唯一の源）
            if (form == 3) {
                if (match(s, function_head_re())) { s = substr(s, RLENGTH + 1) }
                # 見出しと `{` の間の空白を落とす
                sub(/^[[:space:]]*/, "", s)
            }
            # ここで先頭にあるのは本体（形 3）か素の（形 5）ブレースなので、それを落とす
            sub(/^\{[[:space:]]*/, "", s)
            # 残りが次の命令の位置
            return s
        }

        # 関数定義の見出しの綴り（`function f` / `function f()` / `f()`）を返す**唯一の場所**。
        # 上の注記のとおり、この一覧を 2 か所に分けて持つと必ず片方が漏れる。
        # 形（`function_form`）・名前（`function_name`）・本体の切り出し（`function_body_rest`）が
        # すべてここを通るので、綴りを足すときに直すのはこの 1 行だけで済む
        function function_head_re() {
            return "^(function[[:space:]]+[A-Za-z_][A-Za-z0-9_]*([[:space:]]*\\(\\))?|[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\\(\\))"
        }

        # 定義の断片から関数名を返す（定義でなければ空文字）。
        # 呼び出しを見つけたときに「どの関数の本体で `set +e` を見たか」を引くために使う
        # **`function_form()` は呼ばない。** 呼び出し側はすでに `fn_form` を控えており
        # （`function_form()` は正規表現を組み立てるので呼び直すと無駄が大きい、という理由で
        # 断片ごとに 1 度だけ求めている）、ここで測り直すとその控えが台無しになる。
        # 名前を取るのに要るのは見出しの綴りだけなので、`function_head_re()` を直接使う
        function function_name(t,   s) {
            # 見出しの綴りに当たらなければ名前は無い
            if (!match(t, function_head_re())) { return "" }
            # 当たった見出しの部分だけを取り出す（本体側は名前に関係ない）
            s = substr(t, 1, RLENGTH)
            # `function` キーワード付きの綴りなら先に落とす（3 綴りのうち 2 つが持つ）
            sub(/^function[[:space:]]+/, "", s)
            # 残りの先頭にある識別子がそのまま関数名
            if (match(s, /^[A-Za-z_][A-Za-z0-9_]*/)) { return substr(s, 1, RLENGTH) }
            # 見出しの形なのに名前が取れないなら、名前で引く仕組みからは外す
            return ""
        }

        # 本体を同じ断片で開く定義（form 2）から、見出しを落とした残り（`{ …`）を返す。
        # 1 行書き（`f() { set +e; }`）の `set` は、見出しが付いたままでは `set_command()` が
        # 拾えない。ここで見出しだけを落として、あとは通常の経路に載せる
        # **入れ子の 1 行定義にも対応するため繰り返す。** `outer() { inner() { set +e; }; … }` は
        # 見出しを 1 つ落としただけでは `{ inner() { set +e` が残り、`set` に届かない
        # （＝ `set +e` の存在自体を見落とす。レビューで実測。fail-open）。
        # 落とした結果は**いちばん外側の関数**に紐づける——`outer` を呼べば `inner` の定義も
        # 呼び出しも走るので、`outer` が弱めると読むのが実 bash と一致する
        function function_body_rest(t,   s, before) {
            s = t
            # 見出しに当たらなければ切り出すものが無い
            if (!match(s, function_head_re())) { return "" }
            # 変化が無くなるまで「空白 → `{` → 見出し」を落とし続ける
            do {
                # この周回の開始時の姿を控える（変化の有無を測るため）
                before = s
                # 先頭の空白を落とす
                sub(/^[[:space:]]+/, "", s)
                # 本体を開く `{` を落とす
                sub(/^\{[[:space:]]+/, "", s)
                # さらに見出しが続くなら、それも落とす（入れ子の定義）
                if (match(s, function_head_re())) { s = substr(s, RLENGTH + 1) }
            } while (s != before)
            return s
        }

        # 定義の本文で見た**弱める向き**を関数名に控える（呼ばれた時点で反映するため）。
        # 短い綴り（`+e`）と長い綴り（`+o errexit`）で書き写しが増えると、片方の綴りに
        # 書き換えるだけで追跡をすり抜けられるので、記録はここ 1 か所に寄せる。
        # 名前が取れなかった定義は名前で引けないので、何も控えずに戻る
        function record_fn_weaken(name, want_e, want_pipe, we, wp, at, we_at, wp_at) {
            # 名前が無ければ後で引けないため記録しない
            if (name == "") { return }
            # errexit を落とす綴りだったか（本文のどの階層で落としたかも控える）
            if (want_e) { we[name] = 1; we_at[name] = at }
            # pipefail を落とす綴りだったか
            if (want_pipe) { wp[name] = 1; wp_at[name] = at }
        }

        # **本文の中で戻していれば、その関数は呼んでも弱めない。**
        # `run_quietly() { set +e; "$@"; set -e; }` は CI スクリプトの定型句で、
        # 呼んだあとの errexit は**有効なまま**。記録しっぱなしにすると、この定型句が
        # あるだけで以降のスイートがすべて「未配線」と誤報され、**required なジョブが
        # 恒常的に赤くなる**（向きは fail-closed だが、検出網ごと信用されなくなる。
        # レビューで実測）。
        # 打ち消せるのは**同じ階層で落とした分だけ**——`set +e; if x; then set -e; fi` の
        # `set -e` は条件次第でしか走らないので、打ち消すと本物の握り潰しを見落とす
        # （fail-open）。最上位の `weak_depth` / `weak_prev` と同じ考え方を関数ごとの台帳へ移したもの
        function clear_fn_weaken(name, want_e, want_pipe, we, wp, at, we_at, wp_at) {
            # 名前が無ければ台帳に無いので何もしない
            if (name == "") { return }
            # errexit を戻す綴りで、**落としたのと同じか、それより外側（＝より確実に走る）**
            # 階層なら取り消す。等号だけだと `f() { case x in a) set +e ;; esac; set -e; }` の
            # ように、条件付きの階層で落として本文で戻す綴りが打ち消せない
            # （本文の `set -e` は必ず走るので、アームの `set +e` は残らない。
            #   正しくゲートする綴りを赤くする。レビューで実測）。
            # **逆向き（外で落として内で戻す）は打ち消さない**——`set +e; if …; then set -e; fi`
            # の `set -e` は走るとは限らないので、握り潰しは残る（fail-open の防止）
            if (want_e && we[name] && we_at[name] >= at) { we[name] = 0 }
            # pipefail も同じ
            if (want_pipe && wp[name] && wp_at[name] >= at) { wp[name] = 0 }
        }

        # アーム見出しの**綴りを返す唯一の場所**（`close_word_re()` と同じ理由。この綴りは
        # 「見出しで始まるか」の判定・見出しの剥がし・「模様を読み切ったか」の 3 か所が読むので、
        # 写しを持つと片方だけが新しい綴りを知る＝同じ断片への答えが割れる。同ファイルの
        # コメントは、以前そのずれが引用の扱いの食い違いとして現れたと記録している）。
        # **末尾の区切りは付けない**——「見出しで始まるか」は境界（空白 / `;` / 行末）を要求し、
        # 「剥がす」側は後ろの空白ごと落とすので、要求する形が呼び出し側で違う。
        # 先頭の `(` は POSIX のアーム綴り（`(a)`）。`[^()]*` は `(` を跨げないので、
        # 任意扱いで明示しないと丸括弧付きのアームだけ当たらない
        # （当たらないとアーム同士の排他が効かず、別アームの `set -e` が
        #   前のアームの `set +e` を打ち消す。実 bash と差分照合して実測）
        function arm_head_re() {
            return "^\\(?[^()]*\\)"
        }

        # 1 行書きで `case … in ` の前置きが手前に付いた見出しの綴り（issue #142 (4)）。
        # **`[^()]*` は内側の `(` を跨げない**ので、上の綴りだけでは
        # `case $M in (lint) …` に当たらない——`case $M in lint) …`（丸括弧なし）は当たるのに
        # POSIX の綴りだけが外れる非対称で、`case $M in (lint) if false; then <lint>; fi;; esac` の
        # 本体が「偽と分かる条件の中」と判定されず、**1 度も走らない lint が
        # リンタ網の証拠に数えられていた**（実測で gate=1。丸括弧なしと複数行書きはどちらも gate=0）。
        # **`case` を含むことまで要求する**のが要点で、` in ` と `(…)` だけを手がかりにすると
        # `grep -e in (x) …` のような無関係な綴りまで見出しと読み、剥がした先に
        # 偽と分かる条件が現れれば**走る本体を死に体**と判定しうる（向きは fail-closed）。
        # 前置きに丸括弧は現れない（`case` の主語に `$(…)` があれば `[^()]*` が跨げず当たらない）
        # ——その場合は当たらない側＝剥がさない側に倒れるので、幻の階層は作らない
        function arm_head_in_re() {
            return "^([^()]*[[:space:]])?" arm_head_in_core_re()
        }

        # 上の綴りの**`case` から後ろの部分だけ**。前置きの付け方が 2 通りあるので
        # （先頭から見る `arm_head_in_re()` と、断片の途中から探す下の `arm_head_in_search_re()`）
        # 中核をここ 1 か所に置く。**写しを作らないこと**——片方だけ直すと、
        # 「見出しとして剥がす綴り」と「釣り合いから外す `)`」が食い違う
        function arm_head_in_core_re() {
            return "case[[:space:]][^()]*[[:space:]]in[[:space:]]*\\(?[^()]*\\)"
        }

        # 同じ見出しを**断片の途中から探す**綴り（issue #145）。`arm_head_in_re()` の前置き
        # `[^()]*` は `(` を跨げないので、`f() { ( case $X in a)` のように**階層を開く前置き**が
        # 手前に付いた 1 行書きには当たらない。釣り合いの勘定はその形でも崩れる
        # （見出しを閉じる `)` が先頭の `(` を打ち消す）ので、探す側の綴りを別に持つ。
        # **`case` の手前は「命令の位置」に限る**（issue #172）——断片の先頭・グループの開き
        # （`(` / `{`）・区切り（`;` / `&` / `|`）・本体を開く語（`do` / `then` / `else`）の
        # 直後だけを見出しの前置きとして認める。**空白なら何でも良いとしてはいけない**
        # ——`( : case x in y )` のような**散文**（`case` が引数の位置にある綴り）に当たって
        # 本物の括弧を閉じる `)` を落とし、閉じない部分シェルの階層が開く。そうなると
        # そのステップの以降すべての記録が「部分シェルの中」として書かれ、
        # issue #149 の位置の判定（部分シェルの中では飛ばす）が丸ごと外れて
        # 握り潰された実行が「ゲートしている」と読まれる（レビューで実測。fail-open）。
        # issue #145 の対象（`f() { ( case $X in a)`）は `(` の直後なので引き続き当たる
        # （関数定義の見出しを跨ぐ必要が無いのが要点）。`{case` は bash で無効だが
        # `{` の後ろには空白が要るだけなので、開きの文字としては区別せず並べる。
        # **本体を開く語は「断片の先頭」にも来る**（レビュー指摘、実測）——`split_commands` は
        # 断片の前後の空白を落とすので、`then case $X in a) :` のように `then ` で始まる
        # 断片では手前に空白が無い。空白を必須にすると当たらず、#145 の fail-open が
        # そのまま戻る（`f() { ( if true; then case … esac; fi ; bash <スイート> ) }` で
        # 実測: `main` は not-wired・この錨だけでは wired）
        # **残る境界**: 飾り（`time case $X in a)`）は前置きとして認めていない
        # ——倒れる向きは「`)` を落とさない」側で、`main` の #145 以前と同じ扱い
        function arm_head_in_search_re() {
            return "(^|[({;&|]|(^|[[:space:]])(do|then|else)[[:space:]])[[:space:]]*" arm_head_in_core_re()
        }

        # 先頭のアーム見出し（`y)` / `(y)` / `y|z)`）を落として、その後ろ（＝命令の位置）を返す。
        # **位置は伏せた写しで測り、切るのは生の本文**——`starts_case_arm()` と同じ規則で、
        # 揃えないと引用の中の `)`（`"a)b") …`）で剥がす量がずれ、残りが分類できなくなって
        # アームの中の複合コマンドが 1 つも数えられない（後の `done` が `case` の階層を閉じ、
        # 一致しないアームの中身が最上位に上がる fail-open。レビューで実測）。
        # 長さは `mask_quoted()` が保つので、伏せた写しで測った桁をそのまま使える
        function drop_arm_head(t,   masked, re) {
            masked = mask_quoted(t)
            # **模様の位置にそのまま来る形を先に見る。** `a) case x in (b) …` では
            # 外側の見出しだけを落とすのが正しく、順序を逆にすると内側の `case … in (b)` まで
            # まとめて落として `case` の階層が 1 つも開かない（一致しないアームの中身が
            # 最上位に上がる fail-open。`open_head` の剥がしが同じ理由を記録している）
            re = arm_head_re() "[[:space:]]*"
            if (match(masked, re)) { return substr(t, RLENGTH + 1) }
            # 1 行書きで `case … in ` の前置きが手前に付く形
            re = arm_head_in_re() "[[:space:]]*"
            if (match(masked, re)) { return substr(t, RLENGTH + 1) }
            return t
        }

        # **1 行書きのアーム見出しを閉じる `)` を釣り合いから外した写し**を返す（issue #145）。
        # `case $X in a)` の `)` は**対応する `(` を持たない**ので、生の釣り合いでは
        # 手前の `(` を打ち消す。`f() { ( case $X in a) :;; esac ; bash x ) }` では
        # それで先頭の `(` の分が消え、`case` の階層が開かないまま続く `esac` が
        # **関数の階層**を閉じて、呼ばれていない本体が「最上位で確実に走る」として
        # 記録されていた（fail-open。`main` から続く既存の穴）。
        # **`drop_arm_head()` とは別にする**のが要点——あちらは見出し**とその手前すべて**を
        # 落として「命令の位置」を返すので、先頭の `(` まで消えて階層の数え方が割れる。
        # ここで落とすのは**閉じる `)` の 1 文字だけ**で、桁も開きもそのまま残る。
        # **POSIX の綴り（`(a)`）は触らない**——開閉が揃っているので釣り合いは崩れていない。
        # **外すのは 1 つだけ**（`match()` は最初の見出ししか見ない）。ここに
        # 「足りない側＝上限が小さい側は fail-closed なので迷ったらその向きへ」と書いてあったのは
        # **誤りだった**（レビューで実測）——`f() { ( case $X in a) case $Y in b) : ;; esac ;; esac ; bash x ) }`
        # は `wired` のままで、向きは塞ぎたかった fail-open そのもの。
        # **ただし全部外す形に広げても、その綴りは `wired` のままだった**（実測）。原因は釣り合いではなく
        # 「1 つの断片が開く `case` を 1 つしか分類しない」ことで、`;;` が断片を切る以上
        # **裸の見出しが 2 つ並ぶのは `case X in a) case Y in b)` という入れ子の形しかなく、
        # そこは必ずそちらの欠陥に当たる**（＝全部外す形は判定を 1 件も変えない）。
        # 何も変えない仕掛けは「守られている」という誤解を生むので入れず、issue #154 で追う。
        # **「外し足りない側は安全」とも書き戻さないこと。**
        function drop_arm_head_close(t,   masked, head, at, kw) {
            masked = mask_quoted(t)
            # 見つからなければ触らない（釣り合いは生のまま＝これまでの挙動）
            if (!match(masked, arm_head_in_search_re())) { return t }
            # **`RSTART` / `RLENGTH` は読んだ直後に控える**（後続の `substr()` / `index()` で壊れうる）
            at = RSTART + RLENGTH - 1
            kw = RSTART
            # **探す綴りは `case` の手前の 1 文字（行頭・空白・`(`）も取り込む。**
            # その 1 文字は見出しの一部ではないので、含めたまま `(` を探すと
            # `(case $X in a)`（`(` と `case` のあいだに空白が無い形。bash では有効）が
            # **POSIX の綴りと誤判定され**、issue #145 の fail-open がそのまま残る（レビューで実測）
            if (substr(masked, kw, 4) != "case") { kw++ }
            head = substr(masked, kw, at - kw + 1)
            # `(` を含む＝POSIX の綴りなので釣り合いは崩れていない
            if (index(head, "(") > 0) { return t }
            # 見出しを閉じる `)` の 1 文字だけを落とす（長さ以外は変えない）
            return substr(t, 1, at - 1) substr(t, at + 1)
        }

        # この断片が、**自分で開いた `case` の模様まで読み切ったか**を返す。
        # `set_arm_here` で代用してはいけない——あれは「**囲っている** `case` のアーム見出しで
        # 始まるか」で、`a) case $Y in` のように外側のアームの中で内側の `case` を開く綴りで
        # 真になるのに、内側の模様はまだ来ていない。逆に「断片が `in` で終わるか」で見ると、
        # 1 行書きで模様が `|` に切られた `case X in (aa|done|cc)` を取りこぼし、
        # 模様の途中の閉じ語（`done`）が `case` の階層を閉じてしまう
        # （一致しないアームの中身が最上位に上がる fail-open。どちらもレビューで実測）。
        # 判定は `case … in ` の**後ろ**にアーム見出しを閉じる `)` があるか（伏せた写しで測る）
        function case_arm_consumed(t,   masked, from, rest) {
            masked = mask_quoted(t)
            # そもそも `case` を含まなければ、模様の話ではない
            # **一番内側＝最後の `case` を探す。** 1 行に入れ子で書くと外側の `case` が
            # 先に来るので、最初の 1 つで測ると外側の消費済みの模様を答えてしまい、
            # 内側のアームの位置が立たない（そのアームの `set +e` が捨てられる fail-open。
            # レビューで実測）
            from = masked
            while (match(from, /(^|[[:space:]])case[[:space:]]/)) { from = substr(from, RSTART + RLENGTH) }
            # 1 度も当たらなければ `case` を含まない＝模様の話ではない
            if (from == masked) { return 0 }
            # **`case` の後ろの最初の `in` を探す**。1 本の貪欲な正規表現で測ると
            # 断片の中の**最後**の `in`（`match) echo hello in` の裸の `in` など）に
            # 引っ張られ、消費済みの模様を「まだ来ていない」と読む（fail-open。レビューで実測）
            if (!match(from, /[[:space:]]in([[:space:]]|$)/)) { return 0 }
            # `in` の後ろが模様の位置
            rest = substr(from, RSTART + RLENGTH)
            # 見出しを閉じる `)` まで来ていれば、この断片で模様は消費済み。
            # **ここは `in` の後ろを見ているので前置き付きの綴りは要らない**
            # （綴り自体は `arm_head_re()` が唯一の源。写しを持つと答えが割れる）
            return (rest ~ (arm_head_re() "([[:space:]]|;|$)"))
        }

        # `case` を開く語の綴りを返す**唯一の場所**（`close_word_re()` / `function_head_re()` と同じ理由）
        function case_word_re() {
            return "^case([[:space:]]|$)"
        }

        # **この綴りが `case` を開くかを返す唯一の判定。** `open_form()` が分類に使うのと
        # **同じ剥がし方**（`strip_struct_wrappers()`）を通すのが要点——生の綴りへ当てると
        # `time case $X in …` / `! case $X in …` は分類では形 2（`case`）なのにこちらでは
        # `case` と読まれず、`case_depth` も `arm_expected` も立たないまま**アーム模様の `)` が
        # 部分シェルの閉じとして数えられる**（一致しないアームの中身が「最上位で確実に走る」に
        # 化ける fail-open。2 語足すだけで「最上位だけ」の絞り込みを迂回できた。レビューで実測）。
        # 綴りそのものは `case_word_re()` が唯一の源のまま（写しを増やさない）
        function opens_case_word(t) {
            return (strip_struct_wrappers(t) ~ case_word_re())
        }

        # `case` を閉じる語の綴りを返す**唯一の場所**
        function esac_word_re() {
            return "^esac([[:space:]]|;|$)"
        }

        # 複合コマンドを閉じる語の綴りを返す**唯一の場所**（`function_head_re()` と同じ理由。
        # この一覧は深さの勘定と `case` の入れ子の勘定の 2 つの走査が読むので、写しを持つと
        # 片方だけが新しい綴りを知る＝`depth` と `case_depth` がずれる。同ファイルの分析に
        # よれば、そのずれはアームの `set +e` を捨てる fail-open として現れる）
        function close_word_re() {
            return "^(fi|done|esac|\\})([[:space:]]|;|$)"
        }

        # 先頭の閉じ語 1 つ分（と後ろの `;` / 空白）を落として返す。落とせなければ元のまま返す
        # ので、呼び出し側は「変化が無ければ打ち切る」で無限ループを避けられる
        function drop_close_word(t,   s2) {
            s2 = t
            sub(/^(fi|done|esac|\})[[:space:]]*;?[[:space:]]*/, "", s2)
            return s2
        }

        # いまいる階層を内側から外側へたどり、**一番内側の部分シェルの階層**を返す（無ければ 0）。
        # もとは「部分シェルの中で握り潰された最後のコマンド」を覚える台帳のために入れたが
        # （issue #152）、**その台帳は issue #199 で削除した**。いまの消費側は
        # `sub_id[...]`（`set` の帳簿が使う部分シェルの同一性）と `sub_lead_in` の 3 か所で、
        # どれも「最後のコマンド」は覚えていない——失敗を追うときに候補の台帳を探さないこと
        function enclosing_subshell_depth(d, at) {
            return innermost_marked_depth(d, at)
        }

        # **いまいる階層を内側から外側へたどり、印（`at[]`）が立つ最初の階層を返す**（無ければ 0）。
        # 部分シェルの印と「走るか分からない」印で同じ歩きが要るので 1 か所に寄せてある
        # （同じ本体を 2 つ持つと、片方だけに「閉じた階層は見ない」などの条件が付く）。
        # 呼び出し側は**何の印を渡したか**で意味が決まるため、名前では `subshell` 側の
        # 包みを残してある（`enclosing_subshell_depth`。読み手が印の種類を取り違えないため）
        function innermost_marked_depth(d, at,   k) {
            for (k = d; k >= 1; k--) { if (at[k]) { return k } }
            return 0
        }

        # その断片が**コマンドを 1 つでも走らせるか**。閉じ語・閉じ括弧・区切りだけの断片
        # （`)` / `} )` / `done )` / `fi ;`）は何も走らせないので偽を返す（issue #152）。
        # **近似であることを承知で使う。** 消費側は 4 つで（issue #199 で引き上げを削除したので
        # もう「引き上げを見送る／してしまう」ではない。**4 つ目は包み `carries_own_command()`
        # 経由**なので `carries_command(` の grep では出ない——8 巡目のレビューで「3 つ」が
        # 誤りだと分かった）、**取り違えの向きは消費側ごとに違う**:
        #   - 偽と分かる枝の解除（`dead_depth`）: 照合する深さを選ぶ側なので**真と読みすぎると
        #     解除が遅れる**（閉じる前の深い方で照合するため）＝走る記録まで死に体として捨て、
        #     正しくゲートしているスイートが一覧から消える（fail-closed）。**早く解除して
        #     「必ず走る」と読むのは偽と読みすぎた側**（下の段落が実測として記録している向き）。
        #     レビュー指摘で測り直した: `carries_command` を常に真にすると
        #     `for … do set +e; if false; then exit 1; fi; set -e; bash <スイート>; done` の
        #     スイートが一覧から 0 件になり、常に偽にすると残る
        #   - コマンドが走る階層の算定（`run_depth`）: 取り違えると記録が別の階層に載る（両向き）
        #   - ステップ最後のコマンドの照会: 真と読みすぎると「後ろにコマンドがある」と読む（fail-closed）
        #   - 無条件の脱出の判定（`carries_own_command()` → `cmd_seen` → `preceded_here`）:
        #     真と読みすぎると「手前でコマンドが走った」と読む（向きは下の `carries_own_command()`
        #     の説明が正本。あちらは開き記号を数えないので、この述語とは答えが違う）
        # 落とす綴りは `close_word_re()` が持つ閉じ語と括弧・区切りだけに限る（広げると
        # 上の 4 つへ別々の向きで波及する）
        function carries_command(t,   s2, before, closed, dropped) {
            s2 = t
            closed = 0
            while (1) {
                before = s2
                sub(/^[[:space:]]*/, "", s2)
                if (sub(/^[);]+[[:space:]]*/, "", s2)) { closed = 1 }
                # **閉じ括弧に付いたリダイレクトは終了状態を変えないのでコマンドに数えない**
                # （issue #152 のレビュー指摘。当時の消費側は引き上げで、`) >/dev/null` を
                #  「後ろにコマンドがある」と読むと引き上げを見送っていた——**その機構は
                #  issue #199 で削除した**ので、いま同じ取り違えが出る先は上の一覧の
                #  「ステップ最後のコマンドの照会」で、向きは変わらず fail-closed＝実測）
                # **ただし閉じ括弧を伴わない裸のリダイレクトは 1 つのコマンド**で、`$?` を 0 に
                # する（レビュー指摘、実測）。区別しないと `bash <スイート> && echo ok` の次の行に
                # `> out` だけを置いた形で「連鎖がステップの最後」と読まれ、握り潰された実行が
                # ゲートしていると報告される
                if (closed) { sub("^" redirect_lead_re "[[:space:]]*", "", s2) }
                dropped = drop_close_word(s2)
                if (dropped != s2) { closed = 1; s2 = dropped }
                if (s2 == before) { break }
            }
            return (s2 != "")
        }

        # **その断片が自分で何かを走らせるか**（開くだけの `(` / `{` は数えない）。
        # `carries_command()` は「後ろにコマンドがあるか」を測る述語なので開き記号も
        # 非空として数えるが、脱出の判定が要るのは「手前で**実際に走って `$?` を
        # 置き換えた**コマンドがあるか」で、開くだけの断片はそれに当たらない
        # （数えると `|| (` 改行 `exit` 改行 `exit 1` 改行 `)` の素の `exit` が
        #  「手前のコマンド次第」に落ち、必ず非 0 で抜ける形を握り潰しと読む fail-closed）
        function carries_own_command(t,   s2) {
            s2 = t
            # 開き記号（`(` / `{` / `!`）を落としてから中身を見る
            while (sub(/^[[:space:]]*[({!][[:space:]]*/, "", s2)) { }
            return carries_command(s2)
        }

        # 内側から見て、**走るかどうかがそこで決まる**一番内側の階層を返す（無ければ 0）。
        # 関数の台帳で「同じところで落として戻したか」を測るのに使う。
        # **素の深さでは測れない**（ブレースグループや `if true` の本体は同じシェルで必ず走るので、
        # そこで戻した `set -e` は本文で戻したのと同じ）。**関数の階層まで一気に畳んでもいけない**
        # ——`f() { set +e; if [ -n "$X" ]; then set -e; fi; }` の `set -e` は条件次第でしか
        # 走らないのに打ち消しが成立し、握り潰された関数が「戻している」と読まれる
        # （fail-open。レビューで実測）。そこで**走るか分からない階層（`uncertain_at`）と
        # 関数定義の階層（`fndef_at`）で止まり、必ず走る階層は透かす**
        function enclosing_scope_depth(d, unc_at, fn_at,   k) {
            for (k = d; k >= 1; k--) { if (unc_at[k] || fn_at[k]) { return k } }
            return 0
        }

        # いまいる階層を内側から外側へたどり、最も近い関数定義の名前を返す（無ければ空文字）。
        # `fndef_at[]` が立っている階層だけを見るので、閉じた階層に残った名前は拾わない
        # （閉じ側の後始末を 2 か所へ増やさないための決め方。issue #121 を悪化させない）
        function enclosing_fndef_name(d, at, names,   k) {
            # 内側（深い方）から順に見て、最初に見つかった定義の名前を返す
            for (k = d; k >= 1; k--) { if (at[k]) { return names[k] } }
            return ""
        }

        # `errexit` を 1 つ分更新し、**落とした階層の記録**（`weak_depth` / `weak_prev`。どちらも大域）も
        # 併せて維持する。短い綴りと長い綴りで記録の有無がずれると、片方の括りだけが
        # 打ち消せずゲートしているステップが「未配線」と誤報されるため、ここ 1 か所に寄せてある。
        # **打ち消しは「1 に戻す」ではなく「落とす前の値へ戻す」**のが要点で、
        # 1 に固定すると内側の括りが**外側でまだ効いている** `set +e` まで消してしまう（fail-open）
        # `cancel` を**引数で受け取らない**のが要点。ループの外で 1 度だけ計算すると、
        # `set +e -e` のように 1 つの語で自分を打ち消す綴りで判定が古いままになり、
        # 2 コマンドに分けた同じ意味（`set +e` 改行 `set -e`）と答えが食い違う
        function apply_errexit(on, strengthen_base, at_uncertain, weaken_ok, current, at, at_sub,   cancel, ok, updated) {
            # 同じ階層で自分が落とした分か（毎回この場で測る）
            # **同じか、それより外側（＝より確実に走る）階層で戻したなら打ち消し。**
            # 等号だけだと、閉じたブレースの外で戻す `{ set +e; }` ＋ `set -e` が
            # 打ち消せない。逆向き（外で落として内で戻す）を認めないのが要点で、
            # `set +e; if …; then set -e; fi` の `set -e` は走るとは限らない（fail-open の防止）
            cancel = (current == 0 && weak_depth >= at && weak_depth >= 0)
            # 強める向きを反映してよいか（確実に走るか、自分で落とした分の打ち消しか）
            ok = (strengthen_base && (at_uncertain == 0 || cancel))
            # 打ち消し（同じ階層で自分が落とした分を戻す）なら、**落とす前の値**へ返す。
            # **1 に固定してはいけない。** 落とす前が -1（＝明示なし）だったとき、1 を返すと
            # 「`set -e` が明示された」と読まれ、`shell: bash {0}` のように `-e` を持たない
            # シェルでも errexit が有効と扱われる。走らないループの中の括りが、
            # 握り潰されたスイートを「ゲートしている」と読ませる（fail-open。実 bash と差分照合して実測）
            # 記録を残すのは「まだ握り潰されていない状態から落とした」ときだけなので
            # （下の `current != 0`）、外側で `set +e` がまだ効いている入れ子はここへ来ない
            # 確実に走ると分かるなら `set -e` は「明示された」ので 1。
            # 分からないときだけ落とす前の値へ戻す（`shell: bash {0}` のように
            # `-e` を持たないシェルで、明示された `set -e` を捨てないため）
            if (on && cancel && ok) { weak_depth = -1; return (at_uncertain == 0) ? 1 : weak_prev }
            # それ以外は通常の適用（`next` は awk の予約語なので使わない）
            updated = set_flag(on, ok, weaken_ok, current)
            # 新しく落としたなら、その階層と落とす前の値を控える
            # **どの部分シェルの中で落としたかも控える**（issue #152 のレビュー指摘）。
            # 深さの数値だけでは、閉じたブレースと同じ深さに開いた部分シェルを
            # 区別できず、ブレースの中で落とした分が「この部分シェルの中で落とした」
            # ことになる（`{ set +e; }` ＋ `( set -e; … )` が wired に化けた＝実測）。
            # 階層ごとに振る連番（`sub_id`）で同一性を見る（0 は「部分シェルの外」）
            if (!on && updated == 0 && current != 0) { weak_depth = at; weak_prev = current; weak_sub = at_sub }
            return updated
        }

        # その断片が `case` のアーム見出しで始まるか（`y)` / `(y)` / `y|z)`、
        # および 1 行書きで `case … in ` の前置きが手前に付いた `case $M in (y) …`）。
        # **伏せた本文で測る**——引用の中の `) `（`echo "a) b"`）をアームと読むと、
        # 深さの勘定と括りの記録の両方が狂う。同じ規則が 3 か所にあったので 1 つへ寄せた
        # （うち 1 か所は生の本文で測っており、引用の扱いが食い違っていた）
        function starts_case_arm(t,   masked, tail) {
            masked = mask_quoted(t)
            # 境界（空白 / `;` / 行末）まで要求する。綴りは `arm_head_re()` /
            # `arm_head_in_re()` が唯一の源（剥がす側と同じものを読む）
            tail = "([[:space:]]|;|$)"
            return (masked ~ (arm_head_re() tail)) || (masked ~ (arm_head_in_re() tail))
        }

        # 先頭の飾りを落として `set …` そのものを返す。該当しなければ空文字。
        # **落としてよいのは「現在のシェルのまま `set` を呼ぶ」書き方だけ**——
        # ブレースグループ / 変数代入の前置き / `builtin` / `command` / `eval`。
        # `CI_WORKFLOW_COMMAND_PREFIXES` の実行ラッパ一覧（`sudo` / `env` / `timeout` 等。
        # `CI_WORKFLOW_COMMAND_START` と `CI_WORKFLOW_BLOCK_BODY_START` がそこを読む）は
        # **意図的に共有しない**。あちらは「スクリプトを走らせるか」を問う側の一覧で、
        # どれも別プロセスを起こすため `set` を渡しても親のオプションは変わらない
        # （`sudo set +e` は握り潰しではない）。同じ一覧にすると fail-closed 側に化ける
        function set_command(t,   probe) {
            # 飾りを落とす。`set` は特殊組み込みなので `command` / `builtin` 経由でも
            # 現在のシェルで走る＝落としてよい（第 2 引数が 1）
            probe = strip_command_prefixes(t, 1)
            # 飾りを落とした先が `set` でなければ、この断片に `set` は無い
            return (probe ~ /^set([[:space:]]|$)/) ? probe : ""
        }

        # 先頭の飾りを落として「実際に走る命令」の先頭を返す。**`set` を探す側と
        # 関数の呼び出しを探す側が同じ一覧を通る**ようにするための共通部分で、
        # 一覧を 2 か所に分けると片方にしか無い綴りで検出をすり抜けられる
        # （`{ f; }` の 2 文字で呼び出しの追跡が外れていた。レビューで実測）。
        # `strip_lookup_bypass` は `command` / `builtin` を落としてよいかどうか——
        # この 2 つは**シェル関数の探索を飛ばす**綴りなので、`set` のような組み込みを
        # 探すときは落としてよいが、関数の呼び出しを探すときに落としてはいけない
        # （`command f` は関数 f ではなく外部コマンド f を探す。実 bash と差分照合して実測）
        function strip_command_prefixes(t, strip_lookup_bypass,   probe) {
            probe = t
            # 剥がせるものが無くなるまで繰り返す（入れ子で重なることがある）
            while (1) {
                # ブレースグループは同じシェルで走る
                if (sub(/^\{[[:space:]]+/, "", probe)) { continue }
                # `VAR=x set +e` の前置き（特殊組み込みなので代入も残るが、要点は `set` が走ること）
                if (sub(/^[A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*[[:space:]]+/, "", probe)) { continue }
                # 同じ組み込みをそのまま呼ぶ書き方（関数を探すときは落とさない。上の説明を参照）
                if (strip_lookup_bypass && sub(/^(builtin|command)[[:space:]]+/, "", probe)) { continue }
                # **条件の位置も命令の位置。** `if set +e; then …` の `set` は条件として
                # 現在のシェルで走るので、握り潰しはそのまま効く（実 bash と差分照合して実測）。
                # `struct_text` 側では剥がせない——あちらは `if` が 1 階層開くことを数える
                # ための本文で、剥がすと深さの勘定が壊れる。**`set` と呼び出しを探す側でだけ**落とす
                if (sub(/^(if|elif|while|until)[[:space:]]+/, "", probe)) { continue }
                # `eval` は現在のシェルで走るので、引用を外して中身を見る
                if (sub(/^eval[[:space:]]+/, "", probe)) { gsub(/["\047]/, "", probe); continue }
                # `\set` はエイリアス展開を止めるだけで、呼ぶ組み込み・関数は同じ
                if (sub(/^\\[[:space:]]*/, "", probe)) { continue }
                # `! set +e` は終了状態を反転するだけ。オプションの変更はそのまま効く
                if (sub(/^![[:space:]]+/, "", probe)) { continue }
                # `time` は計測するだけで、組み込み・関数は現在のシェルで走る
                if (sub(/^time[[:space:]]+(-p[[:space:]]+)?/, "", probe)) { continue }
                # 先頭に置いたリダイレクトも前置きであって別プロセスではない
                if (sub("^" redirect_lead_re "[[:space:]]+", "", probe)) { continue }
                break
            }
            return probe
        }

        # **後ろの制御構造を「開き 1 つ」として数えるのを邪魔しない飾り**だけを落として返す。
        # 落とすのは `time` / `!` の 2 つで、どちらも**自分では階層を開かない**うえ、
        # 後ろに続く制御構造の条件がそのまま本体の運命を決める
        # （`time if false; then X; fi` も `! if false; …` も X は 1 度も走らない。
        #  `!` は終了状態を反転するだけ、`time` は計測するだけ）。
        # **`eval` を落とさない理由は下の段落が記録している**（引用で包んだ形を毒するため）。
        #
        # **`(` は入れない。** 部分シェルの階層は釣り合い（`paren_delta()`）が別に数えるので、
        # ここで落として `open_form()` が後ろの `if` も形 2 として返すと、1 つの断片で
        # 同じ階層を二重に開く（`set` の記録・`case` の模様・関数の台帳がすべて 1 つずれる）。
        # 偽と分かる条件を見るだけの判定は `strip_dead_cond_prefixes()` が `(` も落とす
        # ——あちらは深さを動かさないので二重に数える心配が無い。
        #
        # **`strip_command_prefixes()` とは別にする。** あちらは `if|elif|while|until` を
        # 落として「実際に走る命令」を返すので、ここで使うと**分類したい制御構造の語そのもの**が
        # 消える。ブレースグループ（`{ `）も落とさない——`open_form()` が階層として数える綴りで、
        # 剥がすと深さの勘定と食い違う
        #
        # **`!` を剥がしたかどうかは `STRUCT_INVERTED` へ控える**（`mask_quoted()` の
        # `MASK_*` / `cross_lead_subshells()` の `LEAD_SUBSHELLS` と同じ、awk で
        # 2 つ目の戻り値を返す形）。本体が走るかは変わらないが、**失敗がジョブへ伝わるかは
        # 変わる**ので、「必ず走る」の印（`true_at`）を置く側がこれを見る必要がある。
        # 呼び出し側で綴りを書き写して判定しないこと——この関数が剥がす綴りの唯一の源だから
        function strip_struct_wrappers(t,   probe) {
            probe = t
            # 前の呼び出しの結果が残らないよう、毎回ここで戻す（fail-closed 側は 0）
            STRUCT_INVERTED = 0
            # 剥がせるものが無くなるまで繰り返す（`! time if false` のように重なる）
            while (1) {
                # `time` は計測するだけで、後ろの制御構造はそのまま走る
                if (sub(/^time[[:space:]]+(-p[[:space:]]+)?/, "", probe)) { continue }
                # `!` は終了状態を反転するだけで、本体が走るかは変えない
                # **重ねた `!` は打ち消し合う**ので真偽を反転する（`1` を代入して掛け金に
                # すると `! ! if true; then <呼び出し>; fi` を「反転されている」と読み、
                # 実際には伝わる失敗を「伝わらない」と判定する——倒れる向きは fail-closed だが、
                # このコメント自身が「`!` は終了状態を**反転**する」と書いているとおり偶奇の話）
                if (sub(/^![[:space:]]+/, "", probe)) { STRUCT_INVERTED = !STRUCT_INVERTED; continue }
                break
            }
            return probe
        }

        # **連鎖（`&&` / `||`）の左辺が真偽どちらに決まるかを返す**（`"t"` / `"f"` / 不明なら `""`）。
        # 判定の前に**先頭のグループの開き（`(` / `{`）・末尾の閉じ・飾り（`time` / `!`）を落とす**
        # のが要点。生の綴りで `true` と比べていた頃は、`( true && <呼び出し>` の左辺が
        # 「真と分かる」に当たらず、連鎖を「走るか分からない」に数える側（issue #150）が
        # **実際には必ず走る呼び出しを「未配線」と報告**していた（実測で `( … )` と `{ … }` の
        # 8 形。`&&` / `||` の向きが分かる形はすべてここを通る）。
        # **`!` は真偽を反転する**（`! true && x` の `x` は走らない。実 bash で確認済み）。
        # 落とす綴りの源は `strip_struct_wrappers()` と `CI_WORKFLOW_GROUP_OPENERS` 側にあり、
        # ここでは「開きと閉じの記号」だけを自分で見る——`split_commands` が切った断片は
        # 釣り合っていないことがあるので、釣り合いの判定には使えない（開きの数は数えない）
        # **判定の前の正規化だけを行い、残った綴りを返す**（`chain_literal_status()` と
        # `chain_never_succeeds()` が共有する。§6 DRY——写しを 2 つ持つと、落とす綴りを
        # 直したときに片方だけが古くなる）。反転の偶奇は `CHAIN_PROBE_FLIP`、
        # 算術コマンドだったかは `CHAIN_PROBE_ARITH` に載せる
        function chain_status_probe(t,   probe, before, aprobe) {
            probe = t
            # 反転の回数（偶奇）を持つ。`! !` は打ち消し合う
            CHAIN_PROBE_FLIP = 0
            CHAIN_PROBE_ARITH = 0
            # 剥がせるものが無くなるまで交互に落とす（`( ! true` のように重なる）
            while (1) {
                before = probe
                # `time` / `!` を剥がし、`!` を剥がしたぶんだけ真偽を反転する
                probe = strip_struct_wrappers(probe)
                if (STRUCT_INVERTED) { CHAIN_PROBE_FLIP = !CHAIN_PROBE_FLIP }
                # **算術コマンド（`(( … ))`）は読まない。** 丸括弧を 2 つ落とすと中身が
                # 「コマンドとしての `true`」に見えるが、算術の真偽は**変数の値**で決まる
                # ——`(( true ))` は未設定の変数 `true` を 0 と読むので終了状態は 1（偽）。
                # 読むと向きが逆の判定になり、`! (( true )) && set +e` の `set +e` を
                # 「走らない」と数えて握り潰されたスイートを「ゲートしている」と読む
                # （`main` には無い、この差分が入れかけた退行。レビューで実測）
                # **算術コマンドは真偽を読まない**が、**本文は控える**（issue #183）。
                # 読む側（`chain_never_succeeds()`）だけが、10 進の整数リテラルという
                # 疑いの余地が無い形に限って使う。ここで真偽まで決めてしまうと
                # `chain_literal_status()` 側の「読めないなら値を主張しない」が壊れる
                if (probe ~ /^\(\(/) {
                    CHAIN_PROBE_ARITH = 1
                    CHAIN_PROBE_ARITH_BODY = ""
                    aprobe = probe
                    # `(( … ))` を両端から外せたときだけ本文として控える（外せない綴りは
                    # 読めない扱い）。末尾の `;` は `split_commands` が落とし切らない形に備える
                    if (sub(/^\(\(/, "", aprobe) && sub(/\)\)[[:space:]]*;?[[:space:]]*$/, "", aprobe)) {
                        CHAIN_PROBE_ARITH_BODY = trim(aprobe)
                    }
                    return ""
                }
                # 先頭のグループの開きを 1 つ落とす。**綴りは `CI_WORKFLOW_GROUP_OPENER` が源**
                # で、`{` の後ろの空白は必須（`{true` は bash として成り立たない綴りなので、
                # 落とすと `{true && <呼び出し>` を「真と分かる」と読んでしまう。レビューで実測）
                sub("^[[:space:]]*" group_open_re, "", probe)
                # 何も落ちなければ終わり（必ず短くなるので止まる）
                if (probe == before) { break }
            }
            # 末尾の閉じと区切りを落とす（`( true )` の中身を見るため）。
            # **`}` は落とさない**——`{ true; }` は `;` で切られるので左辺は `}` だけの断片になり
            # （下記の残る境界）、落として得るものが無い一方、`{ echo a; true } && …` のように
            # **bash が解析できない綴り**を「真と分かる」と読む口になる（レビューで実測）
            # **閉じと閉じのあいだに空白があっても落とす**（レビュー指摘。実測）。
            # `[;)]*` は空白を跨げないので `( ( <呼び出し> || false ) )` の右辺は
            # `false ) )` のまま読めず、**空白を 1 つ詰めた同じプログラムとだけ答えが
            # 食い違う**（前者 not-wired ・ 後者 wired。真値はどちらも GATES）
            # **残る境界（この広げ方が持ち込んだ fail-open）**: 落とす数に上限が無いので、
            # 閉じが余る綴り（`|| ( ( false ) ) )` ・ `|| ( false ) )` など）も `false` まで
            # 削れて「成功しえない」と読まれ wired になる（真値 NOGATE。`main` は
            # not-wired）。**ただしこれらは bash が解析できない**——`bash -n` が
            # 「syntax error near unexpected token `)`」で落ち、スイートが成功しても
            # step は非 0 で終わるので**毎回必ず赤**になり、スイートの省略を隠せない
            # （issue #206 と同じ「すでに走らないワークフローについて誤った答えを返す」
            # 類型）。釣り合いを数えて閉じようとすると、**手前の断片で開いた階層を
            # 閉じる正当な断片**（`( set +e; bash <スイート> )` の末尾など）まで
            # 読めなくなり、正しくゲートしている綴りを赤くする側へ倒れる——
            # 階層の深さはこの純粋な文字列ヘルパーからは見えないので、近似を増やさず
            # 境界として記録する（issue #206 に記録済み）
            sub(/[[:space:]]*([;)][[:space:]]*)*$/, "", probe)
            return trim(probe)
        }

        function chain_literal_status(t,   probe) {
            probe = chain_status_probe(t)
            # **ここでは算術コマンドを読まない**（`chain_never_succeeds()` は整数リテラルを
            # 読むが、あちらとは問いが違う。issue #183）。この関数が決めるのは
            # 「次の断片が走るか」で、読めない綴りで値を主張すると**走らない呼び出しを
            # 実行の証拠に数える** fail-open になる（`chain_status_probe()` の説明が
            # 記録している退行がまさにそれ）。
            # **整数リテラルの読みをここへ広げる変異は、1 件もピンを落とさない**（実測）
            # ——`(( 1 )) && <呼び出し>` のような形が未配線になる原因は連鎖側の
            # `uncertain` で、真偽を読めても答えが変わらないため。**答えを変えないから
            # 広げてよいのではなく、広げても得が無いうえ上の fail-open の口が開く**ので
            # 広げない。ピンで止められない境界なので、規約とレビューで守る
            if (CHAIN_PROBE_ARITH) { return "" }
            # `true` / `:` は真、`false` は偽。反転されていれば入れ替える
            if (probe == "true" || probe == ":") { return CHAIN_PROBE_FLIP ? "f" : "t" }
            if (probe == "false") { return CHAIN_PROBE_FLIP ? "t" : "f" }
            # それ以外は読めない（`""`＝走るか分からない側へ倒す。fail-closed）。
            # **残っている境界**: `{ true; } && <呼び出し>` は左辺が `}` だけの断片になるので
            # 読めない（`split_commands` が `;` で切る）。グループの終了状態は最後に走った
            # コマンドのものなので「直前の状態を引き継ぐ」形は書けるが、**連鎖の切れ目を
            # 判定する側（`prev_op` が `&&` / `||` でなければ状態を捨てる）が先に走るので
            # 引き継ぎだけでは何も変わらない**（実測。1 度入れて外した）。
            # 切れ目の判定ごと変えると `set` の到達判定まで動くので、この 1 形は
            # fail-closed のまま残す（`( true ) && …` は括弧が同じ断片に載るので読める）
            return ""
        }

        # **その綴りが「成功しえない」なら 1 を返す**（`||` の右辺が並びの失敗を
        # 握り潰せるかを見る側。issue #174 のレビュー指摘）。`||` の右辺が成功すれば
        # 並びの終了状態は 0 になり左辺の失敗は消えるが、**右辺自身が必ず失敗する綴り**
        # （`false` / `exit 1` / `exit` / `return 1`）なら並びはいつでも失敗するので、
        # 失敗は握り潰されずに伝わる（実測で GATES）。ここを「偽と分かる綴り（`false`）
        # だけ」にすると `bash <スイート> && echo ok || exit 1` を未配線と報告する
        # ——**正しく配線されている綴りを赤にする fail-closed**（`main` は wired と答えており、
        # issue #174 の差分が入れた退行。レビューで実測）
        # **`exit` / `return` は 0 を明示したときだけ成功する**。引数が無ければ `$?`
        # （＝直前の失敗）で終わるので失敗、数値以外（`exit $rc`）は読めないので
        # 「成功しえない」側へ倒す——`||` の枝の `exit` は失敗を伝えるために書くのが
        # ほぼすべてで、握り潰し扱いにすると上と同じ fail-closed になる
        # **脱出の綴りをここで一手に引き受ける**（レビュー指摘。§6 一元管理）。
        # 以前は同じ正規表現が 5 か所に写してあり、**1 か所だけ広げ忘れた**ために
        # `exit "$?"`（shellcheck が勧める引用形）が「読めない引数」に落ちて
        # 正しくゲートしている綴りを赤くしていた。綴りを足すときはここだけを直す。
        # 戻り値は脱出の綴りなら整形後の本文、そうでなければ空文字
        function escape_probe(t,   probe) {
            probe = chain_status_probe(t)
            if (probe !~ /^(exit|return)([[:space:]]+[^[:space:]]+)?$/) { return "" }
            return probe
        }
        # **引数が「直前の状態をそのまま持ち出す」綴りか**（引数なしと `$?` の 4 綴り）。
        # `||` の右辺が走るのは左辺が落ちたときだけなので、どちらも必ず非 0 で終わる。
        # 引用の有無と波括弧の有無で 4 通りあり、どれも実測で GATES
        function escape_arg_carries_status(probe) {
            return (probe ~ /^(exit|return)([[:space:]]+("\$\?"|\$\?|"\$\{\?\}"|\$\{\?\}))?$/) ? 1 : 0
        }
        # **引数が 10 進の数値リテラルか**（剰余の規則は `escape_literal_status()` が持つ）
        function escape_arg_is_literal(probe) {
            return (probe ~ /^(exit|return)[[:space:]]+[0-9]+$/) ? 1 : 0
        }
        # **途中で成功して抜けうる脱出か**（issue #191 のレビュー後に実測で見つけた 3 つ目の穴）。
        # `||` の右辺が複合のとき「成功しえない」と言えるのは**最後のコマンドが成功しえない**
        # ことに加えて、**その手前に成功して抜ける脱出が無い**ときだけ。`bash <スイート> ||`
        # `( exit 0` / `exit 1 )` は最後が `exit 1` でも `exit 0` で抜けるので並びは成功し、
        # 実 `bash -e` は NOGATE（握り潰し）なのに「ゲートしている」と答える fail-open になる。
        # 引数が読めない `exit` は「成功しうる」側＝握り潰し側へ倒す（`main` と同じ答え）
        function escape_can_succeed(t, preceded,   probe) {
            probe = escape_probe(t)
            # 脱出の綴りでなければ関係ない（普通のコマンドは階層を抜けない）
            if (probe == "") { return 0 }
            # 0 以外の数値リテラルなら必ず失敗する（抜けても並びは失敗する）。
            # **剰余の規則は `escape_literal_status()` が唯一の源**（`exit 256` は成功して抜ける）
            if (escape_arg_is_literal(probe)) { return (escape_literal_status(probe) == 0) ? 1 : 0 }
            # **引数が読めない脱出（素の `exit` / `exit $rc`）は手前のコマンド次第**
            # （レビュー指摘。`chain_never_succeeds()` は別の問いに答える関数で、読めない
            #  引数を「成功しえない」側へ倒すため、そのまま委ねると `|| (` / `echo cleanup` /
            #  `exit` / `)` が wired になる＝実 `bash -e` は NOGATE で fail-open）。
            # この印を読むのは `||` の右辺だけで、右辺が走るのは**左辺が落ちたとき**なので、
            # 手前に何も走っていなければ直前の状態＝左辺の失敗を引き継いで必ず非 0 で抜ける。
            # 手前に走ったコマンドがあればその状態は読めないので「成功しうる」側＝握り潰し側
            # （`main` と同じ答え）へ倒す
            return preceded ? 1 : 0
        }
        # **脱出の数値リテラルが実際に残す終了状態**（待機状態は 8 ビットなので 256 で割った余り）。
        # `escape_can_succeed()` / `chain_never_succeeds()` / `||` の歩きが同じ規則を読む（§6 DRY）
        function escape_literal_status(probe,   arg) {
            arg = probe
            # `exit` / `return` と空白を落として引数だけにする
            sub(/^(exit|return)[[:space:]]+/, "", arg)
            # 数値として読んで 256 の剰余を返す（`exit 256` は 0、`exit 300` は 44）
            return (arg + 0) % 256
        }
        # **引数の終了状態が読めない脱出か**（`exit $rc` / `exit "${code}"`）。
        # 素の `exit` と `exit $?` は読める——`||` の右辺が走るのは**左辺が落ちたとき**だけで、
        # どちらも `$?`（＝その失敗の状態）で終わるので必ず非 0 になる。
        # それ以外の変数・式は 0 にもなりうるので、`||` の歩きは**握り潰し側＝未配線**へ倒す
        # （実測: `rc=0` のとき `bash <スイート> || exit $rc` は実 `bash -e` で NOGATE。
        # 「読めないなら失敗を伝える」と読むと**1 件も走らないスイートが「ゲートしている」**になる）
        function escape_status_unreadable(t,   probe) {
            probe = escape_probe(t)
            # 脱出でなければこの問いの対象外
            if (probe == "") { return 0 }
            # 引数なし・`$?` の 4 綴りは左辺の失敗をそのまま持ち出すので読める
            if (escape_arg_carries_status(probe)) { return 0 }
            # 数値リテラルも読める
            if (escape_arg_is_literal(probe)) { return 0 }
            # 残りは読めない
            return 1
        }
        # **そのシェルを必ず終わらせる脱出か**（`exit` だけ。`return` は呼び出し元へ戻るだけ）。
        # `exit` は errexit の有無も並びの位置も問わずその場でシェルを終えるので、
        # `set +e` の下でも、後ろに行があっても、終了状態はその `exit` のものになる
        # （実測: `set +e` / `bash <スイート> || exit 1` / `echo done` は GATES。
        # 位置と errexit を見ていたので未配線＝正しくゲートしている綴りを赤くしていた）
        function exit_ends_shell(t, probe, head) {
            probe = chain_status_probe(t)
            # `exit` 以外（普通のコマンド・`return`）は対象外
            if (probe !~ /^exit([[:space:]]+[^[:space:]]+)?$/) { return 0 }
            # **手前で部分シェルを開いている綴りは対象外**（実測で見つけた穴）。
            # `chain_status_probe()` は開き括弧も落とすので、`{ ( exit 1 )` のように
            # 1 断片で部分シェルを開く綴りが「同じシェルの `exit`」に見えてしまう——
            # その `exit` が終えるのは部分シェルだけなので、`set +e` の下では
            # 失敗が伝わらない（実 `bash -e` は NOGATE。印を立てると fail-open）。
            # **階層の識別子では判定できない**: 命令の手前で開いた数（`cmd_opens`）は
            # 括弧の開きを数えない経路があり、記録の階層が部分シェルではなく
            # 外のグループになる（実測）。綴りの手前に `(` があるかで見る
            head = t
            sub(/exit.*$/, "", head)
            if (head ~ /\(/) { return 0 }
            # 読める数値リテラルで 0 になるなら「成功して終わる」ので別扱い
            if (escape_arg_is_literal(probe)) { return (escape_literal_status(probe) != 0) ? 1 : 0 }
            # 引数なし・`$?` の 4 綴りは非 0（上の `escape_status_unreadable` と同じ理由）
            if (escape_arg_carries_status(probe)) { return 1 }
            # 読めない引数は主張しない
            return 0
        }
        function chain_never_succeeds(t,   probe) {
            probe = chain_status_probe(t)
            # **算術コマンドは 10 進の整数リテラルだけ読む**（issue #183）。算術コマンドの
            # 終了状態は「値が 0 なら 1（失敗）・非 0 なら 0（成功）」で、リテラルなら
            # 変数にも演算にも依らず確定する。読まないと `|| (( 0 ))` が握り潰し扱いになり、
            # **並びはいつでも失敗する**のに未配線と報告する（実 `bash -e` は GATES。
            # 正しく配線されている綴りを赤にする fail-closed）。
            # **リテラル以外は `main` と同じ「成功しうる」側へ倒す**（`(( x ))` は変数次第、
            # `(( 1-1 ))` は演算次第）。倒れる向きは握り潰し＝未配線で、**issue が書いていた
            # 「読めないので位置の判定へ落とす」は採れない**——実測すると `|| (( 1 ))` が
            # wired へ動き（実 `bash -e` は NOGATE）、**1 件も走らないスイートが
            # 「ゲートしている」と読まれる fail-open** になる。向きを取り違えないこと
            if (CHAIN_PROBE_ARITH) {
                # **残る境界: 先頭が 0 の綴りは厳密には 8 進**（レビュー指摘、実測）。
                # bash は `(( 08 ))` を "value too great for base" で**必ず失敗**させるので
                # 正しい分類は「成功しえない」だが、ここでは非 0 として読む＝握り潰し側へ倒れる
                # （答えは `main` と同じ not-wired。実 `bash -e` は GATES なので残る fail-closed）。
                # **先頭 0 を読む対象から外す形も書いて測ったが、どちらの枝も「成功しうる」へ
                # 倒れるので答えが 1 件も変わらなかった**——何も変えない仕掛けは置かない規約に
                # 従って入れていない。直すなら 8 進の規則（`08` / `09` はエラーで失敗、
                # `010` は 8 で成功）まで入れて、`(( 08 ))` が wired へ動くことをピンで固定する
                if (CHAIN_PROBE_ARITH_BODY ~ /^[0-9]+$/) {
                    # 0 は必ず失敗（`!` が付いていれば必ず成功）
                    if (CHAIN_PROBE_ARITH_BODY ~ /^0+$/) { return CHAIN_PROBE_FLIP ? 0 : 1 }
                    # 非 0 は必ず成功
                    return CHAIN_PROBE_FLIP ? 1 : 0
                }
                return 0
            }
            # 綴りから真偽が分かる形は `chain_literal_status()` と同じ規則で読む
            if (probe == "true" || probe == ":") { return CHAIN_PROBE_FLIP ? 1 : 0 }
            if (probe == "false") { return CHAIN_PROBE_FLIP ? 0 : 1 }
            # 脱出（`exit` / `return`）は引数で決まる。`!` は見ない——`exit` は戻らないので
            # 反転する相手がいない（`return` に `!` を付ける綴りは実在しないため同じ扱い）。
            # **数値リテラルの終了状態は 256 で割った余り**（レビュー後に実測で見つけた穴）。
            # 待機状態は 8 ビットなので `exit 256` / `exit 512` は**成功して終わる**のに、
            # 「0 を明示したときだけ成功」と読むと `bash <スイート> || exit 256` が
            # 「ゲートしている」と答える（実 `bash -e` は NOGATE ＝ fail-open。`main` は未配線）
            if (probe ~ /^(exit|return)([[:space:]]+[^[:space:]]+)?$/) {
                if (probe ~ /^(exit|return)[[:space:]]+[0-9]+$/) { return (escape_literal_status(probe) != 0) ? 1 : 0 }
                return 1
            }
            # それ以外は普通のコマンドなので成功しうる（握り潰しうる）
            return 0
        }

        # **`eval` はここに入れない**（レビューで実測した fail-closed）。`eval` に複合コマンドを
        # 渡す書き方は引用で包むので `split_commands` が中の `;` で切らず、
        # `eval "if false; then echo skipped; fi"` が**1 断片で自己完結する**。
        # `eval ` と引用符を落として分類すると `open_form()` が先頭を `if` と読んで階層を開くが、
        # 閉じる `fi` は同じ断片に飲まれているので**閉じる断片が永遠に来ない**——
        # 同じステップの以降すべてのコマンドが `uncertain` のまま記録され、
        # リンタ網も実行の照会も「配線されていない」と事実と逆の診断を返す（実測で
        # `main` は WIRED／この形を入れた版は not-wired）。引用を外した `eval if false; then …`
        # は bash として解釈できない綴りなので、落とす利点も無い。

        # **偽と分かる条件を見る側**の飾り落とし。上の飾りに加えて、**それ自身が階層を開く開き**
        # （部分シェル `(` ・ブレースグループ `{` ・関数定義の見出し ・ `case` のアーム見出し）も落とす。
        # `( if false; then X; fi )` / `{ if false; … }` / `f() { if false; … }` /
        # `case $M in lint) if false; …` の X はどれも 1 度も走らないが、`open_form()` は
        # これらで始まる断片の**後ろの制御構造**を分類しない（`(` を読ませると階層を二重に開く。
        # 残り 3 つは `open_form()` 自身が別の形として 1 階層開くので、そこへ重ねられない）。
        # 深さを動かさないこの判定でだけ落として、偽と分かる条件を取りこぼさないようにする
        # ——4 形とも `main` では照合に当たらず、ブロック本体の先頭を許した時点で
        # **1 度も走らない lint が証拠に化けた**（レビューで実測）。
        # **残る境界**: `( if <条件>; then X; fi )` のように条件が読めない形では、`(` が開く
        # 階層だけが立ち `uncertain` は立たない。実行の照会は深さ 0 だけを見るので影響は無く、
        # リンタの照合は「条件付きの lint も証拠として数える」設計なのでこれで正しい
        function strip_dead_cond_prefixes(t,   probe, before) {
            probe = t
            # 開きと飾りが交互に重なることがあるので、綴りが減らなくなるまで回す
            while (1) {
                before = probe
                # 部分シェルの開き（階層は釣り合いが数える）
                sub(/^\([[:space:]]*/, "", probe)
                # **関数定義の見出し**（`f() {` / `function f {`）。綴りは `function_head_re()` が唯一の源。
                # 見出しの後ろの `{` は次の行で落ちる
                if (match(probe, function_head_re())) {
                    probe = substr(probe, RLENGTH + 1); sub(/^[[:space:]]*/, "", probe)
                }
                # **ブレースグループの開き**（階層は `open_form()` が形 5 / 形 3 として数える）
                sub(/^\{[[:space:]]*/, "", probe)
                # **`case` のアーム見出し**（`lint)`）。引用の中の `)` は `mask_quoted()` が伏せるので
                # `echo "a)"` のような綴りは当たらない
                if (starts_case_arm(probe)) { probe = drop_arm_head(probe) }
                probe = strip_struct_wrappers(probe)
                if (probe == before) { break }
            }
            return probe
        }

        # `set` のオプション 1 つ分の新しい値を返す。**向きごとに反映してよい条件が違う**（issue #113）。
        # `on` が真なら `-`（ゲートを強める）、偽なら `+`（弱める）。反映してよくなければ現在値を返す。
        # 短い綴りと長い綴りで同じ判断を書き写さないよう、ここ 1 か所に寄せてある
        function set_flag(on, strengthen_ok, weaken_ok, current) {
            # 強める向きは、確実に走ると分かるときだけ立てる
            if (on) { return strengthen_ok ? 1 : current }
            # 弱める向きは、走るかもしれない時点で落とす
            return weaken_ok ? 0 : current
        }

        # その構造行がステップの中の鍵かどうかを返す。**ジョブ直下の鍵は `steps:` と同じ桁**に並ぶ
        # （どちらもジョブというマップの鍵なので）。ダッシュで始まる行はステップの先頭鍵なので中側。
        # その構造行が「ジョブ直下の鍵」「ステップ自身の鍵」「それより内側（入れ子の中身）」の
        # どれかを返す。**3 通りに分けるのが要点**で、真偽 2 通りにすると
        # `with:` の下の入れ子の並びに書かれた `- if: false` の行き先が無く、
        # ジョブ直下（＝ジョブ全体を止める）かステップ（＝外側のステップを止める）へ
        # 誤って割り当てられる（どちらも、実行されているスイートを「未配線」と誤報する。レビューで実測）
        function key_scope(probe, indent) {
            # `steps:` にまだ入っていない段階では、**ジョブ直下の鍵の桁**と比べる。
            # 「ジョブより深ければジョブ直下」と決めると、`steps:` より前に来ることの多い
            # `env:` / `strategy:` / `container:` の**中身**（`env: defaults: none` など）まで
            # ジョブ直下の鍵と読み、ジョブ全体を証拠から外してしまう（レビューで実測）
            if (steps_indent < 0 || step_dash_indent < 0) {
                if (job_indent < 0 || indent <= job_indent) { return "outside" }
                return (job_key_indent < 0 || indent == job_key_indent) ? "job" : "nested"
            }
            # ダッシュで始まる行は、**基準の桁にあるときだけ**ステップの 1 つ目の鍵（`- if: false`）
            if (probe ~ /^[[:space:]]*-([[:space:]]|$)/) {
                return (indent == step_dash_indent) ? "step" : "nested"
            }
            # `steps:` と同じ桁の鍵はジョブ直下のもの（`- name:` を同じ桁に書く書式でもここで分かれる）
            if (indent <= steps_indent) { return "job" }
            # ステップ自身の鍵の桁ならステップのもの、それより深ければ入れ子の中身
            return (indent == step_key_indent) ? "step" : "nested"
        }

        # 溜めた 1 ステップ分を、無効化されていなければジョブの控えへ移す。
        # **ここでは出力しない**のが要点で、ジョブ単位の無効化キー（`if: false` 等）は
        # YAML のキー順が自由である以上 `steps:` の**後ろ**にも書ける。書いた時点で
        # 出力済みのステップは取り消せないため、ジョブ 1 つ分を溜めてから出す
        # **階層の中で errexit が免除されているか。** 複合コマンドを AND-OR の並びの
        # 左辺に置くと（`{ … } && echo ok`）、bash はその複合の**中まで** errexit を
        # 免除する（実測: `set -e; ( false; echo z ) && echo ok` は `z` を印字して 0 で終わる）。
        # 免除されている階層では、どの失敗もその場で落とさず「最後に走ったコマンドの
        # 状態」としてだけ外へ出る。親が免除されていれば中も免除される
        function scope_suppressed(s,   guard) {
            guard = 0
            while (s > 0 && guard++ < 200) {
                if (scope_op[s] == "&&" || scope_op[s] == "||") { return 1 }
                s = scope_parent[s]
            }
            return 0
        }
        # **閉じ括弧／閉じ語に付いた区切りは「複合コマンド全体」のもので、中の並びのものではない**
        # （issue #191 のレビュー指摘）。`( bash <スイート> && echo ok ) && echo ok` の
        # `echo ok )` は階層の最後のコマンドでありながら後ろに `&&` を持つので、これを
        # 中の並びの区切りとして読むと「右辺は階層 0 の複合」に見えて読めず、未配線へ倒れていた
        # （実 `bash -e` は GATES、`main` も wired。`( set +e; bash <スイート> ) && echo ok` も同じ形）。
        # 閉じた後の区切りは階層ごとの `scope_op` が運ぶので、ここでは**空（並びの終わり）**を返す
        function sep_of(cur, s) {
            # いま居る階層をこの記録が閉じているなら、その区切りは外のもの
            if ((scope_close_at[s] + 0) == cur) { return "" }
            # そうでなければ記録自身の区切り（閉じで塗り替わる前の値）
            return rec_opx[cur]
        }
        # 連鎖の右辺（同じステップの次の記録）。階層をまたぐかは呼び出し側が見る
        function chain_rhs(cur,   nx) {
            nx = cur + 1
            if (nx > nbuf) { return 0 }
            if (rec_stepid[nx] != rec_stepid[cur]) { return 0 }
            return nx
        }
        # **記録の失敗が `run:` の終了状態へ届くかを、囲っている階層を 1 段ずつ出ながら判定する**
        # （issue #191 / #168 / #175 / #178 / #189 の残り）。`run:` の終了状態は
        # 「最後に走ったコマンドの状態」で、errexit はその手前で落とす仕組みなので、
        # 判定は 2 つの道のどちらかになる: (a) その場で落ちる、(b) 階層の最後の状態として
        # 外へ出続ける。**位置を見るのは (b) のときだけ**——`bash <スイート>; echo z` は
        # errexit がその場で落とすので位置を問わず伝わる（位置を一律に見ると、正しく
        # ゲートしている綴りを赤くする）。
        # `absorbed` は「追っている失敗が並びに吸われて、その場では落ちない」状態で、
        # 階層を出るたびに消える（複合コマンドの失敗は親から見れば 1 つのコマンドの失敗で、
        # そこでは errexit がその場で落とす）
        function record_gates(i,   cur, s, op, nx, ns, ce, ls, absorbed, guard, key, e_here, p_here, inv, aborts, via_opened, dg, dgp, dgq) {
            # そもそも走らない記録（到達不能・死に体・`exit` の後ろ）は伝わらない
            if (rec_dead[i]) { return 0 }
            cur = i; s = rec_scope[i]; op = sep_of(i, s); absorbed = 0
            e_here = rec_e[i]; p_here = rec_p[i]
            guard = 0
            while (guard++ < 1000) {
                # 背景実行の失敗は親の終了状態に出ない
                if (op == "&") { return 0 }
                # **`exit` がシェルを終えたあとは、並びの後ろの要素は 1 つも走らない**
                # （レビュー 5 巡目の実測）。`bash <スイート> || exit 1 || echo z` の
                # `|| echo z` は走らないので握り潰せない（実 `bash -e` は GATES。
                # 握り潰し扱いにすると正しくゲートしている綴りを赤くする）。
                # 並びの終わりとして扱えば、位置の判定は `aborts` が飛ばす
                if (aborts) { op = "" }
                if (op == "&&" || op == "||" || op == "|") {
                    nx = chain_rhs(cur)
                    if (nx == 0) { return 0 }
                    # **パイプの左側は `pipefail` が無ければ捨てられる。** ただしそれは
                    # 「追っている失敗がこのコマンド自身のもの」のときだけで、すでに並びへ
                    # 吸われている（`absorbed`）なら、このパイプラインは**走らない要素**の
                    # 一部にすぎないので `pipefail` は関係ない（`bash <スイート> && echo ok | cat`
                    # は左が落ちた時点で右のパイプラインごと飛ばされ、並びの状態は
                    # スイートの失敗になる。実 `bash -e` は GATES）
                    if (op == "|" && !absorbed && !p_here) { return 0 }
                    # **右辺が複合（階層を開く）なら、その複合の終わりまで飛ぶ。**
                    # 並びの要素は複合 1 つぶんなので、位置はその閉じた記録で測る。
                    # 手掛かりは 2 通り: `( … )` / `{ … ; }` は開き記号が命令の手前に来るので
                    # **記録自身が内側の階層に載る**。一方 `if true; then` / `for f in a; do` /
                    # `case x in` の見出しは条件や一覧を外側で走らせるので記録は外側に載り、
                    # **開いた階層の控え**（`rec_opened`）だけが手掛かりになる（issue #198。
                    # 見ないと `bash <スイート> && if true; then` 改行 `echo x` 改行 `fi` の連鎖が
                    # 見出しで終わり、本体の `echo x` が「後ろに続くコマンド」に見えて位置の
                    # 判定が gate を 0 にする＝実 `bash -e` は GATES なので fail-closed）
                    if (rec_scope[nx] != s) {
                        ns = rec_scope[nx]
                        while (ns > 0 && scope_parent[ns] != s) { ns = scope_parent[ns] }
                        via_opened = 0
                    }
                    # 控えは「コマンドの階層のすぐ内側」なので、その親は常にこの階層
                    # （`scope_at[run_depth + 1]` の親は `scope_at[run_depth]`）。
                    # **親を確かめ直す門番は置かない** —— 構造的に必ず真で、構成した 160 形
                    # （制御構造 4 種 × `&&` / `||` × 包み 5 種 × 後ろの行 × 手前で階層を
                    # 閉じる形）でも答えが 1 件も変わらなかった（何も変えない仕掛けは置かない）
                    else if ((rec_opened[nx] + 0) > 0) {
                        ns = rec_opened[nx] + 0
                        via_opened = 1
                    }
                    else { ns = 0; via_opened = 0 }
                    # **残る境界（レビュー 8 巡目の記録）**: 上のたどりが `s` を親に持つ先祖を
                    # 見つけられないと `ns` は 0 のまま進み、**別の階層の記録をこの階層の帳簿で
                    # 測る**ことになる。釣り合いの取れた入れ子では起こらない（全ピンと、構成した
                    # 綴り——見出しをそのまま置く形と `( … )` / `{ … ; }` で包んだ形——で到達しない
                    # ＝実測）が、構造として保証されているわけではない。未配線へ倒す門番を書いて
                    # 測ったが**1 件も答えが変わらなかった**ので置いていない
                    # （何も変えない仕掛けは「守られている」と誤解させる。§6）
                    if (ns > 0) {
                        ce = scope_close_at[ns] + 0
                        # 閉じていない（読めない）形は握り潰し側＝未配線へ倒す
                        if (ce == 0 || ce <= cur) { return 0 }
                        # **連鎖の右辺が無い複合も読めない**（レビュー 9 巡目。この差分が入れた
                        # fail-open）。見出しの複合を受け入れるようにした結果、
                        # `bash <スイート> && if true; then` 改行 `echo a &&` 改行 `fi` のように
                        # **構文エラーでスイートが 1 件も走らない**綴りまで配線済みと答えていた
                        # （実 `bash -e` は NOGATE・`main` も未配線）。見るのは「中の記録の区切りが
                        # `&&` / `||` なのに、その次が閉じ語か継続語（`else` / `elif`）」という、
                        # **右辺が無いことがその場で分かる形だけ**——`bash` の構文は再実装しない
                        # （綴りを 1 つずつ足す道は取らない。残る境界は `docs/requirements.md` に記録）。
                        # **包みの形（`( … )` / `{ … ; }`）はこの枝を通らない**（開き記号が
                        # コマンドの手前に来るので記録が内側に落ち、`rec_opened` が立たない）——
                        # `bash <スイート> && { echo a &&` 改行 `}` も `( … )` 版と同じく配線済みと
                        # 答える（真値 NOGATE＝fail-open。**`main` も同じ答え**で、ピンではなく
                        # 境界として記録している。issue #211）
                        if (via_opened) {
                            for (dg = nx + 1; dg < ce; dg++) {
                                if (!(dg in buf)) { continue }
                                split(buf[dg], dgp, "\t")
                                if (dgp[2] != "&&" && dgp[2] != "||") { continue }
                                if (!((dg + 1) in buf)) { return 0 }
                                split(buf[dg + 1], dgq, "\t")
                                if (dg + 1 == ce || dgq[6] ~ /^(else|elif)([[:space:]]|;|$)/) { return 0 }
                            }
                        }
                        if (op == "||") {
                            # 複合の状態は「その中で最後に走ったコマンド」の状態。
                            # 成功しえないなら並びはいつでも失敗する（issue #198 の一部。
                            # 中が読めない形は握り潰し側へ倒す）
                            ls = last_scope_cmd[rec_stepid[nx] "\t" ns] + 0
                            if (ls == 0) { return 0 }
                            # **その「最後のコマンド」が走ると証明できないなら、いつでも失敗する
                            # とは読めない**（レビュー指摘。この差分が入れた fail-open）。制御構造の
                            # 本体は条件や一覧が空なら 1 度も走らないので、`|| if [ -n "$DEBUG" ]; then`
                            # 改行 `false` 改行 `fi` の複合は**成功して抜けうる**——実 `bash -e` は
                            # NOGATE なのに「並びはいつでも失敗する」と読んで配線済みを返していた
                            # （6 形で実測）。門番は兄弟の `scope_fatal` が持つものと同じ `rec_unc` で、
                            # **`return 0` ではなく下の枝へ落とす**——本体が読めなくても手前に
                            # 「走ると証明できる」致命的な記録があれば複合はそこで死ぬので
                            # （実測: `|| ( false; if [ -n "$D" ]; then true; fi )` は GATES）
                            if ((!via_opened || rec_unc[ls] == 0) && chain_never_succeeds(rec_txt[ls])) {
                                # 反転の扱いは素の右辺と同じ（`|| { ! true ; }`。下の `||` の枝を参照）
                                inv = CHAIN_PROBE_FLIP
                            }
                            else {
                                # **最後が成功しうるなら、中で errexit がその場で落とす記録を見る**
                                # （レビュー指摘。`|| ( false; true )` は `false` で死ぬので
                                # 並びはいつでも失敗する＝実 `bash -e` は GATES）。
                                # 控えは `scope_fatal`（上の控え側の説明を参照）
                                if (!((rec_stepid[nx] "\t" ns) in scope_fatal)) { return 0 }
                                # **複合が並びの最後の要素でなければ、中の errexit は抑制されている**
                                # ——`|| ( false; true ) && echo z` の複合は最後の要素ではないので
                                # `false` では死なず、複合の状態は最後のコマンド（`true`）のもの
                                # ＝並びは成功しうる（握り潰し側へ倒す）
                                if (sep_of(ce, s) != "" && sep_of(ce, s) != ";") { return 0 }
                                inv = 0
                            }
                            # **手前に成功して抜ける脱出があれば、最後まで行かずに成功しうる**
                            if ((rec_stepid[nx] "\t" ns) in scope_exit_ok) { return 0 }
                            absorbed = inv ? 1 : 0
                            # **同じシェルの中の `exit` はその場でシェルを終える**（`exit_ends_shell()`
                            # の説明を参照）。見るのは「その階層で最後に走る記録」が
                            # **その階層自身のもの**で、かつ部分シェルでないときだけ——部分シェルの
                            # `exit` が終えるのはその部分シェルで、入れ子の中の `exit` も同じ
                            # （実測: `set +e` ＋ `bash <スイート> || ( echo x; exit 1 )` ＋後ろの行は NOGATE）
                            if (rec_scope[ls] == ns && !scope_sub[ns] && exit_ends_shell(rec_txt[ls]) \
                                && sep_of(ce, s) != "|" && sep_of(ce, s) != "&") { aborts = 1 }
                        }
                        else if (op == "&&") { absorbed = 1 }
                        cur = ce; op = sep_of(cur, s); e_here = rec_e[cur]; p_here = rec_p[cur]; continue
                    }
                    if (op == "||") {
                        # `||` の右辺が成功しうるなら失敗はそこで握り潰される。成功しえない
                        # なら並びはいつでも失敗し、その右辺が並びの**最後の要素**なので
                        # errexit がその場で落とす（`absorbed` を立てない）
                        if (!chain_never_succeeds(rec_txt[nx])) { return 0 }
                        # **引数の終了状態が読めない脱出は「必ず失敗する」と言えない**ので
                        # 握り潰し側＝未配線へ倒す（`escape_status_unreadable()` の説明を参照。
                        # 複合の右辺で `escape_can_succeed()` が同じ向きに倒しているのと揃える）
                        if (escape_status_unreadable(rec_txt[nx])) { return 0 }
                        # **`!` で反転した右辺は errexit を発動させない**（レビュー指摘。
                        # この差分が入れた fail-open）。bash は「`!` で真偽を反転している
                        # コマンドの失敗」では終了しないので、`bash <スイート> || ! true` の
                        # 並びはいつでも失敗するのに**その場では落ちず**、後ろに行があれば
                        # その行の状態でステップが終わる（実 `bash -e` は NOGATE。
                        # 反転を見ないと「1 件も走らないスイートがゲートしている」と読む）。
                        # 失敗は並びの状態として残るので、**位置が効く形**＝`absorbed` を立てる
                        # （後ろに行が無ければそのままステップの状態になり GATES。実測で
                        # `main` は両方とも未配線＝こちらは fail-closed だった）
                        absorbed = CHAIN_PROBE_FLIP ? 1 : 0
                        # **`exit` はその場でシェルを終える**ので、errexit の有無も位置も問わない
                        # （`exit_ends_shell()` の説明を参照）。印は同じ階層の間だけ持ち越し、
                        # 階層を出るときに落とす——部分シェルの `exit` が終えるのはその部分シェルだけで、
