                        closed_entry_p = 0
                        # 関数定義かどうかは同じ断片の中で変わらないので 1 度だけ求める
                        # （`function_form()` は正規表現を組み立てるので呼び直すと無駄が大きい）
                        fn_form = function_form(struct_text)
                        # この断片が `case` のアーム見出しか。**使う前にここで求める**——
                        # 下の `set` の判定側で求めると 1 周ずれ、アーム見出しの**次**の断片で
                        # 生きている記録を誤って捨てる（`a) set +e` の次の `echo m` で消え、
                        # 同じアームの `set -e` が打ち消せなくなる。実 bash と差分照合して実測）
                        # **伏せた本文で測る。** 引用の中の `) `（`echo "a) b"`）をアームの移動と
                        # 読むと、生きている括りの記録を捨てて正しくゲートしているステップを赤くする
                        # **部分シェルの中ではアーム見出しと読まない。** `split_commands` は
                        # 括弧に関係なく `;` で切るので、`( cd /tmp; echo prep )` の後半は
                        # `echo prep )` という断片になる。これをアーム見出しとして剥がすと
                        # 閉じ括弧が釣り合いから消え、`subshell` が 0 に戻らないまま
                        # 以降の `set +e` がすべて「子シェルの中」として無視される
                        # （握り潰されたコマンドが「ゲートしている」と読まれる。main も同じ挙動）
                        # **この断片自身が `case` を開く場合も含める。** 深さも `case_depth` も
                        # 増えるのは断片の末尾なので、1 行書き（`case $X in a) … ;; esac`）を
                        # 処理している最中はまだ 0。含めないとアームの `)` が部分シェルの閉じとして
                        # 数えられ、囲っているブロックの階層・`uncertain`・偽の印まで巻き戻る
                        # （走らないはずの本体が「最上位で確実に走る」に化ける。実測）
                        # **この off-by-one の補償と「`case` の中か」の判定は、ここ 1 か所で求めて
                        # 使い回す**（写しを持つと答えが割れ、片方だけを直したときに残りが黙って
                        # 別の答えを返す。`starts_case_arm()` を 1 つへ寄せたのと同じ理由で、同ファイルの
                        # コメントは、そのとき 3 か所のうち 1 か所が引用の扱いを食い違わせていたと記録している）
                        # **この断片が `case` を開くか。** 同じ問いが 4 か所（この下の `case_scope`・
                        # アーム模様の位置・`case_depth` の勘定）に要るので 1 つの名前へ寄せる
                        # ——写しを持つと片方だけを直したときに答えが割れる（実際、この写しの
                        # ずれがそのまま 2 件の fail-open になっていた。レビューで実測）
                        opens_case = opens_case_word(struct_text)
                        # この断片が（先頭とは限らず）`case` を開くか。**`open_head` の剥がし方と
                        # `case_scope` の両方がこれを読む**——剥がす側だけ先頭一致にすると、
                        # `{ case never in match) …` で `starts_case_arm()` が前置きごと模様と読み、
                        # `case … in match)` まで丸ごと落として階層が 1 つも開かない
                        # （一致しないアームの中身が最上位に上がる fail-open。レビューで実測）
                        case_opens_at = walk_opens_case(struct_text, fn_form, 1)
                        opens_case_here = (case_opens_at > 0)
                        case_scope = (case_depth > 0 || opens_case_here)
                        # **部分シェルの中では、模様の位置にいるときだけアーム見出しと読む**
                        # （issue #142 (3) のレビューで実測）。`subshell == 0` を無条件に課していた
                        # 理由は `( cd /tmp; echo prep )` の後半——`split_commands` は括弧に関係なく
                        # `;` で切るので `echo prep )` が断片になり、これをアーム見出しとして
                        # 剥がすと閉じ括弧が釣り合いから消えて `subshell` が 0 へ戻らない
                        # （以降の `set +e` がすべて「子シェルの中」として無視される）。
                        # だが無条件にすると**部分シェルの中の `case` が丸ごと読めない**:
                        # `( case "$X" in` → `a)` の `)` が部分シェルの閉じとして数えられ、
                        # `case` の階層がその場で打ち消されて**一致しないアームの中身が
                        # 「最上位で確実に走る」**になる（merged main でも同じ。実測）。
                        # 2 つを分けるのは**模様の位置にいるか**で、`arm_expected` が
                        # `case … in` の直後と `;;` の直後だけを追っている
                        # （括弧の勘定が `arm_at == 1 && arm_expected` で同じ手がかりを使うのと揃える）。
                        # `( cd /tmp` は `case … in` の直後には書けない綴りなので、
                        # この条件で取り違えは起きない
                        # **模様の位置でも `esac` は見出しではなく閉じ**（レビューで実測）。
                        # `esac )` は `^\(?[^()]*\)$` に当たるので、`;;` の直後（模様の位置）に
                        # 来ると見出しとして剥がされ、**`)` が釣り合いから消えて部分シェルが
                        # 永久に閉じない**（以降その断片の `set` がすべて「子シェルの中」として
                        # 無視され、握り潰されたスイートが「ゲートしている」と読まれる fail-open）。
                        # 閉じ語の走査は既に同じ例外を持つ（模様の位置で消費するのは `esac` だけ）
                        # ので、そちらと**同じ綴り**（`esac_word_re()`）で揃える。
                        # POSIX でも `esac` は引用しないとアーム模様に使えないので、
                        # 見出しと読む余地は無い（`esac)` のように `)` が直接続く綴りは
                        # `esac_word_re()` に当たらないので、模様として今までどおり読む）。
                        # **緩めた枝だけに掛ける**のが要点で、`subshell == 0` の側は
                        # 閉じる部分シェルが無く `)` を食べても害が無い（`main` と同じ挙動を保つ）
                        set_arm_here = (case_scope \
                                        && (subshell == 0 \
                                            || (arm_expected && struct_text !~ esac_word_re())) \
                                        && starts_case_arm(struct_text))
                        # **アーム見出しの後ろは命令の位置。** 剥がさないと、アームの中で開いた
                        # 複合コマンド（`a) for i in 1; do …` / `a) case $Y in`）が 1 つも数えられず、
                        # 後の `done` / `esac` が **`case` の**階層を閉じてしまう
                        # （一致しないアームの中身が最上位に上がる／内側の `case` の模様を
                        #   読めなくなる。どちらもレビューで実測）。
                        # **この断片自身が `case` を開く場合は剥がさない**——剥がすと `case … in a)` を
                        # まとめて落として `case` の階層そのものが開かなくなる。
                        # `set` の処理より前のここで 1 度だけ求める（開き側のループが読む）
                        open_head = struct_text
                        if (set_arm_here && !opens_case_here) { open_head = drop_arm_head(open_head) }
                        # **別の `case` アームへ移ったら、この階層の括りの記録は捨てる。**
                        # アーム同士は排他なので、`*)` の `set -e` は `linux*)` の `set +e` を
                        # 打ち消さない（`else` / `elif` と同じ理屈。複数行で書いたときは
                        # それぞれの `set` が断片の先頭になるので、深さだけでは区別できない）
                        if (set_arm_here && weak_depth == depth) { weak_depth = -1 }
                        # **ループを途中で抜ける綴りがあると、括りの後半は走るとは限らない。**
                        # `set +e … continue … set -e` は、最後の周回が `continue` を通ると
                        # errexit を落としたまま終わる。記録を捨てて打ち消しを成立させない。
                        # **走らないと分かっている綴りは数えない**（`true || continue` や
                        # `if false; then exit 1; fi`）——数えると、2 トークン足すだけで
                        # 正しくゲートしているステップを恒常的に赤くできる（実測）
                        if (struct_text ~ /^(break|continue|return|exit)([[:space:]]|;|$)/ \
                            && dead_depth < 0 && !unreachable && weak_depth >= 0) { weak_depth = -1 }
                        # **ブロックを開く語に続けて 1 行で書いた `set` も同じ `set`。**
                        # `split_commands` が `;` で切るので、`if …; then set +e; fi` の断片は
                        # `then set +e` になる。`^set` だけで探すと当たらず、**同じ意味を 1 行で
                        # 書き直すだけで**握り潰しが見えなくなる（`{ set +e; }` に至っては
                        # 無条件に走るのに丸ごと見落とす。実 bash と差分照合して実測）。
                        # 見出しの予約は**次の 1 断片だけ**有効（`{` 以外が来たら消える）。
                        # **`set` の判定より前に**確定させるのが要点で、後ろに置くと
                        # `f()` と次行の `{ set -e; }` で、まだ `fndef` が立っていない状態のまま
                        # 定義の本文を最上位のコードとして読む（fail-open。実 bash と差分照合して実測）
                        was_pending_fndef = pending_fndef
                        if (struct_text != "") { pending_fndef = 0 }
                        # **いま関数定義の本文の中にいるか**を、`set` を見つけたかどうかとは
                        # 無関係にこの場で確定させる。`set` が見つかった断片でしか代入しないと、
                        # 呼び出しの判定に使い回したときに前の断片の値が残る
                        # （定義の中の呼び出しを最上位の呼び出しと読む fail-open）
                        in_fndef_body = (fndef > 0 || was_pending_fndef)
                        # **この断片が関数定義の本文の中か**（この断片自身が本体を開く 1 行書きも含む）。
                        # `set` の反映と呼び出しの追跡が**同じ判断**を使うよう 1 か所で決める
                        in_fndef_here = (in_fndef_body || fn_form == 2)
                        # その本文がどの関数のものか（呼び出しで名前から引くために使う）。
                        # **入れ子の階層は内側から外側へたどって最も近い定義に紐づける**が、
                        # 1 断片に畳まれた入れ子（`outer() { inner() { set +e; }; … }`）だけは
                        # **いちばん外側**（`outer`）に紐づく——`function_body_rest()` が見出しを
                        # まとめて落とすためで、`outer` を呼べば内側の定義も呼び出しも走るので
                        # これが実 bash と一致する（同関数のコメントを参照）
                        fndef_name_here = (fn_form == 2) ? function_name(struct_text) \
                                          : (was_pending_fndef ? pending_fndef_name \
                                             : enclosing_fndef_name(depth, fndef_at, fndef_name))
                        # 本文の先頭に立ちうる語を**繰り返し**剥がす（`then { set +e; }` のように
                        # 入れ子になるため 1 つでは足りない）。**ここで剥がす一覧には `if` /
                        # `elif` / `while` / `until` も入る**（条件の位置も現在のシェルで走るので
                        # `set` はそのまま効く）が、`ci_workflow_runs_script` 側は
                        # 本体の先頭の語（`do` / `then` / `else`）までしか許さない
                        # ——条件に置いた呼び出しは落ちても `set -e` を発動させないため
                        # （issue #123 (3)。ここに「あちらは `do` を許してはいけない」と
                        #   書いてあったが、0 回まわる本体を除いているのは錨ではなく
                        #   `top` の絞り込みだった。詳細は `CI_WORKFLOW_BLOCK_BODY_START`）
                        set_probe = set_command(struct_text)
                        # **1 行で書いた定義の本文も覗く。** `f() { set +e; }` は見出しが前に付くので
                        # `set_command()` が当たらず、`set +e` の存在そのものを見落としていた。
                        # ここで見出しだけを落として拾い、下で「本体の中の `set`」として
                        # （＝その場では反映せず、関数名に控える形で）扱う
                        if (set_probe == "" && fn_form == 2) { set_probe = set_command(function_body_rest(struct_text)) }
                        # **部分シェルの後ろも覗く**（issue #180、交互の剥がしへ拡張したのが
                        # issue #187）。`( set +e` と 1 行で書くと `strip_command_prefixes()` は
                        # `(` を落とさない（落とすと階層を二重に開く。同関数の「`(` は入れない」の
                        # 段落が理由）ので、**握り潰しの存在そのものを見落としていた**——`errexit`
                        # が立ったままになるので、その部分シェルの中の呼び出しがまるごと
                        # 「合否に効く」と読まれる（実測で `( set +e` ＋
                        # `while true; do bash <スイート>; break; done` ＋ `)` は実 `bash -e` で
                        # NOGATE なのに wired。**4 トークンでスイートをゲートから外せる fail-open**）。
                        # **歩きは `set_open_depth()` に 1 つだけ持たせる**（issue #187）——以前は
                        # ここで `cross_lead_subshells()` を 1 回呼ぶだけだったので、前置きが
                        # `(` の手前にある綴り（`{ ( set +e` ・ `time ( set +e` ・ `{ { ( set +e`）で
                        # 1 つも越えられず、同じ fail-open が 3 形残っていた。深さを数える側と
                        # 同じ歩きなので、記録する深さと**その `set` が走る階層**が構造的にそろう。
                        # **`(` を 1 つも含まない断片は歩かない。** `set_probe` が空の断片はほとんどなので、
                        # 門番を置かないと全断片が `paren_delta()` の 1 文字ずつの走査を払う（§8）。
                        # 門番を「断片が `(` を含むか」にしてあるのは、前置きの後ろに隠れた `(` も
                        # 拾う必要があるから（`subshell_open_re()` を使うと issue #187 の 3 形へ戻る）
                        set_open_n = -1
                        set_crossed_sub = 0
                        # **同じ歩きの結果を「命令の位置」の判定にも渡す**（issue #189）。
                        # `strip_command_prefixes()` は `(` を落とさない（落とすと階層を二重に
                        # 開く）ので、`( exit 0; bash <スイート> )` ・ `( f; bash <スイート> )` では
                        # 命令の位置に何があるかを見落とし、その部分シェルの残りを死に体に
                        # できずに**スイートが 1 行も走らないのに「ゲートしている」と読んで**いた
                        # （実測で真値 NOGATE なのに wired。**3 トークンで必須スイートを静かに
                        #   外せる fail-open**）。歩きを増やさず、ここで求めた綴りと越えた
                        # 部分シェルの深さを下の呼び出しの追跡（そこから脱出の判定）へ渡す
                        cmd_rest = ""
                        cmd_sub = 0
                        cmd_fndef = 0
                        cmd_fnname = ""
                        cmd_fnat = 0
                        # **脱出の適用は 1 か所に寄せる**（issue #189）。素の `exit` と
                        # 「無条件に `exit` する関数の呼び出し」は区間の付け方がまったく同じなので、
                        # 見つけた側は旗を立てるだけにして、**死に体の印を解除したあと**で 1 度だけ
                        # 適用する——呼び出しの追跡は解除より手前にあるので、その場で印を付けると
                        # 同じ断片の解除（`depth_in <= dead_depth`）に消される（実測で素通りした）
                        exit_here = 0
                        exit_sub = 0
                        if (set_probe == "" && index(struct_text, "(") > 0) {
                            set_open_n = set_open_depth(open_head, fn_form, (open_head == struct_text))
                            # **越えた関数定義の数と名前は部分シェルを越えたかに関わらず控える。**
                            # `SET_OPEN_SUB > 0` の中に置くと、部分シェルを含まない綴り
                            # （`outer() { inner() { exit 0` ）で 1 件も控えられず、入れ子の
                            # 脱出が外側の名前で台帳へ入る（実測）
                            cmd_fndef = SET_OPEN_FNDEF
                            cmd_fnname = SET_OPEN_FNNAME
                            cmd_fnat = SET_OPEN_FNAT
                            # **命令の位置の綴りも部分シェルを越えたかに関わらず控える**
                            # （issue #189 のレビュー）。`SET_OPEN_SUB > 0` の中に置くと、
                            # ブレースだけで越えた定義（`{ f() { exit 0`）で綴りが空のまま
                            # 残り、名前は控えたのに本文の `exit` を誰も見ない——同じ意味の
                            # `( f() { exit 0` だけが正しく答える非対称になっていた（実測で
                            # 真値 NOGATE なのに wired。`main` も同じなので新しい穴では
                            # ないが、片方だけ閉じた形は次の人を誤らせる）
                            cmd_rest = SET_OPEN_REST
                            # **越えた部分シェルがあるときだけ覗く。** 越えていないなら
                            # `set_command(struct_text)` が既に同じ綴りを見ているので二度は見ない
                            if (SET_OPEN_SUB > 0) {
                                set_probe = set_command(SET_OPEN_REST)
                                # **越えた深さを控えるのは、そこで `set` が見つかったときだけ**
                                # （予約は見つかった `set` のためのもの。同じ断片の別経路
                                # ——アーム走査——で見つかる `set` もその部分シェルの中で走るので
                                # 同じ番号で正しい）
                                if (set_probe != "") { set_crossed_sub = SET_OPEN_SUB }
                                # 越えた深さは `set` が見つかったかに関わらず控える
                                cmd_sub = SET_OPEN_SUB
                            }
                        }
                        # **命令の位置に置けたか**を控える。使うのは**下のアーム走査に入るかの
                        # 門番 1 か所だけ**——素の綴りで見つかったならアームを探す必要が無い。
                        # **「置けたなら向きの判断に `uncertain` を使える」と書かないこと**
                        # （issue #123 の補足。実際には `strengthen_base` が `set_probe == text`
                        #  だけで決まっており、`set_placed` はそこを一度も読んでいない。
                        #  このファイルはコメントから推論して欠陥を見つける運用なので、
                        #  存在しない制御経路の説明は保守上の罠になる）。
                        # 強める向きを `set_probe == text` に限る理由はその定義の近くに書いてある
                        # **同じ名前で定義し直したら、前の本文で控えた弱めは残らない。**
                        # `f() { set +e; }` のあとに `f() { :; }` と書けば、呼んでも弱めない。
                        # 消さないと古い記録が勝ち、正しくゲートしているステップを「未配線」と
                        # 誤報して required なジョブを赤くする（レビューで実測。`main` は正しい）。
                        # **本体を開く断片で消す**のが要点で、深さが増えるより前・かつ
                        # この断片の `set` を記録するより前なので、1 行書きの
                        # `f() { set +e; }` でも「消してから記録する」順序になる。
                        # **歩きが越えた定義でも消す**（issue #189 のレビュー）。`fn_form` は
                        # `^` 錨なので `{ f() { :; }` ・ `( f() { return 0; }` のように見出しの
                        # 手前に括りがある綴りでは消しが走らず、古い「無条件に脱出する」記録が
                        # 生き残って呼び出しの後ろを死に体にしていた（実測で真値 GATES が
                        # wired → not-wired。`main` は正しく答えていた）。そのために**歩きの
                        # 後ろへ移してある**——`cmd_fnname` は歩きが決めるので、元の位置
                        # （`fndef_name_here` を決めた直後）では読めない。弱めの台帳
                        # （`fnweak_*`）も同じところで消すが、あちらは**記録する側が越えた定義を
                        # 見送る**ので、消しが広がっても「古い記録が残る」側だけが直り、
                        # 緩む向きには動かない
                        # **部分シェルを越えて見つけた定義では消さない**（issue #189 の 3 巡目の
                        # レビューで実測）。部分シェルの中の再定義は**親の関数を置き換えない**ので、
                        # 消すと `f() { exit 0; }` ＋ `( f() { :; } )` ＋ `f` が「もう脱出しない」
                        # として wired になる（真値 NOGATE。1 つ前のコミットは正しく not-wired
                        # だった＝この門番を落とすと自分で fail-open を開く）。ブレースだけで
                        # 越えた定義（`{ f() { :; }`）は同じシェルなので消すのが正しい。
                        # 部分シェルの中で再定義して**その中で呼ぶ**綴り
                        # （`( f() { return 0; }` 改行 `f )`）は、台帳が残っても脱出が
                        # 部分シェルの中だけを死に体にするので外のスイートは生きたまま——
                        # つまりこの門番はどちらの向きも壊さない（実測でピン 2 形とも緑）
                        fn_name_here = (fn_form == 2 || was_pending_fndef) ? fndef_name_here \
                                       : ((cmd_fndef == 1 && cmd_sub == 0) ? cmd_fnname : "")
                        if (fn_name_here != "") {
                            fnweak_e[fn_name_here] = 0
                            fnweak_pipe[fn_name_here] = 0
                            # 無条件の `exit` の台帳も同じところで消す（issue #189）。
                            # 残すと `f() { exit 0; }` のあとに `f() { :; }` と書き直しても
                            # 古い記録が勝ち、**正しくゲートしているスイートを「未配線」と
                            # 誤報**して required なジョブを赤くする（向きが逆の fail-closed）
                            fnexit[fn_name_here] = 0
                            # 手前の `return` の控えも同じところで消す（同じ理由）
                            fnret[fn_name_here] = 0
                        }
                        set_placed = (set_probe != "")
                        # **パイプの構成要素とバックグラウンドは子シェルで走る。** `true | set -e` も
                        # `set -e &` も親のオプションは変えないので、どちらの向きも反映しない
                        # （`prev_op` は手前の区切り、`ops[j]` は直後の区切り。実 bash と差分照合して実測）
                        # `case` のアーム模様（`a|linux*)`）の `|` は選択肢の区切りであってパイプではない。
                        # `split_commands` はそこで切るので、素直に見ると本文が「パイプの構成要素」に化け、
                        # アームの中の `set +e` が丸ごと落ちる（実 bash と差分照合して実測）
                        # **入ってきた区切りをここで控える。** `prev_op` はこの断片の処理中に
                        # 自分の区切りへ更新されるので、開き側の判定まで持たない
                        pipe_in = (prev_op == "|")
                        # **入ってきた `&&` / `||` も同じ理由でここで控える。** 下の `true_at`
                        # （「本体は必ず走る」の印）は直後の区切りしか見ていなかったため、
                        # `test -n "$RUN" && if true; then <呼び出し>; fi` のように**手前**で
                        # 連鎖に守られた `if true` が「必ず走る」と記録されていた。
                        # 錨が継続語を許すようになった時点で、その本体が**実行の証拠**に化ける
                        # （実 `bash -e` では左辺が偽なら 1 度も走らないのに `wired`。
                        #  レビューで実測。`&&` / `||` の並びは `set -e` を発動させない）。
                        # **`prev_op` を下で読み直してはいけない**——`prev_op` は断片の処理中に
                        # 自分の区切りへ更新されるので、開き側まで持たない（`pipe_in` と同じ事情）
                        # **結論の分かる連鎖は「走るか分からない」に数えない。** 短絡で向きが
                        # 決まっている形（`false && echo mid || bash <スイート>` の `||` の右・
                        # `true || echo mid && bash <スイート>` の `&&` の右）は**必ず走る**ので、
                        # 連鎖の有無だけで見送ると実行される呼び出しを「未配線」と事実と逆に
                        # 診断する（その 2 形は対で固定済み。実測で落ちた）。
                        # 逆向き（`&&` の手前が偽・`||` の手前が真）は上で `unreachable` が立ち、
                        # 記録の `gate` が 0 になるのでここでは触らない
                        chain_in = ((prev_op == "&&" && chain_status != "t") || (prev_op == "||" && chain_status != "f"))
                        # **入ってきた `|` が模様の区切りなのは、模様の位置にいたときだけ。**
                        # `set_arm_here` だけで見送ると、`echo x | { case zz in zz) set +e` の
                        # ように**本物のパイプ**で入ってきた断片がたまたまアーム見出しを含む場合まで
                        # 見送り、子シェルの `set +e` を親に効いたものとして扱う
                        # （正しくゲートする綴りを赤くする。レビューで実測）
                        set_forked = ((prev_op == "|" && !(set_arm_here && arm_expected)) || ops[j] == "|" || ops[j] == "&")
                        if (!set_placed) {
                            # **`case` のアームの後ろは命令の位置。** `case "$X" in Linux) set +e` は
                            # `;` で切れないので 1 つの断片に載り、`^set` では当たらない。
                            # **アームの綴りは 2 通り**あり、POSIX では先頭に `(` を書ける
                            # （`(Linux) set +e`）。1 文字足すだけで握り潰しが見えなくなるのを防ぐ
                            # **断片のどこにある `set` でも拾ってはいけない。** 以前は語の切れ目なら
                            # どこでも拾っていたが、それだと `echo Hint: run set +e first` のような
                            # ただの言及まで握り潰しとして数え、ゲートしているステップを
                            # 「未配線」と誤報して赤くする（実 bash と差分照合して実測）。
                            # 判定は伏せた本文で行い（引用の中の `)` をアームと読まないため）、
                            # 解析は生の本文で行う（伏せた本文では `set "+e"` の綴りを読めない。
                            # 長さは保たれるので位置はそのまま使える）
                            # **`case` の中でだけ探す。** 絞らないと、コマンド置換の `)` を
                            # アームと読んで `echo $(date) set +e` の言及まで拾い、
                            # ゲートしているステップを「未配線」と誤報する（実測）。
                            # **この断片自身が `case` を開く場合も含める**——深さが増えるのは
                            # 断片の末尾なので、1 行書き（`case $X in a) set +e`）はまだ 0 のまま
                            set_masked = case_scope \
                                         ? mask_quoted(struct_text) : ""
                            # **`)` を 1 つずつ越えながら `set` を探す。** 1 つの正規表現で
                            # 先頭から当てると、`case $(echo linux) in linux) set +e` のように
                            # 主語にコマンド置換がある綴りで `$( … )` を食べて本物のアームを
                            # 取り逃がす（実 bash と差分照合して実測）。丸括弧の組はまとめて越える
                            # ので、`( set +e )` のような部分シェルは中身を跨いで終端の外へ出る
                            # ＝ `set` に着地せず、これまでどおり反映しない
                            set_arm = 0
                            # `case` の外（`set_masked` が空）では走査するものが無い。
                            # 回すと `set_command()` の剥がしを同じ本文に対して 2 度走らせるだけ
                            # **初回は呼び出し側（`set_placed`）が既に空と判定済み**なので飛ばし、
                            # 最初の `)` の先から見る。飛ばさないと同じ本文に対して
                            # `set_command()` の剥がしをもう一度走らせるだけになる
                            set_probe = ""
                            while (set_masked != "" && set_arm <= length(set_masked)) {
                                set_rest = substr(set_masked, set_arm + 1)
                                # 次の `)` まで進める（丸括弧の組があれば組ごと）
                                if (!match(set_rest, /^[^()]*\([^()]*\)[[:space:]]*/) \
                                    && !match(set_rest, /^[^()]*\)[[:space:]]*/)) { set_arm = -1; break }
                                # **ここに「1 文字も進まないなら打ち切る」門番は置かない。**
                                # 上の `match()` はどちらの選択肢も `)` を 1 つ要求するので
                                # `RLENGTH >= 1` が必ず成り立ち、`set_arm` は毎周必ず増える
                                # ＝ループは `length(set_masked)` で必ず終わる（issue #123 の補足。
                                #  何も変えない門番は読み手に「守られている」と誤解させるだけ）。
                                # **空にも当たる選択肢を足すときは、同時にこの門番を戻すこと**
                                set_arm += RLENGTH
                                # 進んだ先が命令の位置なら確定
                                set_probe = set_command(substr(struct_text, set_arm + 1))
                                if (set_probe != "") { break }
                            }
                            # ここへ来た時点で `set_probe` は、着地した `set …` か空のどちらか
                            # （ループは着地したときだけ `break` し、それ以外は空のまま抜ける）
                        }
                        # **部分シェルの中で見た `set` も、その部分シェルの中へは反映する**
                        # （issue #152）。以前は `subshell == 0` で丸ごと捨てていたため、
                        # `( while true; do set +e; bash <スイート>; break; done )` の握り潰しが
                        # 見えず、1 度も合否に効かない呼び出しが「ゲートしている」と読まれた。
                        # 親へ漏らさないのは下の「部分シェルを閉じたら入口の姿へ戻す」が担う
                        if (set_probe != "" && dead_depth < 0 && !set_forked && !unreachable) {
                            # **`set` の反映は「どちらへ倒すか」で非対称にする（issue #113）。**
                            # 制御構造の中（`uncertain > 0`）は走るか分からないが、`+` と `-` では
                            # 分からないときに倒すべき先が逆になる:
                            #   - ゲートを**強める**向き（`-e` / `-o errexit` / `-o pipefail`）を
                            #     当て推量で反映すると、通らない分岐の `set -e` が握り潰しを隠す
                            #     ＝**fail-open**。だから確実に走ると分かるときだけ反映する。
                            #   - ゲートを**弱める**向き（`+e` / `+o errexit` / `+o pipefail`）を
                            #     無視すると、実際には握り潰されているステップが「合否に効く」と
                            #     読まれる＝これも**fail-open**。だから走るか分からなくても反映する。
                            # 以前は両向きとも `uncertain == 0` を要求していたため後者が空いており、
                            # `if [ -n "$CI" ]; then set +e; fi` の 3 行（`$CI` は Actions で常に真）で
                            # スイートの失敗を握り潰したまま全表明を緑のまま通せた（実 bash と差分照合して実測）。
                            # 代償として「通らないかもしれない分岐の `set +e`」は未配線と誤報しうるが、
                            # そちらは CI が赤くなって人が見る**fail-closed** 側なので許容する。
                            # **関数定義の本文は「その場では走らない」ので弱める向きも反映しない。**
                            # `cleanup() { set +e; … }` は定義しただけでは何も起きず、反映すると
                            # 実際にはゲートしている後続を「未配線」と誤報して CI を赤いままにする。
                            # **見送るのは「その場での反映」だけで、見なかったことにはしない**——
                            # 本文で見た弱める向きは関数名に控え（`fnweak_*`）、その関数が
                            # 呼ばれた断片で反映する（下の呼び出し追跡。issue #120 (2)）
                            # 反映してよい条件は向きで違う。強める向きは、命令の位置に置けて・
                            # 制御構造の外で・**連鎖に守られていない**ときだけ信用する。
                            # `set +e` の後ろに `[ -z "$FORCE" ] && set -e` と書かれた場合、
                            # この `set -e` は条件次第でしか走らないのに `uncertain` は 0 のままで、
                            # 握り潰しを打ち消したように見えていた（実 bash と差分照合して実測）
                            # **関数定義の本文は、その場では走らない。** 見出しの次に来る `{`
                            # （`f()` → `{ set -e; }`）も本文の中なので、どちらの向きも反映しない。
                            # **定義を開く断片そのもの（`f() { set +e; }`）もここへ来る。**
                            # 以前は `set_command()` が見出しを剥がさず `set_probe` が空になるため
                            # 素通りしていたが、それでは本文の `set +e` の存在自体を見落とし、
                            # 関数が呼ばれたときの握り潰しを控えることもできなかった。
                            # いまは上で見出しを落として拾うので、`fn_form == 2` を本文の中として扱う
                            # （扱わないと、定義しただけの `set +e` を最上位の指定として反映し、
                            #   ゲートしているステップを「未配線」と誤報する）
                            # **強める向きを信用するのは `set` が断片の先頭そのもののときだけ。**
                            # 継続語や `{` を剥がして見つけた `set` は、剥がした側に
                            # `{ if false` のような開き語が混ざっていることがあり、そのときの
                            # `uncertain` は内側の入れ子をまだ数えていない（走らないブロックの
                            # `set -e` を最上位の指定として credit してしまう。実 bash と差分照合して実測）。
                            # 弱める向きは剥がした先でも反映する——見えた `set +e` を無視する側が
                            # fail-open になるため。ここも「分からないときは弱い方」で揃える
                            # **同じ階層で括った `set +e … set -e` は打ち消し合う。** 非対称の扱いは
                            # 「通らない分岐の `set -e` が**外側**の握り潰しを隠す」ことへの備えなので、
                            # 落としたのが同じ階層の `set +e` なら、戻す側も同じだけ条件付きであって
                            # 隠すものが無い。ここを見ないと `for f in …; do set +e; check; set -e; done`
                            # のような括りが「以降ずっと握り潰し」と読まれ、ゲートしているステップを
                            # 「未配線」と誤報して CI を恒常的に赤くする（実 bash と差分照合して実測）
                            # 同じ階層の括りを打ち消せるのは、その階層で自分が落としたときだけ
                            # 強める向きに共通の前提（命令の位置・定義の外・連鎖に守られていない）
                            # **部分シェルの中の `set -e` は、自分で落とした分を戻すときだけ信用する**
                            # （issue #152）。親が `set +e` している下での `( set -e; … )` を
                            # 素直に credit すると、部分シェルは自分の中で止まるだけで親は止まらない
                            # のに「合否に効く」と読む（fail-open。打ち消しかどうかは
                            # `apply_errexit()` の `cancel` が階層の向きで判断するので、
                            # ここでは「**その部分シェルの中で**落とした記録があるか」までを見る）。
                            # **「落とした記録があるか」だけでは足りない**——外側の `set +e` が
                            # 記録を残しているだけで内側の `set -e` を credit してしまい、
                            # `set +e` ＋ `( set -e; bash <スイート> )` が wired に化ける
                            # （部分シェルは自分の中で止まるだけで親は止まらないので実 bash は
                            #  NOGATE。540 形の総当たりで 47 形が新しく誤った＝実測）
                            strengthen_base = (set_probe == text && !in_fndef_here && prev_op != "&&" && prev_op != "||" \
                                               && (subshell == 0 \
                                                   || (weak_depth >= 0 && weak_sub != 0 \
                                                       && weak_sub == sub_id[enclosing_subshell_depth(depth, subshell_at)])))
                            # **括りの記録は errexit のものなので、errexit の判断にしか使わない**
                            # （`apply_errexit()` の中で測る）。pipefail まで巻き込むと、無関係な
                            # `set +e` が同じ階層で開いているだけで走らないループの中の
                            # `set -o pipefail` が credit され、パイプ越しの失敗が伝わらない
                            # ステップを「伝わる」と読む（fail-open。実測）。
                            # pipefail には自前の括り記録が無いので、確実に走ると分かるときだけ
                            strengthen_pipe_ok = (strengthen_base && uncertain == 0)
                            # **`case` を開く断片に載ったアームの `set` は、本体の階層に属する。**
                            # 深さが増えるのはこの断片の**末尾**なので、素直に `depth` で記録すると
                            # 同じアームの後続（1 つ深い）の `set -e` が打ち消せず、
                            # 正しくゲートしているステップを赤くする（複数行で書いた同じアームとも
                            # 答えが食い違う。実 bash と差分照合して実測）
                            # **記録するのは「その `set` が走る深さ」**で、`set_open_depth()` が
                            # それを数える（素の「この断片が開いた数」ではない——`if set +e; then` の
                            # `set` は**条件の位置**にあり `if` が開く階層の**外**で走るので、
                            # 数えると 1 つ深く記録して打ち消しが成立しなくなる）。
                            # **`case` の分だけを `+1` する古い数え方に戻さないこと**——
                            # `{ case x in a) set +e` のように `case` の前に別の開きがある綴りや、
                            # アーム見出しを剥がした先で開くブレースを取りこぼし、同じ括りの
                            # `set -e` と階層が食い違って打ち消せなくなる（正しくゲートする綴りを
                            # 赤くする。レビューで実測）
                            # **歩きは 1 度だけ**（issue #187）。上の探す側が同じ引数で既に
                            # 歩いているので、控えてあればそれを使う——2 度歩くと費用が倍に
                            # なるうえ、「同じ答えが返るはず」という誰も強制していない約束が生まれる
                            set_depth = depth + ((set_open_n >= 0) ? set_open_n : set_open_depth(open_head, fn_form, (open_head == struct_text)))
                            # **先頭の部分シェルを越えて見つけた `set` は、その部分シェルの中に属する**
                            # （issue #180）。階層ごとの連番（`sub_id`）はこの断片の開き側で振られるが、
                            # それは下の開きループ（この `set` の処理より後ろ）なので、素直に
                            # `sub_id[enclosing_subshell_depth(depth, …)]` を読むと**親**の番号になり、
                            # 同じ部分シェルの中の `set -e` が打ち消せない（`( set +e` 改行 `set -e`
                            # 改行 `bash <スイート>` が、実 `bash -e` では GATES なのに `not-wired`
                            # ＝正しくゲートする綴りを赤くする。実測）。
                            # **番号を予想しない。** 「開き側は先頭から順に振るので `sub_serial + n`
                            # だろう」と見込むと、上限が食い違う綴り（越える数は生の釣り合いで
                            # 数えるのに、開き側はアーム見出しを補正した `paren` で回る）で
                            # **予想した番号が別の部分シェルへ渡り**、握り潰しの記録が無関係な階層の
                            # `set -e` で打ち消される（fail-open）。ここで**先に振って**おき、
                            # 開き側は空いていなければそれを使う（余った予約はそこで捨てる）。
                            # 先頭が `(` の断片は外側の階層を閉じないので、`depth` より深い枠は空
                            set_sub = sub_id[enclosing_subshell_depth(depth, subshell_at)]
                            if (set_crossed_sub > 0) {
                                # **予約するのは「その `set` が属する部分シェル」の階層 1 つだけ**
                                # （issue #187）。越えた数（`depth + 越えた個数`）で数えると、
                                # 前置きが開く階層を数え落として**ブレースの階層**へ当たる
                                # ——`{ ( set +e` では部分シェルは `depth+2` に開くので、
                                # `depth+1` へ予約すると握り潰しがどの部分シェルとも結び付かず、
                                # 同じ部分シェルの中の `set -e` が打ち消せない（`{ ( set +e` 改行
                                # `set -e` 改行 `bash <スイート>` が wired → not-wired へ動く
                                # ＝正しくゲートする綴りを赤くする。issue #187 がレビューの
                                # 実測として記録している退行）。深さを数える側と同じ歩きが
                                # 返す値を使うので、この食い違いは構造的に起きない。
                                # 外側の部分シェルは予約しない——開き側が新しい番号を振るのが
                                # 正しく（別の部分シェルなので）、`set` はそのどれにも属さない
                                sub_serial++; sub_id[depth + set_crossed_sub] = sub_serial
                                set_sub = sub_id[depth + set_crossed_sub]
                                # **どの断片が予約したかを控える。** 開き側がその階層まで開けない
                                # 綴りでは予約が余り、残すとその番号が**後の別の部分シェル**へ渡って、
                                # 握り潰しの記録が無関係な階層の `set -e` で打ち消される（fail-open）。
                                # 余りは「同じ断片か」で弾くので捨てて回る必要が無い
                                # （印は論理行と断片の対——`j` だけでは行をまたいで重なる）。
                                # **開き側が越えた数より少なく開く綴りは実在する**（issue #172 の
                                # アーム模様の surgery は `(` を 1 文字落とすので `paren` が
                                # 生の釣り合いより小さくなりうる。`case $X in` の直後の
                                # `( set +e |` がその形）。**余りが出るその綴りを作る検査は
                                # どのスイートも持っていない**ので、余りの始末だけは規約と
                                # レビューで守る。**印そのものはピンが掛かっている**
                                # （issue #200 で実測: この行を消す変異と、開き側が印を見ず必ず
                                #  振り直す変異のどちらでも落ちる。**件数は書かない**——ピンを
                                #  足すたびに動く。「印に当たるピンは無い」と読めると、相乗りの
                                #  経路ごと消してよいと誤解されるので分けて書く）
                                sub_res_at = i ":" j
                            }
                            # **関数ごとの台帳で使う階層。** 本体を同じ断片で開く 1 行書き
                            # （`f() { set +e; }`）では深さが増えるのが断片の末尾なので、
                            # 素の `depth` で控えると、続く断片の `set -e`（1 つ深い）と
                            # 階層が一致せず打ち消せない
                            # **見出しが別行の綴り（`f()` 改行 `{ …`）も同じ**。あの `{` の断片でも
                            # 本体の階層が開くのは断片の末尾なので、`fn_form` だけを見ると
                            # 1 つ浅く控えてしまい、続く `set -e` と階層が一致せず打ち消せない
                            # （`f()` 改行 `{ set +e; set -e; }` が「弱める関数」に化ける。レビューで実測）
                            # **台帳の階層は「その関数の本体の階層」**であって、`set` が走る階層ではない。
                            # 定義を開く断片ではその 1 つ下が本体（開くのは断片の末尾）。それ以外の
                            # 断片では、囲っている定義の階層まで戻して数える——`set` が走る深さで
                            # 控えると、`f() {` 改行 `{ set +e; }` 改行 `set -e` のように本文の中で
                            # ブレースを挟むだけで記録側と打ち消し側の階層が食い違い、本文で戻して
                            # いる関数が「弱める関数」として残る（正しくゲートする綴りを赤くする。
                            # ブレースグループは同じシェルなので bash では打ち消せる。レビューで実測）
                            fn_body_depth = (fn_form == 2 || was_pending_fndef) \
                                            ? depth + last_deciding_open(open_head, fn_form, (open_head == struct_text), was_pending_fndef) \
                                            : enclosing_scope_depth(depth, uncertain_at, fndef_at)
                            # 台帳の打ち消しを認めてよい綴りか。強める向きを信用する条件から
                            # 「定義の外であること」だけを外したもの——ここは定義の**中**の話で、
                            # 見ているのは「この関数を呼んだあと errexit が有効か」だから
                            fn_cancel_ok = (set_probe == text && prev_op != "&&" && prev_op != "||")
                            # 弱める向きは、定義の本文でなければ（＝走るかもしれない時点で）反映する
                            weaken_ok = (!in_fndef_here)
                            # **語を左から右へ順に適用する。** bash はそう解釈するので
                            # `set +e -e` は後ろの `-e` が勝つ。1 本の正規表現で断片全体を見ると
                            # この順序が落ち、ゲートしているステップを「未配線」と誤報して赤くする
                            # **引用符は外してから語に切る。** `set "+e"` も `set '+e'` も
                            # bash には `set +e` と同じで、外さないと綴りを読めず握り潰しを見落とす
                            gsub(/["\047]/, "", set_probe)
                            nsetw = split(set_probe, setw, /[[:space:]]+/)
                            for (sw = 2; sw <= nsetw; sw++) {
                                setopt = setw[sw]
                                # **最初の非オプション語でそこから後ろは位置パラメータになる。**
                                # `--` もここで落ちる（2 文字目が `[a-zA-Z]` ではないため）
                                # 読み飛ばして続けると、`set +e foo -e` の `-e` を効いたものとして数え、
                                # 実際には握り潰されているステップが「合否に効く」と読まれる（fail-open）
                                # `-` / `+` で始まる短い綴りの並び（`-e` / `+ex` / `-euo`）だけを読む
                                # **大文字も混ざる**（`-Eeuo pipefail` は定型句）。小文字だけを
                                # 許すと語ごと捨ててしまい、`+eE` の握り潰しを見落とし、
                                # `-Eeuo pipefail` ではゲートを「効いていない」と誤報する。
                                # 拾うのは小文字の `e` / `o` だけなので、`E`（errtrace）とは混ざらない
                                if (setopt !~ /^[-+][a-zA-Z]*$/) { break }
                                # 先頭の記号が向きを決める（`-` で有効化、`+` で無効化）
                                seton = (substr(setopt, 1, 1) == "-")
                                # 記号を除いた残りが、まとめて書かれたオプション文字の並び
                                setbody = substr(setopt, 2)
                                # 並びのどこかに `e` があれば errexit の指定
                                if (setbody ~ /e/) { errexit = apply_errexit(seton, strengthen_base, uncertain, weaken_ok, errexit, set_depth, set_sub) }
                                # **定義の本文で見た弱める向きは、関数名に控えておく。**
                                # 定義しただけでは走らないので上では反映されないが、
                                # 呼ばれればシェルを共有するので握り潰しは呼び出し元へ漏れる。
                                # 控えるのは弱める向きだけ（強める向きまで信用すると、
                                # 呼ばれるとは限らない `set -e` が外側の握り潰しを隠す fail-open）
                                # 短い綴りで落ちるのは errexit だけ（`pipefail` は長い綴りのみ）
                                # **部分シェルを越えて見つけた握り潰しは控えない**（issue #187 のレビュー指摘、実測）。
                                # `f() { ( set +e; : ); }` の `set +e` は部分シェルと一緒に消えるので、
                                # 呼び出し元の errexit は立ったまま——控えると「この関数は弱める」と
                                # 記録され、呼び出しより後ろのスイートが**まるごと未配線**と報告される
                                # （真値 GATES なのに not-wired。正しくゲートする綴りを赤くする向きで、
                                # 1 行書き・別行書き・`function f {`・`time (`・二重の部分シェル・
                                # ブレース挟み・入れ子の定義の **7 形**で実測した）。打ち消し側
                                # （`seton` の枝）は `fn_cancel_ok`（`set_probe == text`）が
                                # 部分シェル越しの綴りを既に除くので、ここでは触らない
                                if (in_fndef_here && !seton && set_crossed_sub == 0) { record_fn_weaken(fndef_name_here, setbody ~ /e/, 0, fnweak_e, fnweak_pipe, fn_body_depth, fnweak_e_at, fnweak_pipe_at) }
                                # 同じ本文の同じ階層で戻していれば、その関数は呼んでも弱めない
                                else if (in_fndef_here && seton && fn_cancel_ok) { clear_fn_weaken(fndef_name_here, setbody ~ /e/, 0, fnweak_e, fnweak_pipe, fn_body_depth, fnweak_e_at, fnweak_pipe_at) }
                                # **末尾が `o` なら次の語が長い綴りの名前**（`-o errexit` / `-euo pipefail`）。
                                # 短い綴りだけを見ると、1 行でゲートを外したまま「ゲートしている」と読む
                                # **`o` は並びのどこにあってもよい。** bash は `-oe pipefail` を
                                # `-eo pipefail` と同じに扱う（末尾だけを見ると pipefail を取りこぼす）
                                if (setbody ~ /o/ && sw < nsetw) {
                                    # 名前の語を消費する（次の周回では読まない）
                                    sw++
                                    setname = setw[sw]
                                    # `errexit` は失敗でその場で止まるかどうか
                                    # **長い綴りでも同じ記録を残す。** 残さないと、`set +o errexit … set -o errexit` の
                                    # 括りだけが打ち消せず、ゲートしているステップが「未配線」と誤報される
                                    if (setname == "errexit") { errexit = apply_errexit(seton, strengthen_base, uncertain, weaken_ok, errexit, set_depth, set_sub) }
                                    # `pipefail` が立っていればパイプ越しでも失敗が伝わる
                                    else if (setname == "pipefail") { pipefail = set_flag(seton, strengthen_pipe_ok, weaken_ok, pipefail) }
                                    # 長い綴り（`+o errexit` / `+o pipefail`）も短い綴りと同じように控える
                                    # 長い綴りも同じ門番を通す（理由は短い綴り側のコメント）
                                    if (in_fndef_here && !seton && set_crossed_sub == 0) { record_fn_weaken(fndef_name_here, setname == "errexit", setname == "pipefail", fnweak_e, fnweak_pipe, fn_body_depth, fnweak_e_at, fnweak_pipe_at) }
                                    else if (in_fndef_here && seton && fn_cancel_ok) { clear_fn_weaken(fndef_name_here, setname == "errexit", setname == "pipefail", fnweak_e, fnweak_pipe, fn_body_depth, fnweak_e_at, fnweak_pipe_at) }
                                }
                            }
                        }
                        # **本文で `set +e` を見た関数が呼ばれたら、その時点で弱めを反映する。**
                        # 定義しただけでは何も起きないので上では見送っているが、関数は
                        # シェルを共有するため、呼ばれた瞬間に握り潰しが呼び出し元へ漏れる。
                        # 追跡しないと `f() { set +e; }` と `f` の 2 行でスイートの失敗を
                        # 握り潰せる——issue #113 が塞いだ `if [ -n "$CI" ]; then set +e; fi` と
                        # 同じ規模の抜け道（実 bash と差分照合して実測。fail-open）。
                        # 反映するのは**弱める向きだけ**で、`set` 本体と同じ非対称の扱いに揃える。
                        # 除外の条件も `set` と同じ（走らないブロック・子シェル・パイプの構成要素・
                        # 定義の本文の中では、呼び出しても親のオプションは変わらないか、そもそも走らない）
                        # **判定は `struct_text` で行う。** `split_commands` は `;` で切るので
                        # `if …; then f` の断片は `then f` になり、生の本文で先頭の識別子を
                        # 取ると `then` を関数名と読んで呼び出しを丸ごと取り逃がす
                        # （`if [ -n "$CI" ]; then f; fi` の 3 行で握り潰しが素通りする。fail-open）
                        # **1 行書きの定義は本文側を見る**（`g() { f; }` の呼び出しは見出しの後ろ）
                        call_probe = (fn_form == 2) ? function_body_rest(struct_text) : struct_text
                        # `case` のアーム見出しの後ろも命令の位置（`linux) f`）。
                        # 剥がす綴りは上の `paren_probe` と揃える（`starts_case_arm()` の判定を使い回す）
                        if (set_arm_here) { call_probe = drop_arm_head(call_probe) }
                        # **1 行の POSIX 綴り（`case X in (linux) f`）は `starts_case_arm()` に当たらない。**
                        # あの判定は `[^()]*` で測るので、アームの `)` の手前に `(` があると跨げず、
                        # 断片の先頭が `case` のまま残る＝呼び出し先が `case` と読まれて追跡が外れる
                        # （`(` を 1 つ足すだけで塞いだ穴が開き直す。実 bash と差分照合して実測）。
                        # 同じ綴りを 2 行に分けた場合は正しく扱えるので、1 行に畳んだときだけの穴だった。
                        # ここでは最初の `)` までを見出しとして落とす。`case $(uname) in (linux) f` の
                        # ようにコマンド置換が主語にある綴りは `$( … )` で止まって命令に届かないが、
                        # **届かない側は「弱めを反映しない」＝これまでどおり**なので新しい穴は開かない
                        # （`set` を探す側は `)` を 1 つずつ越える走査で同じ綴りに対応している）
                        # **`case` を開く断片だけに限る。** `case_depth > 0` まで広げると
                        # アームの**中身**の断片にも掛かり、`f $(date)` のような呼び出しが
                        # `[^)]*` に `$(` を跨がれて丸ごと消える＝弱めが反映されない
                        # （握り潰されたスイートが「ゲートしている」と読まれる fail-open。
                        #   レビューで実測）。アームの中身は上の `set_arm_here` と、
                        # 見出しを持たない普通の断片としての扱いで足りる
                        else if (opens_case) {
                            sub(/^[^)]*\)[[:space:]]*/, "", call_probe)
                        }
                        # **先頭の飾りは `set` を探すときと同じ一覧で落とす。** 落とさないと
                        # `{ f; }` / `! f` / `eval f` / `time f` / `VAR=1 f` / `\f` のどれでも
                        # 追跡が外れる（`{ f; }` は 2 文字の抜け道。レビューで実測。fail-open）。
                        # `command` / `builtin` だけは落とさない——**関数の探索を飛ばす**綴りなので、
                        # `command f` は関数 f の呼び出しではない（実 bash と差分照合して実測）
                        call_probe = strip_command_prefixes(call_probe, 0)
                        # **先頭の部分シェルの後ろの呼び出しも読む**（issue #189）。`( f` は
                        # `strip_command_prefixes()` が `(` を落とさないので名前に 1 度も当たらず、
                        # `f() { exit 0; }` ＋ `( f; bash <スイート> )` のスイートが「必ず走る」と
                        # 記録されていた。`set` を探す側が同じ断片で既に歩いた結果
                        # （`cmd_rest` / `cmd_sub`）を使い回す——**歩きは増やさない**。
                        # **越えた深さは控えておく**（`call_sub`）。弱めの反映は部分シェルの中では
                        # 見送るので、`subshell` だけでなくこの値も門番に使う必要がある
                        call_sub = 0
                        # **定義を越えたときは識別子で始まっていても取り直す。** 定義の見出し
                        # （`f() { exit 0`）は識別子で始まるので、下の「識別子で始まらないとき」
                        # の条件には当たらず、本文の `exit` が命令の位置として見えなかった
                        if (cmd_fndef > 0 && cmd_rest != "") {
                            call_probe = strip_command_prefixes(cmd_rest, 0)
                            call_sub = cmd_sub
                        }
                        else if (cmd_sub > 0 && call_probe !~ /^[A-Za-z_][A-Za-z0-9_]*/) {
                            call_probe = strip_command_prefixes(cmd_rest, 0)
                            call_sub = cmd_sub
                        }
                        # **`subshell == 0` は名前を取り出す門番から外し、使う側へ移してある**
                        # （issue #189）。弱めの反映は部分シェルの中では見送る（親のオプションは
                        # 変わらない）が、**無条件に `exit` する関数の呼び出しはその部分シェルを
                        # 終わらせる**ので、同じ名前をそちらでも引く必要がある。
                        # **見送りは正しい答えではない**（issue #197）——`quiet() { set +e; }` を
                        # `( quiet; bash <スイート>; echo x )` で呼ぶと実 bash は失敗を捨てるのに
                        # wired と答える（`main` も同じ）。素で書いた `( set +e; … )` は issue #152
                        # の手当てで正しく not-wired なので、**同じ意味の 2 つの綴りで答えが割れて
                        # いる**。直し方は `set` 側と同じ「階層を限った反映」で、**門番を単に外す
                        # のは誤り**——`apply_errexit()` は開く前の深さで記録するので
                        # `( quiet )` 改行 `bash <スイート>` の errexit が最上位で落ちたままになり、
                        # 真値 GATES を not-wired にする（その対はピンにしてある）
                        # **この断片で死に体の区間が終わるなら、終わった側で読む**（issue #189 の
                        # レビュー）。印の解除は閉じるループの後ろにあるのに、呼び出しの追跡は
                        # ここ（閉じる前）なので、**区間が終わるその断片の呼び出しだけが
                        # 追跡から落ちて**いた——`f() { exit 0; }` ＋ `( exit 0` 改行 `echo a )`
                        # 改行 `f` 改行 `bash <スイート>` は実 bash でスイートが 1 行も走らないのに
                        # wired（`main` も同じなので新しい穴ではないが、**3 行足すだけで必須
                        # スイートを静かに外せる** fail-open）。素の `exit` の側は解除より後ろに
                        # あるので同じずれが無く、2 つの経路で答えが割れていた。
                        # ここの `depth` は閉じる前の値（＝下で `depth_in` に控えるのと同じもの）
                        # なので、解除と同じ条件をコマンド持ちの断片について評価できる
                        if ((dead_depth < 0 || depth <= dead_depth) && !set_forked && !unreachable \
                            && match(call_probe, /^[A-Za-z_][A-Za-z0-9_]*/)) {
                            # 先頭の識別子を呼び出し先の名前の候補として取り出す
                            fncall = substr(call_probe, 1, RLENGTH)
                            # 名前の後ろに続く部分（引数の有無を見て、語の切れ目かを確かめる）
                            fncall_rest = substr(call_probe, RLENGTH + 1)
                            # **語の切れ目のときだけ呼び出しと読む。** `foo=1`（代入）や `foobar`（別の名前）を
                            # 巻き込むと、走らない握り潰しを反映してゲートしているステップを赤くする
                            if (fncall_rest == "" || fncall_rest ~ /^[[:space:]]/) {
                                # **定義の本文の中の呼び出しは、その場では走らない**ので何もしない。
                                # 外側の関数が呼ばれれば走るため、呼び出し関係をたどって
                                # 弱めを伝播させる仕組みも一度は入れたが、**関数の本文は
                                # 「弱める／戻す」が起きた順序で結果が決まる**（`main() { set -e; relax; }`
                                # と `f() { g; set -e; }` は同じ材料でも答えが逆になる）。
                                # 順序を持たない台帳で近似すると、伝播を許せば握り潰しを見落とし
                                # （fail-open）、伝播を止めれば正しくゲートしているステップを赤くする
                                # （fail-closed）——どちらの向きにも実際に外し、レビューで 3 巡続けて
                                # 回帰を出した。**間接の追跡は順序付きの解析として別途入れる**ことにし、
                                # ここでは直接の本文だけを見る（`main` と同じ＝新しい穴は開かない）
                                # **呼び先が無条件に `exit` するなら、呼んだ時点から後ろは走らない**
                                # （issue #189）。`f() { exit 0; }` を呼んだあとのスイートは実
                                # `bash -e` で 1 行も走らないのに「必ず走る」と記録されていた
                                # （真値 NOGATE なのに `wired`。**3 行でスイートを静かに外せる
                                #   fail-open**）。台帳は `set` の弱めと同じ形で、定義の本文で
                                # 無条件に脱出する綴りを見たときだけ名前に控える。
                                # **部分シェルの中の呼び出しは部分シェルだけを死に体にする**
                                # ——上の脱出の判定（素の `exit`）とまったく同じ分岐へそろえる
                                # **`case` を開く断片は除く**（issue #189。隣の脱出のアームと同じ門番）。
                                # 1 行に畳んだ `case $X in a) f ;; esac` では `case` の階層が
                                # **この断片の末尾**で開くので、判定の時点では `uncertain` がまだ 0 で
                                # 素通りする。模様が当たるかは主語と照合しないと決まらない
                                # （issue #147）ので、数えると**実際にはゲートしているスイートを
                                # 「未配線」と報告**する（実測で `case $M in a) f ;; esac` ＋
                                # `bash <スイート>` が wired → not-wired ＝入れてはいけない向き）
                                # **連鎖の右辺でも「必ず走る」と分かるなら数える**（issue #202）。
                                # 以前は `prev_op` が `&&` / `||` なら一律に見送っていたため、
                                # `true && f`（`f() { exit 0; }`）のあとのスイートが「必ず走る」と
                                # 記録され、実 `bash -e` では 1 行も走らないのに `wired` だった
                                # （**2 トークン足すだけで必須スイートをゲートから外せる fail-open**）。
                                # **門番を単に外してはいけない**——読めない左辺（`[ -z "$X" ] && f`）の
                                # 右辺まで数えると、条件次第で走らない脱出で後ろを死に体にして
                                # **実際にはゲートしているスイートを「未配線」と報告**する
                                # （issue #189 で何度も踏んだ向き）。判定は既にある `chain_in`
                                # （「この断片が走ると証明できない連鎖の中か」）をそのまま読む
                                # ——新しい勘定は作らない（§6）。連鎖に入っていない断片では
                                # `chain_in` は 0 なので、従来の門番の意味はそのまま含まれる
                                if (!in_fndef_here && fnexit[fncall] && !opens_case_here \
                                    && uncertain == 0 && chain_depth == 0 \
                                    && !chain_in) {
                                    # 旗だけ立てて、下の 1 か所（解除のあと）で適用する
                                    exit_here = 1
                                    exit_sub = call_sub
                                }
                                # **この断片で部分シェルを越えた呼び出しの弱めも、その部分シェルへ
                                # 帰属させて反映する**（issue #200）。かつては `call_sub == 0` を門番に
                                # 加えて見送っていたが、それは `( quiet` 改行 `bash <スイート>` 改行
                                # `echo x )`（`quiet() { set +e; }`）を wired と答える fail-open だった
                                # ——実 bash では部分シェルの最後が `echo x` なので失敗は外へ出ない。
                                # **門番を単に外すのは誤り**で、`apply_errexit()` が `depth`＝部分シェルの
                                # **外**の階層で記録するため、内側の `set -e` が打ち消せなくなる
                                # （`strengthen_base` は「その部分シェルの中で落とした記録か」を
                                #   `weak_sub` で見る）。issue の実測では、外すだけだと 32 形が直る
                                # 代わりに `( ( quiet` 改行 `set -e` …の形が fail-closed へ倒れていた。
                                # **直し方は `set` 側と同じ「先に番号を振る」**（issue #180 / #187 で
                                # 入れた仕掛けを再利用する。新しい機構は作らない＝§6）
                                if (!in_fndef_here) {
                                    # 弱めを記録する階層＝この断片で越えた分だけ内側（越えていなければ `depth`）
                                    call_weak_at = depth + call_sub
                                    # **いま囲っている部分シェルの番号**（前の断片で開いた `(` の中なら
                                    # その番号、最上位なら 0）。`set` 側の `set_sub` とまったく同じ引き方で、
                                    # これを渡さないと「部分シェルの中で落とした」と結び付かず、
                                    # 閉じたときに入口の姿へ戻す経路も効かない
                                    call_weak_sub = sub_id[enclosing_subshell_depth(depth, subshell_at)]
                                    # この断片で部分シェルを越えて呼んだときだけ、越えた先の番号が要る
                                    # **予約するのは弱める関数を呼ぶときだけ**（レビュー指摘）。
                                    # ここは識別子で始まる断片すべてを通るので、条件を付けないと
                                    # `( echo hi` でも連番を 1 つ消費して共有の印（`sub_res_at`）を
                                    # 主張する。読み手は下の `fnweak_e[fncall]` の 1 か所だけなので
                                    # 挙動は変わらないが、印の意味が「弱めが階層を予約した」から
                                    # 「何かが予約した」へ広がり、`set` 側が「ピンが無い」と
                                    # 記録している余りの危険をそのぶん広げる
                                    if (call_sub > 0 && fnweak_e[fncall]) {
                                        # **階層ごとの連番はこの断片の開き側（下の開きループ）で振られる**ので、
                                        # ここで素直に読むと**親**の番号になり同じ部分シェルの中の `set -e` が
                                        # 打ち消せない。`set` 側と同じく**先に振って**おき、開き側は空いて
                                        # いなければそれを使う（`sub_res_at` が「この断片が予約した」の印）。
                                        # 既に `set` 側が同じ断片・同じ階層へ予約していればそれに相乗りする
                                        # ——振り直すと記録がどの階層とも結び付かなくなる
                                        if (!(sub_id[call_weak_at] && sub_res_at == i ":" j)) { sub_serial++; sub_id[call_weak_at] = sub_serial; sub_res_at = i ":" j }
                                        # 予約した（または相乗りした）番号を記録に添える
                                        call_weak_sub = sub_id[call_weak_at]
                                    }
                                    # **`at` に使うのは「越えた一番内側の部分シェル」の増分**（`call_sub`）で、
                                    # `set` 側が `at` に使う「開いた階層すべての数」ではない。ブレースを
                                    # 一緒に越える綴り（`( { quiet; set -e; …`）では命令が走るのは 1 段深い
                                    # ブレースの中だが、打ち消しの比較が「弱めた階層以上の深さで戻したか」
                                    # なので**ブレースの中の `set -e` でも成立する**（混在 6 形で実測。
                                    # 部分シェル側で戻す形・3 段の入れ子も含めて真値どおり）。
                                    # **余った予約の始末は `set` 側の注記が正本**（開き側が越えた数より
                                    # 少なく開く綴りでは予約が余る。印を共有しているので同じ境界が掛かる）
                                    # **呼び出しに着いた時点で畳み直す。** 定義の順序は自由なので、
                                    # 控えた時点では呼び先がまだ弱めると分かっていないことがある
                                    # errexit を落とした関数なら、`set +e` と同じ扱いで落とす
                                    # （`apply_errexit()` を通すので、同じ階層の `set -e` で打ち消せる）
                                    # **第 7 引数（どの部分シェルの中で落としたか）を省かない**
                                    # （issue #189 の 3 巡目のレビュー）。省くと awk の未初期化値が
                                    # `weak_sub` へ入り、いまは数値比較なので 0 と同じに振る舞うが、
                                    # 比較の書き方が変わった瞬間に「部分シェルの中で落とした」と
                                    # 誤って帰属する。部分シェルの外なら意図の 0 を明示する
                                    if (fnweak_e[fncall]) { errexit = apply_errexit(0, 0, uncertain, 1, errexit, call_weak_at, call_weak_sub) }
                                    # **pipefail は部分シェルの中では据え置く**（門番は `main` と同じ
                                    # `subshell == 0 && call_sub == 0` のまま＝この変更で挙動を動かさない）。
                                    # `set_flag()` は階層を持たないので、部分シェルの中で反映すると内側の
                                    # `set -o pipefail` で打ち消せず**正しくゲートする綴りを赤くする**
                                    # （errexit 側が `apply_errexit()` で階層を持つのと非対称）。
                                    # **`call_sub == 0` だけに緩めるのでは足りない**——呼び出しを開き括弧の
                                    # 次の行に書くと `call_sub` は 0 なので反映され、`set -o pipefail` /
                                    # `( pq` / `set -o pipefail` / `bash <スイート> | cat )` が
                                    # wired → not-wired へ倒れた（真値 GATES。この差分の作業中に実測し、
                                    # `fncall_pipefail_scope` のピンで固定した）。
                                    # 階層を持たせるのは issue #203（部分シェル・グループの中の
                                    # `set -o pipefail` が反映されない）の仕事なので、そこで一緒に閉じる
                                    if (fnweak_pipe[fncall] && subshell == 0 && call_sub == 0) { pipefail = set_flag(0, 0, 1, pipefail) }
                                }
                            }
                        }
                        # 空の断片（`;;` や行頭の区切り）は記録しない
                        # **アームの終端（`;;` / `;&`）の跡だけを見る。** `split_commands` は
                        # `;` ごとに切るので `;;` は「空の断片＋区切り `;`」として現れる。
                        # **区切りを見ずに「空の断片」だけで判定してはいけない**——行末の
                        # ただの `;`（`a) :;`）も最後の空の断片を作るため、アームの本体の
                        # 途中で模様の位置が立ち、続く本物の部分シェルの `(` を模様と読む
                        # （一致しないアームの中身が最上位に上がる fail-open。`;` 1 文字で
                        #   この検査を外せる状態だった。レビューで実測）。
                        # 終端の跡は**区切りを伴う**空の断片なので、そこだけを見る
                        # （最後の空の断片は区切りを持たない＝`ops[j]` が空文字）
                        if (text == "") {
                            # `&` を認めるのは `;&`（フォールスルー）のときだけ。`|&` も空の断片を
                            # 残すが、あれはパイプであってアームの終端ではない——認めるとアームの
                            # 本体の途中で模様の位置が立ち、本物の部分シェルの `(` を模様と読む
                            # （fail-open。レビューで実測）。直前の区切りは空でない断片のものが残る
                            if (case_depth > 0 && (ops[j] == ";" || (ops[j] == "&" && prev_op == ";"))) { arm_expected = 1 }
                            continue
                        }
                        # **制御構造の深さを追う。** `if` / `while` / `for` / `case` / 関数定義の中身は
                        # 条件や呼び出し元を読まないと実行されるか分からない。1 行で書かれた
                        # `if false; then bash x; fi` は `then` を実行ラッパに入れないことで弾けていたが、
                        # 同じ意味を 3 行で書くと弾けていなかった（2 行足すだけでスイートを止められる。レビューで実測）。
                        # 閉じ側を先に見るのは `fi` / `done` が自分の階層を閉じるため
                        # 閉じ側。**その階層が「走るか分からない」側だったかを覚えておき**、
                        # 対応する分だけ戻す（`uncertain_at[]` が階層ごとの印）
                        # この断片が閉じる階層の数（キーワードの分＋括弧の分）。
                        # 畳むループを 1 つにするための勘定（issue #121）
                        close_n = 0
                        # **閉じ語も 1 断片に 2 つ以上載る。** 開き側が 1 断片で複数開けるように
                        # なった以上、閉じ側も同じだけ閉じられないと深さが戻らない
                        # （`f() { if :; then` … `fi }` は bash では 2 つ閉じる。1 つしか
                        #   閉じないと以降が「まだ関数の本体の中」に見え、正しくゲートしている
                        #   呼び出しを「未配線」と誤報する。レビューで実測）
                        # **模様の位置では閉じ語も模様。** `case $X in` / `;;` の直後に来る
                        # `done|other)` の `done` は `done` という模様であって `do … done` の
                        # 閉じではない。閉じ扱いすると `case` の階層をそこで畳んでしまい、
                        # 直前のアームで見た `set +e` まで巻き戻される（fail-open。レビューで実測）。
                        # **`esac` だけは例外**——模様の位置に来た `esac` は空の `case` の終わりで、
                        # 本当に閉じる（`case x in esac` は bash の妥当な綴り）
                        close_probe = text
                        # 模様の位置かどうかを見るのは**断片の先頭の閉じ語だけ**。
                        # 2 つ目以降はもう模様ではない（`esac }` の `}` を模様と読むと
                        # 階層が戻らず、以降が「まだ関数の本体の中」に見える。レビューで実測）
                        close_first = 1
                        # **ここでは数えるだけで、階層はまだ畳まない**（issue #121）。
                        # 畳む処理は括弧の分と共通で、以前は**同じ 8 行がここと括弧側の 2 か所に
                        # 写しで**あった（階層ごとの状態を 1 つ足すたびに片方へ入れ忘れる形で、
                        # PR #118 が実際にそれをやっている）。数だけ `close_n` に集めて
                        # **1 つのループ**で畳めば写しが消える。
                        # **順序は変わらない**——どちらの経路も「内側から 1 つずつ、同じ 8 行」なので、
                        # 合計を内側から畳むのと結果が同じ（`closed_entry_e` / `closed_scope` は
                        # 内側から順に積むので、引き継ぎ方もそのまま成り立つ）。
                        # **括弧側の判定（`paren_probe`）がこの畳みを先に必要としないことも要る**——
                        # 読むのは `text` / `set_arm_here` / `case_scope` / `arm_expected` / `ops[j]` だけで、
                        # どれもこの断片に入る前に確定しており `depth` にも `subshell` にも依存しない
                        # （依存していたら、畳む位置を後ろへ動かした時点で判定が変わっていた）
                        # **数え過ぎても結果は変わらない**ので、残りの深さを引く形にはしない。
                        # 以前は 2 つのループが別々に `depth > 0` で止まっていたので、閉じた総数は
                        # 「キーワードの分を深さで打ち切り、残りの深さで括弧の分を打ち切る」＝
                        # `min(min(K, depth) + P, depth)`。畳むループを 1 つにすると合計を 1 度だけ
                        # `depth > 0` で打ち切るので `min(K + P, depth)` になり、**K <= depth なら
                        # 同じ式、K > depth ならどちらも `depth`** で、ずれる入力が存在しない
                        # （`K` は消費できる閉じ語の数、`P` は `max(0, -paren)`）。
                        # **実測でも、残りの深さを引く形との差は 1 件も無い**——効かない条件を残すと
                        # 「ここで打ち切っている」と読めてしまうので置かない（§6 デッドコードを残さない）
                        while (close_probe ~ close_word_re() && depth > 0 \
                               && !(close_first && arm_expected \
                                    && (close_probe !~ esac_word_re() || prev_op == "|"))) {
                            close_first = 0
                            close_n++
                            # **`case` の入れ子はここでは数えない。** この走査は `depth > 0` で
                            # 止まるので、階層を別の綴りが先に閉じてしまい `esac` が深さ 0 で
                            # 来る場合に数え損ねる。数えるのは下の `esac_probe` の走査
                            # （`depth` から独立に、同じ閉じ語の綴りと同じ模様の位置の判定で歩く）
                            # 閉じた語の分だけ進める。**1 文字も減らなければ打ち切る**（無限ループ避け）
                            close_rest = drop_close_word(close_probe)
                            if (close_rest == close_probe) { break }
                            close_probe = close_rest
                        }
                        # **括弧は釣り合いで測る。** 閉じ側が断片の**先頭**に来るとは限らず、
                        # `( cd /tmp; echo hi )` のように末尾で閉じる書き方だと深さが戻らない
                        # ——この ci.yml も 1 行の部分シェルを使っており、その後ろに呼び出しを
                        # 足した瞬間に「配線されていない」と逆の診断で赤くなる（レビューで実測）。
                        # `$(foo)` のようなコマンド置換は開閉が揃うので差し引き 0 になる
                        # **`case` のパターン（`never)`）の `)` は部分シェルの閉じではない。**
                        # 数えてしまうと `case` が開いた深さがその場で打ち消され、
                        # 一致しないアームの中身が「最上位で実行される」と読まれる（レビューで実測）
                        paren_probe = text
                        # 上で求めた判定を使い回す（`starts_case_arm()` は伏せ処理を伴うので、
                        # **判定そのもの**を同じ断片で 2 度求めない。剥がす綴りも揃える）。
                        # **「`mask_quoted()` を 1 度しか通らない」という意味ではない**
                        # （issue #123 の補足）——`set_masked` は真偽ではなく**伏せた本文**が
                        # 必要なので別に 1 度通る。節約しているのは判定と剥がしの方で、
                        # 伏せ処理まで 1 回に畳むには伏せた写しを控える器が要る（§8 の
                        # 「計測してから最適化する」に従い、要ると分かってから入れる）
                        if (set_arm_here) {
                            paren_probe = drop_arm_head(paren_probe)
                        }
                        # **アーム模様が `|` で切られた前半の `(` は部分シェルの開きではない。**
                        # `split_commands` は `(a|q)` を `(a` と `q)` に切るので、素直に数えると
                        # 釣り合いが崩れて幻の階層が開き、以降その断片の `set` がすべて
                        # 「部分シェルの中」として無視され、`esac` は本物の階層ではなく
                        # 幻の方を閉じる（以降の呼び出しが「未配線」に化ける。実測）
                        # **この断片自身が `case` を開く場合も含める**（issue #123 (4)。fail-open）。
                        # 深さも `case_depth` も増えるのは断片の末尾なので、1 行書きの
                        # `case x in (x|y) set +e ;; esac` を処理している最中はまだ 0 のままで、
                        # `case_depth > 0` だけを条件にすると当たらない（`set_arm_here` /
                        # `set_masked` が既に補償しているのと同じ off-by-one）。
                        # **`(` が先頭にあるとは限らない**のも同じ理由——1 行書きでは
                        # `case x in (x` のように `case … in ` の前置きが手前に付く。
                        # ただし**「`case … in` の直後」か「断片の先頭」に限る**のが要点で、
                        # 「閉じられていない最後の `(`」まで広げると `case` の中の**本物の**
                        # 部分シェルを食う——`case never in a) time ( : | cat ) …` の `(` を
                        # 落とすと階層が開かず、続く `)` がアームの階層を閉じて、
                        # **一致しないアームの中身が最上位のコード**として読まれる
                        # （fail-open。まさにこのライブラリが塞ぐ *absence == pass* の形。
                        #   レビューで実測）。**判定は「模様の位置にいるか」で行う**——
                        # アーム模様が現れるのは `case … in` の直後と `;;` の直後の 2 か所だけで、
                        # そのどちらかを `arm_expected` が追っている（`;;` は `split_commands` が
                        # 空の断片として切るので、そこで立て直す）。同じ断片に `case … in ` の
                        # 前置きが載る 1 行書きは、その前置き自体を手がかりにする。
                        # **「先頭の `(`」や「1 語かどうか」を手がかりにしてはいけない**——
                        # `case never in a) NL ( : | cat $(date) ) NL bash x ;; esac` の `( :` は
                        # 断片の先頭にあり、括弧の後ろも 1 語なのに**本物の部分シェル**で、
                        # 落とすと続く `)` がアームの階層を閉じて、一致しないアームの中身が
                        # 最上位のコードとして読まれる（`main` から続く fail-open。レビューで実測）。
                        # 判定を誤る向きは**落とさない側が fail-closed**（幻の階層が開いて以降の
                        # 呼び出しが「未配線」に化ける）なので、迷ったら落とさない側へ倒す
                        # （伏せた写しで位置を測る。引用の中の `(` を数えないため。長さは保たれる。
                        #   `RSTART` は後続の `trim()` / `~` で壊れうるので、読んだ直後に控える）
                        else if (case_scope && ops[j] == "|") {
                            arm_masked = mask_quoted(paren_probe)
                            if (match(arm_masked, /\([^()]*$/)) {
                                arm_at = RSTART
                                if ((arm_at == 1 && arm_expected) \
                                    || substr(arm_masked, 1, arm_at - 1) ~ /(^|[[:space:]])case[[:space:]].*[[:space:]]in[[:space:]]*$/) {
                                    paren_probe = substr(paren_probe, 1, arm_at - 1) substr(paren_probe, arm_at + 1)
                                }
                            }
                        }
                        # **階層を開く前置きが手前に付いた 1 行書きの見出しも外す**（issue #145）。
                        # `set_arm_here` は「**囲っている** `case` のアーム見出しで始まるか」なので
                        # `f() { ( case $X in a)` では偽になり、上の剥がしを通らない。その結果
                        # 見出しを閉じる `)` が先頭の `(` を打ち消して `paren` が 0 になり、
                        # `(` の階層が 1 つも開かないまま続く `esac` が**関数の階層**を閉じて、
                        # 呼ばれていない本体が「最上位で確実に走る」として記録されていた。
                        # 落とすのは `)` の 1 文字だけなので、先頭の `(` はそのまま数えられる
                        paren_probe = drop_arm_head_close(paren_probe)
                        paren = paren_delta(paren_probe)
                        # 括弧で閉じる分を同じ勘定へ足す（キーワードの分は上で数えてある）
                        if (paren < 0) { close_n -= paren }
                        # **階層を畳むのはここ 1 か所だけ**（issue #121）。キーワードで閉じる分と
                        # 括弧で閉じる分を合わせて、内側から 1 つずつ戻す。
                        # 階層ごとの状態（`uncertain_at` / `fndef_at` / `true_at` /
                        # `subshell_at` / `entry_*`）を増やすときに触るのはこのループだけでよい
                        # **閉じる前の深さを控える**（issue #189）。この断片の中身が走るのは
                        # 「閉じる前」の階層で、`bash <スイート> )` のように閉じ括弧が同じ断片に
                        # 載る綴りでは閉じた後の深さと 1 つ以上ずれる。死に体の区間の照合
                        # （下の `dead_depth` の解除）はこの値で行う——閉じた後の深さで照合すると、
                        # `( exit 0; bash <スイート> )` の 2 つ目の断片で印が**記録より前に**
                        # 解除され、1 行も走らないスイートが「必ず走る」と記録される（実測）
                        # **囲っている部分シェルの階層も閉じる前に控える**（issue #189 のレビュー）。
                        # 呼び出しから立った脱出の旗（`exit_here`）を適用するのは下の 1 か所で、
                        # そこは閉じるループより**後ろ**。`f )` のように呼び出しと閉じ括弧が
                        # 同じ断片に載る綴りでは、適用の時点で `subshell` がすでに 0 に戻って
                        # いるため「部分シェルの中の脱出」が**シェルごとの脱出**として記録され、
                        # 以降のすべての記録が gate 0 になる（実測で `f() { exit 0; }` ＋ `(` ＋
                        # `f )` ＋ `bash <スイート>` が wired → not-wired ＝正しくゲートして
                        # いるワークフローを赤くする fail-closed。`)` を別行に置いた綴りだけが
                        # 正しく答えるという、改行の位置で答えが変わる形でもあった）
                        sub_lead_in = (subshell > 0) ? enclosing_subshell_depth(depth, subshell_at) : 0
                        depth_in = depth
                        # この断片が閉じた階層（識別子）を控える。閉じた後の区切りは
                        # 記録を書き出すときに分かるので、そこで `scope_op` へ入れる
                        nclosed_scope = 0
                        # 命令の位置より手前でこの断片が開いた階層の数（下の開き側で数える）
                        cmd_opens = 0
                        # この断片の記録の番号（書き出した直後に控える。0 なら書いていない）
                        rec_at = 0
                        for (closing = 0; closing < close_n && depth > 0; closing++) {
                            if (uncertain_at[depth]) { uncertain--; uncertain_at[depth] = 0; closed_uncertain = 1 }
                            if (fndef_at[depth]) { fndef--; fndef_at[depth] = 0 }
                            true_at[depth] = 0
                            # **部分シェルの入口は別に控える**（issue #152）。下の巻き戻しで
                            # 使うのは「閉じた一番外側の**部分シェル**の入口」で、`closed_entry_*`
                            # （閉じた一番外側の階層）とは別物——`{ set +e; ( : ) }` のように
                            # 同じシェルのブレースを一緒に閉じる断片では、ブレースの入口まで
                            # 戻すと**親で効いている握り潰し**を消してしまう（fail-open）
                            if (subshell_at[depth]) {
                                subshell--; subshell_at[depth] = 0; sub_id[depth] = 0; closed_subshell = 1
                                closed_sub_e = entry_errexit[depth]; closed_sub_p = entry_pipefail[depth]
                                closed_sub_seen = 1
                            }
                            if (chain_at[depth]) { chain_depth--; chain_at[depth] = 0 }
                            # **反転した階層を閉じた断片は、その中の最後のコマンドを載せている。**
                            # 階層が閉じるのは記録より**先**なので（1 行に畳んだ
                            # `! ( : ; bash <スイート> )` は閉じ括弧が呼び出しと同じ断片）、
                            # ここで控えないと反転が記録に載らず「最上位で確実に走る」になる
                            # （issue #155。実測で `! { … }` の複数行は閉じたのに
                            #  `! ( … )` の 1 行書きだけが wired のまま残った）
                            if (inverted_at[depth]) { closed_inverted = 1; inverted_at[depth] = 0 }
                            # 巻き戻し先はこの断片が閉じた**一番外側**の階層の入口。
                            # 閉じる順は内側からなので、上書きし続ければ最後に残るのが一番外側
                            closed_entry_e = entry_errexit[depth]; closed_entry_p = entry_pipefail[depth]; closed_entry_seen = 1
                            # 閉じた階層を控える（区切りはこの断片の記録を書くときに入れる）
                            nclosed_scope++; closed_scope[nclosed_scope] = scope_at[depth]
                            depth--
                        }
                        # **フォークして閉じた複合コマンドの中の `set` は親へ漏れない。**
                        # `while …; do set +e; done | cat` / `{ set +e; } | cat` / `… &` は
                        # どれも子シェルで走るので、閉じた時点で入口のオプションへ巻き戻す
                        # （issue #123 (1)）。開き側の子シェル判定は**複合を開く断片に `|` が
                        # 付いているとき**しか成立せず、複合がパイプの**左側**にあると一度も
                        # 真にならないため、そこでしか効かない `set +e` を親に効いたものとして
                        # 扱い、正しくゲートしているステップを「未配線」と誤報して赤くしていた。
                        # **`||` / `&&` / `;` はフォークしない**（実 bash と差分照合して実測。
                        # `{ set +e; } || true` の握り潰しは親へ漏る）ので、対象は `|` と `&` だけ。
                        # 「閉じた断片に付いた区切りは閉じた階層に掛かる」という `scope_op` と
                        # 同じ考え方を、区切りではなくオプションへ当てたもの
                        # **括りの記録（`weak_depth`）はここで触らない。** 巻き戻すのは
                        # 子シェルの中で変わったオプションだけで、**外側の階層で落とした**
                        # `set +e` の記録は生きている。消すと
                        # `for … do set +e; { :; } | cat; set -e; done` のように括りの
                        # 途中にフォークする複合が挟まるだけで `set -e` が打ち消せなくなり、
                        # 正しくゲートしているステップを「未配線」と誤報して赤くする
                        # （fail-closed。レビューで実測）。閉じたブロックの**中**で落とした分は
                        # 下の `(closed_subshell || closed_uncertain) && weak_depth > depth` が
                        # 捨てている——**「閉じたら必ず」ではない**（フォークした階層と、走ると
                        # 証明できない階層だけ）。issue #199 まではここに「どの階層でも閉じたら」と
                        # 読める旗の名前が書いてあり、内側の `set +e` は常に捨てられると誤読できた
                        # **部分シェルを閉じたら、区切りに関係なく入口の姿へ戻す**（issue #152）。
                        # `( … )` は常に子シェルで走るのでオプションは親へ漏れない。戻さないと
                        # 中の `set +e` が親へ漏れ、正しくゲートしているステップを「握り潰されて
                        # いる」と誤報して必須ジョブを赤くする（issue が明示的に禁じている向き）。
                        # **記録（`weak_depth`）はここで触らない**——理由は下の `|` / `&` の
                        # 巻き戻しと同じで、外側の階層で落とした分は生きている
                        if (closed_sub_seen) {
                            errexit = closed_sub_e
                            pipefail = closed_sub_p
                        }
                        if (closed_entry_seen && (ops[j] == "|" || ops[j] == "&")) {
                            errexit = closed_entry_e
                            pipefail = closed_entry_p
                            # **関数ごとの台帳はここでは触らない。** 「閉じた階層より深いところで
                            # 控えた分」を落とす形にすると、**最上位で定義した関数**（本文は深さ 1）が、
                            # 無関係な複合コマンドが深さ 0 でフォークして閉じただけで消える
                            # ——`quiet() { set +e; }` の後ろに `… done | sort` が 1 行あるだけで
                            # 握り潰しの記録が失われ、握り潰されたスイートが「ゲートしている」と
                            # 読まれる（fail-open。レビューで実測）。階層の数値だけでは
                            # 「この複合の中で控えたか」を区別できないため、区別できる印を
                            # 持たせるまでは触らない（子シェルの中の `set +e` を関数の台帳へ
                            # 残してしまう側は fail-closed なので、そちらへ倒す）
                        }
                        # 閉じたブロックの中で落とした記録は、外へ持ち出さない。
                        # **実際に閉じた断片でだけ見る**のが要点で、無条件に比べると
                        # `case … in y) set +e` のように「これから増える階層」へ記録した分を
                        # 同じ断片の中で消してしまう（深さが増えるのは断片の末尾のため）
                        # **記録を捨てるのは子シェルを閉じたときだけ。** 同じシェルで走る括り
                        # （`{ … }` / `if … fi` / ループ）の中で落とした `set +e` は、閉じた後も
                        # 親に残る——bash がそうだから。以前は「閉じた階層より深い記録は捨てる」
                        # としていたが、`set` を**走る深さ**で記録するようになった以上それでは
                        # `{ set +e; }` ＋ 外の `set -e` の打ち消しまで消える。
                        # 外の `set -e` が内の `set +e` を打ち消してよいかは、深さの向きで
                        # `apply_errexit()` が判断する（外側＝より確実に走る側だけが打ち消す）
                        if ((closed_subshell || closed_uncertain) && weak_depth > depth) { weak_depth = -1 }
                        # **条件がその場で偽と分かるブロックの中身は、どの照会からも証拠にしない。**
                        # 深さで除くのは実行の照会だけなので、`if false; then shellcheck $LIST; fi` は
                        # リンタの照合（ステップの形を見る側）を素通りしてしまう——2 行で lint を止められる
                        # （実行の証拠にならないだけでなく、そもそも走らないので合否にも効かない。レビューで実測）
                        # **照合の深さは「この断片の中身が走る階層」で選ぶ**（issue #189）。
                        # コマンドを載せた断片の閉じ括弧は**後置**（`bash <スイート> )`）なので
                        # 中身は閉じる前の階層で走る——閉じた後の深さで照合すると印が記録より
                        # 前に解除され、1 行も走らないスイートが「必ず走る」と記録される（実測）。
                        # 逆に閉じ語だけの断片（`fi` / `)` / `done`）は中身を持たず、**その断片の
                        # 後半で読む `set` は閉じた後の階層で走る**ので、そちらは閉じた後の深さで
                        # 照合しなければならない——`for … do` ＋ `set +e` ＋
                        # `if false; then exit 1; fi` ＋ `set -e` の `set -e` は `fi` の断片で
                        # 印が解けていないと読まれず、正しくゲートしているステップが赤くなる
                        # （ピン「偽と分かるブロックの中の exit も括りを壊さない」が実測で落ちた）。
                        # 先頭に閉じ語を置いて同じ断片にコマンドを続ける綴りは bash に無い
                        # （`)` / `}` / `fi` の後ろは区切りか演算子が必須）ので、2 つは排他
                        if (dead_depth >= 0 && (carries_command(text) ? depth_in : depth) <= dead_depth) { dead_depth = -1 }
                        # **直前の区切りも見る。** `true || bash x` / `false && bash x` は
                        # その場で偽と分かる条件なので、その断片は 1 度も走らない
                        # ——`|| true` より 1 トークン短くスイートを止められる（レビューで実測）
                        # **連鎖の途中で終わらせない。** `false && a && bash x` のように
                        # 2 つ先へ続く形でも、その先はすべて走らない（レビューで実測）。
                        # `;` や行末で連鎖が切れたら、そこで伝播も終わる
                        # **向きが変わる連鎖を取り違えない。** `false && echo mid || bash x` の
                        # `bash x` は走る（`&&` が外れた時点の状態は失敗なので `||` の右が動く）。
                        # 「直前が `||`／`&&` なら伝播を続ける」とだけ書くと、走る呼び出しを
                        # 「未配線」と事実と逆に診断して赤くする（レビューで実測）。
                        # 走らなかった断片は連鎖の状態を変えない（判定は最後に走った結果で決まる）
                        # **判定は `chain_literal_status()` が持つ**（先頭のグループの開きや
                        # `!` を見てから真偽を決める。生の綴りで比べると `( true` が読めない）
                        if (!unreachable && dead_depth < 0) { chain_status = chain_literal_status(text) }
                        # ジョブの控えへ積む。**判定に要る材料（直後の区切り・`set` の明示・深さ）ごと**渡し、
                        # ゲートかどうかの結論はジョブが確定するときに出す
                        nbuf++
                        # **控えるのは生の本文（`text`）で、継続語を剥がした `struct_text` ではない。**
                        # issue #123 (3) は「1 行に畳んだ `if true; then bash x; fi` も実行の証拠に
                        # すべき」と言い（断片が `then bash x` になり `CI_WORKFLOW_COMMAND_START` に
                        # 当たらないため）、実際 `struct_text` を控えればその 1 件は直る。
                        # **だが同じ変更で fail-open が丸ごと開く**（実測）——`open_form()` が読めない
                        # 語で始まる断片（`( if false`、`time if …`、`! if …`）では
                        # 制御構造そのものが分類されず、`uncertain` も `dead_depth` も立たない。
                        # そこへ継続語を剥がした本文を控えると、**1 度も走らない本体が
                        # 「最上位で確実に走る」**として記録される:
                        #     ( if false; then bash x; fi )   → 「配線されている」
                        # 剥がさなければ `then bash x` のまま当たらない——**ただしそれが受け皿だったのは
                        # issue #123 (3) までで、`ci_workflow_runs_script` の錨が継続語を許した時点で
                        # この受け皿は消えた**（`CI_WORKFLOW_BLOCK_BODY_START` は `then ` / `do ` /
                        # `else ` を許す）。いま畳んだ本体を止めているのは `uncertain` と `dead_depth`
                        # の勘定だけで、**「生の本文なら当たらないから安全」と書き戻さないこと。**
                        # なお `CI_WORKFLOW_COMMAND_START` の説明にあった同趣旨の一文は
                        # issue #123 (3) で消えているので、そこを参照先にしないこと（いまの正本は
                        # `CI_WORKFLOW_BLOCK_BODY_START` の説明と `test/ci_coverage_test.sh` の
                        # 「錨は網ごとに選び分ける」）。
                        #
                        # **上の 4 形は開き側が読めるようになった**（issue #114 のレビュー）。
                        # `time` / `!` は `open_form()` が `strip_struct_wrappers()` を
                        # 通して分類するので階層が開き、`(` は釣り合いが階層を開く。
                        # **偽と分かる条件そのものは `strip_dead_cond_prefixes()` 経由で見る**ので、
                        # `( if false; then bash x; fi )` は畳んでも複数行でも gate=0 で記録される
                        # （複数行の綴りは `main` では素通りしていた既存の穴で、同じ変更で閉じた）。
                        # それでも**ここで控えるのは生の本文のまま**にする——`struct_text` を控えると
                        # 「0 回まわるループの中の呼び出し」まで最上位の実行として記録され、
                        # そちらは条件を読まずに判断できない（`for f in $EMPTY; do bash x; done`）。
                        # つまりここで生の本文を控える理由は「死に体の除去」から
                        # 「回数の分からない本体を `struct_text` 経由で持ち上げないこと」へ移った
                        # （錨が継続語を許すようになったので、受け皿としての働きはもう無い）
                        # **手前の `&&` / `||` も「走るか分からない」印に数える。** 5 列目は
                        # 「走ると証明できない理由の数」で、制御構造の深さ（`uncertain`）に
                        # 連鎖の分を足す——実行の照会（`top`）はこの列が 0 の記録だけを通すので、
                        # `test -n "$RUN" && bash <スイート>` が「最上位で確実に走る」として
                        # 数えられなくなる（実 `bash -e` では `$RUN` が空なら 1 度も走らないのに
                        # `wired` だった＝**2 トークンで必須スイートを無効化できる fail-open**。
                        # issue #150。`main` 既存で、素の呼び出し・ブレース・部分シェルの 3 形）。
                        # **`chain_in` を見るのは `true_at` の枝だけでは足りない**——あちらは
                        # 「`if true` の本体を最上位へ持ち上げるか」の判定で、持ち上げない形
                        # （素の呼び出し）には掛からない。記録を書き出すこの 1 か所で見る。
                        # **リンタの照会（`top` を渡さない）は巻き込まない**のが要点で、
                        # `test -n "$FILES" && shellcheck $FILES` は正当な綴り——`gate` 側を
                        # 0 にすると、正しく設定されたリンタを「配線されていない」と報告する
                        # **記録は 6 列**（ステップ番号・直後の区切り・errexit・pipefail・走るか分からない数・本文）。
                        # 7 列目として「部分シェルの中か」を載せていたが、issue #191 で gate の
                        # 判定が `record_gates()` へ移った時点で読み手が消えた——部分シェルの
                        # 情報は階層ごとの `scope_sub` が運ぶので、載せ続けると「この旗が判定に
                        # 効く」と読める写しになる（レビュー指摘。§6 デッドコード）
                        buf[nbuf] = step_id "\t" ops[j] "\t" ((dead_depth >= 0 || unreachable || exit_seen) ? 0 : errexit) "\t" pipefail "\t" (uncertain + (chain_in ? 1 : 0) + (closed_inverted ? 1 : 0)) "\t" text
                        rec_at = nbuf
                        # **「走らない記録」と「errexit が切れている記録」を分けて控える**
                        # （issue #191）。どちらも 3 列目は 0 になるので、位置で判定する側
                        # （`set +e` の下でステップ最後なら伝わる）が区別できないと、
                        # 到達不能な呼び出しを「ゲートしている」と読む fail-open になる
                        rec_dead[nbuf] = (dead_depth >= 0 || unreachable || exit_seen) ? 1 : 0
                        # **「走ると証明できない理由」のうち制御構造の分だけを控える**。
                        # 記録の 5 列目は `chain_in`・反転を足した合計なので、`|| (` の中
                        # （連鎖の右辺なので `chain_in` が立つ）が区別できない
                        rec_unc[nbuf] = uncertain
                        # **閉じた階層の区切りは「閉じたあとに続く区切り」**（この断片の区切り）で、
                        # 付けるのは**この断片が閉じた一番外側の階層だけ**（`closed_scope` は
                        # 内側から積むので末尾が一番外側）。内側の階層にも同じ区切りを付けると、
                        # 歩きが内側を出た時点で `&&` を拾って「吸われた」と判断し、まだ
                        # 部分シェルを出ていないのに位置の判定を省く fail-closed になる
                        # （`( { bash <スイート> ; } ) && echo ok` が not-wired。実測）。
                        # 内側は「閉じた直後に外側の閉じが続く」＝並びの終わりなので区切りは空
                        for (ci = 1; ci <= nclosed_scope; ci++) {
                            scope_close_at[closed_scope[ci]] = nbuf
                            scope_op[closed_scope[ci]] = (ci == nclosed_scope) ? ops[j] : ""
                        }
                        # **部分シェルの中の記録を閉じるときに引き上げる仕掛けはここにあった**
                        # （issue #152 で入れ、#199 で削除）。**削除は 2 つのことをした。**
                        # (1) 入れ子で部分シェルを開く綴りでは、内側の**裸の開き括弧**の記録が
                        # 「合否に効くコマンドの一覧」（`ci_workflow_gating_commands`）から落ちる
                        # ——引き上げが errexit を入口の値へ書き戻していたため公開対象に入っていた。
                        # **入れ子で開けば必ず落ちるわけではない。** 素の入れ子（`(` / `set +e` /
                        # `(` / `shellcheck $LIST` / `)` / `)`）と、そこへ `echo y` を内側／内側の
                        # 閉じの後ろへ足す形、開きの前に `true` を置く形は、**main も head も同じ
                        # 記録**で差が出ない（16 巡目のレビューが「入れ子で開く綴り」という一般化へ
                        # 反例を出し、こちらでも測り直した）。差が出たのは**開き／閉じの断片が
                        # コマンドを持つ**綴りで、`shellcheck $LIST && (` ＋ `echo x` ＋独立行の `)`
                        # が main 6 件・head 5 件、`shellcheck $LIST | cat )` が main 4 件・head 3 件
                        # （**パイプは条件ではない**——前者は持たない）。**条件をこれ以上綴りの規則へ
                        # 一般化しない**（挙げたのは測った形そのもので、落ちるのはどの形でも
                        # 裸の `(` だけ）。この記録はコマンドを持たないので
                        # 照会 3 つ（いずれもコマンドの綴りで突き合わせる）からは観測できず、
                        # 答えは動かない。
                        # (2) **`main` の fail-open を直した**（4 巡目のレビューが反例を出して実測。
                        # 範囲は 7 巡目に測り直した）——**部分シェルの最後に走るのが `set -e`**
                        # になる綴りは実 `bash -e` で NOGATE（最後に走るのが `set -e` なので
                        # スイートの失敗は外へ出ない）なのに、引き上げが入口の errexit を
                        # 書き戻すため `main` は wired と答えていた。削除後は正しく未配線。
                        # **制御構造は条件ではない**——いちばん素直な `( ` / `set +e` /
                        # `bash <スイート>` / `set -e` / `)` も同じで、閉じる断片の
                        # リダイレクト（`) >/dev/null` 等）でも同じ。**向きは一方向**で、
                        # 変わるのは必ず wired → not-wired（逆向きは 1 件も無い。corpus ごとの
                        # 実測値は `docs/requirements.md` の変更履歴が正本——**件数を写さない**。
                        # 形の数は corpus の作り方で変わるので、写すと必ず古くなる）。
                        # **だから「どの判定も決めていなかった」は誤り**で、当時の計測
                        # （全ピン・36 形・corpus 7 本 3,530 形）にこの形が 1 つも
                        # 入っていなかっただけ。向きが fail-open なので
                        # `ci_workflow_test.sh` の `sub_tail_set_case` のループで押さえた
                        # （**件数は書かない**——`main` ではその全件が落ちる＝実測。
                        #  そのうち「`set -e` に戻したあと処理が続く」1 本だけが、
                        #  「最後が `set -e` のときだけ」と狭めて引き上げを戻す変異を捕まえる）
                        #
                        # ---- ここまでが削除の記録。以下は直後の live なコード（`dead_depth`）の契約 ----
                        # 偽と分かる条件のブロックに入るところを覚える（この深さより深い間は無効）
                        # **連鎖が続くなら条件は 1 語だけではない。** `split_commands` は `&&` / `||` で
                        # 切るので、`if false || true; then` の断片は `if false` になる。素直に
                        # 「必ず走らない」と印を付けると、実際には走る本体の `set +e` が捨てられ、
                        # 握り潰されたスイートが「ゲートしている」と読まれる（fail-open。実測）。
                        # **除くのは短絡で結論が変わりうる向きだけ**にする（無条件に除くと、
                        # 本当に走らない `if false && true` の本体まで生きていると読んで
                        # 正しくゲートしているステップを赤くする。実測で両向きを確認）:
                        #   - 条件が偽（`if false` / `while false`）… `&&` はそのまま偽なので印を維持、
                        #     `||` は右側で真になりうるので除く
                        #   - 条件が真（`until true`）… `||` はそのまま真なので印を維持、
                        #     `&&` は右側で偽になりうるので除く
                        # **開き側が読めない飾りの後ろも見る**（issue #114 のレビューで実測）。
                        # `( if false; then shellcheck $LIST; fi )` は `open_form()` が
                        # `( if false` を分類できないため階層も `uncertain` も立たず、
                        # ここで `^if` だけを見ていると偽と分かる条件が記録されない。
                        # すると**1 度も走らない本体がリンタの照合を満たす**（下の控えに
                        # gate=1 で載る）——`main` でも複数行で書けば素通りしていた既存の穴で、
                        # ブロック本体の先頭を許す開始位置（`CI_WORKFLOW_BLOCK_BODY_START`）を
                        # 入れると 1 行書きでも素通りするようになる。剥がす綴りは
                        # `strip_dead_cond_prefixes()` が唯一の源（なぜ `open_form()` 側で
                        # 読まないか・残る境界も同関数の説明にある）
                        # **既に偽の印が付いているなら求めない**（issue #142 (6)）。
                        # 消費側 2 つはどちらも `dead_depth < 0` で短絡するのに無条件で
                        # 求めていたため、死に体のブロックに入ったあとの断片すべてで
                        # `starts_case_arm()` / `drop_arm_head()`（どちらも 1 文字ずつの
                        # 伏せ処理を通る）と `function_head_re()` の組み立てを走らせて
                        # 捨てていた。同ファイルが `starts_case_arm()` の**判定**について
                        # 「同じ断片で 2 度求めない」と書いているのと同じ節約
                        # **印を付ける深さは「その制御構造を囲っている階層」**で、断片に入る前の
                        # `depth` とは**同じとは限らない**（issue #142 のレビューで実測）。
                        # 階層を開く前置き（`{` ・ `f() {` ・ `(`）が手前に付くと、制御構造は
                        # `depth + 1` ではなくもっと深いところで開くので、`depth` を印にすると
                        # **閉じた後も印が残り**、同じ前置きの中で*走る*後続の断片まで
                        # 死に体として記録される（`{ if false; then :; fi` 改行 `bash x` 改行 `}` の
                        # `bash x` が `not-wired` に化ける＝**正しくゲートしている綴りを赤くする**
                        # fail-closed。`main` でもブレース・関数の前置きで再現し、
                        # `(` を開き側で数えるようにしたことで `(` もこの形に入った）。
                        # 深さは `last_deciding_open()`（走るかどうかがそこで決まる一番内側の
                        # 増分）から導く——**開き側のループと同じ歩き方**なので、前置きを
                        # 1 つ足しても印の位置がずれない。**下限は 1**（＝従来の `depth`）に
                        # 留める: 歩き方と `strip_dead_cond_prefixes()` の剥がす綴りが食い違う
                        # 綴り（`case` の外のアーム見出しなど）では 0 が返り、そのまま引くと
                        # 印が浅くなりすぎて `dead_depth >= 0` を満たさなくなる（fail-open）
                        if (dead_depth < 0) {
                            dead_probe = strip_dead_cond_prefixes(struct_text)
                            # **語リストが空の `for` / `select` も本体が 1 度も走らない**
                            # （issue #200 のレビュー。`main` 既存の fail-closed で、`for v in ; do set +e; done`
                            #  ＋ スイート ＋ `echo x` は真値 GATES なのに未配線と答えていた）。
                            # 直前の区切りの門番は要らない——語リストはコマンドではないので
                            # `in` の直後に `&&` / `||` / `|` / `&` が来る綴りは bash の構文エラーで、
                            # 「split された結果 `in` の後ろが空に見えるだけ」という形が作れない。
                            # **`in` の後ろに 1 語でもあれば対象外**（`for v in "" ;` は空文字 1 語で
                            # 本体が 1 度走る。`for v in $EMPTY;` は中身が読めないので**数えない**
                            # ——空と決め打つと、実際は回る本体の `set +e` を捨てて
                            # 握り潰されたスイートを「ゲートしている」と読む fail-open になる）
                            if ((ops[j] != "||" \
                                 && dead_probe ~ /^(if|while)[[:space:]]+false([[:space:]]|;|$)/) \
                                || (ops[j] != "&&" \
                                    && dead_probe ~ /^until[[:space:]]+true([[:space:]]|;|$)/) \
                                || dead_probe ~ /^(for|select)[[:space:]]+[A-Za-z_][A-Za-z0-9_]*[[:space:]]+in[[:space:]]*(;|$)/) {
                                dead_lead = last_deciding_open(open_head, fn_form, (open_head == struct_text), was_pending_fndef)
                                if (dead_lead < 1) { dead_lead = 1 }
                                dead_depth = depth + dead_lead - 1
                            }
                        }
                        # **脱出する綴りの後ろは 1 つも走らない**（issue #151。`main` 既存の fail-open）。
                        # `if true; then exit 0; bash <スイート>; fi` と
                        # `while true; do break; bash <スイート>; done` は**2 トークンで必須スイートを
                        # 止められる**のに「最上位で確実に走る」と記録されていた（実 bash では
                        # スイートが 1 行も走らないのに `wired`。`exit` の次の行も同じ）。
                        # **見るのは無条件の脱出だけ。** `[ -z "$X" ] && exit 1` のような条件付きの
                        # 脱出で後ろを死に体にすると、**CI では通過する早期ガード**を持つワークフローの
                        # スイートがすべて「未配線」になり、正しい設定を赤くする（行き過ぎた fail-closed）。
                        # 連鎖で入ってきた断片は `unreachable` と `prev_op` で除き、パイプ・背景は
                        # `set_forked` で除く（別プロセスなので親は終わらない）。
                        # **判定は `call_probe`（命令の位置を求めた写し）を使い回す**——継続語・
                        # アーム見出し・飾り（`{ ` / `!` / `time` / 代入）を落とす綴りの源を増やさない
                        # **走らないブロックの中の脱出も数えない。** ここには以前
                        # 「`dead_depth < 0` は置かない——偽と分かる開きは `uncertain` も立てるので
                        # `uncertain == 0` が先に除く。実測で足しても外しても 602 件すべて緑＝
                        # 何も変えない門番だった」と書いてあったが、**その実測は不完全だった**
                        # （issue #181）。死に体の印が付く経路は 2 つあり、**どちらも `uncertain` を
                        # 立てない**:
                        #   (a) **真と分かる条件の残りのアーム**（`if true; then …; else exit 1; fi` の
                        #       `else` 側）。`true_at` の枝が `dead_depth` を付けるだけ。
                        #   (b) **`break` / `continue` / `return` の後ろ**（下のアームが付ける）。
                        # どちらも中の `exit` が `exit_seen` を立て、**以降ステップの全記録が
                        # gate 0** になる（1 度も走らない `exit` のせいで、正しくゲートしている
                        # スイートが「未配線」と逆の診断で赤くなる fail-closed。実測で
                        # `if true; then echo a; else exit 1; fi` ＋ `bash <スイート>` も
                        # `while true; do break; exit 1; done` ＋ `bash <スイート>` も
                        # 実 `bash -e` で GATES なのに not-wired だった）
                        # **1 行に畳んだ `case` のアームの中も数えない**（`opens_case_here`）
                        # ——`case $X in a) exit 1 ;; esac` では `case` の階層が**この断片の
                        # 末尾**で開くので、判定の時点では `uncertain` がまだ 0 で上の門番を
                        # すり抜ける。模様が当たるかは主語と照合しないと決まらない（issue #147）
                        # ので、ここで数えると**実際にはゲートしているスイートを「未配線」と
                        # 報告**する（レビューで実測。複数行に分けた同じ綴りは `case` の階層が
                        # 先に開くので `uncertain` が立ち、以前から正しく除かれていた）
                        # **死に体の区間の中の脱出はどちらのアームも数えない**ので、条件は
                        # ここに 1 つだけ置く（2 つのアームに書き写すと、脱出の綴りが増えたとき
                        # 片方だけが古くなる——まさに issue #181 で `exit` と `break` の答えが
                        # 食い違っていた形）
                        # **脱出の判定も「命令の位置の綴り」を使う**（issue #189）。`call_probe` は
                        # 上で**先頭の部分シェルを越えた綴り**へ差し替えてあり（越えた深さは
                        # `call_sub`）、`(` を落とさない `strip_command_prefixes()` のままでは
                        # `( exit 0` が脱出語に 1 度も当たらない。**ここで別に歩き直さない。**
                        # 歩きを増やさないためでもあるが、それ以上に**越えたことを知らない
                        # 判定が生まれる**のが危ない——一度そう書いたところ、上の差し替えで
                        # 綴りが `exit 0` になっているぶん「越えていない」と読み、部分シェルの
                        # 中の脱出を**ステップ全体の脱出**として扱った（`( exit 0` 改行
                        # `echo inner )` 改行 `bash <スイート>` が not-wired ＝正しくゲートして
                        # いるスイートを赤くする fail-closed。実測で `main` は wired）
                        esc_probe = call_probe
                        esc_sub = call_sub
                        # **本文の手前に `return` があれば、そのあとの `exit` は無条件ではない**
                        # （issue #189 のレビュー）。`f() { [ -z "$X" ] && return 0; exit 1; }` は
                        # X が未設定なら戻るので、呼んだあともスイートは走って失敗が伝わる
                        # （実測 GATES）。それでも台帳へ控えると以降の最上位の記録がすべて
                        # gate 0 になり、**正しくゲートしているステップを「未配線」と誤報**する。
                        # **条件付きの `return` も数える**のが要点——`uncertain` / `subshell` の
                        # 門番は「その `exit` の時点で開いている階層」しか見ず、手前で起きた
                        # 脱出を 1 つも覚えないので、ガード節（CI スクリプトの定型句）がそのまま
                        # 穴になる。`&&` で入った断片は下の脱出のアームが除くため、ここは
                        # アームより手前に置いて区切りを問わず控える
                        # **越えた定義の名前でも控える**（issue #189 のレビュー）。下の `exit` の
                        # 台帳は `cmd_fndef == 1` の経路でも記録するのに、ここが `in_fndef_here`
                        # だけを見ていたため、見出しと `return` が同じ断片に載る綴り
                        # （`( f() { return 0; exit 1; }` ・ `{ f() { … }`）で控えが 1 件も
                        # 入らず、続く `exit` だけが記録されて「無条件に脱出する関数」に
                        # なっていた（実測で真値 GATES が wired → not-wired ＝正しくゲートして
                        # いるワークフローを赤くする向き。`main` は正しく答えていた）
                        if ((in_fndef_here || cmd_fndef == 1) && !unreachable && dead_depth < 0 \
                            && esc_probe ~ /^return([[:space:]]|$)/) {
                            fn_name_here = in_fndef_here ? fndef_name_here : cmd_fnname
                            if (fn_name_here != "") { fnret[fn_name_here] = 1 }
                        }
                        # **連鎖の右辺の脱出を数えるのは `exit` だけ**（issue #202）。
                        # `true && exit 0` / `false || exit 0` は右辺が必ず走るので後ろは死に体で、
                        # 以前は `prev_op` が `&&` / `||` なら一律に見送っていたため
                        # **2 トークン足すだけで必須スイートをゲートから外せる fail-open** だった。
                        # 読めない左辺（`test -n "$X" && exit 0`）は `chain_in` が立つので従来どおり
                        # 見送る（数えると、条件次第で走らない脱出で後ろを死に体にして**実際には
                        # ゲートしているスイートを「未配線」と報告**する＝issue #189 の向き）。
                        # **`break` / `continue` には広げない**（実測）——`true && break` を
                        # `( … )` / `{ … ; }` / `if true; then … fi` の中で数えると、ループの外の
                        # `break` でその階層の残りを死に体にしてしまい、**真値 GATES の 36 形が
                        # 未配線へ倒れた**。ループの中かどうかを見ていないのが根（issue #204）で、
                        # そこを直すまでは連鎖の手前の `prev_op` で見送る側に留める。
                        # `return` も同じ扱い（関数の外の `return` の読み方は issue #204 が持つ）
                        if (!set_forked && !unreachable && !opens_case_here && dead_depth < 0 \
                            && ((prev_op != "&&" && prev_op != "||") \
                                || (!chain_in && esc_probe ~ /^exit([[:space:]]|$)/)) \
                            && esc_probe ~ /^(exit|break|continue|return)([[:space:]]+[^[:space:]]+)?[[:space:]]*$/) {
                            # `exit` はシェルごと終わるので、以降のすべての断片が到達不能。
                            # **部分シェルの中と定義の本文は除く**——`( exit 0 )` は親を終わらせず、
                            # 定義しただけの本文は呼ばれるまで走らない（除かないと、呼ばれない
                            # 関数に `exit` を書くだけでステップ全体が死に体になる＝fail-closed）
                            if (esc_probe ~ /^exit([[:space:]]|$)/) {
                                # **走るかどうか分からない位置の `exit` は数えない**（`uncertain == 0`）。
                                # `if [ -n "$X" ]; then exit 0; fi` や `case` のアームの中の `exit` は
                                # 条件次第で走らないので、後ろを死に体にすると**実際にはゲートしている
                                # スイートを「未配線」と報告**する（実測で 2 形が化けた）。
                                # `if true; then` / `while true; do` は `uncertain` を立てない側なので
                                # ここを通る——狙っている穴はその 2 形
                                # **部分シェルの中の脱出は、その部分シェルの残りだけを死に体にする**
                                # （issue #189）。以前は `subshell == 0` で丸ごと除いていたので
                                # 「ステップ全体を死に体にしない」ことは正しく守れていた一方、
                                # **その部分シェルの残りを死に体にする手当てが 1 つも無かった**
                                # ——`( exit 0; bash <スイート> )` のスイートが「必ず走る」と記録され、
                                # 実 `bash -e` では 1 行も走らないのに `wired` だった。
                                # 隣のアーム（`break` / `continue` / `return`）が既に正しい形を
                                # 持っているので、同じ「階層を限った `dead_depth`」へそろえる
                                # **歩きが関数定義を越えていたら、この `exit` は本文の中**
                                # （issue #189 のレビュー）。`in_fndef_here` は `^` 錨の
                                # `function_form()` 由来なので `( f() { exit 0` を定義と読めず、
                                # 定義しただけの本文の脱出でその部分シェルの残りを死に体に
                                # していた（実測で真値 GATES なのに not-wired）
                                if (uncertain == 0 && chain_depth == 0 && !in_fndef_here && cmd_fndef == 0) {
                                    # 旗だけ立てて、下の 1 か所（呼び出し側と共通）で適用する
                                    exit_here = 1
                                    exit_sub = esc_sub
                                }
                                # **定義の本文の無条件の `exit` は関数ごとの台帳へ控える**（issue #189）。
                                # `!in_fndef_here` は「定義しただけの本文は走らない」ことを正しく
                                # 守っているが、**呼ばれた時点では何も効かなかった**——`f() { exit 0; }`
                                # を呼んだあとのスイートは 1 行も走らないのに「必ず走る」と記録されて
                                # いた。このライブラリは `set` の弱めのために既に関数ごとの台帳を
                                # 持っているので、同じ形で「この関数は無条件に `exit` する」も運ぶ。
                                # **部分シェルの中の `exit` は控えない**（`f() { ( exit 0 ); }` は
                                # 呼んでも親を終わらせない）。定義そのものが部分シェルの中にある
                                # 綴り（`( f() { exit 0; }; f )`）も控えない側へ倒す——`main` と
                                # 同じ（新しい穴は開かない）で、残る境界として記録する
                                # **条件は「本体の階層より内側に不確かさが無いか」で測る**（issue #189）。
                                # `uncertain == 0` では**定義を開く断片しか通らない**——複数行の
                                # 本文は「関数が呼ばれるか分からない」ぶんの印が本体の階層に
                                # 立っているので、`f() {` 改行 `exit 0` 改行 `}` が 1 つも
                                # 控えられなかった（実測。1 行書きだけ直って同じ穴が残る形）。
                                # ここで答えたいのは「**呼んだら**脱出するか」なので、本体より
                                # 外側の不確かさ（＝呼ばれるかどうか）は数えない。
                                # **本体の階層は `fn_body_depth` と同じ求め方にする**——定義を開く
                                # 断片では階層が増えるのが断片の末尾なので、素の `depth` で測ると
                                # 1 つ浅くなり、部分シェルの中で定義した綴りの判定が狂う
                                # **越えた定義が 2 つ以上なら控えない**（issue #189 のレビュー）。
                                # 1 行に畳んだ入れ子（`outer() { inner() { exit 0; }; }`）では
                                # `function_body_rest()` が見出しをまとめて落とすので命令の位置が
                                # `exit 0` になる一方、`fndef_name_here` は**いちばん外側**の名前
                                # ——`fnexit["outer"]` が立ち、`outer` を呼んだだけで以降が死に体に
                                # なる（実測で真値 GATES なのに not-wired）。複数行で書いた同じ
                                # 入れ子は `fndef_at` の歩きで内側に紐づくので正しい。
                                # ブレースを挟む綴り（`f() { { exit 0`）も 2 以上にはならないが、
                                # **控えない側へ倒れる綴りがある**ことは残る境界として記録する
                                # **名前は「この脱出を含む定義」から取る。** `in_fndef_here` が
                                # 偽でも、歩きが定義を 1 つ越えていればその本文の中にいる
                                # （`( f() { exit 0` ）。歩きが控えた名前を使えば、部分シェルの
                                # 後ろで定義した関数も呼び出し側で引ける——ここを `in_fndef_here`
                                # だけに頼ると、`( f() { exit 0; }` ＋ `f` の呼び出しが
                                # 台帳に無く「スイートは必ず走る」と記録される（fail-open）
                                # **部分シェルを越えたかどうかではなく、それが定義の外か中かで分ける。**
                                # `esc_sub == 0` だけを条件にしていた版では `( f() { exit 0` が
                                # 控えられず、`( f() { exit 0; }` ＋ `f` の呼び出しが「スイートは
                                # 必ず走る」と記録された（実測で真値 NOGATE なのに wired）。
                                # 越えた部分シェルの位置が定義より**手前**なら本文の中の脱出
                                # （控える）、**後ろ**なら部分シェルの中の脱出（控えない）
                                # **`case` を開く断片の門番はここに書かない**——囲っている
                                # `if`（上の脱出のアームの入口）が同じ `!opens_case_here` を
                                # 持っており、重ねても 1 つも答えが変わらない（変異で実測。
                                # 外しても 798 件すべて緑・117 形の総当たりでも差分 0）。
                                # 守っていない門番は読み手に守られていると誤解させるだけ（§6）
                                else if (chain_depth == 0 \
                                         && (esc_sub == 0 || (cmd_fndef == 1 && esc_sub < cmd_fnat)) \
                                         && cmd_fndef <= 1 && (in_fndef_here || cmd_fndef == 1) \
                                         && !fnret[in_fndef_here ? fndef_name_here : cmd_fnname]) {
                                    fn_name_here = in_fndef_here ? fndef_name_here : cmd_fnname
                                    fn_lead = (fn_form == 2 || was_pending_fndef) \
                                              ? depth + last_deciding_open(open_head, fn_form, (open_head == struct_text), was_pending_fndef) \
                                              : innermost_marked_depth(depth, fndef_at)
                                    # 本体より内側に「走るか分からない」階層があれば控えない
                                    # （`f() { if [ -n "$X" ]; then exit 0; fi; }` は呼んでも
                                    #   脱出するとは限らず、控えると**正しくゲートしている
                                    #   スイートを「未配線」と誤報**する＝逆向きの fail-closed）
                                    # 本体より内側の部分シェルの中の脱出も控えない（親は終わらない）
                                    if (innermost_marked_depth(depth, uncertain_at) <= fn_lead \
                                        && innermost_marked_depth(depth, subshell_at) <= fn_lead \
                                        && fn_name_here != "") { fnexit[fn_name_here] = 1 }
                                }
                            }
                            # `break` / `continue` / `return` はいちばん内側の階層を抜けるので、
                            # **その階層が閉じるまで**が到達不能（偽と分かる条件と同じ区間の形）。
                            # **`break 2` 以上は 1 階層ぶんしか見ない**——足りない側は `main` と
                            # 同じ（新しい穴は作らない）ので、残る境界として記録する
                            else if (depth > 0) { dead_depth = depth - 1 }
                        }
                        # **脱出の適用はここだけ**（issue #189）。素の `exit` と、無条件に `exit` する
                        # 関数の呼び出しの 2 経路が同じ旗を立て、区間の付け方をここで 1 度だけ決める
                        # （2 か所に書き写すと、どちらかに部分シェルの手当てだけが残る——
                        #   まさに `exit` と `break` の答えが食い違っていた issue #181 の形）
                        if (exit_here) {
                            # この断片で開いた部分シェルの後ろなら、その階層が閉じるまで死に体
                            if (exit_sub > 0) { dead_depth = depth + exit_sub - 1 }
                            # 既に部分シェルの中にいるなら、一番内側の部分シェルが閉じるまで。
                            # **読むのは閉じる前に控えた階層**（上の `sub_lead_in`）——閉じ括弧が
                            # 同じ断片に載る綴りでも部分シェルの残りだけを死に体にできる。
                            # 見つからない綴りでは何もしない（印に -1 を書き戻さない）
                            else if (sub_lead_in > 0) { dead_depth = sub_lead_in - 1 }
                            # 部分シェルの外の脱出はシェルごと終わるので、以降の全記録が到達不能
                            else { exit_seen = 1 }
                        }
                        # **閉じた外側の区切りを中身の記録へ塗り替える処理は置いていない。**
                        # `( bash x ) || true` のように grouping を閉じた断片に付いた区切りは
                        # 中身にも掛かる（中身だけを見ると区切りが無いので「ゲートしている」と
                        # 読まれる）が、その伝播はいま**階層ごとの区切り**（`scope_op`）と
                        # `record_gates()` の外へのたどりが担う。`if true; then bash <スイート>; fi`
                        # `&& echo ok` の `&&` が `fi` に付く形（issue #149）も同じ経路で読む。
                        # 以前は記録の 2 列目を書き換えていたが、読む側が「塗り替える前の区切り」を
                        # 優先していたので**答えが 1 件も変わらなかった**（issue #191 のレビュー指摘。
                        # 実測で 840 件すべて緑・corpus の抽出も 1 バイト違わない）ので、
                        # 何も変えない仕掛けは置かないという規約（§6）に従って消してある
                        # 次の断片から見た「直前」を控える
                        prev_op = ops[j]
                        # 開く前の深さと `case` の入れ子を控える（下でパイプの中かどうかを印すのに使う）
                        depth_before = depth
                        case_before = case_depth
                        # 開き側はこの断片の後ろから効く（`if` 自身は外側の階層にある）
                        # `case` の入れ子を数えておく（上のパターン判定に使う）
                        # （アーム模様の位置＝`arm_expected` の代入は開き側のループの後にある。
                        #   `case` は断片の先頭にあるとは限らず、開いたかどうかは
                        #   ループを通らないと分からないため）
                        # **`case` の入れ子は `depth` とは独立に数える。** 閉じ側のループは
                        # `depth > 0` で止まるので、その中で数えると「階層は別の綴りが先に
                        # 閉じてしまい `esac` が深さ 0 で来る」場合に数え損ね、以降ずっと
                        # 「`case` の中」に見える（パイプの子シェル判定が外れ、正しくゲートする
                        #   綴りを赤くする。レビューで実測）。開く側は開き側のループが数える
                        # ——どちらも断片の先頭にあるとは限らないため `^esac` だけでは足りず、
                        # 断片に含まれる閉じ語をたどった結果で数える
                        # **模様の位置の判定は閉じ側の走査と揃える**（`prev_op` はこの断片の処理中に
                        # 自分の区切りへ更新されるので、こちらでは控えてある `pipe_in` を読む。
                        # 素直に `prev_op` と書くと「前が `|`」ではなく「後ろが `|`」を意味し、
                        # `esac | cat` で `case_depth` だけが残る。レビューで実測）。 揃えないと、模様の中の
                        # `esac`（`(done|esac|zz)`）で `case_depth` だけが減り、以降 `case_scope` が
                        # 偽になって本物のアームの `set` が見つからなくなる（fail-open。レビューで実測）
                        esac_probe = text
                        esac_first = 1
                        while (esac_probe ~ close_word_re() \
                               && !(esac_first && arm_expected \
                                    && (esac_probe !~ esac_word_re() || pipe_in))) {
                            esac_first = 0
                            if (esac_probe ~ esac_word_re() && case_depth > 0) { case_depth-- }
                            esac_rest = drop_close_word(esac_probe)
                            if (esac_rest == esac_probe) { break }
                            esac_probe = esac_rest
                        }
                        # **「必ず走る入れ子」と「走るか分からない入れ子」を分ける。**
                        # `( … )` / `{ … }` の grouping と `if true` / `while true` の本体は必ず走るので、
                        # 中の `set +e` は効くし、中の呼び出しは実行の証拠になる。
                        # 一方 `if <条件>` / ループ / 関数定義の中身は、条件や呼び出し元を読まないと決まらない
                        # （両者を深さ 1 本で扱うと、grouping の中の呼び出しが「未配線」と誤報され、
                        #   通る分岐の `set +e` が握り潰しを隠す。どちらもレビューで実測）
                        # **連鎖が続くなら条件は `true` だけではない。** `split_commands` は `&&` で
                        # 切るので `if true && [ -z "$SKIP" ]; then` の断片は `if true` になる。
                        # 素直に「必ず走る」と読むと、2 トークン足すだけで走るとは限らない本体が
                        # 「最上位で確実に走る」に化ける（実 bash と差分照合して実測。fail-open）
                        # **1 つの断片が複合コマンドを 2 つ以上開くことがある**（issue #123 (5)）。
                        # `f() { g() { : ; }; bash x; }` のように本体が同じ断片でもう 1 つ開く綴りは
                        # 1 つしか数えないと階層が足りず、続く `}` が**関数の**階層を閉じてしまう
                        # ＝呼ばれていない関数の本文の残りが最上位のコードとして読まれる（fail-open）。
                        # これは `ci_coverage_test.sh` の「全スイートが実行されるか」に直接効き、
                        # 実際のコマンド一覧から外したスイートでも、**呼ばれない関数の中に名前を書くだけで**
                        # 「配線されている」と報告できてしまう（本ライブラリが塞ぐと宣言している
                        # *absence == pass* の形そのもの）。
                        # 辿るのは「開いた直後が命令の位置」になる綴り（関数の本体・ブレース）だけで、
                        # 条件の位置（`if <条件>`）では止める（`open_rest()` の説明を参照）
                        open_probe = open_head
                        # 断片の**先頭**の開きかどうか（見出しと結び付く `{` は先頭の 1 つだけ）
                        first_open = 1
                        # この断片で `!` を剥がしたか（issue #155。素のグループの飾り）
                        head_inverted = 0
                        # この断片で開いた階層に印を付けて回るための走査位置
                        od = depth_before
                        while (1) {
                            # **先頭の飾り（`time` / `!`）を素のグループの手前で落とす**（issue #155）。
                            # `open_form()` は内部で飾りを落として制御構造を分類するが、
                            # ブレースの判定だけは**剥がす前の綴り**を見るので `! { … }` は
                            # 種類 0（何も開かない）になり、下の `(` を越えるループも `^\(` を
                            # 求めるので `! ( … )` では 1 度も回らない。どちらも階層を 1 つも
                            # 開かないので、**反転された本体が「最上位で確実に走る」として
                            # 記録される**（実 `bash -e` では `!` が終了状態を反転するので
                            # ジョブは緑のまま＝スイートの失敗が届かない。`main` 既存の fail-open）。
                            # **落とすのは剥がした先が素のグループ（`(` / `{`）のときだけ**に限る
                            # ——関数定義の判定（`function_form()`）は見出しの綴りを見るので、
                            # 飾りが付いた形を剥がして渡すと「定義」と誤分類しうる（同関数の
                            # コメントが理由を記録している）。制御構造は `open_form()` の中の
                            # 剥がしで既に分類できているので、ここで触る必要が無い
                            open_stripped = strip_struct_wrappers(open_probe)
                            if (open_stripped != open_probe && open_stripped ~ /^[({]/) {
                                open_probe = open_stripped
                                # `!` を剥がしたかは下の `inverted` と OR で合わせる
                                # （`open_form()` が内部で剥がすと `STRUCT_INVERTED` が上書きされる）
                                if (STRUCT_INVERTED) { head_inverted = 1 }
                            }
                            # **先頭に並ぶ部分シェルの開き（`( if true; then`）はここで開く。**
                            # `open_form()` は `(` を読まない（釣り合いが階層を数えるので、
                            # 読ませると同じ階層を二重に開く）。そのため以前は `(` の後ろの
                            # 制御構造が**1 階層も開かないのに `fi` / `esac` だけが閉じる**状態で、
                            # 壊れ方が 2 つあった（issue #142 (3)。どちらも実測）:
                            #   `( if [ -n "$X" ]; then <呼び出し>; fi )` の本体が `uncertain` 0
                            #   ＝「最上位で確実に走る」として記録される（1 文字で「最上位だけ」の
                            #   絞り込みを迂回できる）。さらに閉じる側が 1 つ余分に閉じるので、
                            #   **外側の条件の `uncertain` まで消える**（`( if true; … fi )` を
                            #   `if [ -n "$X" ]` の中へ置くと、続く呼び出しが最上位扱いになった）。
                            # ここで開けば釣り合いの正側（下の `paren > 0`）と二重にならず、
                            # **並びも綴りの順**になる（`(` が外・制御構造が内）。順序が逆だと
                            # `else` が見る階層が部分シェル側になり、`true_at` の印に当たらない。
                            # 釣り合いが 0 の断片（`( : )`）は階層が残らないので開かない
                            while (paren > 0 && open_probe ~ subshell_open_re()) {
                                depth++
                                open_scope(depth); cmd_opens++
                                # **番号は上の `set` の処理が先に振っていることがある**（issue #180）。
                                # 空いていなければそれを使う——振り直すと、越えて見つけた `set +e` の
                                # 記録がどの階層とも結び付かず、同じ部分シェルの中の `set -e` で
                                # 打ち消せない（正しくゲートする綴りを赤くする）
                                subshell_at[depth] = 1; subshell++
                                if (!(sub_id[depth] && sub_res_at == i ":" j)) { sub_serial++; sub_id[depth] = sub_serial }
                                # **`!` で反転された部分シェルの中は実行の証拠にしない**（issue #155）。
                                # 走りはするので**リンタの照会（`top` を渡さない）では数えてよい**
                                # ——`uncertain` を立てる形なら実行の照会だけに効く（issue が
                                # 指定している向き。`! shellcheck …` でも shellcheck は走る）
                                if (head_inverted) { uncertain++; uncertain_at[depth] = 1; inverted_at[depth] = 1 }
                                paren--
                                sub(subshell_open_re(), "", open_probe)
                                # 見出しと結び付く `{` は断片の先頭の 1 つだけ。`(` を越えた先の
                                # `{` は部分シェルの中の素のグループなので、関数の本体ではない
                                first_open = 0
                            }
                            # いま先頭にある綴りが何を開くかを分類する
                            # 本文が `struct_text` そのもののあいだは、控えてある `fn_form` を渡す。
                            # **`first_open` を使い回さない**のが要点で、あちらは「見出しと結び付く
                            # `{` か」を表す別の意味の旗。いまは同じ周回で切り替わるので値は一致するが、
                            # 片方の意味を変えたときに**別の本文に対する `fn_form`** を渡してしまう
                            # （`f() { { :; }` の内側の `{` を関数の本体と誤分類し、閉じない階層が残る）
                            open_kind = open_form(open_probe, fn_form, (open_probe == struct_text))
                            # **`!` で反転された開きも「必ずゲートする」ではない。** `open_form()` は
                            # `strip_struct_wrappers()` を通して分類するので `! if true; then` も
                            # 種類 1 になるが、`!` は終了状態を**反転**するので本体が走って失敗しても
                            # ジョブは緑のまま終わる（`! if true; then bash <suite>; fi` を実 bash で
                            # 測ると rc=0）。この行は `open_form()` の**直後**に置くのが要点で、
                            # `STRUCT_INVERTED` はそこで通した `strip_struct_wrappers()` の結果
                            # （以降で別の断片を剥がすと上書きされる）。
                            # **ここに到達するのは `open_form()` が種類を返した形だけ**で、
                            # `! { … }` / `! ( … )` は階層を 1 つも開かないので**そもそも通らない**
                            # （issue #155 で追う fail-open）。**この族は「`main` から続く既存の穴」で
                            # ちょうど半分**で、実測（6 種の包み × 4 種の中身）では
                            # 複数行の `! { if true; then bash <suite>; fi; }` は #123 の前から wired、
                            # **1 行に畳んだ綴り**（`! { if true; then bash <suite>; fi; }` を
                            # `run:` の 1 行に書く形）は #123 が `ci_workflow_runs_script` の
                            # 開始位置を広げたことで not-wired → wired へ動いた。
                            # つまり `!inverted` は**包まれていない綴り**を閉じただけで、
                            # 包んだ族は開いたまま（向きはどちらも危険側）
                            # **ここで `head_inverted` を OR しない。** 手前で落とした `!` は
                            # 素のグループ（`(` / `{`）にしか付かず、そのグループの階層が
                            # この行より先に開いて `uncertain` を背負うので、内側の
                            # `if true` をどちらに読んでも記録は「走ると証明できない」側に
                            # 入る（実測で、OR を足しても外しても 634 件すべて緑＝何も
                            # 変えない仕掛けだった。何も変えない仕掛けは「守られている」と
                            # 誤解させるので置かない）
                            inverted = STRUCT_INVERTED
                            # 必ず走る条件（`if true` / `while true`）。**連鎖に守られていればその限りではない**
                            # ——`split_commands` は `&&` で切るので `if true && [ -z "$SKIP" ]; then` の
                            # 断片は `if true` になる。素直に「必ず走る」と読むと、2 トークン足すだけで
                            # 走るとは限らない本体が「最上位で確実に走る」に化ける（fail-open。実測）
                            if (open_kind == 1 && !chain_in && !inverted && ops[j] != "&&" && ops[j] != "||") {
                                depth++; true_at[depth] = 1
                                open_scope(depth)
                                # **必ず走る入れ子なので grouping と同じ扱い。** 開始位置を控えないと、
                                # 閉じた `fi` / `done` に付いた `|| true` が中身へ伝わらず、
                                # 握り潰された実行が「ゲートしている」と読まれる
                            }
                            # 走るか分からない制御構造（連鎖に守られた `if true` と、`!` で反転された `if true` もここへ落ちる）
                            else if (open_kind == 1 || open_kind == 2) {
                                depth++; uncertain++; uncertain_at[depth] = 1
                                open_scope(depth)
                                # **`case` の入れ子はここで数える。** 断片の先頭とは限らない
                                # （`f() { case x in` のように本体の中で開くことがある）
                                if (opens_case_word(open_probe)) { case_depth++ }
                                # **閉じた `fi` / `done` に付いた区切りは中身すべてに掛かる。**
                                # grouping と同じで、控えないと `fi || true` が本体へ伝わらず、
                                # 握り潰された実行が「ゲートしている」と読まれる（実測）
                            }
                            # 関数定義（`f() { …` / `function f { …`）も 1 階層開く
                            else if (open_kind == 3) {
                                depth++; uncertain++; uncertain_at[depth] = 1
                                open_scope(depth); cmd_opens++
                                fndef++; fndef_at[depth] = 1
                                # この階層の本文がどの関数のものかを控える（呼び出しで引くため）
                                # **1 つの断片の中で入れ子に定義した関数は、外側の名前で台帳に載せる。**
                                # `set` を探す側は `function_body_rest()` が最奥の本文まで一気に
                                # 落とした結果を**外側の定義の断片で**読むので、内側の名前で控えると
                                # 記録した名前と参照する名前が食い違い、呼んでも反映されない
                                # （fail-open。レビューで実測）
                                # **台帳の名前は「`set` を探す側がどの名前に帰属させるか」に合わせる。**
                                # 断片の先頭が定義なら `function_body_rest()` が入れ子の見出しを
                                # まとめて落として最奥の本文を返す＝見つかる `set` は**先頭の**定義の
                                # ものとして扱われるので、その断片で開くどの階層も先頭の名前で載せる
                                # （内側の名前で控えると記録と参照が食い違い、呼んでも反映されない）。
                                # 先頭が定義でなければ（`{ f() { …`）その経路は働かないので、
                                # 各階層は自分の名前で載せる（外側の名前へ寄せると名無しになり、
                                # 台帳への記録そのものが落ちる。どちらもレビューで実測）
                                fndef_name[depth] = (fn_form == 2) ? function_name(struct_text) \
                                                                   : function_name(open_probe)
                            }
                            # 見出しだけの綴りは深さを動かさず、次の `{` を関数本体として予約する
                            # 名前も一緒に控える（次の `{` が本体を開いたときに引き継ぐ）
                            else if (open_kind == 4) {
                                pending_fndef = 1; pending_fndef_name = function_name(open_probe)
                            }
                            # **ブレースグループ（`cmd || { echo bad; exit 1; }`）も 1 階層開く。**
                            # 閉じ側の `}` だけを数えると深さが 1 つ足りなくなり、以降の断片が
                            # 「最上位」に見える——条件の中でしか走らない呼び出しが実行の証拠に化ける（レビューで実測）
                            else if (open_kind == 5) {
                                depth++
                                open_scope(depth); cmd_opens++
                                # 直前が関数の見出しなら、この `{` が本体の開き（走るとは限らない）。
                                # **断片の先頭の `{` に限る**のが要点で、2 つ目以降は本体の中の
                                # 素のグループであり、見出しとは結び付かない
                                if (first_open && was_pending_fndef) {
                                    uncertain++; uncertain_at[depth] = 1
                                    fndef++; fndef_at[depth] = 1
                                    # 見出しの行で控えた名前を、本体を開いたこの階層へ引き継ぐ
                                    fndef_name[depth] = pending_fndef_name
                                }
                                # そうでなければ素の grouping（必ず走るので uncertain は増やさない）
                                # **ただし `!` で反転されていれば実行の証拠にしない**（issue #155）
                                else {
                                    if (head_inverted) { uncertain++; uncertain_at[depth] = 1; inverted_at[depth] = 1 }
                                }
                            }
                            # 本体が同じ断片の中で続く綴り以外は、ここで終わり
                            if (open_kind != 3 && open_kind != 5) { break }
                            # 開き 1 つ分を落として、次の命令の位置へ進む
                            open_rest_probe = open_rest(open_probe, open_kind)
                            # **1 文字も減らなければ打ち切る**（無限ループ避け。綴りを足したときの保険）
                            if (open_rest_probe == open_probe) { break }
                            open_probe = open_rest_probe
                            first_open = 0
                        }
                        # 部分シェルの開き分（釣り合いの正側）を足す。
                        # **部分シェルであることを階層ごとに覚える**（中の `set` を外へ持ち出さない）
                        # **上の連鎖から切り離してある**のが要点（issue #123 (2)）。以前はパイプの
                        # 子シェル判定の `else` に束縛されており、`echo x | { (` のように
                        # 1 断片が `{` と `(` を同時に開くとパイプの中でだけ `(` の階層が開かず、
                        # 後の `)` が**ブレースの**階層を閉じて以降の深さが 1 つずれていた
                        if (paren > 0) {
                            for (closing = 0; closing < paren; closing++) {
                                depth++
                                open_scope(depth)
                                subshell_at[depth] = 1; subshell++; sub_serial++; sub_id[depth] = sub_serial
                            }
                        }
                        # **この記録のコマンドが走る階層を控える**（issue #191）。記録を書き出す
                        # 時点の `depth` は**閉じた後・開く前**なので、そのまま載せると
                        # `( bash <スイート>; echo z ) && echo ok` が 3 件とも深さ 0 になり
                        # 入れ子が復元できない（実測）。コマンドの位置は「閉じる前の深さ
                        # （`depth_in`）＋ 命令の手前で開いた数」で、閉じ語は**コマンドの後ろ**に
                        # しか来ない（手前に来る綴りは区切りで別の断片に割れる。issue #189 の
                        # `carries_command` の切り分けと同じ理由）。
                        # **識別子は深さではなく階層ごとの連番**にする —— 深さだけだと
                        # `( bash <スイート> )` と `( echo z )` が並ぶ形で「同じ深さの最後の
                        # コマンド」が後ろの部分シェルになり、正しくゲートする綴りを赤くする
                        if (rec_at > 0) {
                            run_depth = carries_command(text) ? (depth_in + cmd_opens) : depth_in
                            rec_scope[rec_at] = (run_depth > 0) ? scope_at[run_depth] : 0
                            # **この断片がコマンドの階層より内側へ開いた階層**も控える（issue #198）。
                            # `if true; then` / `for f in a; do` / `case x in` の見出しは**条件や一覧を
                            # 外側の階層で走らせる**ので記録自身は外側に載るが、並びの要素としては
                            # 閉じ語（`fi` / `done` / `esac`）までが 1 つのコマンドで、連鎖の歩きは
                            # その閉じで位置を測る必要がある。`( … )` / `{ … ; }` は開き記号が命令の
                            # 手前に来るので `cmd_opens` に数えられ、記録自身が内側へ載る＝ここは 0 で
                            # よい（歩きは `rec_scope` の違いでそれを複合と見分ける）。
                            # **材料も場所も `rec_scope` と同じ**にしてあるのが要点で、開き側の各枝で
                            # 控えると (a) 枝ごとに書き写すことになり、(b) 1 断片が 2 つ開いた形で
                            # 内側へ上書きしないための門番が要り、(c) **控えない記録が残る**ので
                            # 前のジョブの値が読まれうる（記録の番号はジョブごとに振り直すため）
                            rec_opened[rec_at] = (depth > run_depth) ? scope_at[run_depth + 1] : 0
                        }
                        # **この断片が開いた階層すべてに、断片に入る前のオプションを控える**
                        # （下の「フォークした複合の巻き戻し」で使う）。`errexit_before` /
                        # `pipefail_before` は断片の間ずっと同じ値なので、開き方（制御構造・
                        # 関数・ブレース・括弧）ごとに書き分ける必要はなく、**開き終わった
                        # ここ 1 か所**で足りる。写しを増やすと「入口の姿」に何を含めるかを
                        # 変えたときに片方だけが取り残される（同ファイルが繰り返し避けている形）
                        while (od < depth) {
                            od++; entry_errexit[od] = errexit_before; entry_pipefail[od] = pipefail_before
                            # **階層ごとに「部分シェルか」を控える**（issue #191）。errexit の免除は
                            # 同じシェルの中では外へ出ても続くが、部分シェルを出ると終了状態として
                            # 親に渡り、そこで errexit が改めて落とす（実測: `( bash <スイート> &&
                            # echo ok )` ＋ `echo done` は GATES、`{ bash <スイート> && echo ok ; }` ＋
                            # `echo done` は NOGATE）
                            scope_sub[scope_at[od]] = subshell_at[od] ? 1 : 0
                        }
                        # **パイプの構成要素として開いた複合コマンドは子シェルで走る。**
                        # `echo x | while read -r l; do set +e; done` の `set +e` は親へ漏れないので、
                        # 印を付けないと「走るかもしれない握り潰し」として反映し、
                        # 実際にはゲートしているステップを「未配線」と誤報して赤くする
                        # （`( … )` は釣り合いで拾えるが、パイプはこの経路でしか分からない）
                        # **印を付けるのはこの断片が開いた一番外側の階層**（`depth` ではない）。
                        # `echo x | { ( : ) ; set +e ; }` では内側の `(` が先に閉じて `subshell` が
                        # 0 に戻るため、内側だけに印を付けると残りの `set +e` が親に効いたものとして
                        # 扱われる（issue #123 (2)）
                        # **`case` の中と `case` を開く断片では見送る。** アーム模様の `|`
                        # （`a|b)`）は選択肢の区切りであってパイプではなく、`split_commands` は
                        # そこでも切るため、区別が付かない（見送る側は従来どおりの扱いに戻るだけ）
                        # **`case` の中か、この断片が `case` を開いたかは `case_depth` で見る。**
                        # `^case` で見ると、`{ case zz in (zz|yy) …` のように `case` が断片の
                        # 先頭に無い綴りでアーム模様の `|` をパイプと読み、囲っている階層に
                        # 子シェルの印を付けてしまう（そのアームの `set +e` が丸ごと捨てられ、
                        # 握り潰されたスイートが「ゲートしている」と読まれる fail-open。レビューで実測）。
                        # 開き側のループを通った後なので、`case_depth` はこの断片の分まで数え終えている
                        # **見送るのは「この断片から出ていく `|`」が模様の区切りでありうるときだけ。**
                        # 入ってくる `|`（`pipe_in`）は**前の**断片に付いていたもので、`case` の
                        # 外から来ている以上アーム模様の区切りではありえない。`case_depth == 0` と
                        # まとめて見ると `echo x | { case zz in …` のように「パイプの右側で
                        # `case` を開く」綴りまで見送ってしまい、子シェルの中の `set +e` を
                        # 親に効いたものとして扱う（正しくゲートする綴りを赤くする。レビューで実測）
                        if (depth > depth_before && (pipe_in || ops[j] == "|") \
                            && case_before == 0 && !(ops[j] == "|" && case_depth > 0 && !pipe_in) \
                            && !subshell_at[depth_before + 1]) {
                            subshell_at[depth_before + 1] = 1; subshell++; sub_serial++; sub_id[depth_before + 1] = sub_serial
                        }
                        # **連鎖で入った階層も控える**（issue #151 の実測）。
                        # `[ "$c" -eq 2 ] || { echo "FAIL: …"; exit 1; }` の `exit` は `;` の後ろなので
                        # **断片だけ見ると無条件に見える**が、囲っているブレースは `||` の右辺＝条件次第。
                        # 実在の ci.yml がまさにこの形で、数えると**同じステップの後ろ全部が死に体**になった
                        # （失敗経路の 6 記録が `gate` 1 → 0。次に足したスイートが黙って未配線になる）。
                        # 控え方は上の部分シェルと同じ（階層ごとの旗＋件数。畳むのは閉じるループ 1 か所）
                        if (depth > depth_before && chain_in && !chain_at[depth_before + 1]) {
                            chain_at[depth_before + 1] = 1; chain_depth++
                        }
                        # **次の断片がアーム模様の位置か**を控える（上の括弧の勘定が読む）。
                        # `case` を開いた断片の直後だけが立ち、その断片が模様まで載せていれば立てない。
                        # **`^case` ではなく「この断片で `case` の入れ子が増えたか」で見る**——
                        # `{ case x in` のように `case` が先頭に無い綴りでも階層は開くので、
                        # 先頭で見ると次の行の `(x|y)` を模様と読めず、幻の部分シェルが開いて
                        # アームの `set +e` が捨てられる（fail-open。レビューで実測）
                        # 「模様を消費したか」は `case_arm_consumed()` が答える（`set_arm_here` でも
                        # 「断片が `in` で終わるか」でも代用できない理由は、同関数の説明を参照）
                        # **模様が `|` で複数の選択肢に切られていれば、その間ずっと模様の位置。**
                        # `a|done|zz)` は 3 つの断片になり、2 つ目の `done` も模様なので
                        # 閉じ語として扱ってはいけない（1 つ目しか守らないと、選択肢を 1 つ
                        # 増やすだけで `case` の階層が畳まれる。レビューで実測）。
                        # 見出しを閉じる `)` が来た断片（`set_arm_here`）で降ろす
                        arm_expected = (case_depth > case_before && !case_arm_consumed(struct_text)) \
                                       || (arm_expected && !set_arm_here && ops[j] == "|")
                    }
                }
            }
            # 次のステップに備えて溜めた内容を捨てる
            for (i = 1; i <= ncmd; i++) { delete cmds[i] }
            ncmd = 0
            step_disabled = 0
        }

        # 溜めた 1 ジョブ分を、ジョブ単位で止められていなければ出力する。
        # ステップ番号にジョブ名を冠するのは、呼び出し側が「どのジョブが実行するか」まで
        # 問えるようにするため（env は同じジョブからしか見えないので、ジョブを跨いだ
        # 分割は「配線されている」と答えてはいけない）
        function flush_job(   i, parts, shell_name, gate, sc, preceded_here) {
            # 未確定のステップをジョブの控えへ移してから判断する
            flush_step()
            # **env の記録は無効化に関わらず出す。** これは「何が実行されるか」ではなく
            # 「そのジョブがどんな変数を定義しているか」という構造の記述であり、
            # 止まっているジョブの定義を「定義が 0 件」と報告すると、
            # 一覧の書式が壊れたのか job が止まっているのかを取り違えた診断になる
            for (i = 1; i <= nenv; i++) { print jobname "#" envbuf[i] }
            # ジョブごと止められていなければ、コマンドの控えをまとめて出す。
            # **ここで初めて実効シェルが確定する**（ステップ自身の指定 > ジョブの既定 > ワークフローの既定）
            if (!job_disabled) {
                # **ステップごとに「最後に走るコマンドの記録」を先に求める**（issue #149）。
                # `&&` の免除が効くかは「その並びがステップの最後か」で決まるので、
                # 並び順を 1 度なめてから判断する。**止められたジョブでは求めない**
                # ——下の出力はこのブロックの中でしか使わないので、外に置くと
                # 捨てる表のために全記録へ `carries_command()` を回すことになる
                # （レビュー指摘。issue #166 で削った走査と同じ費用）
                # **`&&` を持つ記録が無いジョブで省く門番は、測って入れなかった**（issue #184）。
                # 提案は「`index(buf[i], "\t&&\t")` を 1 周して、無ければこの前走査を飛ばす」。
                # `$SP/p166/big.yml`（11,776 行・20 ジョブ）で交互に 5〜7 ラウンド × 3 回ずつ測ると、
                # **差は min で ±12ms・median で ±29ms と符号すら安定せず、`main` 自身の
                # ばらつき（185ms）の中に完全に収まった**。`&&` を 1 つも含まないワークフロー
                # （門番が全ジョブで前走査を飛ばせる最良ケース）でも同じ。前走査が触るのは
                # 1 ジョブあたり `nbuf` 件（この repo の実測で 34 と 53）で、費用は行ごとの
                # 走査（issue #166 が測った支配項）に対して無視できる。
                # **判定も費用も変えない仕掛けは置かない**という規約に従って入れていない。
                # **なお issue #184 の前提「この repo の `ci.yml` には `&&` を持つ記録が無い」は
                # 誤り**で、実測では `e2e` ジョブに 5 件ある（`type-check` は 0 件）。
                # 入れ直す前に、同じ測り方で**ばらつきの外に出る**ことを示すこと
                # 1 巡目: 判定に要る材料を記録ごとに控える。**「最後のコマンド」は階層ごと**に
                # 数える（ステップ全体で数えると `( bash <スイート> )` と `( echo z )` が
                # 並ぶ形で後ろの部分シェルが「最後」になり、正しくゲートする綴りを赤くする）
                for (i = 1; i <= nbuf; i++) {
                    split(buf[i], parts, "\t")
                    shell_name = (shells[parts[1]] != "") ? shells[parts[1]] : ((job_shell != "") ? job_shell : workflow_shell)
                    rec_stepid[i] = parts[1]
                    rec_txt[i] = parts[6]
                    rec_opx[i] = parts[2]
                    rec_e[i] = (parts[3] == "-1") ? ((shell_name == "" || shell_name == "bash" || shell_name == "sh") ? 1 : 0) : (parts[3] + 0)
                    rec_p[i] = (parts[4] == "-1") ? ((shell_name == "bash") ? 1 : 0) : (parts[4] + 0)
                    # **走らない記録は数えない**（issue #191 のレビュー指摘）。死に体・到達不能な
                    # コマンドは「最後に走ったコマンド」ではないので、数えると
                    # `bash <スイート> || (` / `if false; then` / `exit 1` / `fi` / `)` で
                    # 走らない `exit 1` が `||` の右辺の最後のコマンドに見え、
                    # 「成功しえない右辺」と読んで握り潰しを配線と答える fail-open になる
                    if (carries_command(parts[6]) && !rec_dead[i]) {
                        # **脱出の印は「手前に走ったコマンドがあるか」を見るので、控える前に判定する**
                        # （自分自身を「手前のコマンド」に数えないため）
                        preceded_here = ((parts[1] "\t" rec_scope[i]) in cmd_seen) ? 1 : 0
                        if (escape_can_succeed(parts[6], preceded_here)) {
                            sc = rec_scope[i]
                            while (1) {
                                scope_exit_ok[parts[1] "\t" sc] = 1
                                if (sc == 0 || scope_sub[sc]) { break }
                                sc = scope_parent[sc]
                            }
                        }
                        # **その階層の中で「errexit が効いた状態で必ず失敗する記録」も控える**
                        # （レビュー指摘。`||` の右辺が複合のとき、中の errexit がその場で落とす）。
                        # `bash <スイート> || ( false; true )` は右辺が並びの**最後の要素**なので
                        # 中で errexit が生きており、`false` で部分シェルが死ぬ＝並びはいつでも
                        # 失敗する（実 `bash -e` は GATES）。最後のコマンド（`true`）だけを見ると
                        # 「成功しうる」と読んで未配線＝正しくゲートしている綴りを赤くしていた。
                        # 控えるのは**最初に見つけた 1 件**（手前のものが先に落とす）で、
                        # 祖先の階層にも記す（内側の複合が死ねば外側も死ぬ）
                        # **数えるのは「その記録自身の失敗で errexit が落ちる」ものだけ**
                        # （実測で見つけた穴）。記録の直後が `&&` / `||` なら並びの最後の要素では
                        # ないので errexit は抑制され、`|` ならパイプの左側、`&` なら背後の実行で
                        # どちらも親の状態にならない——`|| { false && echo z ; echo ok ; }` は
                        # `false` では死なず `echo ok` で成功するので握り潰し（実 `bash -e` は
                        # NOGATE。区切りを見ないと「1 件も走らないスイートがゲートしている」と読む）
                        # **`!` で反転した記録も除く**（実測で見つけた穴）。反転したコマンドの
                        # 失敗では errexit が落ちないので、`|| { ! true ; echo ok ; }` は
                        # `echo ok` まで進んで成功する＝握り潰し（実 `bash -e` は NOGATE）。
                        # 判定は `chain_never_succeeds()` が最後に読んだ反転の偶奇で見る
                        # **走ると証明できない記録は数えない**（レビュー指摘。実測で見つけた
                        # fail-open）。`rec_unc[i]` は囲っている制御構造のうち走ると
                        # 証明できないものの数で、呼ばれない関数の本体・空になりうる `for` の
                        # 本体・一致しない `case` のアームはいずれも立てる（記録の 5 列目では
                        # なく素の `uncertain` を見るのは、5 列目が `chain_in` を足した合計で、
                        # `|| (` の中——連鎖の右辺なのでこれが立つ——を区別できないため）。数えると
                        # `bash <スイート> || (` / `die() {` / `exit 1` / `}` / `echo ignored` / `)`
                        # ——`||` の受け皿に補助関数を書くというごく普通の綴り——で、呼ばれない
                        # `exit 1` が「この複合はいつでも失敗する」と読まれ、握り潰しを配線と
                        # 答える（実 `bash -e` は NOGATE）
                        if (rec_e[i] && (parts[2] == "" || parts[2] == ";") \
                            && rec_unc[i] == 0 \
                            && chain_never_succeeds(parts[6]) && !CHAIN_PROBE_FLIP) {
                            if (!((parts[1] "\t" rec_scope[i]) in scope_fatal)) {
                                scope_fatal[parts[1] "\t" rec_scope[i]] = i
                                sc = rec_scope[i]
                                while (sc > 0) {
                                    # **その階層の失敗が親へ届くときだけ祖先へ記す**（レビュー指摘。
                                    # 実測で見つけた fail-open）。階層の閉じの後ろが `&&` / `||` なら
                                    # その中の errexit は抑制され、`|` ならパイプの左側、`&` なら
                                    # 背後の実行で、どちらも親の終了状態にならない——
                                    # `|| (` / `(` / `false` / `) || true` / `true` / `)` は
                                    # 内側が死んでも `|| true` が受けるので外側は成功する
                                    # （実 `bash -e` は NOGATE）
                                    if (scope_op[sc] != "" && scope_op[sc] != ";") { break }
                                    sc = scope_parent[sc]
                                    if (!((parts[1] "\t" sc) in scope_fatal)) { scope_fatal[parts[1] "\t" sc] = i }
                                }
                            }
                        }
                        last_scope_cmd[parts[1] "\t" rec_scope[i]] = i
                        # **複合コマンドは親から見れば 1 つのコマンド**なので、祖先の階層にも
                        # 「この位置で何かが走った」と記す。記さないと
                        # `( set +e` / スイート / `( echo x )` / `)` でスイートが
                        # 「外側の最後のコマンド」に見え、握り潰された実行を配線と読む
                        sc = rec_scope[i]
                        while (sc > 0) { sc = scope_parent[sc]; last_scope_cmd[parts[1] "\t" sc] = i }
                        # **「この階層で何かが走った」も同じ形で控える**（複合は親から見れば
                        # 1 つのコマンドなので祖先にも記す）。読むのは上の脱出の判定だけ
                        if (carries_own_command(parts[6])) {
                            cmd_seen[parts[1] "\t" rec_scope[i]] = 1
                            sc = rec_scope[i]
                            while (sc > 0) { sc = scope_parent[sc]; cmd_seen[parts[1] "\t" sc] = 1 }
                        }
                    }
                }
                # 2 巡目: 記録ごとに「失敗が run: の終了状態へ届くか」を出す
                for (i = 1; i <= nbuf; i++) {
                    split(buf[i], parts, "\t")
                    gate = record_gates(i)
                    print jobname "#" parts[1] "\t" gate "\t" parts[5] "\t" parts[6]
                }
            }
            # 次のジョブに備えて控えと状態を捨てる
            for (i = 1; i <= nenv; i++) { delete envbuf[i] }
            nenv = 0
            for (i = 1; i <= nbuf; i++) {
                delete buf[i]; delete rec_scope[i]; delete rec_dead[i]; delete rec_unc[i]; delete rec_opened[i]
                delete rec_stepid[i]; delete rec_txt[i]; delete rec_opx[i]; delete rec_e[i]; delete rec_p[i]
            }
            for (i in last_scope_cmd) { delete last_scope_cmd[i] }
            for (i in scope_exit_ok) { delete scope_exit_ok[i] }
            for (i in scope_fatal) { delete scope_fatal[i] }
            for (i in cmd_seen) { delete cmd_seen[i] }
            nbuf = 0
            for (i in scope_parent) {
                delete scope_parent[i]; delete scope_op[i]; delete scope_close_at[i]
                delete scope_sub[i]
            }
            for (i in scope_at) { delete scope_at[i] }
            scope_serial = 0
            # ステップごとのシェル指定はジョブをまたいで持ち越さない
            for (i in shells) { delete shells[i] }
            job_disabled = 0
            step_id = 0
        }

        # 無効化を表すキーかどうかを返す（コメント除去済みの行を渡すこと）。
        # **引用符と大文字小文字を先に正規化する**のが要点。YAML は引用符付きの偽を
        # 素の `if: false` と同じスカラーとして読み、GitHub Actions は `FALSE` / `False` も
        # 偽として評価する。素の綴りだけを見ると、**止めたステップが「実行されている」と読まれる**
        # ——本ライブラリが塞ぐと宣言している当の穴が、引用符 2 つで開く（レビューで実測）
        function is_disabling(t,   probe, value) {
            # 引用符を落とし、小文字に揃えた写しで判定する。YAML は引用符付きの偽を素の
            # `if: false` と同じスカラーとして読み、Actions は `FALSE` / `False` も偽として評価する
            probe = t
            gsub(/["\047]/, "", probe)
            probe = tolower(probe)
            # `if:` / `continue-on-error:` の行でなければ、そもそも無効化の話ではない
            if (probe !~ /^[[:space:]]*-?[[:space:]]*(if|continue-on-error):/) { return 0 }
            # 鍵を取り除いて値だけにする
            value = probe
            sub(/^[[:space:]]*-?[[:space:]]*(if|continue-on-error):[[:space:]]*/, "", value)
            # **ノードプロパティも落とす**（issue #126 のレビューで実測）。`if: &a true` は
            # PyYAML も `True` と読む正当な YAML なのに、残すと「真偽を評価できない」側へ落ちて
            # **実際に走ってゲートしているステップが「未配線」になる**（引用符と大文字小文字を
            # ここで正規化しているのと同じ理由。落とすのは名前のある形だけ）
            sub("^" prop_plain_re, "", value)
            value = trim(value)
            # **「止めていない」と確かめられる形だけを通し、残りはすべて無効化として扱う（fail-closed）。**
            # 値が式（`${{ … }}`）やブロックスカラー（`>-`）だと、その場では真偽を評価できない。
            # 評価できないものを「実行され、しかも合否に効く」と主張する資格はこのライブラリに無い
            # ——`action_pin_test.sh` が `permissions:` をブロックスカラーで書かれたとき特権側へ倒すのと同じ判断。
            # 逆に倒すと、`continue-on-error: ${{ … }}` の 1 行でゲートを外しながら全表明が緑のままになる（レビューで実測）
            if (probe ~ /^[[:space:]]*-?[[:space:]]*if:/) {
                # `if: true` だけが「止めていない」と言い切れる形
                return (value == "true") ? 0 : 1
            }
            # `continue-on-error: false` だけが「失敗が job に伝わる」と言い切れる形
            return (value == "false") ? 0 : 1
        }

        {
            # 判定に使う 1 行分の文字列を取り出し、CR を落とす
            line = $0
            sub(/\r$/, "", line)

            # 非構造行＝ブロックスカラーの本文。run: の本体か env の折りたたみブロックのときだけ拾う
            if (!structural[NR]) {
                if (in_run) {
                    # **ブロックスカラーの基準字下げは最初の非空行が決める**（YAML の規則）。
                    # bash が実際に受け取るのはこの分を落とした後の本文なので、
                    # ヒアドキュメントの終端判定もここを基準にする。
                    # **開いた行の桁を基準にすると落としすぎる**——`if …; then` の中など
                    # 基準より深い位置で開いたヒアドキュメントでは、本文中の字下げされた
                    # 区切り語まで終端と読み、以降の本文（＝ただのデータ）が実行と読まれる
                    # （issue #108 と同じ穴が入れ子の形で開く。レビューで実測）
                    # **字下げはスペースだけで測る。** YAML の字下げにタブは使えないので、
                    # 本文の先頭に現れたタブは字下げではなく**内容の一部**。これを字下げと
                    # 数えると後で落としすぎ、タブ字下げされた区切り語を終端と読む（実測）
                    if (run_base_indent < 0 && line ~ /[^[:space:]]/) {
                        run_base_indent = leading_spaces(line)
                    }
                    # **heredoc の本文はデータであってコマンドではない。**
                    # `cat <<EOF` … `bash test/x_test.sh` … `EOF` の中身を実行と読むと、
                    # ファイルへ書き出しているだけの文字列が「配線されている」証拠に化ける
                    # **待ち行列を先頭から 1 つずつ**終端させる。1 行が 2 つ以上開いたときは
                    # bash が本文を読むのと同じ順（開いた順）に消化する
                    if (hd_i <= hd_n) {
                        # 終端の行に来たら**その 1 つ**の本文の読み飛ばしを終える。判定は
                        # `heredoc_terminates` に集約してあり、**bash と同じく「区切り語だけの行」**
                        # だけを終端と認める。見つけられなければ「本文が続く」に倒れるので
                        # 判定は fail-closed 側に寄る。`<<-` かどうかは**その区切り語のもの**を渡す
                        if (heredoc_terminates(line, hd_dash[hd_i], run_base_indent, hd_word[hd_i])) {
                            hd_i++
                        }
                        next
                    }
                    text = trim(strip_comment(line))
                    # 折りたたみ本文なら直前の行に空白で繋ぎ、そうでなければ新しい 1 行として足す
                    if (text != "" && run_folded && ncmd > 0) { cmds[ncmd] = cmds[ncmd] " " text }
                    else if (text != "") { cmds[++ncmd] = text }
                    # この行が heredoc を開いていれば、終端までの本文を読み飛ばす。
                    # **開いた数だけ待ち行列に積む**——1 行に 2 つ以上書けるので、最後の 1 つ
                    # だけを覚えると先に読まれる本文が実行と読まれる（issue #111 (1)）。
                    # 区切り語の切り出し・引用の 3 綴り・`<<-` の別・here-string と算術式の
                    # 除外は、すべて `collect_heredocs` に集約してある
                    collect_heredocs(text)
                } else if (in_env) {
                    # **空白で区切って 1 エントリずつ**控える。折りたたみブロックは最終的に
                    # 1 本の空白区切り文字列になり、消費側（`shellcheck $SHELL_FILES` と
                    # `for f in $SHELL_FILES`）も空白で分割する。1 行 1 パスと決め打つと、
                    # 2 つを同じ行に書いた（消費側には何の影響も無い）だけで誤報する
                    text = trim(strip_comment(line))
                    nvalue = split(text, values, /[[:space:]]+/)
                    for (vi = 1; vi <= nvalue; vi++) {
                        if (values[vi] != "") { envbuf[++nenv] = "env\tval\t" env_var " " values[vi] }
                    }
                }
                next
            }

            # 構造行が来た時点で、直前のブロックスカラー本文は終わっている
            in_run = 0
            in_env = 0
            # 未消化の待ち行列も捨てる（構造行が来た時点で本文は終わっている）
            hd_n = 0
            hd_i = 1
            # コメントを落としてから構造を判定する
            # （`if: false  # 理由` のように理由を添えるのが最も自然な書き方なので、
            #   コメント付きを取りこぼすと「止めたステップが動いている」ことになる）
            probe = unquote_key(strip_comment(line))
            # 空になった行（コメントだけの行）は構造として扱わない
            if (trim(probe) == "") { next }
            # 字下げ幅を測る（入れ子の深さの判定に使う）
            indent = match(probe, /[^[:space:]]/) - 1

            # `env:` と同じかそれより浅い鍵が来たら、その env ブロックは終わっている。
            # **中に居る間の深さは env の桁を基準に測る**（`steps:` の桁を基準にすると、
            # `steps:` より後ろに書かれた `env:` の中身が「ステップの鍵」に見えて読み落とす）
            if (env_indent >= 0 && indent <= env_indent) { env_indent = -1 }
            # 同じ理由で `defaults:` ブロックも、同じか浅い桁の鍵が来たら終わっている
            if (defaults_indent >= 0 && indent <= defaults_indent) { defaults_indent = -1 }

            # **`jobs:` と同じかそれより浅い鍵が来たら、jobs マッピングの外に出ている。**
            # ここでジョブの解釈を閉じないと、`jobs:` の後ろに置かれたトップレベルの
            # `defaults:` の中の `run:` が「run という名前の新しいジョブ」に見え、
            # 直前のジョブが確定されたうえで既定シェルも読めなくなる（レビューで実測）
            if (jobs_indent >= 0 && job_indent >= 0 && indent <= jobs_indent) {
                flush_job()
                # **`jobs:` の位置も忘れる。** 覚えたままだと、`jobs:` の後ろに置かれた
                # 別のトップレベルのブロックの中身が新しいジョブとして読まれ、
                # `jobs:` の外にある `run:` が「CI が実行するコマンド」として記録される（レビューで実測）
                jobs_indent = -1
                job_indent = -1
                steps_indent = -1
                step_dash_indent = -1
                step_key_indent = -1
                env_indent = -1
            }

            # ダッシュだけの行で始まったステップは、次に現れた鍵の桁をステップの鍵の桁とする
            if (step_dash_indent >= 0 && step_key_indent < 0 && indent > step_dash_indent) {
                step_key_indent = indent
            }

            # ジョブに入って最初に現れた鍵の桁を、そのジョブ直下の鍵の桁として覚える
            if (job_indent >= 0 && job_key_indent < 0 && indent > job_indent) { job_key_indent = indent }

            # `jobs:` の位置を覚える
            if (jobs_indent < 0 && probe ~ /^[[:space:]]*jobs:[[:space:]]*$/) { jobs_indent = indent; next }

            # ジョブ名の行（`jobs:` より深く、かつ最初に見つけた深さと同じ）が新しいジョブの始まり
            if (jobs_indent >= 0 && indent > jobs_indent && probe ~ /^[[:space:]]*[A-Za-z_][A-Za-z0-9_.-]*:[[:space:]]*$/ \
                && (job_indent < 0 || indent == job_indent)) {
                # **前のジョブをここで確定させて出力する**（次のジョブの無効化キーを被せない）
                flush_job()
                job_indent = indent
                # ジョブ名を控える（末尾のコロンを落とした識別子がそのまま名前）
                jobname = trim(probe)
                sub(/:$/, "", jobname)
                # 次に現れる鍵の桁が、このジョブ直下の鍵の桁になる
                job_key_indent = -1
                steps_indent = -1
                step_dash_indent = -1
                step_key_indent = -1
                env_indent = -1
                defaults_indent = -1
                job_shell = ""
                next
            }

            # `steps:` の位置を覚える（以降の同じ深さのダッシュがステップの区切り）。
            # **ジョブ直下の `steps:` だけを見る**——`with:` の下に `steps:` という名前の入力があると、
            # そこを新しいステップの並びと読み、入れ子の `- run:` が実行として拾われる（レビューで実測）
            if (job_indent >= 0 && indent > job_indent && probe ~ /^[[:space:]]*steps:[[:space:]]*$/ \
                && (steps_indent < 0 || key_scope(probe, indent) == "job")) {
                steps_indent = indent
                step_dash_indent = -1
                next
            }

            # `defaults:` ブロックの開始。ワークフロー直下なら全ジョブ、ジョブ直下ならそのジョブの既定。
            # **ステップの `shell:` だけを見ても網は閉じない**——`defaults: run: shell: bash {0}` を
            # 3 行足せば全ステップから `-e` が消え、どのステップも自分では `shell:` を書いていない
            # ので「既定どおり」と読まれてしまう（レビューで実測）
            # **ステップの中の `defaults` は別物**（action への入力や env の名前でありうる）。
            # 桁で見分けないと、`with: defaults: enabled` の 1 行でそのジョブ全体が
            # 合否の証拠から外れ、すべてのスイートが「配線されていない」と誤報される
            if (probe ~ /^[[:space:]]*defaults:/ && key_scope(probe, indent) == "job") {
                # ジョブに入った後のジョブ直下ならそのジョブ限定、それ以外はワークフロー全体
                defaults_scope = (job_indent >= 0 && indent > job_indent) ? "job" : "workflow"
                # ワークフロー直下のものは BEGIN の先読みが既に拾っているので、ここでは触らない
                if (defaults_scope == "workflow") { next }
                if (probe ~ /^[[:space:]]*defaults:[[:space:]]*$/) {
                    # ブロック形式。以降の深い行から `shell:` を読む
                    defaults_indent = indent
                } else {
                    # **フロー形式（`defaults: {run: {shell: bash {0}}}`）は 1 行に畳まれていて、
                    # 中の `shell:` を構造行として読めない。** 確かめられない以上「既定どおり
                    # `bash -e` で走る」とは主張できないので、未知のシェル扱いにして
                    # そのジョブ（またはワークフロー全体）の実行を合否の証拠から外す
                    job_shell = "?"
                }
                next
            }

            # `defaults:` の中の `run:` がフロー形式（`run: {shell: bash {0}}`）なら、
            # 中の `shell:` は構造行として現れない。確かめられない以上は未知のシェル扱いにする
            # （ブロック形式だけを見ていると、2 行で全ステップから `-e` を外せる。レビューで実測）
            if (defaults_indent >= 0 && indent > defaults_indent \
                && probe ~ /^[[:space:]]*run:[[:space:]]*[^[:space:]]/) {
                # `defaults_indent` はジョブ直下の `defaults:` でしか立たない
                # （ワークフロー直下は BEGIN の先読みが持つ）ので、ここは常にジョブ側
                job_shell = "?"
                next
            }

            # `defaults:` の中に書かれた `shell:` を既定として控える
            if (defaults_indent >= 0 && indent > defaults_indent \
                && probe ~ /^[[:space:]]*shell:[[:space:]]*[^[:space:]]/) {
                shell_value = read_shell_value(probe)
                # 適用範囲に応じて控え先を分ける（ジョブ側はジョブが変わればリセットされる）
                job_shell = shell_value
                next
            }

            # ジョブ直下の `env:` の位置を覚える（この下の折りたたみブロックがそのジョブの変数）
            # **`steps:` の後ろに書かれていても読む。** YAML のキー順は自由なので `env:` を後ろへ
            # 動かすのは意味を変えない整形だが、読み落とすと「定義 0 件」＝一覧が壊れたという
            # 事実と違う診断で落ちる。ステップ自身の `env:`（より深い桁）とは桁で見分ける
            if (job_indent >= 0 && indent > job_indent && key_scope(probe, indent) == "job" \
                && probe ~ /^[[:space:]]*env:[[:space:]]*$/) {
                env_indent = indent
                next
            }

            # `env:` の下の折りたたみブロック（`NAME: >-` / `NAME: |`）の開始。
            # **どのジョブの env かまで控える**のが要点で、変数は定義したジョブからしか見えない。
            # 一覧だけを合流させて読むと、別のジョブへ移された一覧が「載っている」と見える一方、
            # lint するジョブから見た `$SHELL_FILES` は空になる（レビューで実測）
            # **ここも鍵と指示子のあいだのノードプロパティを読む**（issue #126 のレビューで実測）。
            # 構造行側は `&files >-` をブロックの開始と認めて本文を読み飛ばすのに、ここが
            # 読まないと定義そのものが 1 件も記録されず、`ci_coverage_test.sh` が
            # 「`SHELL_FILES` の定義が 0 か所」という**事実と違う診断**で落ちる（定義は 1 か所ある）
            if (env_indent >= 0 && indent > env_indent \
                && probe ~ ("^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*:[[:space:]]*" prop_re "[|>]([0-9]*[+-]?|[+-]?[0-9]*)[[:space:]]*$")) {
                # 変数名を取り出す（コロンより前が名前）
                env_var = trim(probe)
                sub(/:.*$/, "", env_var)
                # 定義が現れたこと自体を 1 件として控える（定義箇所の数はこれで数えられる）
                envbuf[++nenv] = "env\tdef\t" env_var
                # 以降の非構造行がこの変数の値
                in_env = 1
                next
            }

            # ステップの区切り（`steps:` の下で最初に現れたダッシュと**同じ字下げ**のダッシュ）
            if (steps_indent >= 0 && probe ~ /^[[:space:]]*-([[:space:]]|$)/) {
                # 最初のダッシュの字下げを、このジョブのステップの基準にする
                if (step_dash_indent < 0) { step_dash_indent = indent }
                # 基準と同じ深さのときだけ新しいステップとして扱う（入れ子の並びでは切らない）
                if (indent == step_dash_indent) {
                    flush_step()
                    step_id++
                    # **ステップ自身の鍵が並ぶ桁**を覚える（`- ` の直後の桁）。
                    # `run:` をこの桁に限らないと、`with:` の下に書かれた `run:` という
                    # **action への入力**まで「実行されるコマンド」として拾う（レビューで実測）
                    # **鍵がダッシュと同じ行にあるとは限らない。** `-` だけの行で始めるのも
                    # 正当な YAML で、その場合は次に現れた鍵の桁がステップの鍵の桁になる
                    if (probe ~ /^[[:space:]]*-[[:space:]]*$/) {
                        step_key_indent = -1
                    } else {
                        match(probe, /^[[:space:]]*-[[:space:]]+/)
                        step_key_indent = RLENGTH
                    }
                }
            }

            # 無効化キーの扱いは、ステップの中かジョブ直下かで宛先が変わる。
            # **判定は「ジョブの鍵と同じ桁か」で行う。** ダッシュの桁との比較で決めると、
            # `steps:` と `- name:` を同じ桁に書く（YAML として等しく正しい）書式のとき、
            # ジョブ直下の鍵がステップの鍵と同じ深さになり、**ジョブ全体を止めるキーが
            # 最後の 1 ステップしか止めない**（レビューで実測。round 11 で塞いだはずの形が書式違いで開く）
            if (is_disabling(probe)) {
                scope = key_scope(probe, indent)
                # ステップ自身の鍵ならそのステップだけを止める
                if (scope == "step") { step_disabled = 1 }
                # ジョブ直下ならそのジョブの全ステップが対象
                else if (scope == "job") { job_disabled = 1 }
                # 入れ子の中身（action への入力など）はワークフローの制御ではないので何もしない
                next
            }

            # ここから先は run: の取り出し。ステップの中でなければ関係ない
            if (step_dash_indent < 0) { next }

            # ステップ自身の鍵でない `run:` / `shell:`（`with:` 配下の入力など）は実行の指定ではない。
            # ダッシュ始まりを無条件に通すと、入れ子の並びの `- run:` が実行として拾われる（レビューで実測）
            if (key_scope(probe, indent) != "step") { next }

            # **そのステップがどのシェルで走るかを控える。** 既定（Linux）は `bash -e {0}` なので
            # コマンドが落ちればステップも落ちるが、`shell: bash {0}` のように**テンプレートを
            # 自分で書くと `-e` が消える**——ループの途中の失敗が握り潰され、最後の 1 回の結果だけが
            # ステップの成否になる。1 行足すだけでリンタがゲートでなくなる形なので、
            # 確かめられない綴りは「合否に効かない」側へ倒す（fail-closed）
            if (probe ~ /^[[:space:]]*-?[[:space:]]*shell:[[:space:]]*[^[:space:]]/) {
                shells[step_id] = read_shell_value(probe)
                next
            }

            # `run: |` / `run: >` のブロック開始。以降の非構造行が本体。
            # **鍵と指示子のあいだのノードプロパティも読む**（issue #126）。構造行側だけを
            # 直すと、本文は正しく読み飛ばされるのに**この判定が外れて下の 1 行書きの枝に落ち**、
            # `&suites |` が値として読まれて `suites` という幻のコマンドが記録される（実測）
            if (probe ~ ("^[[:space:]]*-?[[:space:]]*run:[[:space:]]*" prop_re "[|>]")) {
                in_run = 1
                # **明示字下げ指示子（`run: |2`）があれば、基準字下げはそちらが決める。**
                # YAML では指示子の数値が「親ノードの字下げからの相対桁」を表すので、
                # 本文をそれより深く書くと**深い分は内容の一部として残る**。
                # 最初の非空行から決めると、その残る分まで字下げと見なして落としすぎ、
                # 本文中の字下げされた区切り語を終端と読む（＝本文が実行と読まれる。実測）
                scalar_head = probe
                sub(/^.*run:[[:space:]]*/, "", scalar_head)
                # プロパティは指示子の手前の飾りなので落とす（残すと下の `^[|>]` に当たらず、
                # 明示字下げ指示子（`run: &s |2`）が読めないまま基準字下げが未確定になる）
                sub("^" prop_re, "", scalar_head)
                # **`>` は「折りたたみ」で、本文の改行は空白に畳まれて 1 つのコマンドになる。**
                # 1 行ずつ別のコマンドとして読むと、次の行に置かれた `|| true` が
                # 呼び出しと結び付かず、握り潰された実行を「ゲートしている」と読む（レビューで実測）。
                # 段落の区切り（空行）まで再現はしないので、そこでも繋いだ結果は
                # 「握り潰されている」側＝より安全な方に倒れる。
                # **判定は上で落とした `scalar_head` の先頭 1 文字で済ませる**のが要点で、
                # `run:` の前置きとプロパティの綴りを組み立て直すと同じ写しが 3 つ目になり、
                # ブロック開始の判定と折りたたみの判定が食い違う形を書けてしまう
                # （この定数の説明がまさに警告している形。下の `sub` が綴りを書き換える前に決める）
                run_folded = (substr(scalar_head, 1, 1) == ">")
                # **指示子はヘッダの形に錨を打って読む。** `run:` の後ろから数字を拾い集めると、
                # ヘッダの綴りが少しでも緩んだ瞬間に無関係な数字が指示子に化ける
                # （`run: | # issue 108` → 基準字下げ 108 桁 → 字下げを丸ごと落として
                #   どんな深さの区切り語も終端になる＝ issue #108 が開き直る）。
                # 認めるのは `|` / `>` の直後（chomping 記号は前後どちらでもよい）に来た数字だけ
                if (match(scalar_head, /^[|>][+-]?[0-9]/)) {
                    sub(/^[|>][+-]?/, "", scalar_head)
                    sub(/[^0-9].*$/, "", scalar_head)
                } else {
                    scalar_head = ""
                }
                if (scalar_head != "") {
                    # 親ノードの桁は鍵の桁。`- run: |2` のようにダッシュが付く場合は
                    # その分を進めた位置が鍵の桁になる（`- ` の桁で測ると浅く出る）
                    run_base_indent = (match(probe, /^[[:space:]]*-[[:space:]]+/) ? RLENGTH : indent) + scalar_head
                } else {
                    # 指示子が無ければ、基準字下げは最初の非空行が決める（未確定は -1）
                    run_base_indent = -1
                }
                next
            }

            # 1 行で書かれた `run: <command>`。
            # **枝の選び分けにプロパティを読ませない**のが要点で、2 か所で「プロパティを読む /
            # 読まない」が食い違うと同じ行が両方の枝に当たりうる（上のブロック側の判定を
            # 唯一の入口にして、順序に頼らない）。`run: &s |` は上で `next` されている。
            # **ただし値の取り出しでは落とす。** 素のスカラーにもプロパティは置けるので
            # （`run: &suites bash test/x.sh` は値が `bash test/x.sh` の正当な YAML）、
            # 残すと `suites bash test/x.sh` という幻のコマンドが記録され、実行している
            # スイートが「未配線」になる（fail-closed。`main` から続く既存の穴。レビューで実測）。
            # **落とすのは名前のある形だけ**（`prop_plain_re`）。名前の無い `!` を認めると
            # `run: ! bash test/x.sh` が値 `bash test/x.sh` として読まれるが、ランナーが
            # その綴りをシェルへ渡す側だと `!` が終了状態を反転してゲートしない——
            # 「ゲートしている」と言う fail-open になるので、こちらは読まない側へ倒す
            if (probe ~ /^[[:space:]]*-?[[:space:]]*run:[[:space:]]*[^|>[:space:]]/) {
                text = probe
                sub(/^[[:space:]]*-?[[:space:]]*run:[[:space:]]*/, "", text)
                sub("^" prop_plain_re, "", text)
                text = trim(text)
                # **値全体を囲む引用符は落とす。** `run: "bash test/x_test.sh"` は正当な YAML で
                # 中身は同じコマンドだが、引用符が先頭に残るとコマンドの開始位置の判定に外れ、
                # 実行しているのに「どこからも呼ばれていない」と赤くなる（レビューで実測）
                if (text ~ /^".*"$/ || text ~ /^\047.*\047$/) { text = substr(text, 2, length(text) - 2) }
                text = trim(text)
                if (text != "") { cmds[++ncmd] = text }
            }
        }
        # 最後のジョブ（とその最後のステップ）を取りこぼさない
        END { flush_job() }
    ' > "$2"
}

# ワークフローを読み込んで以降の照会に備える。第 1 引数がワークフロー、第 2 引数が一時ファイル。
# 失敗したら非ゼロを返す（呼び出し側が bail などで止める）
ci_workflow_load() {
    # 抽出して終了コードを確かめる（プロセス置換だと awk の失敗を誰も見ない）
    ci_workflow_extract "$1" "$2" || return 1
    # 1 件も取れなければ YAML の書式が変わって読めていない
    [ -s "$2" ] || return 1
    # 以降の照会が使う保存先を覚える
    CI_WORKFLOW_COMMANDS="$2"
    # ここまで来れば読み込み成功
    return 0
}

# **合否に効くコマンドだけ**を `<ジョブ名>#<ステップ番号><TAB><コマンド>` の形で書き出す。
# 第 1 引数はジョブ名の絞り込み（空文字列なら全ジョブ）。
#
# ここを 1 か所に持つ理由は、照会が 3 つ（コマンド単位・ステップ単位・スクリプトの実行）あり、
# **「ゲートに効くか」の判定を写すと片方だけが古くなる**ため。実際、`|| true` を弾く判定は
# スクリプト実行の照会にしか入っておらず、リンタ側は `shellcheck $SHELL_FILES || true` を
# 「動いている」と読んだまま緑で通っていた（レビューで実測）
ci_workflow_gating_commands() {
    # 絞り込むジョブ名（空なら絞り込まない）
    local job_filter="${1-}"
    # 第 2 引数に `top` を渡すと、制御構造（`if` / ループ / 関数）の**中**にある断片を除く。
    # 「本当に実行されるか」を問う照会（スクリプトの実行）はこれを使う——中身が走るかは
    # 条件や呼び出し元を読まないと決まらないため。一方でリンタの形を見る照会は
    # `for … do bash -n "$f"` のようにループの**中**を見たいので、除かない
    local top_only="${2-}"
    # 走査中の 1 行・`ジョブ名#ステップ番号`・ゲートに効くかの印・制御構造の深さ・コマンド本文
    local record key gate depth text
    while IFS= read -r record; do
        # 1 行を「キー」「ゲート印」「深さ」「本文」の 4 列に分ける
        key="${record%%$'\t'*}"
        record="${record#*$'\t'}"
        gate="${record%%$'\t'*}"
        record="${record#*$'\t'}"
        depth="${record%%$'\t'*}"
        text="${record#*$'\t'}"
        # 失敗が job に伝わらないコマンドは、実行の証拠として数えない
        [ "${gate}" = "1" ] || continue
        # 最上位だけを求められていれば、制御構造の中は除く
        [ "${top_only}" != "top" ] || [ "${depth}" = "0" ] || continue
        # ジョブの絞り込みが指定されていれば、そのジョブのものだけを通す
        [ -z "${job_filter}" ] || [ "${key%%#*}" = "${job_filter}" ] || continue
        # 呼び出し側が読む形（キーと本文）で書き出す
        printf '%s\t%s\n' "${key}" "${text}"
    done < "${CI_WORKFLOW_COMMANDS}"
}

# ジョブ直下の `env:` に折りたたみブロックで書かれた変数の記録を読み出す。
# 第 1 引数が種別（`def` = 定義箇所 / `val` = 値のエントリ）、第 2 引数が変数名。
# `def` はその定義があるジョブ名を、`val` はエントリを 1 行 1 件で出す。
#
# **ワークフローを読むのはこのライブラリだけにする**ための関数。呼び出し側が独自に
# 一覧ブロックを探すと YAML の解析器が 2 つになり、`run: |` の本文に同じ見た目の行が
# あったときに片方だけが食い付く（本ライブラリを切り出した理由と同じ）
ci_workflow_env_records() {
    # 読み出す種別と変数名を受け取る
    local kind="$1" name="$2"
    # 走査中の 1 行・`ジョブ名#env` のキー・種別の列・本文
    local record key column text
    while IFS= read -r record; do
        # 1 行を「キー」「種別」「本文」の 3 列に分ける
        key="${record%%$'\t'*}"
        record="${record#*$'\t'}"
        column="${record%%$'\t'*}"
        text="${record#*$'\t'}"
        # 求められた種別の行でなければ読み飛ばす
        [ "${column}" = "${kind}" ] || continue
        # 定義箇所の記録なら、変数名が一致したときにジョブ名を返す
        if [ "${kind}" = "def" ]; then
            [ "${text}" = "${name}" ] && printf '%s\n' "${key%%#*}"
            continue
        fi
        # 値の記録は `<変数名> <エントリ>` の形なので、名前を確かめてからエントリだけを返す
        [ "${text%% *}" = "${name}" ] && printf '%s\n' "${text#* }"
    done < "${CI_WORKFLOW_COMMANDS}"
}

# 控えに現れる**ジョブ名**を 1 行 1 件で返す（重複は畳む）。
#
# **ジョブ名を渡す照会の綴りを確かめるための関数。** `ci_workflow_runs_script` /
# `ci_workflow_command_matches` / `ci_workflow_step_matches` は、存在しないジョブ名を
# 渡されても「そのジョブには無い」と答える——つまり**ジョブを改名した・表の値を打ち間違えた
# だけで「配線されていない」という事実と逆の診断**が出て、しかも診断文は正しい原因を
# 名指しできない（issue #114 のレビューで実測。ケース 4 の 7 件が一斉にそうなった）。
# 呼び出し側はこの一覧と突き合わせて、知らないジョブ名なら**原因を名指しして**落とせる。
#
# **ワークフローを読むのはこのライブラリだけ**という決まりのため、呼び出し側が
# 独自に `jobs:` を探すのではなくここを通す（解析器が 2 つになると、`run: |` の本文に
# 同じ見た目の行があったときに片方だけが食い付く）。
# 控えに入るのは `ジョブ名#ステップ番号`（`run:` を持つステップ）と `ジョブ名#env`
# （折りたたみの `env:` ブロック）だけなので、**そのどちらも持たないジョブは現れない**
# （`uses:` のステップだけのジョブがその形。実測で確認）。
# **呼び出し側の用途には足りる**——`run:` を 1 つも持たないジョブはスイートを走らせられないので、
# そこを `SUITE_JOBS` に登録することは最初から誤り。失敗の文面がその両方
# （改名／`run:` を持たない）を案内する
ci_workflow_job_names() {
    # 走査中の 1 行・キー・ジョブ名
    local record key job
    # 既に出したジョブ名の印。**名前をこのライブラリ固有にする**のが要点で、`seen` のような
    # ありふれた名前を連想配列で宣言すると、`source` したスクリプト側で同名のスカラ変数を
    # 使っているところが shellcheck の SC2178 / SC2128 で落ちる——しかも**ファイルを 1 つずつ
    # 渡したときは source を追わないので再現せず**、CI のように一覧をまとめて渡したときだけ
    # 落ちる（実測。`test/action_pin_test.sh` の `local seen=0` が巻き添えになった）
    local -A emitted_jobs=()
    while IFS= read -r record; do
        # 行頭のキー（`ジョブ名#…`）を取り出す
        key="${record%%$'\t'*}"
        # キーからジョブ名だけを取り出す
        job="${key%%#*}"
        # 空のキーは読み飛ばす（保存先が壊れているときの保険）
        [ -n "${job}" ] || continue
        # 同じジョブ名は 1 度だけ出す
        [ -z "${emitted_jobs[${job}]-}" ] || continue
        emitted_jobs["${job}"]=1
        printf '%s\n' "${job}"
    done < "${CI_WORKFLOW_COMMANDS}"
}

# 合否に効くコマンドのうち **1 つが** 渡したすべての正規表現に一致するかを返す。
# 第 1 引数はジョブ名の絞り込み（空文字列なら全ジョブ）、以降が正規表現。
# 照合は bash 組み込みの `[[ =~ ]]`（ERE）で行う。1 行 1 パターンごとに `grep` を起動すると、
# 現状の ci.yml でも 1 回の照会で百数十プロセスを生む（挙動は同じで費用だけ違う）。
#
# 読み出しはプロセス置換だが、ここで隠れる失敗は無い——`ci_workflow_gating_commands` が
# 失敗しうるのは保存先が読めないときだけで、それは `ci_workflow_load` が既に確かめている。
# かつ出力が空なら一致 0 件＝この関数は非ゼロを返すので、結論は fail-closed に倒れる
ci_workflow_command_matches() {
    # 絞り込むジョブ名を取り出し、残りをパターンとして扱う
    local job_filter="${1-}"
    shift
    # 走査中の 1 行・コマンド本文・当てるパターン・全一致したかの目印
    local record text pattern matched_all
    while IFS= read -r record; do
        # 行頭のキーとタブを落として、コマンド本文だけにする
        text="${record#*$'\t'}"
        # そのコマンドがすべてのパターンを満たすかを確かめる
        matched_all=1
        for pattern in "$@"; do
            # 1 つでも外れたらこのコマンドは候補から外す
            [[ "${text}" =~ $pattern ]] || { matched_all=0; break; }
        done
        # すべて満たすコマンドが見つかれば成功
        [ "${matched_all}" -eq 1 ] && return 0
    done < <(ci_workflow_gating_commands "${job_filter}")
    # 最後まで見つからなければ失敗
    return 1
}

# **1 ステップの中で**（行はまたいでよい）渡したすべての正規表現に一致するかを返す。
# 第 1 引数はジョブ名の絞り込み（空文字列なら全ジョブ）、以降が正規表現。
# `for f in $SHELL_FILES` と `bash -n "$f"` のように、2 行で 1 つの意味を成す形のため
ci_workflow_step_matches() {
    # 絞り込むジョブ名を取り出し、残りをパターンとして扱う
    local job_filter="${1-}"
    shift
    # 各パターンがどのステップで見つかったかを記録する
    local -A hits=()
    # 走査中の 1 行・ステップのキー・コマンド本文・当てるパターン・何番目のパターンかの目印
    local record step text pattern index
    while IFS= read -r record; do
        # ステップのキーとコマンド本文に分ける
        step="${record%%$'\t'*}"
        text="${record#*$'\t'}"
        # パターンを順に当てる
        index=0
        for pattern in "$@"; do
            index=$((index + 1))
            # 一致したら「このステップでこのパターンが見つかった」と印を付ける
            [[ "${text}" =~ $pattern ]] && hits["${step}:${index}"]=1
        done
    done < <(ci_workflow_gating_commands "${job_filter}")

    # すべてのパターンが揃ったステップが 1 つでもあるかを調べる
    # 何らかのパターンが当たったステップ番号の集合
    local -A steps=()
    # 走査中のキーと、そのステップが全パターンを満たしたかの目印
    local key complete
    for key in "${!hits[@]}"; do steps["${key%%:*}"]=1; done
    for step in "${!steps[@]}"; do
        complete=1
        index=0
        for pattern in "$@"; do
            index=$((index + 1))
            # 1 つでも欠けていればこのステップは該当しない
            [ -n "${hits[${step}:${index}]-}" ] || { complete=0; break; }
        done
        # すべて揃ったステップが見つかれば成功
        [ "${complete}" -eq 1 ] && return 0
    done
    # 最後まで見つからなければ失敗
    return 1
}

# 指定したスクリプトを実行し、**その結果がジョブの合否に効く** `run:` ステップがあるかを返す。
#
# **「コマンドの位置に現れること」まで見る**のが要点。パスが行のどこかに現れるだけで良しとすると、
# `echo "skipping bash test/foo_test.sh until the flake is fixed"` や `ls -l test/foo_test.sh` が
# 「実行している」と読まれる——実行をやめた当のコミットが緑で通る。
#
# **失敗が握り潰された呼び出しも数えない。** `bash test/x_test.sh || true` / 末尾の `&` /
# `pipefail` の無いパイプ / `set +e` の下は、いずれもスイートを走らせはするが
# **落ちても job を止めない**。効果は `continue-on-error: true` と同じで、しかも 1 トークン足すだけで済む
# （このライブラリのヘッダが「削除より足す方が見落としやすい」と言っている当の形。レビューで実測）。
# **`set +e` は制御構造の中に書かれていても数えない**（issue #113）。走るか分からない `set +e` を
# 無視すると `if [ -n "$CI" ]; then set +e; fi` の 3 行で握り潰しを隠せるため、
# 弱める向きだけは「走るかもしれない」時点で反映する（詳細は上の `set` の判定にあるコメント）。
# 判定そのものは `ci_workflow_gating_commands` が持ち、ここは「コマンドの位置に現れるか」だけを見る。
#
# 第 1 引数がスクリプトのパス、第 2 引数（省略可）が絞り込むジョブ名。
#
# 一方で呼び出しの書き方の揺れ（`bash -x path` / `bash ./path` / `bash "path"` /
# `FOO=1 bash path` / `timeout 300 bash path` / 実行権限に頼った `./path`）は吸収する。
# **条件部（`if ! bash path` など）は吸収しない**——下の `wrapper` の説明のとおり、
# 条件に置かれたコマンドは落ちても job を止めないため。厳密な `bash <path>` だけを認めると、
# 意味の変わらない書き換えで「どこからも呼ばれていない」という事実と逆の診断とともに赤くなる
ci_workflow_runs_script() {
    # パスを正規表現リテラルとしてエスケープする
    local escaped
    escaped="$(ci_workflow_regex_escape "$1")"
    # 第 2 引数があればそのジョブに絞り込む（省略時は全ジョブ）
    local job_filter="${2-}"

    # 実行を許すオプションの綴り。短いまとめ書き（`-x` / `-eu`）は **n を含まないもの**だけ——
    # `-n` / `-nx` は構文を見るだけで実行しない。長いオプション（`--norc` 等）は許すが、
    # `--noexec` は下で別に弾く（`n` を含む長オプションを一律に拒むと `--norc` が誤って赤くなる）
    # `-o pipefail` のように**引数を取るオプション**も 1 つの綴りとして認める。
    # 認めないと、`bash -euo pipefail test/x_test.sh` のように厳しくしただけの書き換えで
    # 「どこからも呼ばれていない」と事実と逆の診断で赤くなる（レビューで実測）
    local option='(--[a-zA-Z0-9][a-zA-Z0-9-]*|-[a-mo-zA-MO-Z0-9]*o[[:space:]]+[a-z]+|-[a-mo-zA-MO-Z0-9]+)'
    # **区切りで切られた断片の先頭**がコマンドの開始位置（`;` `&&` `||` `|` `&` は分割済み）。
    # 環境変数の前置きは読み飛ばし、**実行ラッパの語も許す**: `timeout 300 bash x` /
    # `sudo bash x` はどれも終了コードをそのまま通す書き方で、認めないと
    # 「どこからも呼ばれていない」と事実と逆の診断で赤くなる
    # （この repo の e2e も `timeout 5 bash -c …` を使っている）。
    # 許すのは**終了コードをそのまま通す実行ラッパだけ**——`echo` / `ls` を許すと言及が実行に化ける。
    # **ブロック本体の先頭（`do` / `then` / `else`）は許すが、条件の位置は許さない。**
    # `if bash x; then …` の判定に置かれたコマンドは落ちても `set -e` を発動させず job も
    # 止めないので、`if ` を剥がす側（`strip_command_prefixes()`）とは別扱いにする
    # ——ここで剥がすのは**本体の先頭の語だけ**で、`if` / `elif` / `while` / `until` は入れない。
    # 本体が走るかどうかは錨ではなく `top` の絞り込み（`uncertain == 0`）が答える:
    # `if false` は `dead_depth`、条件の読めない `if` と `for … do` は `uncertain` を立てるので
    # 渡ってこない。`if true; then` / `while true; do` だけが通り、そこは実際に必ず走る
    # （issue #123 (3)。実 bash を真値とした 30 形の差分照合で改善 7 形・新しい誤り 0 形。
    # **その 30 形に `!` / 後置の `&&` は入っていない**——上の定数の説明を参照）。
    # 開始位置の綴りは 1 か所（`CI_WORKFLOW_BLOCK_BODY_START`）に置いてある
    # パスの直後は空白（引数・リダイレクトが続く）か `)` か断片の終わり。
    # **直後の演算子までここで見ようとしない**のが要点で、`bash x 2>&1 | tee log` のように
    # 間にリダイレクトが 1 つ入るだけで「握り潰し」の判定が外れる。
    # 失敗が job に伝わるかは断片の区切り（`ci_workflow_gating_commands` が渡す印）が答える
    # パスの前に付く**ワークスペース由来の接頭辞**（`$GITHUB_WORKSPACE/` / `${GITHUB_WORKSPACE}/` /
    # `${{ github.workspace }}/` / `./`）だけを許す。この ci.yml が既に
    # `"$GITHUB_WORKSPACE/bin/aidock"` の形を使っており、認めないと同じ書き方へ揃えた瞬間に
    # 「どこからも呼ばれていない」と事実と逆の診断で赤くなる。
    # **変数一般に広げない**——`\$HOME/test/x_test.sh` や `\$FIXTURE_DIR/test/x_test.sh` は
    # 同じ名前の**別のファイル**を指しうるので、それを配線の証拠にしてはいけない
    # （リテラルのディレクトリを許さないのと同じ理由。レビューで実測）
    local base='([$]GITHUB_WORKSPACE/|[$][{]GITHUB_WORKSPACE[}]/|[$][{][{][[:space:]]*github\.workspace[[:space:]]*[}][}]/|\./)?'
    local invocation="${CI_WORKFLOW_BLOCK_BODY_START}(bash([[:space:]]+${option})*[[:space:]]+)?[\"']?${base}${escaped}[\"']?([[:space:]]|[)]|\$)"

    # 合否に効くコマンドだけを見る（`|| true` や `set +e` の下にあるものは渡ってこない）
    local record text
    while IFS= read -r record; do
        # キーを落としてコマンド本文だけにする
        text="${record#*$'\t'}"
        # コマンドの位置に現れていなければ対象外
        [[ "${text}" =~ $invocation ]] || continue
        # `--noexec` と `-o noexec`（`-n` の別綴り）は構文を見るだけなので実行の証拠にならない
        [[ "${text}" =~ (^|[[:space:]])(--noexec|-[a-zA-Z]*o[[:space:]]+noexec)([[:space:]]|$) ]] && continue
        # ここまで来れば「実行され、その結果が job の合否に効く」と言える
        return 0
    done < <(ci_workflow_gating_commands "${job_filter}" top)
    # 最後まで見つからなければ失敗
    return 1
}
